1: /* Builds an original low-poly xiphos (leaf-shaped bronze blade, worn iron hilt) as a standalone GLB.
2:    Hand-painted look from small baked textures; flat-shaded facets for the PS2/GameCube feel.
3:    Run from the repository root: node .impeccable/tools/xiphos-sword.mjs */
4: import { Document, NodeIO } from "@gltf-transform/core";
5: import { ALL_EXTENSIONS } from "@gltf-transform/extensions";
6: import * as THREE from "../../vendor/three/three.module.min.js";
7: import sharp from "sharp";
8: import fs from "node:fs";
9: import path from "node:path";
10: 
11: const output = "assets/models/xiphos-sword.glb";
12: const document = new Document();
13: const root = document.createScene("Xiphos");
14: const buffer = document.createBuffer();
15: const sceneNode = document.createNode("Xiphos");
16: root.addChild(sceneNode);
17: 
18: /* Seeded so the painted wear is the same on every build. */
19: let seed = 7;
20: const rand = () => {
21:   seed = (seed * 16807) % 2147483647;
22:   return (seed - 1) / 2147483646;
23: };
24: const range = (a, b) => a + rand() * (b - a);
25: 
26: /* Blade texture: u runs edge to edge, v runs base (top row) to tip (bottom row). */
27: const bladeSvg = () => {
28:   const patina = [];
29:   for (let i = 0; i < 46; i += 1) {
30:     const x = range(14, 114);
31:     const y = range(0, 250) ** 1.08 * 0.94;
32:     const color = rand() < 0.55 ? "#4f8f7a" : rand() < 0.5 ? "#6fae94" : "#3e6f5f";
33:     patina.push(`<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${range(3, 13).toFixed(1)}" ry="${range(4, 18).toFixed(1)}" fill="${color}" opacity="${range(0.25, 0.6).toFixed(2)}"/>`);
34:   }
35:   const pits = [];
36:   for (let i = 0; i < 70; i += 1) {
37:     pits.push(`<circle cx="${range(10, 118).toFixed(1)}" cy="${range(0, 256).toFixed(1)}" r="${range(0.5, 1.6).toFixed(2)}" fill="#3d2a18" opacity="${range(0.25, 0.55).toFixed(2)}"/>`);
38:   }
39:   const scratches = [];
40:   for (let i = 0; i < 26; i += 1) {
41:     const x = range(8, 120);
42:     const y = range(0, 250);
43:     const len = range(6, 22);
44:     const tilt = range(-0.5, 0.5);
45:     scratches.push(`<path d="M${x.toFixed(1)} ${y.toFixed(1)} l${(len * tilt).toFixed(1)} ${len.toFixed(1)}" stroke="#f6dca2" stroke-width="${range(0.4, 1).toFixed(2)}" opacity="${range(0.2, 0.45).toFixed(2)}"/>`);
46:   }
47:   return `
48:   <svg xmlns="http://www.w3.org/2000/svg" width="128" height="256" viewBox="0 0 128 256">
49:     <defs>
50:       <linearGradient id="bronze" x1="0" x2="1">
51:         <stop stop-color="#f0c67a"/><stop offset=".12" stop-color="#cf9a52"/>
52:         <stop offset=".42" stop-color="#b27a3c"/><stop offset=".5" stop-color="#dcaa62"/>
53:         <stop offset=".58" stop-color="#b27a3c"/><stop offset=".88" stop-color="#cf9a52"/>
54:         <stop offset="1" stop-color="#f0c67a"/>
55:       </linearGradient>
56:       <linearGradient id="edge" x1="0" x2="1">
57:         <stop stop-color="#f7dc9c" stop-opacity=".95"/><stop offset="1" stop-color="#f7dc9c" stop-opacity="0"/>
58:       </linearGradient>
59:       <linearGradient id="tipFade" x1="0" y1="0" x2="0" y2="1">
60:         <stop offset=".55" stop-color="#2e4a40" stop-opacity="0"/><stop offset="1" stop-color="#2e4a40" stop-opacity=".18"/>
61:       </linearGradient>
62:       <filter id="soft"><feGaussianBlur stdDeviation="2.4"/></filter>
63:     </defs>
64:     <rect width="128" height="256" fill="url(#bronze)"/>
65:     <g filter="url(#soft)">${patina.join("")}</g>
66:     <rect width="128" height="256" fill="url(#tipFade)"/>
67:     ${pits.join("")}
68:     <rect x="60" width="8" height="256" fill="#d9a560" opacity=".55"/>
69:     <rect x="63" width="2" height="256" fill="#f4d391" opacity=".8"/>
70:     <rect x="55" width="3" height="256" fill="#6e4520" opacity=".45"/>
71:     <rect x="70" width="3" height="256" fill="#6e4520" opacity=".45"/>
72:     <rect width="12" height="256" fill="url(#edge)"/>
73:     <rect x="116" width="12" height="256" fill="url(#edge)" transform="rotate(180 122 128)"/>
74:     ${scratches.join("")}
75:   </svg>`;
76: };
77: 
78: /* Worn iron: mottled grey with rust blooms and bright rubbed scratches. Tiles. */
79: const ironSvg = () => {
80:   const blotches = [];
81:   for (let i = 0; i < 40; i += 1) {
82:     const color = rand() < 0.5 ? "#3a3936" : "#77736b";
83:     blotches.push(`<ellipse cx="${range(0, 128).toFixed(1)}" cy="${range(0, 128).toFixed(1)}" rx="${range(4, 14).toFixed(1)}" ry="${range(3, 10).toFixed(1)}" fill="${color}" opacity="${range(0.3, 0.6).toFixed(2)}"/>`);
84:   }
85:   const rust = [];
86:   for (let i = 0; i < 18; i += 1) {
87:     const color = rand() < 0.5 ? "#7a4a2b" : "#9b5a2e";
88:     rust.push(`<ellipse cx="${range(0, 128).toFixed(1)}" cy="${range(0, 128).toFixed(1)}" rx="${range(2, 9).toFixed(1)}" ry="${range(2, 7).toFixed(1)}" fill="${color}" opacity="${range(0.3, 0.65).toFixed(2)}"/>`);
89:   }
90:   const scratches = [];
91:   for (let i = 0; i < 22; i += 1) {
92:     const x = range(0, 128);
93:     const y = range(0, 128);
94:     scratches.push(`<path d="M${x.toFixed(1)} ${y.toFixed(1)} l${range(-10, 10).toFixed(1)} ${range(-6, 6).toFixed(1)}" stroke="#a8a49a" stroke-width="${range(0.4, 1).toFixed(2)}" opacity="${range(0.3, 0.6).toFixed(2)}"/>`);
95:   }
96:   return `
97:   <svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
98:     <defs><filter id="soft"><feGaussianBlur stdDeviation="2"/></filter></defs>
99:     <rect width="128" height="128" fill="#5b5a56"/>
100:     <g filter="url(#soft)">${blotches.join("")}${rust.join("")}</g>
101:     ${scratches.join("")}
102:   </svg>`;
103: };
104: 
105: /* Dark leather cord wound around the grip. */
106: const leatherSvg = () => {
107:   const bands = [];
108:   for (let y = -16; y < 80; y += 8) {
109:     bands.push(`<path d="M0 ${y} L64 ${y + 16}" stroke="#2b1a12" stroke-width="2.2" opacity=".85"/>`);
110:     bands.push(`<path d="M0 ${y + 3} L64 ${y + 19}" stroke="#7a5236" stroke-width="1.2" opacity=".55"/>`);
111:   }
112:   return `
113:   <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64">
114:     <rect width="64" height="64" fill="#4a2f20"/>
115:     ${bands.join("")}
116:   </svg>`;
117: };
118: 
119: const makeTexture = async (name, svg) => {
120:   const png = await sharp(Buffer.from(svg)).png().toBuffer();
121:   return document.createTexture(name)
122:     .setImage(new Uint8Array(png))
123:     .setMimeType("image/png")
124:     .setURI(`${name.toLowerCase().replace(/\s+/g, "-")}.png`);
125: };
126: const textures = {
127:   blade: await makeTexture("Xiphos bronze", bladeSvg()),
128:   iron: await makeTexture("Xiphos iron", ironSvg()),
129:   leather: await makeTexture("Xiphos leather", leatherSvg()),
130: };
131: 
132: const makeMaterial = (name, texture, options = {}) => {
133:   const material = document.createMaterial(name)
134:     .setBaseColorFactor([1, 1, 1, 1])
135:     .setMetallicFactor(options.metallic ?? 0)
136:     .setRoughnessFactor(options.roughness ?? 0.8)
137:     .setBaseColorTexture(texture);
138:   return material;
139: };
140: const materials = {
141:   blade: makeMaterial("Patinated bronze", textures.blade, { metallic: 0.55, roughness: 0.42 }),
142:   iron: makeMaterial("Worn iron", textures.iron, { metallic: 0.6, roughness: 0.68 }),
143:   leather: makeMaterial("Leather cord", textures.leather, { roughness: 0.9 }),
144: };
145: 
146: /* Facets: every triangle gets its own normal. */
147: const faceted = (geometry) => {
148:   const flat = geometry.index ? geometry.toNonIndexed() : geometry;
149:   flat.computeVertexNormals();
150:   return flat;
151: };
152: /* Hilt pieces share a tiling iron texture; project UVs from the side so the scale matches across parts. */
153: const boxUv = (geometry, scale = 7) => {
154:   const pos = geometry.getAttribute("position");
155:   const uv = new Float32Array(pos.count * 2);
156:   for (let i = 0; i < pos.count; i += 1) {
157:     uv[i * 2] = (pos.getX(i) + pos.getZ(i) * 0.7) * scale;
158:     uv[i * 2 + 1] = pos.getY(i) * scale;
159:   }
160:   geometry.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
161:   return geometry;
162: };
163: 
164: let triangles = 0;
165: const addMesh = (name, geometry, material, position = [0, 0, 0], rotation = [0, 0, 0]) => {
166:   const positions = geometry.getAttribute("position");
167:   const normals = geometry.getAttribute("normal");
168:   const uv = geometry.getAttribute("uv");
169:   triangles += (geometry.index ? geometry.index.count : positions.count) / 3;
170:   const primitive = document.createPrimitive().setMaterial(material)
171:     .setAttribute("POSITION", document.createAccessor().setType("VEC3").setArray(new Float32Array(positions.array)).setBuffer(buffer))
172:     .setAttribute("NORMAL", document.createAccessor().setType("VEC3").setArray(new Float32Array(normals.array)).setBuffer(buffer));
173:   if (uv) primitive.setAttribute("TEXCOORD_0", document.createAccessor().setType("VEC2").setArray(new Float32Array(uv.array)).setBuffer(buffer));
174:   if (geometry.index) primitive.setIndices(document.createAccessor().setType("SCALAR").setArray(new Uint32Array(geometry.index.array)).setBuffer(buffer));
175:   const mesh = document.createMesh(name).addPrimitive(primitive);
176:   const transform = new THREE.Object3D();
177:   transform.position.fromArray(position);
178:   transform.rotation.set(...rotation);
179:   sceneNode.addChild(document.createNode(name).setMesh(mesh)
180:     .setTranslation(transform.position.toArray())
181:     .setRotation(transform.quaternion.toArray()));
182: };
