/* Builds an original low-poly Muscular Humanoid White Werewolf Warrior boss as a standalone GLB.
   Route A per .impeccable/docs/3d-models.md (the Sketchfab reference 45c53ad96ccf4754a6f36e70165fbafc
   by oxYde has downloads disabled and no listed licence).
   Run from the repository root: node .impeccable/tools/werewolf-boss.mjs */
import { Document, NodeIO } from "@gltf-transform/core";
import { ALL_EXTENSIONS } from "@gltf-transform/extensions";
import * as THREE from "../../vendor/three/three.module.min.js";
import sharp from "sharp";
import fs from "node:fs";
import path from "node:path";

const output = "assets/models/werewolf-boss.glb";
const document = new Document();
const root = document.createScene("WerewolfBoss");
const buffer = document.createBuffer();
const sceneNode = document.createNode("WerewolfBoss");
root.addChild(sceneNode);

/* Seeded RNG so the painted textures are identical on every build. */
let seed = 73;
const rand = () => {
  seed = (seed * 16807) % 2147483647;
  return (seed - 1) / 2147483646;
};
const range = (a, b) => a + rand() * (b - a);

/* White & silver wolf fur with muscle contour shading and subtle brush strokes. */
const furSvg = () => {
  const strokes = [];
  for (let i = 0; i < 110; i += 1) {
    const x = range(4, 252);
    const y = range(4, 252);
    const len = range(8, 26);
    const dx = range(-4, 4);
    const col = rand() < 0.5 ? "#ffffff" : rand() < 0.6 ? "#cfd5df" : "#abb3c2";
    strokes.push(
      `<path d="M${x.toFixed(1)} ${y.toFixed(1)} l${dx.toFixed(1)} ${len.toFixed(1)}" stroke="${col}" stroke-width="${range(1.0, 2.4).toFixed(2)}" stroke-linecap="round" opacity="${range(0.22, 0.55).toFixed(2)}"/>`,
    );
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256">
    <defs>
      <linearGradient id="furBase" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#f7f9fc"/>
        <stop offset="0.45" stop-color="#eaedf3"/>
        <stop offset="0.82" stop-color="#d5dbe6"/>
        <stop offset="1" stop-color="#b8c0cf"/>
      </linearGradient>
      <linearGradient id="furSide" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stop-color="#aeb7c7" stop-opacity="0.45"/>
        <stop offset="0.22" stop-color="#ffffff" stop-opacity="0"/>
        <stop offset="0.5" stop-color="#9aa3b5" stop-opacity="0.22"/>
        <stop offset="0.78" stop-color="#ffffff" stop-opacity="0"/>
        <stop offset="1" stop-color="#aeb7c7" stop-opacity="0.45"/>
      </linearGradient>
    </defs>
    <rect width="256" height="256" fill="url(#furBase)"/>
    <rect width="256" height="256" fill="url(#furSide)"/>
    ${strokes.join("")}
  </svg>`;
};

/* Dark fur & shadowy inner ear / nose / claw dark slate-charcoal. */
const darkSvg = () => {
  const flecks = [];
  for (let i = 0; i < 40; i += 1) {
    const col = rand() < 0.5 ? "#1f2229" : "#494e5c";
    flecks.push(
      `<ellipse cx="${range(0, 128).toFixed(1)}" cy="${range(0, 128).toFixed(1)}" rx="${range(3, 10).toFixed(1)}" ry="${range(4, 12).toFixed(1)}" fill="${col}" opacity="${range(0.25, 0.55).toFixed(2)}"/>`,
    );
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
    <rect width="128" height="128" fill="#323640"/>
    ${flecks.join("")}
  </svg>`;
};

/* Dark charcoal martial trousers & wrist wraps with cloth fold shading. */
const clothSvg = () => {
  const folds = [];
  for (let i = 0; i < 36; i += 1) {
    const x = range(6, 122);
    const y = range(0, 100);
    const h = range(18, 60);
    const col = rand() < 0.5 ? "#181a20" : "#3a3e4a";
    folds.push(
      `<path d="M${x.toFixed(1)} ${y.toFixed(1)} q${range(-6, 6).toFixed(1)} ${(h * 0.5).toFixed(1)} ${range(-4, 4).toFixed(1)} ${h.toFixed(1)}" stroke="${col}" stroke-width="${range(1.5, 3.6).toFixed(2)}" fill="none" opacity="${range(0.3, 0.6).toFixed(2)}"/>`,
    );
  }
  for (let y = 8; y < 128; y += 14) {
    folds.push(`<line x1="0" y1="${y}" x2="128" y2="${y + 4}" stroke="#1c1e24" stroke-width="1.4" opacity="0.35"/>`);
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
    <defs>
      <linearGradient id="clothG" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#2f333d"/>
        <stop offset="0.6" stop-color="#23262e"/>
        <stop offset="1" stop-color="#181a20"/>
      </linearGradient>
    </defs>
    <rect width="128" height="128" fill="url(#clothG)"/>
    ${folds.join("")}
  </svg>`;
};

/* Crimson-red rope belt, sash tails, and war markings. */
const crimsonSvg = () => {
  const braids = [];
  for (let y = -16; y < 144; y += 10) {
    braids.push(`<path d="M0 ${y} L128 ${y + 22}" stroke="#6e1715" stroke-width="2.6" opacity="0.65"/>`);
    braids.push(`<path d="M0 ${y + 4} L128 ${y + 26}" stroke="#d94b43" stroke-width="1.5" opacity="0.55"/>`);
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
    <defs>
      <linearGradient id="redG" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="#c93832"/>
        <stop offset="0.5" stop-color="#9e2420"/>
        <stop offset="1" stop-color="#751816"/>
      </linearGradient>
    </defs>
    <rect width="128" height="128" fill="url(#redG)"/>
    ${braids.join("")}
  </svg>`;
};

/* Fierce glowing crimson-amber wolf eyes. */
const eyeSvg = () => `
  <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64">
    <radialGradient id="eyeG" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#ffd27d"/>
      <stop offset="0.45" stop-color="#f23a2e"/>
      <stop offset="1" stop-color="#5e0c0a"/>
    </radialGradient>
    <rect width="64" height="64" fill="url(#eyeG)"/>
  </svg>`;

const makeTexture = async (name, svg) => {
  const png = await sharp(Buffer.from(svg)).png().toBuffer();
  return document
    .createTexture(name)
    .setImage(new Uint8Array(png))
    .setMimeType("image/png")
    .setURI(`${name.toLowerCase().replace(/\s+/g, "-")}.png`);
};

const textures = {
  fur: await makeTexture("Werewolf white fur", furSvg()),
  dark: await makeTexture("Werewolf dark slate", darkSvg()),
  cloth: await makeTexture("Werewolf martial cloth", clothSvg()),
  crimson: await makeTexture("Werewolf crimson sash", crimsonSvg()),
  eye: await makeTexture("Werewolf crimson eye", eyeSvg()),
};

const makeMaterial = (name, texture, options = {}) => {
  const mat = document
    .createMaterial(name)
    .setBaseColorFactor(options.color ?? [1, 1, 1, 1])
    .setMetallicFactor(options.metallic ?? 0)
    .setRoughnessFactor(options.roughness ?? 0.85)
    .setBaseColorTexture(texture);
  if (options.emissive) mat.setEmissiveFactor(options.emissive);
  return mat;
};

const materials = {
  fur: makeMaterial("White wolf fur", textures.fur, { roughness: 0.82 }),
  furShade: makeMaterial("Shaded wolf fur", textures.fur, { color: [0.84, 0.87, 0.92, 1], roughness: 0.86 }),
  dark: makeMaterial("Dark wolf hide", textures.dark, { roughness: 0.75 }),
  cloth: makeMaterial("Martial trousers", textures.cloth, { roughness: 0.9 }),
  crimson: makeMaterial("Crimson sash", textures.crimson, { roughness: 0.78 }),
  scar: makeMaterial("Crimson war mark", textures.crimson, { color: [0.92, 0.34, 0.32, 1], roughness: 0.8 }),
  eye: makeMaterial("Glowing wolf eye", textures.eye, { emissive: [0.95, 0.22, 0.16], roughness: 0.3 }),
};

const faceted = (geometry) => {
  const flat = geometry.index ? geometry.toNonIndexed() : geometry;
  flat.computeVertexNormals();
  return flat;
};

const boxUv = (geometry, scale = 3.2) => {
  const pos = geometry.getAttribute("position");
  const uv = new Float32Array(pos.count * 2);
  for (let i = 0; i < pos.count; i += 1) {
    const u = 0.5 + (pos.getX(i) + pos.getZ(i) * 0.65) * scale;
    const v = 0.5 - pos.getY(i) * scale;
    uv[i * 2] = u;
    uv[i * 2 + 1] = v;
  }
  geometry.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
  return geometry;
};

/* Anatomical ring loft along a station table:
   each station is { p: [x, y, z], rx, rz, ry?, roll?, pitch?, yaw? }
   and `section` is an array of [cx, cz] points on the unit circle. */
const defaultSection = (sides = 10) => {
  const pts = [];
  for (let k = 0; k < sides; k += 1) {
    const a = (k / sides) * Math.PI * 2;
    pts.push([Math.cos(a), Math.sin(a)]);
  }
  return pts;
};

const loft = (stations, section = defaultSection(10), { capStart = true, capEnd = true } = {}) => {
  const n = section.length;
  const positions = [];
  const uvs = [];
  const indices = [];

  stations.forEach((st, sIdx) => {
    const prev = stations[Math.max(0, sIdx - 1)].p;
    const next = stations[Math.min(stations.length - 1, sIdx + 1)].p;
    const tangent = new THREE.Vector3(next[0] - prev[0], next[1] - prev[1], next[2] - prev[2]);
    if (tangent.lengthSq() < 1e-8) tangent.set(0, 1, 0);
    tangent.normalize();

    /* Build local frame (right, tangent, forward) */
    const upHint = Math.abs(tangent.z) > 0.85 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(0, 0, 1);
    const right = new THREE.Vector3().crossVectors(tangent, upHint).normalize();
    const forward = new THREE.Vector3().crossVectors(right, tangent).normalize();

    const vCoord = sIdx / Math.max(1, stations.length - 1);
    for (let k = 0; k < n; k += 1) {
      const [cx, cz] = section[k];
      const ox = cx * st.rx;
      const oz = cz * st.rz;
      const oy = (st.ry ?? 0) * cz;
      const vx = st.p[0] + right.x * ox + forward.x * oz + tangent.x * oy;
      const vy = st.p[1] + right.y * ox + forward.y * oz + tangent.y * oy;
      const vz = st.p[2] + right.z * ox + forward.z * oz + tangent.z * oy;
      positions.push(vx, vy, vz);
      uvs.push(k / n, vCoord);
    }
  });

  for (let s = 0; s < stations.length - 1; s += 1) {
    for (let k = 0; k < n; k += 1) {
      const a = s * n + k;
      const b = s * n + ((k + 1) % n);
      const c = a + n;
      const d = b + n;
      indices.push(a, b, c, b, d, c);
    }
  }

  if (capStart) {
    const startCenter = positions.length / 3;
    const p0 = stations[0].p;
    positions.push(p0[0], p0[1], p0[2]);
    uvs.push(0.5, 0);
    for (let k = 0; k < n; k += 1) {
      indices.push(startCenter, (k + 1) % n, k);
    }
  }

  if (capEnd) {
    const endCenter = positions.length / 3;
    const pEnd = stations[stations.length - 1].p;
    positions.push(pEnd[0], pEnd[1], pEnd[2]);
    uvs.push(0.5, 1);
    const base = (stations.length - 1) * n;
    for (let k = 0; k < n; k += 1) {
      indices.push(endCenter, base + k, base + ((k + 1) % n));
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  return faceted(geo);
};

/* Mirror a station table across X (left <-> right). */
const mirrorStations = (stations) =>
  stations.map((st) => ({
    ...st,
    p: [-st.p[0], st.p[1], st.p[2]],
  }));

/* Create curved fur spike / mane lock along a 3-point arc. */
const spikeGeo = (base, mid, tip, rx, rz, sides = 6) =>
  loft(
    [
      { p: base, rx: rx * 0.72, rz: rz * 0.72 },
      { p: [base[0] * 0.65 + mid[0] * 0.35, base[1] * 0.65 + mid[1] * 0.35, base[2] * 0.65 + mid[2] * 0.35], rx, rz },
      { p: mid, rx: rx * 0.82, rz: rz * 0.82 },
      { p: [mid[0] * 0.45 + tip[0] * 0.55, mid[1] * 0.45 + tip[1] * 0.55, mid[2] * 0.45 + tip[2] * 0.55], rx: rx * 0.42, rz: rz * 0.42 },
      { p: tip, rx: 0.002, rz: 0.002 },
    ],
    defaultSection(sides),
  );

/* Articulated node hierarchy so the boss can breathe, turn its head, poise its arms, and sway its tail. */
const nodes = {
  Pelvis: document.createNode("Pelvis").setTranslation([0, 0, 0]),
  Torso: document.createNode("Torso").setTranslation([0, 0.52, 0]),
  Head: document.createNode("Head").setTranslation([0, 0.31, 0.04]),
  LeftArm: document.createNode("LeftArm").setTranslation([0.23, 0.25, 0.0]),
  RightArm: document.createNode("RightArm").setTranslation([-0.23, 0.25, 0.0]),
  LeftForeArm: document.createNode("LeftForeArm").setTranslation([0.08, -0.17, 0.02]),
  RightForeArm: document.createNode("RightForeArm").setTranslation([-0.08, -0.17, 0.02]),
  LeftLeg: document.createNode("LeftLeg").setTranslation([0, 0, 0]),
  RightLeg: document.createNode("RightLeg").setTranslation([0, 0, 0]),
  Tail: document.createNode("Tail").setTranslation([0, 0.48, -0.1]),
};
sceneNode.addChild(nodes.Pelvis);
nodes.Pelvis.addChild(nodes.Torso);
nodes.Torso.addChild(nodes.Head);
nodes.Torso.addChild(nodes.LeftArm);
nodes.Torso.addChild(nodes.RightArm);
nodes.LeftArm.addChild(nodes.LeftForeArm);
nodes.RightArm.addChild(nodes.RightForeArm);
nodes.Pelvis.addChild(nodes.LeftLeg);
nodes.Pelvis.addChild(nodes.RightLeg);
nodes.Pelvis.addChild(nodes.Tail);

let triangles = 0;
const addPart = (parent, name, geometry, material, position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1]) => {
  const g = geometry.getAttribute("uv") ? geometry : boxUv(geometry);
  const pos = g.getAttribute("position");
  const norm = g.getAttribute("normal");
  const uv = g.getAttribute("uv");
  triangles += (g.index ? g.index.count : pos.count) / 3;
  const prim = document
    .createPrimitive()
    .setMaterial(material)
    .setAttribute("POSITION", document.createAccessor().setType("VEC3").setArray(new Float32Array(pos.array)).setBuffer(buffer))
    .setAttribute("NORMAL", document.createAccessor().setType("VEC3").setArray(new Float32Array(norm.array)).setBuffer(buffer));
  if (uv) {
    prim.setAttribute("TEXCOORD_0", document.createAccessor().setType("VEC2").setArray(new Float32Array(uv.array)).setBuffer(buffer));
  }
  if (g.index) {
    prim.setIndices(document.createAccessor().setType("SCALAR").setArray(new Uint32Array(g.index.array)).setBuffer(buffer));
  }
  const mesh = document.createMesh(name).addPrimitive(prim);
  const obj = new THREE.Object3D();
  obj.position.fromArray(position);
  obj.rotation.set(...rotation);
  obj.scale.fromArray(scale);
  parent.addChild(
    document
      .createNode(name)
      .setMesh(mesh)
      .setTranslation(obj.position.toArray())
      .setRotation(obj.quaternion.toArray())
      .setScale(obj.scale.toArray()),
  );
};

/* ============================================================================
   1. MUSCULAR TORSO (local to Torso at y = 0.52)
   Heroic V-taper: narrow waist -> sculpted abs -> wide lats & pectorals -> traps
   ============================================================================ */
const torsoSection = [
  [-1.0, 0.0],
  [-0.86, 0.52],
  [-0.42, 0.92],
  [0.0, 0.78], // Sternum / linea alba furrow!
  [0.42, 0.92],
  [0.86, 0.52],
  [1.0, 0.0],
  [0.88, -0.58],
  [0.42, -0.95],
  [0.0, -0.82], // Spine furrow!
  [-0.42, -0.95],
  [-0.88, -0.58],
];
addPart(
  nodes.Torso,
  "TorsoCore",
  loft(
    [
      { p: [0, -0.05, 0.0], rx: 0.115, rz: 0.082 },
      { p: [0, 0.01, 0.005], rx: 0.122, rz: 0.088 },
      { p: [0, 0.08, 0.012], rx: 0.142, rz: 0.102 },
      { p: [0, 0.15, 0.02], rx: 0.178, rz: 0.122 },
      { p: [0, 0.22, 0.022], rx: 0.208, rz: 0.134 },
      { p: [0, 0.28, 0.01], rx: 0.185, rz: 0.118 },
      { p: [0, 0.33, -0.005], rx: 0.118, rz: 0.095 },
    ],
    torsoSection,
  ),
  materials.fur,
);

/* Sculpted pectoral plates and 6-pack abdominal muscle blocks */
for (const side of [-1, 1]) {
  addPart(
    nodes.Torso,
    `Pectoral_${side > 0 ? "L" : "R"}`,
    loft(
      [
        { p: [side * 0.018, 0.19, 0.09], rx: 0.032, rz: 0.042 },
        { p: [side * 0.068, 0.195, 0.112], rx: 0.052, rz: 0.054 },
        { p: [side * 0.125, 0.205, 0.096], rx: 0.046, rz: 0.046 },
        { p: [side * 0.165, 0.225, 0.065], rx: 0.026, rz: 0.028 },
      ],
      defaultSection(8),
    ),
    materials.fur,
  );
  /* Three pairs of sculpted abdominal muscles */
  [
    [0.135, 0.036, 0.024, 0.098],
    [0.088, 0.034, 0.022, 0.094],
    [0.042, 0.031, 0.02, 0.086],
  ].forEach(([ay, w, h, az], idx) => {
    addPart(
      nodes.Torso,
      `Ab_${side > 0 ? "L" : "R"}_${idx}`,
      loft(
        [
          { p: [side * 0.012, ay, az - 0.006], rx: h * 0.75, rz: 0.022 },
          { p: [side * (0.016 + w * 0.5), ay, az + 0.008], rx: h, rz: 0.03 },
          { p: [side * (0.018 + w), ay, az - 0.004], rx: h * 0.72, rz: 0.02 },
        ],
        defaultSection(7),
      ),
      materials.furShade,
    );
  });
}

/* Thick trapezius & upper-back muscle mass supporting the wolf head and mane */
addPart(
  nodes.Torso,
  "Traps",
  loft(
    [
      { p: [-0.15, 0.25, -0.02], rx: 0.045, rz: 0.05 },
      { p: [-0.08, 0.30, -0.01], rx: 0.072, rz: 0.072 },
      { p: [0, 0.32, -0.005], rx: 0.082, rz: 0.082 },
      { p: [0.08, 0.30, -0.01], rx: 0.072, rz: 0.072 },
      { p: [0.15, 0.25, -0.02], rx: 0.045, rz: 0.05 },
    ],
    defaultSection(8),
  ),
  materials.fur,
);

/* Layered white mane cascading over chest, shoulders, and upper back */
const maneLocks = [
  /* Upper back & shoulder mane spikes */
  [[0, 0.33, -0.03], [0, 0.26, -0.15], [0, 0.12, -0.22], 0.055, 0.042],
  [[0.07, 0.32, -0.03], [0.12, 0.25, -0.14], [0.15, 0.11, -0.2], 0.048, 0.038],
  [[-0.07, 0.32, -0.03], [-0.12, 0.25, -0.14], [-0.15, 0.11, -0.2], 0.048, 0.038],
  [[0.13, 0.30, -0.01], [0.22, 0.26, -0.1], [0.29, 0.18, -0.15], 0.042, 0.032],
  [[-0.13, 0.30, -0.01], [-0.22, 0.26, -0.1], [-0.29, 0.18, -0.15], 0.042, 0.032],
  /* Lower dorsal mane tufts (visible behind the waist/arms like the reference) */
  [[0.12, 0.2, -0.08], [0.2, 0.11, -0.14], [0.25, 0.01, -0.17], 0.04, 0.03],
  [[-0.12, 0.2, -0.08], [-0.2, 0.11, -0.14], [-0.25, 0.01, -0.17], 0.04, 0.03],
  [[0, 0.2, -0.09], [0, 0.08, -0.16], [0, -0.03, -0.19], 0.048, 0.034],
  /* Front collar ruff framing the wolf jaw */
  [[0.06, 0.29, 0.06], [0.09, 0.24, 0.12], [0.07, 0.18, 0.14], 0.034, 0.026],
  [[-0.06, 0.29, 0.06], [-0.09, 0.24, 0.12], [-0.07, 0.18, 0.14], 0.034, 0.026],
  [[0, 0.28, 0.07], [0, 0.23, 0.125], [0, 0.17, 0.14], 0.036, 0.026],
];
maneLocks.forEach(([b, m, t, rx, rz], idx) => {
  addPart(nodes.Torso, `ManeLock_${idx}`, spikeGeo(b, m, t, rx, rz, 6), idx % 2 ? materials.fur : materials.furShade);
});

/* ============================================================================
   2. WOLF HEAD, SNOUT, EARS, EYES & HEAD MANE (local to Head at y=0.83, z=0.04)
   ============================================================================ */
const skullSection = [
  [-1.0, 0.0],
  [-0.82, 0.62],
  [-0.36, 0.96],
  [0.0, 1.0],
  [0.36, 0.96],
  [0.82, 0.62],
  [1.0, 0.0],
  [0.78, -0.68],
  [0.0, -0.92],
  [-0.78, -0.68],
];
/* Cranium + long tapered lupine muzzle */
addPart(
  nodes.Head,
  "WolfSkullMuzzle",
  loft(
    [
      { p: [0, 0.05, -0.08], rx: 0.075, rz: 0.072 },
      { p: [0, 0.045, -0.02], rx: 0.098, rz: 0.086 },
      { p: [0, 0.035, 0.035], rx: 0.092, rz: 0.078 }, // Brow & cheekbones
