/* Builds an original low-poly Muscular Humanoid White Werewolf Warrior boss as a standalone GLB.
   Route A per .impeccable/docs/3d-models.md (the Sketchfab reference 45c53ad96ccf4754a6f36e70165fbafc
   by oxYde has downloads disabled and no listed licence).
   Run from the repository root: node .impeccable/tools/werewolf-boss.mjs */
import { Document, NodeIO } from "@gltf-transform/core";
import { ALL_EXTENSIONS } from "@gltf-transform/extensions";
import * as THREE from "../../vendor/three/three.module.min.js";
import sharp from "sharp";
import fs from "node:fs";
import path from "node:path";

const output = "assets/models/werewolf-boss.glb";
const document = new Document();
const root = document.createScene("WerewolfBoss");
const buffer = document.createBuffer();
const sceneNode = document.createNode("WerewolfBoss");
root.addChild(sceneNode);

/* Seeded RNG so the painted textures are identical on every build. */
let seed = 73;
const rand = () => {
  seed = (seed * 16807) % 2147483647;
  return (seed - 1) / 2147483646;
};
const range = (a, b) => a + rand() * (b - a);

/* White & silver wolf fur with muscle contour shading and subtle brush strokes. */
const furSvg = () => {
  const strokes = [];
  for (let i = 0; i < 120; i += 1) {
    const x = range(4, 252);
    const y = range(4, 252);
    const len = range(8, 24);
    const dx = range(-3, 3);
    const col = rand() < 0.55 ? "#ffffff" : rand() < 0.6 ? "#d3d9e4" : "#b2bac9";
    strokes.push(
      `<path d="M${x.toFixed(1)} ${y.toFixed(1)} l${dx.toFixed(1)} ${len.toFixed(1)}" stroke="${col}" stroke-width="${range(1.0, 2.2).toFixed(2)}" stroke-linecap="round" opacity="${range(0.2, 0.5).toFixed(2)}"/>`,
    );
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256">
    <defs>
      <linearGradient id="furBase" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#f9fbff"/>
        <stop offset="0.5" stop-color="#eceff5"/>
        <stop offset="0.85" stop-color="#d9dfe9"/>
        <stop offset="1" stop-color="#c2c9d6"/>
      </linearGradient>
      <linearGradient id="furSide" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stop-color="#b8c0cf" stop-opacity="0.35"/>
        <stop offset="0.25" stop-color="#ffffff" stop-opacity="0"/>
        <stop offset="0.5" stop-color="#a5aebe" stop-opacity="0.18"/>
        <stop offset="0.75" stop-color="#ffffff" stop-opacity="0"/>
        <stop offset="1" stop-color="#b8c0cf" stop-opacity="0.35"/>
      </linearGradient>
    </defs>
    <rect width="256" height="256" fill="url(#furBase)"/>
    <rect width="256" height="256" fill="url(#furSide)"/>
    ${strokes.join("")}
  </svg>`;
};

/* Dark charcoal-silver neck ruff & shadow fur under the wolf jaw. */
const ruffSvg = () => {
  const strokes = [];
  for (let i = 0; i < 60; i += 1) {
    const x = range(4, 124);
    const y = range(4, 124);
    const col = rand() < 0.5 ? "#5a606e" : "#98a0b0";
    strokes.push(
      `<path d="M${x.toFixed(1)} ${y.toFixed(1)} l${range(-2, 2).toFixed(1)} ${range(8, 18).toFixed(1)}" stroke="${col}" stroke-width="1.8" stroke-linecap="round" opacity="0.45"/>`,
    );
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
    <defs>
      <linearGradient id="ruffG" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#6b7280"/>
        <stop offset="0.6" stop-color="#8b93a4"/>
        <stop offset="1" stop-color="#cfd5e0"/>
      </linearGradient>
    </defs>
    <rect width="128" height="128" fill="url(#ruffG)"/>
    ${strokes.join("")}
  </svg>`;
};

/* Dark fur & shadowy inner ear / nose / claw dark slate-charcoal. */
const darkSvg = () => {
  const flecks = [];
  for (let i = 0; i < 40; i += 1) {
    const col = rand() < 0.5 ? "#181a20" : "#3d424f";
    flecks.push(
      `<ellipse cx="${range(0, 128).toFixed(1)}" cy="${range(0, 128).toFixed(1)}" rx="${range(3, 10).toFixed(1)}" ry="${range(4, 12).toFixed(1)}" fill="${col}" opacity="${range(0.25, 0.55).toFixed(2)}"/>`,
    );
  }
  return `
  <svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">
    <rect width="128" height="128" fill="#262932"/>
    ${flecks.join("")}
  </svg>`;
};

/* Dark charcoal martial trousers & wrist wraps with cloth fold shading. */
const clothSvg = () => {
  const folds = [];
  for (let i = 0; i < 36; i += 1) {
    const x = range(6, 122);
