const faceted = (geometry) => {
  const flat = geometry.index ? geometry.toNonIndexed() : geometry;
  flat.computeVertexNormals();
  return flat;
};

const defaultSection = (sides = 10) => {
  const pts = [];
  for (let k = 0; k < sides; k += 1) {
    const a = (k / sides) * Math.PI * 2;
    pts.push([Math.cos(a), Math.sin(a)]);
  }
  return pts;
};

/* Anatomical ring loft along a station table:
   each station is { p: [x, y, z], rx, rz }
   Instead of flat disk end-caps that shade dark at joints, `domeStart`/`domeEnd` add a rounded cap ring! */
const loft = (
  stations,
  section = defaultSection(10),
  { up = [0, 0, 1], domeStart = true, domeEnd = true, capStart = true, capEnd = true } = {},
) => {
  const full = [];
  if (domeStart && stations.length >= 2) {
    const s0 = stations[0];
    const s1 = stations[1];
    const d = new THREE.Vector3(s0.p[0] - s1.p[0], s0.p[1] - s1.p[1], s0.p[2] - s1.p[2]).normalize();
    const r = Math.min(s0.rx, s0.rz) * 0.38;
    full.push({
      p: [s0.p[0] + d.x * r, s0.p[1] + d.y * r, s0.p[2] + d.z * r],
      rx: s0.rx * 0.52,
      rz: s0.rz * 0.52,
    });
  }
  full.push(...stations);
  if (domeEnd && stations.length >= 2) {
    const sN = stations[stations.length - 1];
    const sP = stations[stations.length - 2];
    const d = new THREE.Vector3(sN.p[0] - sP.p[0], sN.p[1] - sP.p[1], sN.p[2] - sP.p[2]).normalize();
    const r = Math.min(sN.rx, sN.rz) * 0.38;
    full.push({
      p: [sN.p[0] + d.x * r, sN.p[1] + d.y * r, sN.p[2] + d.z * r],
      rx: sN.rx * 0.52,
      rz: sN.rz * 0.52,
    });
  }

  const n = section.length;
  const positions = [];
  const uvs = [];
  const indices = [];
  const upVec = new THREE.Vector3(...up).normalize();

  full.forEach((st, sIdx) => {
    const prev = full[Math.max(0, sIdx - 1)].p;
    const next = full[Math.min(full.length - 1, sIdx + 1)].p;
    const tangent = new THREE.Vector3(next[0] - prev[0], next[1] - prev[1], next[2] - prev[2]);
    if (tangent.lengthSq() < 1e-8) tangent.set(0, 1, 0);
    tangent.normalize();

    /* Build stable local frame: `right` is roughly +X, `forward` is roughly `upVec` */
    let hint = upVec;
    if (Math.abs(tangent.dot(hint)) > 0.92) {
      hint = Math.abs(tangent.y) > 0.9 ? new THREE.Vector3(0, 0, 1) : new THREE.Vector3(0, 1, 0);
    }
    const right = new THREE.Vector3().crossVectors(tangent, hint).normalize();
    const forward = new THREE.Vector3().crossVectors(right, tangent).normalize();

    const vCoord = sIdx / Math.max(1, full.length - 1);
    for (let k = 0; k < n; k += 1) {
      const [cx, cz] = section[k];
      const ox = cx * st.rx;
      const oz = cz * st.rz;
      const vx = st.p[0] + right.x * ox + forward.x * oz;
      const vy = st.p[1] + right.y * ox + forward.y * oz;
      const vz = st.p[2] + right.z * ox + forward.z * oz;
      positions.push(vx, vy, vz);
      uvs.push(k / n, vCoord);
    }
  });

  for (let s = 0; s < full.length - 1; s += 1) {
    for (let k = 0; k < n; k += 1) {
      const a = s * n + k;
      const b = s * n + ((k + 1) % n);
      const c = a + n;
      const d = b + n;
      indices.push(a, b, c, b, d, c);
    }
  }

  if (capStart) {
    const startCenter = positions.length / 3;
    const s0 = full[0];
    const s1 = full[1];
    const d = new THREE.Vector3(s0.p[0] - s1.p[0], s0.p[1] - s1.p[1], s0.p[2] - s1.p[2]).normalize();
    const tip = Math.min(s0.rx, s0.rz) * 0.22;
    positions.push(s0.p[0] + d.x * tip, s0.p[1] + d.y * tip, s0.p[2] + d.z * tip);
    uvs.push(0.5, 0);
    for (let k = 0; k < n; k += 1) {
      indices.push(startCenter, (k + 1) % n, k);
    }
  }

  if (capEnd) {
    const endCenter = positions.length / 3;
    const sN = full[full.length - 1];
    const sP = full[full.length - 2];
    const d = new THREE.Vector3(sN.p[0] - sP.p[0], sN.p[1] - sP.p[1], sN.p[2] - sP.p[2]).normalize();
    const tip = Math.min(sN.rx, sN.rz) * 0.22;
    positions.push(sN.p[0] + d.x * tip, sN.p[1] + d.y * tip, sN.p[2] + d.z * tip);
    uvs.push(0.5, 1);
    const base = (full.length - 1) * n;
    for (let k = 0; k < n; k += 1) {
      indices.push(endCenter, base + k, base + ((k + 1) % n));
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  return faceted(geo);
};

/* Create curved fur spike / mane lock along a 3-point arc. */
const spikeGeo = (base, mid, tip, rx, rz, sides = 6, up = [0, 1, 0]) =>
  loft(
    [
      { p: base, rx: rx * 0.72, rz: rz * 0.72 },
      { p: [base[0] * 0.65 + mid[0] * 0.35, base[1] * 0.65 + mid[1] * 0.35, base[2] * 0.65 + mid[2] * 0.35], rx, rz },
      { p: mid, rx: rx * 0.82, rz: rz * 0.82 },
      { p: [mid[0] * 0.45 + tip[0] * 0.55, mid[1] * 0.45 + tip[1] * 0.55, mid[2] * 0.45 + tip[2] * 0.55], rx: rx * 0.42, rz: rz * 0.42 },
      { p: tip, rx: 0.002, rz: 0.002 },
    ],
    defaultSection(sides),
    { up, domeStart: true, domeEnd: false },
  );

