211: const defaultSection = (sides = 10) => {
212:   const pts = [];
213:   for (let k = 0; k < sides; k += 1) {
214:     const a = (k / sides) * Math.PI * 2;
215:     pts.push([Math.cos(a), Math.sin(a)]);
216:   }
217:   return pts;
218: };
