220: /* Anatomical ring loft along a station table:
221:    each station is { p: [x, y, z], rx, rz }
222:    Instead of flat disk end-caps that shade dark at joints, `domeStart`/`domeEnd` add a rounded cap ring! */
223: const loft = (
224:   stations,
225:   section = defaultSection(10),
226:   { up = [0, 0, 1], domeStart = true, domeEnd = true, capStart = true, capEnd = true } = {},
227: ) => {
228:   const full = [];
229:   if (domeStart && stations.length >= 2) {
230:     const s0 = stations[0];
231:     const s1 = stations[1];
232:     const d = new THREE.Vector3(s0.p[0] - s1.p[0], s0.p[1] - s1.p[1], s0.p[2] - s1.p[2]).normalize();
233:     const r = Math.min(s0.rx, s0.rz) * 0.38;
234:     full.push({
235:       p: [s0.p[0] + d.x * r, s0.p[1] + d.y * r, s0.p[2] + d.z * r],
236:       rx: s0.rx * 0.52,
237:       rz: s0.rz * 0.52,
238:     });
239:   }
240:   full.push(...stations);
241:   if (domeEnd && stations.length >= 2) {
242:     const sN = stations[stations.length - 1];
243:     const sP = stations[stations.length - 2];
244:     const d = new THREE.Vector3(sN.p[0] - sP.p[0], sN.p[1] - sP.p[1], sN.p[2] - sP.p[2]).normalize();
245:     const r = Math.min(sN.rx, sN.rz) * 0.38;
246:     full.push({
247:       p: [sN.p[0] + d.x * r, sN.p[1] + d.y * r, sN.p[2] + d.z * r],
248:       rx: sN.rx * 0.52,
249:       rz: sN.rz * 0.52,
250:     });
251:   }
252: 
253:   const n = section.length;
254:   const positions = [];
255:   const uvs = [];
256:   const indices = [];
257:   const upVec = new THREE.Vector3(...up).normalize();
258: 
259:   full.forEach((st, sIdx) => {
260:     const prev = full[Math.max(0, sIdx - 1)].p;
261:     const next = full[Math.min(full.length - 1, sIdx + 1)].p;
262:     const tangent = new THREE.Vector3(next[0] - prev[0], next[1] - prev[1], next[2] - prev[2]);
263:     if (tangent.lengthSq() < 1e-8) tangent.set(0, 1, 0);
264:     tangent.normalize();
265: 
266:     /* Build stable local frame: `right` is roughly +X, `forward` is roughly `upVec` */
267:     let hint = upVec;
268:     if (Math.abs(tangent.dot(hint)) > 0.92) {
269:       hint = Math.abs(tangent.y) > 0.9 ? new THREE.Vector3(0, 0, 1) : new THREE.Vector3(0, 1, 0);
270:     }
271:     const right = new THREE.Vector3().crossVectors(tangent, hint).normalize();
272:     const forward = new THREE.Vector3().crossVectors(right, tangent).normalize();
273: 
274:     const vCoord = sIdx / Math.max(1, full.length - 1);
275:     for (let k = 0; k < n; k += 1) {
276:       const [cx, cz] = section[k];
277:       const ox = cx * st.rx;
278:       const oz = cz * st.rz;
279:       const vx = st.p[0] + right.x * ox + forward.x * oz;
280:       const vy = st.p[1] + right.y * ox + forward.y * oz;
281:       const vz = st.p[2] + right.z * ox + forward.z * oz;
282:       positions.push(vx, vy, vz);
283:       uvs.push(k / n, vCoord);
284:     }
285:   });
286: 
287:   for (let s = 0; s < full.length - 1; s += 1) {
288:     for (let k = 0; k < n; k += 1) {
289:       const a = s * n + k;
290:       const b = s * n + ((k + 1) % n);
291:       const c = a + n;
292:       const d = b + n;
293:       indices.push(a, b, c, b, d, c);
294:     }
295:   }
296: 
297:   if (capStart) {
298:     const startCenter = positions.length / 3;
299:     const s0 = full[0];
300:     const s1 = full[1];
301:     const d = new THREE.Vector3(s0.p[0] - s1.p[0], s0.p[1] - s1.p[1], s0.p[2] - s1.p[2]).normalize();
302:     const tip = Math.min(s0.rx, s0.rz) * 0.22;
303:     positions.push(s0.p[0] + d.x * tip, s0.p[1] + d.y * tip, s0.p[2] + d.z * tip);
304:     uvs.push(0.5, 0);
305:     for (let k = 0; k < n; k += 1) {
306:       indices.push(startCenter, (k + 1) % n, k);
307:     }
308:   }
309: 
310:   if (capEnd) {
311:     const endCenter = positions.length / 3;
312:     const sN = full[full.length - 1];
313:     const sP = full[full.length - 2];
314:     const d = new THREE.Vector3(sN.p[0] - sP.p[0], sN.p[1] - sP.p[1], sN.p[2] - sP.p[2]).normalize();
315:     const tip = Math.min(sN.rx, sN.rz) * 0.22;
316:     positions.push(sN.p[0] + d.x * tip, sN.p[1] + d.y * tip, sN.p[2] + d.z * tip);
317:     uvs.push(0.5, 1);
318:     const base = (full.length - 1) * n;
319:     for (let k = 0; k < n; k += 1) {
320:       indices.push(endCenter, base + k, base + ((k + 1) % n));
321:     }
322:   }
323: 
324:   const geo = new THREE.BufferGeometry();
325:   geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
326:   geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
327:   geo.setIndex(indices);
328:   return faceted(geo);
329: };
