377:     .setMaterial(material)
378:     .setAttribute("POSITION", document.createAccessor().setType("VEC3").setArray(new Float32Array(pos.array)).setBuffer(buffer))
379:     .setAttribute("NORMAL", document.createAccessor().setType("VEC3").setArray(new Float32Array(norm.array)).setBuffer(buffer));
380:   if (uv) {
381:     prim.setAttribute("TEXCOORD_0", document.createAccessor().setType("VEC2").setArray(new Float32Array(uv.array)).setBuffer(buffer));
382:   }
383:   if (geometry.index) {
384:     prim.setIndices(document.createAccessor().setType("SCALAR").setArray(new Uint32Array(geometry.index.array)).setBuffer(buffer));
385:   }
386:   const mesh = document.createMesh(name).addPrimitive(prim);
387:   const obj = new THREE.Object3D();
