389:   obj.rotation.set(...rotation);
390:   obj.scale.fromArray(scale);
391:   parent.addChild(
392:     document
393:       .createNode(name)
394:       .setMesh(mesh)
395:       .setTranslation(obj.position.toArray())
396:       .setRotation(obj.quaternion.toArray())
397:       .setScale(obj.scale.toArray()),
398:   );
