};

const spawnHitSparks = (at, color = PAL.yellow, count = 8) => {
  debris.slice(0, count).forEach((d, i) => {
    const a = (i / count) * Math.PI * 2 + Math.random() * 0.4;
    const spd = 2.2 + Math.random() * 2.6;
    d.mesh.position.set(at.x, at.y + 1.1, at.z);
    d.mesh.material = glow(color, 1.8);
    d.mesh.scale.setScalar(0.65);
    d.mesh.visible = true;
    d.v.set(Math.cos(a) * spd, 2.4 + Math.random() * 2.2, Math.sin(a) * spd);
    d.spin.set(Math.random() * 8, Math.random() * 8, Math.random() * 8);
    d.life = 0.36;
    d.size = 0.65;
  });
  fx.push((dt) => {
    let alive = false;
    debris.slice(0, count).forEach((d) => {
      if (d.life <= 0) return;
      d.life -= dt;
      if (d.life <= 0) {
        d.mesh.visible = false;
        return;
      }
      alive = true;
      d.v.y -= 12 * dt;
      d.mesh.position.addScaledVector(d.v, dt);
      d.mesh.rotation.x += d.spin.x * dt;
      d.mesh.rotation.y += d.spin.y * dt;
      d.mesh.scale.setScalar(Math.max(0.05, d.size * (d.life / 0.36)));
    });
    return alive;
  });
};

const triggerAttack = () => {
  if (introLive || combat.dodgeTimer > 0) return false;
  if (combat.timer > 0 && combat.timer > 0.14) return false;
  /* Auto-equip swords if Niko swings so combat works right away */
  swordPickup.debug(true);
  longswordPickup.debug(true);
  combat.combo = combat.chainWindow > 0 ? (combat.combo % 3) + 1 : 1;
  combat.duration = combat.combo === 3 ? 0.52 : 0.38;
  combat.timer = combat.duration;
  combat.chainWindow = 0.72;
  combat.didHit = false;

  /* Turn toward active combat target or nearest target in reach */
  const focus = lockTarget === dummy
    ? dummyFocus
    : lockTarget === bossGroup || robot.position.distanceTo(bossGroup.position) <= 5.2
      ? bossFocus
      : robot.position.distanceTo(dummy.position) <= 3.6
        ? dummyFocus
        : null;
  if (focus) {
    const dx = focus.x - robot.position.x;
    const dz = focus.z - robot.position.z;
    if (dx * dx + dz * dz > 0.001) {
      state.yaw = robot.rotation.y = Math.atan2(dx, dz);
    }
  }
  const lunge = combat.combo === 3 ? 0.55 : 0.28;
  const stepPos = robot.position.clone();
  stepPos.x += Math.sin(robot.rotation.y) * lunge;
  stepPos.z += Math.cos(robot.rotation.y) * lunge;
  resolveCollisions(stepPos);
  stepTo(robot.position, stepPos);
  robot.position.x = stepPos.x;
  robot.position.z = stepPos.z;
  slashArc.visible = true;
  slashArc.material.color.set(combat.combo === 3 ? PAL.red : combat.combo === 2 ? PAL.yellow : PAL.cream);
  slashArc.rotation.z = combat.combo === 2 ? Math.PI : 0;
  return true;
};

const triggerDodge = () => {
  if (introLive || combat.dodgeTimer > 0 || combat.dodgeCooldown > 0) return false;
  combat.dodgeTimer = 0.28;
  combat.dodgeCooldown = 0.55;
  combat.timer = 0;
  const move = inputVector();
  if (move.lengthSq() > 0.01) {
    combat.dodgeDir.copy(move).normalize();
  } else {
    combat.dodgeDir.set(-Math.sin(robot.rotation.y), 0, -Math.cos(robot.rotation.y));
  }
  state.hop = 0.15;
  return true;
};

const damageBoss = (amount, knock = 0.35) => {
  if (boss.state === "defeated") return false;
  boss.hp = Math.max(0, boss.hp - amount);
  boss.hitFlash = 0.22;
  shake = Math.max(shake, 0.18);
  spawnHitSparks(bossGroup.position, PAL.yellow, 9);
  const awayX = bossGroup.position.x - robot.position.x;
  const awayZ = bossGroup.position.z - robot.position.z;
  const dist = Math.hypot(awayX, awayZ) || 1;
  const nextX = bossGroup.position.x + (awayX / dist) * knock;
  const nextZ = bossGroup.position.z + (awayZ / dist) * knock;
  if (island.nav.walkable(nextX, nextZ)) {
    bossGroup.position.x = nextX;
    bossGroup.position.z = nextZ;
  }
  if (boss.hp <= 0) {
    boss.state = "defeated";
    boss.timer = 4.0;
    bossTelegraph.visible = false;
  } else if (boss.state !== "windup" || combat.combo === 3) {
    boss.state = "stagger";
    boss.timer = 0.36;
    bossTelegraph.visible = false;
  }
  return true;
};

let lockTarget = null;

