  robot.position.addScaledVector(combat.dodgeDir, 10.5 * dt);
  resolveCollisions(robot.position);
  stepTo(prevDodge, robot.position);
  robot.position.y = island.groundAt(robot.position.x, robot.position.z);
}
if (combat.knockVel.lengthSq() > 0.01) {
  const prevKnock = robot.position.clone();
  robot.position.addScaledVector(combat.knockVel, dt);
  resolveCollisions(robot.position);
  stepTo(prevKnock, robot.position);
  robot.position.y = island.groundAt(robot.position.x, robot.position.z);
  combat.knockVel.multiplyScalar(Math.exp(-10 * dt));
}

