  combat.timer = Math.max(0, combat.timer - dt);
  const u = 1 - combat.timer / combat.duration;
  const swingCurve = Math.sin(u * Math.PI);
  slashArc.visible = true;
  slashArc.material.opacity = swingCurve * 0.85;
  slashArc.scale.setScalar(0.85 + u * 0.45);
  slashArc.rotation.z = (combat.combo === 2 ? -1 : 1) * (-1.2 + u * 2.4);

  if (bot.bones && bot.model) {
    bot.model.updateWorldMatrix(true, false);
    const e = bot.model.matrixWorld.elements;
    faceRight.set(e[8], e[9], e[10]).normalize();
    const rotWorld = (bone, axis, radians) => {
      const parent = bone?.parent;
      if (!parent) return;
      bone.updateWorldMatrix(true, false);
      const world = bone.getWorldQuaternion(posedQ);
      keyA.setFromAxisAngle(axis, radians);
      world.premultiply(keyA);
      parent.getWorldQuaternion(keyB);
      bone.quaternion.copy(keyB.invert()).multiply(world);
    };
    if (combat.combo === 1) {
      rotWorld(bot.bones.Spine2, worldUp, (u - 0.35) * 0.85);
      rotWorld(bot.bones.RightArm, faceRight, -1.25 * swingCurve);
      rotWorld(bot.bones.RightArm, worldUp, (u - 0.4) * 1.6);
      rotWorld(bot.bones.RightForeArm, faceRight, -0.55 * swingCurve);
    } else if (combat.combo === 2) {
      rotWorld(bot.bones.Spine2, worldUp, -(u - 0.35) * 0.9);
      rotWorld(bot.bones.LeftArm, faceRight, -1.3 * swingCurve);
      rotWorld(bot.bones.LeftArm, worldUp, -(u - 0.4) * 1.6);
      rotWorld(bot.bones.LeftForeArm, faceRight, -0.6 * swingCurve);
    } else {
      rotWorld(bot.bones.Spine2, faceRight, 0.35 * swingCurve);
      rotWorld(bot.bones.Spine2, worldUp, Math.sin(u * Math.PI * 2) * 0.95);
      rotWorld(bot.bones.RightArm, faceRight, -1.45 * swingCurve);
      rotWorld(bot.bones.LeftArm, faceRight, -1.45 * swingCurve);
    }
  }

  if (!combat.didHit && u >= 0.28 && u <= 0.72) {
    const toBossX = bossGroup.position.x - robot.position.x;
    const toBossZ = bossGroup.position.z - robot.position.z;
    const bossDist = Math.hypot(toBossX, toBossZ);
    const fwdX = Math.sin(robot.rotation.y);
    const fwdZ = Math.cos(robot.rotation.y);
    const dotBoss = bossDist > 0.001 ? (toBossX * fwdX + toBossZ * fwdZ) / bossDist : 1;
    if (bossDist <= 3.15 && dotBoss > 0.15 && boss.state !== "defeated") {
      combat.didHit = true;
      const dmg = combat.combo === 3 ? 45 : combat.combo === 2 ? 30 : 25;
      damageBoss(dmg, combat.combo === 3 ? 0.55 : 0.28);
    } else {
      const toDummyX = dummy.position.x - robot.position.x;
      const toDummyZ = dummy.position.z - robot.position.z;
      const dummyDist = Math.hypot(toDummyX, toDummyZ);
      if (dummyDist <= 2.6) {
        combat.didHit = true;
        spawnHitSparks(dummy.position, PAL.cream, 6);
