import puppeteer from "puppeteer-core";

/* node boss-check.mjs [base] [prefix] -> ../review/<prefix>-{spawn,lockon,slash,telegraph}.png */
const base = process.argv[2] || "http://127.0.0.1:8765/";
const prefix = process.argv[3] || "boss";
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await puppeteer.launch({
  executablePath: "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
  headless: true,
  protocolTimeout: 120000,
  args: ["--ignore-gpu-blocklist"],
});
const page = await browser.newPage();
page.on("pageerror", (error) => console.log("pageerror", error.message));
page.on("console", (msg) => /boss|werewolf|failed|error/i.test(msg.text()) && console.log("console", msg.text()));
await page.setViewport({ width: 1200, height: 800 });
await page.goto(`${base}?view=world&t=${Date.now()}`, { waitUntil: "domcontentloaded" });
for (let i = 0; i < 400 && !(await page.evaluate(() => document.documentElement.classList.contains("world-ready"))); i += 1) await wait(50);
await page.evaluate(() => void window.PortfolioWorld.debug.finishIntro());
await page.addStyleTag({ content: ".hud, .world-help, .world-labels { display: none !important; }" });
await wait(2200);

const d = (fn, ...args) => page.evaluate(fn, ...args);
console.log("initial", JSON.stringify(await d(() => window.PortfolioWorld.debug.boss())));
await page.screenshot({ path: `../review/${prefix}-spawn.png` });

/* Engage & lock onto the Werewolf Boss */
await d(() => {
  window.PortfolioWorld.debug.sword(true);
  window.PortfolioWorld.debug.longsword(true);
  window.PortfolioWorld.debug.boss({ engage: true });
  window.PortfolioWorld.debug.zoom(1.65);
});
await wait(900);
console.log("locked", JSON.stringify(await d(() => window.PortfolioWorld.debug.boss())));
await page.screenshot({ path: `../review/${prefix}-lockon.png` });

/* Trigger player sword slash combo and capture mid-swing */
await d(() => window.PortfolioWorld.debug.attack());
await wait(160);
await page.screenshot({ path: `../review/${prefix}-slash1.png` });
await wait(260);
await d(() => window.PortfolioWorld.debug.attack());
await wait(160);
await page.screenshot({ path: `../review/${prefix}-slash2.png` });
await wait(280);
console.log("after-combo", JSON.stringify(await d(() => window.PortfolioWorld.debug.boss())));

/* Trigger boss windup telegraph & attack */
await d(() => window.PortfolioWorld.debug.boss({ windup: "slam" }));
await wait(350);
console.log("windup", JSON.stringify(await d(() => window.PortfolioWorld.debug.boss())));
await page.screenshot({ path: `../review/${prefix}-telegraph.png` });
await wait(450);
console.log("attack", JSON.stringify(await d(() => window.PortfolioWorld.debug.boss())));
await page.screenshot({ path: `../review/${prefix}-attack.png` });

await browser.close();

