1: #ifndef PIXELPASS_SMEAR_INCLUDED
2: #define PIXELPASS_SMEAR_INCLUDED
3: 
4: // Motion smear.
5: //
6: // PixelPassSmearEffect feeds this the renderer's current world position and its position from a
7: // few frames ago. Vertices that trail the direction of travel get stretched back toward where the
8: // object used to be, which reads as a hand-drawn streak. The leading face is left untouched so
9: // the silhouette stays readable once the frame is pixelated.
10: //
11: // Constants are declared by PIXELPASS_VERTEX_EFFECT_PROPERTIES inside UnityPerMaterial.
12: 
13: float PixelPassSmearHash(float n)
14: {
15:     return frac(sin(n) * 43758.5453);
16: }
17: 
18: float PixelPassSmearNoise(float3 x)
19: {
20:     float3 p = floor(x);
21:     float3 f = frac(x);
22:     f = f * f * (3.0 - 2.0 * f);
23: 
24:     float n = p.x + p.y * 57.0 + 113.0 * p.z;
25: 
26:     return lerp(
27:         lerp(lerp(PixelPassSmearHash(n + 0.0), PixelPassSmearHash(n + 1.0), f.x),
28:              lerp(PixelPassSmearHash(n + 57.0), PixelPassSmearHash(n + 58.0), f.x), f.y),
29:         lerp(lerp(PixelPassSmearHash(n + 113.0), PixelPassSmearHash(n + 114.0), f.x),
30:              lerp(PixelPassSmearHash(n + 170.0), PixelPassSmearHash(n + 171.0), f.x), f.y),
31:         f.z);
32: }
33: 
34: float3 PixelPassApplySmear(float3 positionOS)
35: {
36:     float3 travelWS = _SmearCurrentPositionWS.xyz - _SmearPreviousPositionWS.xyz;
37:     float travelDistance = length(travelWS);
38: 
39:     if (_SmearStrength <= 0.0 || travelDistance < 1e-5)
40:         return positionOS;
41: 
42:     float3 positionWS = TransformObjectToWorld(positionOS);
43:     float3 fromPivot = positionWS - _SmearCurrentPositionWS.xyz;
44: 
45:     // SafeNormalize keeps vertices sitting exactly on the pivot from producing a NaN direction.
46:     float trailing = saturate(-dot(travelWS / travelDistance, SafeNormalize(fromPivot)));
47: 
48:     float noise = _SmearNoiseScale > 1e-4
49:         ? PixelPassSmearNoise(positionWS * _SmearNoiseScale)
50:         : 1.0;
51: 
52:     // Clamped per axis rather than by magnitude, matching how the streak length is authored.
53:     float3 clampedTravel = clamp(travelWS, -_SmearMaxDistance.xxx, _SmearMaxDistance.xxx);
54:     float3 smearWS = -clampedTravel * trailing * noise * _SmearStrength;
55: 
56:     return TransformWorldToObject(positionWS + smearWS);
57: }
58: 
59: #endif

