226:         private void Tick(float deltaTime)
227:         {
228:             if (m_SetupIsInvalid || m_TargetRenderers.Count == 0)
229:                 return;
230: 
231:             Vector3 currentPosition = GetTrackedPosition();
232: 
233:             if (m_RecentPositions.Count == 0)
234:                 ResetHistory(currentPosition);
235: 
236:             float sampleTime = Application.isPlaying ? Time.time : Time.unscaledTime;
237:             m_RecentPositions.Enqueue(new SmearSample(currentPosition, sampleTime));
238:             while (m_RecentPositions.Count > m_FrameLag + 1)
239:                 m_RecentPositions.Dequeue();
240: 
241:             SmearSample oldestSample = m_RecentPositions.Peek();
242:             Vector3 rawTravel = currentPosition - oldestSample.position;
243:             float sampleDuration = Mathf.Max(sampleTime - oldestSample.time, 0.0001f);
244:             float travelSpeed = rawTravel.magnitude / sampleDuration;
245:             float speedFactor = Mathf.InverseLerp(m_MinSpeedForSmear, Mathf.Max(m_MinSpeedForSmear + 0.0001f, m_SpeedForMaxSmear), travelSpeed);
246:             Vector3 targetOffset = Vector3.ClampMagnitude(rawTravel * speedFactor, m_MaxSmearDistance);
247: 
248:             if (!m_EffectEnabled || m_SmearStrength <= 0.0f)
249:             {
250:                 targetOffset = Vector3.zero;
251:                 speedFactor = 0f;
252:                 ResetHistory(currentPosition);
253:             }
254: 
255:             bool shouldSnapToTarget = travelSpeed >= m_InstantResponseSpeed;
256:             if (shouldSnapToTarget)
257:             {
258:                 m_CurrentSmearOffset = targetOffset;
259:             }
260:             else
261:             {
262:                 // Growing into a smear is snappier than releasing out of one, which reads better than
263:                 // a symmetric blend when the character stops abruptly.
264:                 float sharpness = targetOffset.sqrMagnitude > m_CurrentSmearOffset.sqrMagnitude
265:                     ? m_FollowSharpness
266:                     : m_ReleaseSharpness;
267: 
268:                 float blend = 1.0f - Mathf.Exp(-sharpness * Mathf.Max(deltaTime, 0.0001f));
269:                 m_CurrentSmearOffset = Vector3.Lerp(m_CurrentSmearOffset, targetOffset, blend);
270:             }
271: 
272:             float threshold = m_StationaryThreshold * m_StationaryThreshold;
273:             if (targetOffset.sqrMagnitude <= threshold && m_CurrentSmearOffset.sqrMagnitude <= threshold)
274:             {
275:                 m_CurrentSmearOffset = Vector3.zero;
276:                 speedFactor = 0f;
277:             }
278: 
279:             m_CurrentSpeedFactor = speedFactor;
280: 
281:             PublishSmear(m_CurrentSmearOffset);
282:         }
283: 
284:         private void PublishSmear(Vector3 smearOffset)
285:         {
286:             if (m_TargetRenderers.Count == 0)
287:                 return;
288: 
289:             Vector3 currentPosition = GetTrackedPosition();
290:             Vector3 previousPosition = currentPosition - smearOffset;
291:             float strength = m_EffectEnabled ? m_SmearStrength * m_CurrentSpeedFactor : 0.0f;
292: 
293:             if (m_PropertyBlock == null)
294:                 m_PropertyBlock = new MaterialPropertyBlock();
295: 
296:             MaterialPropertyBlock block = m_PropertyBlock;
297: 
298:             for (int index = 0; index < m_TargetRenderers.Count; ++index)
299:             {
300:                 Renderer target = m_TargetRenderers[index];
301:                 if (target == null)
302:                     continue;
303: 
304:                 // Read back first so we do not wipe overrides another system put on this renderer.
305:                 target.GetPropertyBlock(block);
306:                 block.SetVector(SmearCurrentPositionId, currentPosition);
307:                 block.SetVector(SmearPreviousPositionId, previousPosition);
308:                 block.SetFloat(SmearStrengthId, strength);
309:                 block.SetFloat(SmearMaxDistanceId, m_MaxSmearDistance);
310:                 block.SetFloat(SmearNoiseScaleId, m_NoiseScale);
311:                 target.SetPropertyBlock(block);
312:             }
313:         }
314: 
315:         private void CacheRenderers()
316:         {
317:             m_TargetRenderers.Clear();
318: 
319:             Transform searchRoot = m_TargetRoot != null ? m_TargetRoot : transform;
320: 
321:             Renderer[] candidates = m_IncludeChildren
322:                 ? searchRoot.GetComponentsInChildren<Renderer>(true)
323:                 : searchRoot.GetComponents<Renderer>();
324: 
325:             int disabledRendererCount = 0;
326:             int unsupportedMaterialCount = 0;
327: 
328:             foreach (Renderer candidate in candidates)
329:             {
330:                 if (candidate == null)
331:                     continue;
332: 
333:                 // Ignore non-rendering entries so a disabled debug mesh on the mover root
334:                 // does not silently become the only smear target.
335:                 if (!candidate.enabled || !candidate.gameObject.activeInHierarchy)
336:                 {
337:                     disabledRendererCount++;
338:                     continue;
339:                 }
340: 
341:                 if (HasSmearProperties(candidate))
342:                 {
343:                     m_TargetRenderers.Add(candidate);
344:                 }
345:                 else
346:                 {
347:                     unsupportedMaterialCount++;
348:                 }
349:             }
350: 
351:             if (m_TargetRenderers.Count == 0)
352:             {
353:                 m_SetupIsInvalid = true;
354:                 Debug.LogWarning(
355:                     "PixelPassSmearEffect found no renderer using a PixelPass lit shader. Put this on the object that moves, " +
356:                     "assign Target Root to the visible model if needed, turn on Include Children, and give the visible mesh a material using " +
357:                     "PixelPass/Cel Character Lit or PixelPass/Stylized Toon Lit. " +
358:                     $"Scanned: {candidates.Length}, disabled: {disabledRendererCount}, unsupported material: {unsupportedMaterialCount}.",
359:                     this);
360:             }
361:         }
362: 
363:         private static bool HasSmearProperties(Renderer target)
364:         {
365:             Material[] materials = target.sharedMaterials;
366: 
367:             foreach (Material material in materials)
368:             {
369:                 if (material != null && material.HasProperty(SmearStrengthId))
370:                     return true;
371:             }
372: 
373:             return false;
374:         }
375: 
376:         private void ResetHistory(Vector3 position)
377:         {
378:             m_RecentPositions.Clear();
379:             float sampleTime = Application.isPlaying ? Time.time : Time.unscaledTime;
380:             for (int index = 0; index <= m_FrameLag; ++index)
381:                 m_RecentPositions.Enqueue(new SmearSample(position, sampleTime));
382:         }
383: 
384:         private Vector3 GetTrackedPosition()
385:         {
386:             Transform trackedTransform = m_TargetRoot != null ? m_TargetRoot : transform;
387: 
388:             if (m_UsePivotPosition || m_TargetRenderers.Count == 0)
389:                 return trackedTransform.position;
390: 
391:             Bounds bounds = m_TargetRenderers[0].bounds;
392:             for (int index = 1; index < m_TargetRenderers.Count; ++index)
393:                 bounds.Encapsulate(m_TargetRenderers[index].bounds);
394: 
395:             return bounds.center;
396:         }
397:     }
398: }

