import * as THREE from "three";

/* Reusable Smear Frame + Sub-Frame Motion Blur Handler.
   Combines:
   1. Unreal Engine SmearFrame (LuggLD/SmearFrame, UE forum 67822):
      - World-space vertex normal dot product with -smearDirection + SmearNormalAngleBias
      - WPT_ExcludeAllShaderOffsets multi-octave 3D Fast Gradient Noise for fine brush/fur streaks
   2. Pixel_Pass (PixelPassSmear.hlsl & PixelPassSmearEffect.cs):
      - Frame-lagged position queue, speed threshold ramp, per-axis travel clamp, and asymmetric
        followSharpness / releaseSharpness damping
   3. Sub-Frame Limb Motion Blur:
      - Softened directional motion-blur shading & feathered tail tips on the primary arm mesh
      - 4 translucent sub-frame ghost shells of the moving arm hierarchy posed across sub-frame
        timestamps along the swing arc so the moving part of the mesh has genuine motion blur. */

const SMEAR_COMMON_GLSL = [
  "uniform vec3 uSmearCurrentWS;",
  "uniform vec3 uSmearPreviousWS;",
  "uniform vec3 uSmearShoulderWS;",
  "uniform vec3 uSmearArmAxisWS;",
  "uniform vec3 uSmearOutwardWS;",
  "uniform float uSmearArmLen;",
  "uniform float uSmearStrength;",
  "uniform float uSmearMaxDistance;",
  "uniform float uSmearNoiseScale;",
  "uniform float uSmearNormalBias;",
  "uniform float uSmearStylize;",
  "float smearHash(vec3 p) {",
  "  p = fract(p * vec3(0.1031, 0.1030, 0.0973));",
  "  p += dot(p, p.yxz + 33.33);",
  "  return fract((p.x + p.y) * p.z);",
  "}",
  "/* Smooth 3D Fast Gradient / Value Noise (UE4 NOISEFUNCTION_FastGradient equivalent) */",
  "float smearGradientNoise(vec3 x) {",
  "  vec3 p = floor(x);",
  "  vec3 f = fract(x);",
  "  f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);",
  "  return mix(",
  "    mix(mix(smearHash(p + vec3(0,0,0)), smearHash(p + vec3(1,0,0)), f.x),",
  "        mix(smearHash(p + vec3(0,1,0)), smearHash(p + vec3(1,1,0)), f.x), f.y),",
  "    mix(mix(smearHash(p + vec3(0,0,1)), smearHash(p + vec3(1,0,1)), f.x),",
  "        mix(smearHash(p + vec3(0,1,1)), smearHash(p + vec3(1,1,1)), f.x), f.y),",
  "    f.z",
  "  );",
  "}",
  "float smearFbm(vec3 p) {",
  "  float v = 0.58 * smearGradientNoise(p);",
  "  v += 0.28 * smearGradientNoise(p * 2.15 + vec3(17.3, 9.1, 5.7));",
  "  v += 0.14 * smearGradientNoise(p * 4.4 + vec3(3.7, 29.3, 13.1));",
  "  return v;",
  "}",
].join("\n");

const SMEAR_VERTEX_BODY_GLSL = [
  "#include <begin_vertex>",
  "float smearAmtVal = 0.0;",
  "float smearFiberVal = 0.5;",
  "float smearArmVal = 0.0;",
  "{",
  "  vec3 travelWS = uSmearCurrentWS - uSmearPreviousWS;",
  "  float travelDist = length(travelWS);",
  "  if (uSmearStrength > 0.0001 && travelDist > 0.0001) {",
  "    /* WPT_ExcludeAllShaderOffsets: pre-offset world position & smooth VertexNormalWS */",
  "    vec3 posWS = (modelMatrix * vec4(transformed, 1.0)).xyz;",
  "    vec3 worldNorm = normalize(mat3(modelMatrix) * normal);",
  "    vec3 smearDir = travelWS / travelDist;",
  "    float armProj = clamp(dot(posWS - uSmearShoulderWS, uSmearArmAxisWS) / max(0.2, uSmearArmLen), 0.0, 1.25);",
  "    float armSpan = smoothstep(0.04, 0.48, armProj);",
  "    /* UE4 SmearFrame normal angle bias: dot(VertexNormalWS, -smearDir) + bias */",
  "    float normalDot = dot(worldNorm, -smearDir);",
  "    float normalMask = clamp((normalDot + uSmearNormalBias) / (1.0 + uSmearNormalBias), 0.0, 1.0);",
  "    normalMask = smoothstep(0.0, 0.92, normalMask);",
  "    /* Compress noise coordinate along smearDir so streaks form fine longitudinal brush fibers */",
  "    vec3 crossPos = posWS - smearDir * dot(posWS - uSmearShoulderWS, smearDir) * 0.86;",
  "    float fiberNoise = uSmearNoiseScale > 0.0001 ? smearFbm(crossPos * uSmearNoiseScale) : 1.0;",
  "    float fineStreak = smoothstep(0.14, 0.88, fiberNoise);",
  "    float streakProfile = mix(0.32, 1.42, fineStreak * fineStreak);",
  "    float w = normalMask * armSpan * streakProfile * uSmearStrength;",
  "    vec3 clampedTravel = clamp(travelWS, -vec3(uSmearMaxDistance), vec3(uSmearMaxDistance));",
  "    /* Gentle outward swing-arc bow so the smeared arm follows the curved punch trajectory */",
  "    vec3 arcBow = uSmearOutwardWS * (sin(clamp(w * 0.78, 0.0, 1.0) * 3.14159265) * 0.26 * armSpan * min(1.0, travelDist));",
  "    vec3 smearWS = -clampedTravel * w + arcBow;",
  "    float scaleSq = max(0.0001, dot(modelMatrix[0].xyz, modelMatrix[0].xyz));",
  "    transformed += (transpose(mat3(modelMatrix)) * smearWS) / scaleSq;",
  "    smearAmtVal = clamp(w, 0.0, 1.0);",
  "    smearFiberVal = fineStreak;",
  "    smearArmVal = armProj;",
  "  }",
  "}",
].join("\n");

export function createSmearHandler(options = {}) {
  const config = {
    frameLag: options.frameLag ?? 4,
    smearStrength: options.smearStrength ?? 1.22,
    maxSmearDistance: options.maxSmearDistance ?? 1.65,
    noiseScale: options.noiseScale ?? 9.5,
    normalBias: options.normalBias ?? 0.34,
    followSharpness: options.followSharpness ?? 28,
    releaseSharpness: options.releaseSharpness ?? 14,
    minSpeedForSmear: options.minSpeedForSmear ?? 1.1,
    speedForMaxSmear: options.speedForMaxSmear ?? 11.0,
    instantResponseSpeed: options.instantResponseSpeed ?? 18.0,
    ghostCount: options.ghostCount ?? 4,
  };

  const uniforms = {
    uSmearCurrentWS: { value: new THREE.Vector3() },
    uSmearPreviousWS: { value: new THREE.Vector3() },
    uSmearShoulderWS: { value: new THREE.Vector3() },
    uSmearArmAxisWS: { value: new THREE.Vector3(0, -1, 0) },
    uSmearOutwardWS: { value: new THREE.Vector3(0, 0, 1) },
    uSmearArmLen: { value: 1.1 },
    uSmearStrength: { value: 0 },
    uSmearMaxDistance: { value: config.maxSmearDistance },
    uSmearNoiseScale: { value: config.noiseScale },
    uSmearNormalBias: { value: config.normalBias },
    uSmearStylize: { value: 0 },
  };

  const depthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
  depthMaterial.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace("#include <common>", `#include <common>\n${SMEAR_COMMON_GLSL}`)
      .replace("#include <begin_vertex>", SMEAR_VERTEX_BODY_GLSL);
  };
  depthMaterial.customProgramCacheKey = () => "ue-pixelpass-smear-depth";

  /* Wrap a lit toon material with the UE4 SmearFrame WPO + directional motion-blur shading */
  const enhanceMaterial = (material) => {
    material.transparent = true;
    const prev = material.onBeforeCompile;
    const baseKey = material.customProgramCacheKey?.() || "soft-map";
    material.onBeforeCompile = (shader, renderer) => {
      prev?.(shader, renderer);
      Object.assign(shader.uniforms, uniforms);
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <common>",
          `#include <common>\n${SMEAR_COMMON_GLSL}\nvarying float vSmearAmt;\nvarying float vSmearFiber;\nvarying float vSmearArm;\nvarying vec3 vSmearNormalWS;`,
        )
        .replace(
          "#include <begin_vertex>",
          `${SMEAR_VERTEX_BODY_GLSL}\nvSmearAmt = smearAmtVal;\nvSmearFiber = smearFiberVal;\nvSmearArm = smearArmVal;\nvSmearNormalWS = normalize(mat3(modelMatrix) * normal);`,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          "#include <common>",
          "#include <common>\nuniform float uSmearStylize;\nvarying float vSmearAmt;\nvarying float vSmearFiber;\nvarying float vSmearArm;\nvarying vec3 vSmearNormalWS;",
        )
        .replace(
          "#include <opaque_fragment>",
          [
            "float smearAlpha = 1.0;",
            "if (vSmearAmt > 0.01) {",
            "  /* 1. Motion-blur lighting softener: smooth out hard cel steps on the fast-moving smeared mesh */",
            "  float blurBlend = smoothstep(0.03, 0.42, vSmearAmt);",
            "  float softTopLight = 0.58 + 0.42 * clamp(vSmearNormalWS.y * 0.65 + 0.35, 0.0, 1.0);",
            "  vec3 blurredBase = diffuseColor.rgb * mix(vec3(0.76, 0.80, 0.88), vec3(1.14, 1.12, 1.10), softTopLight);",
            "  outgoingLight = mix(outgoingLight, mix(outgoingLight, blurredBase, 0.65), blurBlend);",
            "  /* 2. Stylistic brush-streak grading blended softly into the blurred arm fur/bracer */",
            "  float sty = clamp(vSmearAmt * max(0.35, uSmearStylize), 0.0, 1.0);",
            "  vec3 crimsonBlur = vec3(1.18, 0.22, 0.18);",
            "  vec3 warmWhiteBlur = vec3(1.48, 1.32, 1.08);",
            "  vec3 darkShadowStreak = blurredBase * vec3(0.28, 0.24, 0.32);",
            "  vec3 streakTint = mix(blurredBase, crimsonBlur, smoothstep(0.20, 0.72, vSmearArm) * 0.55);",
            "  streakTint = mix(streakTint, warmWhiteBlur, smoothstep(0.52, 0.92, vSmearFiber) * smoothstep(0.12, 0.58, sty) * 0.72);",
            "  streakTint = mix(streakTint, darkShadowStreak, (1.0 - smoothstep(0.18, 0.52, vSmearFiber)) * smoothstep(0.25, 0.80, sty) * 0.75);",
            "  outgoingLight = mix(outgoingLight, streakTint, smoothstep(0.06, 0.48, sty) * 0.86);",
            "  /* 3. Feathered motion-blur fade at the stretched streak tips (like UE4 SmearFrame GIFs) */",
            "  float tipFade = 1.0 - smoothstep(0.42, 0.98, vSmearAmt * (1.18 - vSmearFiber * 0.38));",
            "  smearAlpha = clamp(mix(1.0, tipFade, smoothstep(0.15, 0.45, vSmearAmt)), 0.08, 1.0);",
            "}",
            "#include <opaque_fragment>",
            "gl_FragColor.a *= smearAlpha;",
          ].join("\n"),
        );
    };
    material.customProgramCacheKey = () => `${baseKey}-ue-smear-blur`;
    return material;
  };

  /* Build a translucent motion-blur material for sub-frame ghost shells of the moving arm */
  const makeGhostMaterial = (sourceMat, ghostIndex, totalGhosts) => {
    const frac = (ghostIndex + 1) / (totalGhosts + 1);
    const ghostUniforms = {
      ...uniforms,
      uGhostAlpha: { value: 0 },
      uGhostFrac: { value: frac },
    };
    const mat = new THREE.MeshBasicMaterial({
      map: sourceMat?.map || null,
      color: sourceMat?.color ? sourceMat.color.clone() : new THREE.Color("#ffffff"),
      transparent: true,
      depthWrite: false,
      opacity: 1,
    });
    mat.onBeforeCompile = (shader) => {
      Object.assign(shader.uniforms, ghostUniforms);
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <common>",
          `#include <common>\n${SMEAR_COMMON_GLSL}\nuniform float uGhostFrac;\nvarying float vSmearAmt;\nvarying float vSmearFiber;\nvarying float vSmearArm;\nvarying vec3 vGhostNormWS;`,
        )
        .replace(
          "#include <begin_vertex>",
          `${SMEAR_VERTEX_BODY_GLSL}\n/* Subtle normal inflation + motion blur spread across sub-frames */\ntransformed += normal * (0.004 * uGhostFrac);\nvSmearAmt = smearAmtVal;\nvSmearFiber = smearFiberVal;\nvSmearArm = smearArmVal;\nvGhostNormWS = normalize(mat3(modelMatrix) * normal);`,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          "#include <common>",
          "#include <common>\nuniform float uGhostAlpha;\nuniform float uGhostFrac;\nvarying float vSmearAmt;\nvarying float vSmearFiber;\nvarying float vSmearArm;\nvarying vec3 vGhostNormWS;",
        )
        .replace(
          "#include <opaque_fragment>",
          [
            "float shade = 0.62 + 0.38 * clamp(vGhostNormWS.y * 0.6 + 0.4, 0.0, 1.0);",
            "vec3 blurCol = outgoingLight * shade;",
            "vec3 energyTint = mix(vec3(1.12, 0.28, 0.22), vec3(1.45, 1.28, 1.02), smoothstep(0.4, 0.85, vSmearFiber));",
            "blurCol = mix(blurCol, energyTint, smoothstep(0.25, 0.85, vSmearArm) * (0.28 + 0.25 * uGhostFrac));",
            "float feather = (1.0 - smoothstep(0.55, 1.0, vSmearAmt)) * smoothstep(0.02, 0.28, vSmearArm);",
            "outgoingLight = blurCol;",
            "#include <opaque_fragment>",
            "gl_FragColor.a = uGhostAlpha * feather;",
          ].join("\n"),
        );
    };
    mat.customProgramCacheKey = () => `smear-ghost-${ghostIndex}`;
    mat.userData.ghostUniforms = ghostUniforms;
    return mat;
  };

  /* Create sub-frame motion-blur ghost shells for a limb hierarchy (e.g., RightArm + RightForeArm) */
  const ghostShells = [];
  const bindLimbGhostBlur = (torsoNode, rightArmNode, rightForeArmNode) => {
    ghostShells.length = 0;
    if (!torsoNode || !rightArmNode || !rightForeArmNode) return;
    for (let g = 0; g < config.ghostCount; g += 1) {
      const ghostArm = new THREE.Group();
      ghostArm.name = `RightArmBlurGhost_${g}`;
      ghostArm.position.copy(rightArmNode.position);
      ghostArm.visible = false;

      const ghostFore = new THREE.Group();
      ghostFore.name = `RightForeArmBlurGhost_${g}`;
      ghostFore.position.copy(rightForeArmNode.position);
      ghostArm.add(ghostFore);

      const ghostMats = [];
      const cloneMeshesInto = (srcParent, dstParent) => {
        srcParent.children.forEach((child) => {
          if (child.isMesh) {
            const gMat = makeGhostMaterial(child.material, g, config.ghostCount);
            ghostMats.push(gMat);
            const m = new THREE.Mesh(child.geometry, gMat);
            m.position.copy(child.position);
            m.quaternion.copy(child.quaternion);
            m.scale.copy(child.scale);
            m.castShadow = false;
            m.receiveShadow = false;
            m.frustumCulled = false;
            m.renderOrder = 2;
            dstParent.add(m);
          }
        });
      };
      cloneMeshesInto(rightArmNode, ghostArm);
      cloneMeshesInto(rightForeArmNode, ghostFore);
      torsoNode.add(ghostArm);
      ghostShells.push({ arm: ghostArm, fore: ghostFore, mats: ghostMats, index: g });
    }
  };

  /* Runtime state for PixelPassSmearEffect velocity tracking */
  const state = {
    samples: [],
    currentOffset: new THREE.Vector3(),
    speedFactor: 0,
  };
  const tmpRawTravel = new THREE.Vector3();
  const tmpTargetOffset = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const tmpArmVec = new THREE.Vector3();

  const update = ({
    dt,
    time,
    shoulderWS,
    elbowWS,
    fistWS,
    torsoCenterWS,
    analyticLagFistWS = null,
    whipEnvelope = 0,
    lockedTime = null,
    sampleSubframePose = null,
  }) => {
    const q = state.samples;
    if (!q.length) {
      for (let i = 0; i <= config.frameLag; i += 1) {
        q.push({ pos: fistWS.clone(), time });
      }
    }
    q.push({ pos: fistWS.clone(), time });
    while (q.length > config.frameLag + 1) q.shift();

    const oldest = q[0];
    tmpRawTravel.subVectors(fistWS, oldest.pos);
    const sampleDuration = Math.max(time - oldest.time, 0.0001);
    const travelSpeed = tmpRawTravel.length() / sampleDuration;
    let speedFactor = THREE.MathUtils.clamp(
      (travelSpeed - config.minSpeedForSmear) / Math.max(0.0001, config.speedForMaxSmear - config.minSpeedForSmear),
      0,
      1,
    );
    tmpTargetOffset.copy(tmpRawTravel).multiplyScalar(speedFactor);
    if (tmpTargetOffset.length() > config.maxSmearDistance) {
      tmpTargetOffset.setLength(config.maxSmearDistance);
    }

    let stylizeAmt = 0;
    if (whipEnvelope > 0.001 && analyticLagFistWS) {
      const analyticTravel = tmpDir.subVectors(fistWS, analyticLagFistWS).multiplyScalar(1.22 * whipEnvelope);
      if (analyticTravel.lengthSq() > tmpTargetOffset.lengthSq() || lockedTime != null) {
        tmpTargetOffset.copy(analyticTravel).clampLength(0, config.maxSmearDistance);
      }
      speedFactor = lockedTime != null ? whipEnvelope : Math.max(speedFactor, whipEnvelope);
      stylizeAmt = whipEnvelope;
    } else if (lockedTime != null) {
      tmpTargetOffset.set(0, 0, 0);
      speedFactor = 0;
    }

    if (travelSpeed >= config.instantResponseSpeed || lockedTime != null) {
      state.currentOffset.copy(tmpTargetOffset);
    } else {
      const sharpness =
        tmpTargetOffset.lengthSq() > state.currentOffset.lengthSq()
          ? config.followSharpness
          : config.releaseSharpness;
      const blend = 1 - Math.exp(-sharpness * Math.max(dt, 0.0001));
      state.currentOffset.lerp(tmpTargetOffset, blend);
    }

    state.speedFactor = speedFactor;
    tmpDir.copy(state.currentOffset);
    if (tmpDir.lengthSq() > 0.0001) tmpDir.normalize();

    uniforms.uSmearCurrentWS.value.copy(fistWS).addScaledVector(tmpDir, 0.14);
    uniforms.uSmearPreviousWS.value.copy(fistWS).sub(state.currentOffset);
    uniforms.uSmearShoulderWS.value.copy(shoulderWS);

    tmpArmVec.subVectors(fistWS, shoulderWS);
    const armLen = Math.max(0.25, tmpArmVec.length());
    uniforms.uSmearArmLen.value = armLen;
    uniforms.uSmearArmAxisWS.value.copy(tmpArmVec).divideScalar(armLen);

    uniforms.uSmearOutwardWS.value
      .set(elbowWS.x - torsoCenterWS.x, 0.12, elbowWS.z - torsoCenterWS.z)
      .normalize();
    uniforms.uSmearStrength.value = config.smearStrength * speedFactor;
    uniforms.uSmearMaxDistance.value = config.maxSmearDistance;
    uniforms.uSmearStylize.value = stylizeAmt;

    /* Update sub-frame motion-blur ghost shells along the moving arm trajectory */
    const showGhosts = speedFactor > 0.08 && typeof sampleSubframePose === "function";
    const baseOpacities = [0.34, 0.24, 0.16, 0.09];
    ghostShells.forEach((shell, idx) => {
      if (!showGhosts) {
        shell.arm.visible = false;
        return;
      }
      const subPose = sampleSubframePose((idx + 1) / config.ghostCount);
      if (!subPose) {
        shell.arm.visible = false;
        return;
      }
      shell.arm.visible = true;
      shell.arm.rotation.set(subPose.rightArmRot[0], subPose.rightArmRot[1], subPose.rightArmRot[2]);
      shell.fore.rotation.set(subPose.rightForeRot[0], subPose.rightForeRot[1], subPose.rightForeRot[2]);
      const alpha = (baseOpacities[idx] ?? 0.1) * Math.min(1, speedFactor * 1.15);
      shell.mats.forEach((m) => {
        m.userData.ghostUniforms.uGhostAlpha.value = alpha;
      });
    });
  };

  return {
    uniforms,
    depthMaterial,
    enhanceMaterial,
    bindLimbGhostBlur,
    update,
    getStrength: () => +uniforms.uSmearStrength.value.toFixed(3),
    getStylize: () => +uniforms.uSmearStylize.value.toFixed(3),
    getGhostCount: () => ghostShells.filter((s) => s.arm.visible).length,
  };
}

import * as THREE from "three";

/* Boss Animation Pose & Joint Articulation Handler.
   Drives the articulated hierarchy of `werewolf-boss.glb`:
   Pelvis, Torso, Head, LeftArm, RightArm, LeftForeArm, RightForeArm,
   LeftLeg, RightLeg, LeftShin, RightShin, Tail. */

export const BOSS_PUNCH_DURATION = 1.18;

export function computeBossPose(animState, time, runPhase, punchTime) {
  const pose = {
    pelvisPos: [0, 0, 0],
    pelvisRot: [0, 0, 0],
    torsoRot: [0, 0, 0],
    torsoScale: 1,
    headRot: [0, 0, 0],
    leftArmRot: [0, 0, 0],
    rightArmRot: [0, 0, 0],
    leftForeRot: [0, 0, 0],
    rightForeRot: [0, 0, 0],
    leftLegRot: [0, 0, 0],
    rightLegRot: [0, 0, 0],
    leftShinRot: [0, 0, 0],
    rightShinRot: [0, 0, 0],
    tailRot: [0, 0, 0],
  };

  if (animState === "run") {
    const p = runPhase;
    const s = Math.sin(p);
    const c = Math.cos(p);
    const s2 = Math.sin(p * 2);
    const c2 = Math.cos(p * 2);
    /* Stylistic predatory beast sprint: heavy double-frequency bound, deep forward lean, strong shoulder counter-twist */
    pose.pelvisPos = [c * 0.026, -0.042 + Math.max(-0.028, s2 * 0.042), 0];
    pose.pelvisRot = [0.14, -s * 0.26, c * 0.075];
    pose.torsoRot = [0.34 + c2 * 0.055, s * 0.38, -c * 0.085];
    pose.torsoScale = 1.02;
    pose.headRot = [-0.26 - c2 * 0.035, -s * 0.16, c * 0.04];
    /* Pumping beast-brawler arms opposing the legs */
    pose.leftArmRot = [-s * 0.76 - 0.18, -s * 0.14, 0.28];
    pose.leftForeRot = [-0.88 - Math.max(0, s) * 0.38, 0, -0.16];
    pose.rightArmRot = [s * 0.76 - 0.18, -s * 0.14, -0.28];
    pose.rightForeRot = [-0.88 - Math.max(0, -s) * 0.38, 0, 0.16];
    /* High-driving thighs & snappy knee folds */
    pose.leftLegRot = [s * 0.78 - 0.14, 0, 0.05];
    pose.leftShinRot = [0.24 + Math.max(0, c) * 0.84 + Math.max(0, -s) * 0.18, 0, 0];
    pose.rightLegRot = [-s * 0.78 - 0.14, 0, -0.05];
    pose.rightShinRot = [0.24 + Math.max(0, -c) * 0.84 + Math.max(0, s) * 0.18, 0, 0];
    pose.tailRot = [0.56 + c2 * 0.1, c * 0.32, s * 0.14];
    return pose;
  }

  if (animState === "punch") {
    const u = THREE.MathUtils.clamp(punchTime, 0, BOSS_PUNCH_DURATION);
    const ss = THREE.MathUtils.smoothstep;
    if (u < 0.42) {
      /* Phase 1: Coiled Sekiro/Soulslike wind-up with tension tremor at the peak */
      const w = ss(u, 0.0, 0.33);
      const tremor = u > 0.26 ? Math.sin(u * 75) * 0.025 * ss(u, 0.26, 0.41) : 0;
      pose.pelvisPos = [-0.03 * w, -0.082 * w, -0.055 * w];
      pose.pelvisRot = [0.08 * w, -0.46 * w, -0.06 * w];
      pose.torsoRot = [-0.16 * w, -0.88 * w + tremor, -0.18 * w];
      pose.torsoScale = 1 + 0.05 * w;
      pose.headRot = [0.14 * w, 0.68 * w, 0.12 * w];
      /* Left arm braces forward as martial counter-guard; Right arm cocks far back behind right shoulder */
      pose.leftArmRot = [-0.78 * w, 0.36 * w, 0.34 * w];
      pose.leftForeRot = [-0.58 * w, 0, -0.22 * w];
      pose.rightArmRot = [0.86 * w + tremor, -0.68 * w, -0.82 * w];
      pose.rightForeRot = [-1.24 * w, 0, 0.32 * w];
      pose.leftLegRot = [-0.46 * w, 0.12 * w, 0.08 * w];
      pose.leftShinRot = [0.58 * w, 0, 0];
      pose.rightLegRot = [0.28 * w, -0.12 * w, -0.08 * w];
      pose.rightShinRot = [0.46 * w, 0, 0];
      pose.tailRot = [0.35 * w, 0.48 * w, 0.18 * w];
      return pose;
    }
    if (u < 0.66) {
      /* Phase 2: Explosive right-hand haymaker/smash whip across the arc + impact lock frame */
      const rawS = THREE.MathUtils.clamp((u - 0.42) / 0.11, 0, 1);
      const whip = 1 - Math.pow(1 - rawS, 3.8);
      const impactVib = rawS >= 0.95 ? Math.sin((u - 0.52) * 90) * 0.03 * (1 - ss(u, 0.52, 0.66)) : 0;
      const L = THREE.MathUtils.lerp;
      pose.pelvisPos = [L(-0.03, 0.04, whip), L(-0.082, -0.096, whip), L(-0.055, 0.095, whip)];
      pose.pelvisRot = [L(0.08, 0.24, whip), L(-0.46, 0.54, whip), L(-0.06, 0.09, whip)];
      pose.torsoRot = [L(-0.16, 0.44, whip), L(-0.88, 0.98, whip) + impactVib, L(-0.18, 0.22, whip)];
      pose.torsoScale = L(1.05, 1.03, whip);
      pose.headRot = [L(0.14, -0.28, whip), L(0.68, -0.64, whip), L(0.12, -0.12, whip)];
      /* Left arm rips back in counter-pull while Right arm whips forward and across at full extension */
      pose.leftArmRot = [L(-0.78, 0.68, whip), L(0.36, -0.28, whip), L(0.34, 0.42, whip)];
      pose.leftForeRot = [L(-0.58, -1.06, whip), 0, L(-0.22, -0.18, whip)];
      /* Clean monotonic horizontal-forward haymaker arc so the smear trails smoothly across the swing plane */
      pose.rightArmRot = [
        L(0.86, -1.36, whip),
        L(-0.68, 0.42, whip) + impactVib,
        L(-0.82, -0.46, whip),
      ];
      pose.rightForeRot = [L(-1.24, -0.16, whip) + impactVib, 0, L(0.32, 0.08, whip)];
      pose.leftLegRot = [L(-0.46, -0.58, whip), L(0.12, -0.14, whip), 0.08];
      pose.leftShinRot = [L(0.58, 0.68, whip), 0, 0];
      pose.rightLegRot = [L(0.28, 0.48, whip), L(-0.12, 0.1, whip), -0.08];
      pose.rightShinRot = [L(0.46, 0.22, whip), 0, 0];
      pose.tailRot = [L(0.35, 0.62, whip), L(0.48, -0.58, whip), L(0.18, -0.22, whip)];
      return pose;
    }
    /* Phase 3: Heavy Soulslike recovery back to coiled martial stance */
    const rec = ss(u, 0.66, BOSS_PUNCH_DURATION);
    const idle = computeBossPose("idle", time, runPhase, 0);
    const impact = computeBossPose("punch", time, runPhase, 0.65);
    const blendArr = (a, b) => [
      THREE.MathUtils.lerp(a[0], b[0], rec),
      THREE.MathUtils.lerp(a[1], b[1], rec),
      THREE.MathUtils.lerp(a[2], b[2], rec),
    ];
    pose.pelvisPos = blendArr(impact.pelvisPos, idle.pelvisPos);
    pose.pelvisRot = blendArr(impact.pelvisRot, idle.pelvisRot);
    pose.torsoRot = blendArr(impact.torsoRot, idle.torsoRot);
    pose.torsoScale = THREE.MathUtils.lerp(impact.torsoScale, idle.torsoScale, rec);
    pose.headRot = blendArr(impact.headRot, idle.headRot);
    pose.leftArmRot = blendArr(impact.leftArmRot, idle.leftArmRot);
    pose.leftForeRot = blendArr(impact.leftForeRot, idle.leftForeRot);
    pose.rightArmRot = blendArr(impact.rightArmRot, idle.rightArmRot);
    pose.rightForeRot = blendArr(impact.rightForeRot, idle.rightForeRot);
    pose.leftLegRot = blendArr(impact.leftLegRot, idle.leftLegRot);
    pose.leftShinRot = blendArr(impact.leftShinRot, idle.leftShinRot);
    pose.rightLegRot = blendArr(impact.rightLegRot, idle.rightLegRot);
    pose.rightShinRot = blendArr(impact.rightShinRot, idle.rightShinRot);
    pose.tailRot = blendArr(impact.tailRot, idle.tailRot);
    return pose;
  }

  /* Default: Stylistic coiled martial-beast Idle ("idle") */
  const breath = Math.sin(time * 2.6);
  const sway = Math.sin(time * 1.3);
  const crouch = 0.5 - 0.5 * breath;
  pose.pelvisPos = [sway * 0.016, -0.036 - crouch * 0.022, 0];
  pose.pelvisRot = [0.08, -0.18 + sway * 0.045, sway * 0.03];
  pose.torsoRot = [0.16 + Math.sin(time * 2.6 - 0.5) * 0.048, 0.18 + Math.cos(time * 1.3) * 0.05, -sway * 0.035];
  pose.torsoScale = 1 + Math.max(0, breath) * 0.026;
  pose.headRot = [-0.14 - Math.sin(time * 2.6 - 0.5) * 0.032, -0.06 - sway * 0.04, sway * 0.045];
  /* Lead left claw raised in martial guard, right power hand cocked at the ribs */
  pose.leftArmRot = [-0.44 + breath * 0.05, -0.16, 0.25];
  pose.leftForeRot = [-0.88 + Math.cos(time * 2.6) * 0.06, 0, -0.18];
  pose.rightArmRot = [-0.18 + Math.sin(time * 2.6 + 0.4) * 0.06, 0.16, -0.28];
  pose.rightForeRot = [-0.96 + Math.cos(time * 2.6 + 0.4) * 0.06, 0, 0.22];
  pose.leftLegRot = [-0.24 - crouch * 0.05, 0.06, 0.06];
  pose.leftShinRot = [0.32 + crouch * 0.06, 0, 0];
  pose.rightLegRot = [-0.12 - crouch * 0.05, -0.06, -0.06];
  pose.rightShinRot = [0.24 + crouch * 0.06, 0, 0];
  pose.tailRot = [0.24 + Math.sin(time * 2.2) * 0.08, Math.sin(time * 1.5) * 0.28, Math.cos(time * 1.5) * 0.12];
  return pose;
}

export function applyBossPoseDirect(bossNodes, pose, dampRate, dt) {
  if (!bossNodes.Pelvis) return;
  const dampVal = (cur, goal) => (dampRate <= 0 ? goal : THREE.MathUtils.damp(cur, goal, dampRate, dt));
  const dampRot = (node, rot) => {
    if (!node) return;
    node.rotation.x = dampVal(node.rotation.x, rot[0]);
    node.rotation.y = dampVal(node.rotation.y, rot[1]);
    node.rotation.z = dampVal(node.rotation.z, rot[2]);
  };
  const pRest = bossNodes.Pelvis.userData.restPos;
  bossNodes.Pelvis.position.x = dampVal(bossNodes.Pelvis.position.x, pRest.x + pose.pelvisPos[0]);
  bossNodes.Pelvis.position.y = dampVal(bossNodes.Pelvis.position.y, pRest.y + pose.pelvisPos[1]);
  bossNodes.Pelvis.position.z = dampVal(bossNodes.Pelvis.position.z, pRest.z + pose.pelvisPos[2]);
  dampRot(bossNodes.Pelvis, pose.pelvisRot);
  dampRot(bossNodes.Torso, pose.torsoRot);
  if (bossNodes.Torso) {
    const s = dampVal(bossNodes.Torso.scale.x, pose.torsoScale);
    bossNodes.Torso.scale.set(s, 1 + (s - 1) * 0.7, s);
  }
  dampRot(bossNodes.Head, pose.headRot);
  dampRot(bossNodes.LeftArm, pose.leftArmRot);
  dampRot(bossNodes.RightArm, pose.rightArmRot);
  dampRot(bossNodes.LeftForeArm, pose.leftForeRot);
  dampRot(bossNodes.RightForeArm, pose.rightForeRot);
  dampRot(bossNodes.LeftLeg, pose.leftLegRot);
  dampRot(bossNodes.RightLeg, pose.rightLegRot);
  dampRot(bossNodes.LeftShin, pose.leftShinRot);
  dampRot(bossNodes.RightShin, pose.rightShinRot);
  dampRot(bossNodes.Tail, pose.tailRot);
}

import * as THREE from "three";
import werewolfBossGlb from "./assets/models/werewolf-boss.glb";
import { createSmearHandler } from "./world-smear.js";
import { BOSS_PUNCH_DURATION, computeBossPose, applyBossPoseDirect } from "./world-boss-anim.js";

/* Werewolf Boss Entity, State Machine & Combat Mechanic Handler.
   Coordinates model loading, spawn-court placement, idle/run/punch state transitions,
   and the right-arm UE4 SmearFrame + Pixel_Pass vertex smear and sub-frame motion blur. */

const dampAngle = (current, target, lambda, dt) => {
  const t = 1 - Math.exp(-Math.max(0.01, lambda) * dt);
  const delta = Math.atan2(Math.sin(target - current), Math.cos(target - current));
  return current + delta * t;
};

export function createWerewolfBoss({
  scene,
  island,
  landing,
  robot,
  colliders,
  decal,
  halo,
  glow,
  softMapped,
  bakeShadows,
  isIntroLive,
  addShake,
}) {
  const bossAt = landing.clone();
  bossAt.x -= Math.SQRT1_2 * 3.05;
  bossAt.z += Math.SQRT1_2 * 2.05;
  if (!island.nav.walkable(bossAt.x, bossAt.z)) {
    const near = island.nav.nearest(bossAt.x, bossAt.z);
    if (near) bossAt.copy(near);
  }
  bossAt.y = island.groundAt(bossAt.x, bossAt.z);

  const BOSS_SCALE = 2.65;
  const BOSS_RUN_SPEED = 4.2;
  const bossGroup = new THREE.Group();
  bossGroup.name = "WerewolfBoss";
  bossGroup.position.copy(bossAt);
  const bossHomeYaw = Math.atan2(landing.x - bossAt.x, landing.z - bossAt.z);
  bossGroup.rotation.y = bossHomeYaw;
  scene.add(bossGroup);

  const bossBody = new THREE.Group();
  bossBody.scale.setScalar(BOSS_SCALE);
  bossGroup.add(bossBody);

  const bossCollider = { x: bossAt.x, z: bossAt.z, r: 0.68 };
  colliders.push(bossCollider);
  const bossDecal = decal(scene, {
    color: "#2a3a2a",
    size: 2.1,
    x: bossAt.x,
    z: bossAt.z,
    y: bossAt.y + 0.03,
    opacity: 0.35,
  });

  const armSmear = createSmearHandler({
    frameLag: 4,
    smearStrength: 1.24,
    maxSmearDistance: 1.68,
    noiseScale: 9.5,
    normalBias: 0.34,
    ghostCount: 4,
  });

  /* Fist wind-up charge glint & ground impact shockwave ring */
  const bossChargeHalo = halo(scene, { color: "#ff3828", size: 0.9, opacity: 0 });
  bossChargeHalo.visible = false;
  const impactRingGeo = new THREE.RingGeometry(0.32, 0.52, 24).rotateX(-Math.PI / 2);
  const impactRingMat = new THREE.MeshBasicMaterial({
    color: "#ffece0",
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
  const bossImpactRing = new THREE.Mesh(impactRingGeo, impactRingMat);
  bossImpactRing.visible = false;
  bossImpactRing.renderOrder = 3;
  scene.add(bossImpactRing);

  let bossReady = false;
  const bossNodes = {};

  const loadBoss = async () => {
    const { GLTFLoader } = await import("three/addons/loaders/GLTFLoader.js");
    const gltf = await new GLTFLoader().parseAsync(
      werewolfBossGlb.buffer.slice(werewolfBossGlb.byteOffset, werewolfBossGlb.byteOffset + werewolfBossGlb.byteLength),
      "",
    );
    const wantedNodes = [
      "Pelvis",
      "Torso",
      "Head",
      "LeftArm",
      "RightArm",
      "LeftForeArm",
      "RightForeArm",
      "LeftHand",
      "RightHand",
      "LeftLeg",
      "RightLeg",
      "LeftShin",
      "RightShin",
      "Tail",
    ];
    gltf.scene.traverse((node) => {
      if (wantedNodes.includes(node.name)) {
        bossNodes[node.name] = node;
        node.userData.restPos = node.position.clone();
      }
    });
    const isUnderRightArm = (node) => {
      for (let cur = node; cur; cur = cur.parent) {
        if (cur.name === "RightArm" || cur.name === "RightForeArm") return true;
      }
      return false;
    };
    gltf.scene.traverse((node) => {
      if (!node.isMesh) return;
      const isEye = /Eye/i.test(node.name);
      const onRightArm = isUnderRightArm(node);
      if (isEye) {
        node.material = glow("#ff3b2f", 2.2);
      } else if (node.material?.map) {
        const baseMat = softMapped(node.material.map);
        baseMat.color.copy(node.material.color);
        node.material = onRightArm ? armSmear.enhanceMaterial(baseMat) : baseMat;
        if (onRightArm) {
          node.customDepthMaterial = armSmear.depthMaterial;
        }
      }
      node.castShadow = !isEye;
      node.receiveShadow = !isEye;
      node.frustumCulled = false;
    });
    /* Attach 4 translucent sub-frame motion-blur ghost shells onto the boss's right arm */
    armSmear.bindLimbGhostBlur(bossNodes.Torso, bossNodes.RightArm, bossNodes.RightForeArm);
    bossBody.add(gltf.scene);
    bossReady = true;
    bakeShadows();
  };
  loadBoss().catch((error) => console.warn("Werewolf boss model failed", error));

  const bossState = {
    mode: "auto", /* "auto" | "idle" | "run" | "punch" */
    state: "idle", /* current active state: "idle" | "run" | "punch" */
    inPlace: false,
    lockedTime: null,
    runPhase: 0,
    punchTime: -1,
    punchCooldown: 1.15,
    impactFired: false,
    impactAge: 99,
    impactOrigin: new THREE.Vector3(),
    yaw: bossHomeYaw,
  };

  const tmpShoulderWS = new THREE.Vector3();
  const tmpElbowWS = new THREE.Vector3();
  const tmpFistWS = new THREE.Vector3();
  const tmpLagShoulder = new THREE.Vector3();
  const tmpLagElbow = new THREE.Vector3();
  const tmpLagFist = new THREE.Vector3();

  const samplePunchArmWS = (punchT, time, outShoulder, outElbow, outFist) => {
    const p = computeBossPose("punch", time, bossState.runPhase, punchT);
    applyBossPoseDirect(bossNodes, p, 0, 0);
    bossGroup.updateMatrixWorld(true);
    bossNodes.RightArm.getWorldPosition(outShoulder);
    bossNodes.RightForeArm.getWorldPosition(outElbow);
    bossNodes.RightHand.getWorldPosition(outFist);
  };

  const update = (dt, time) => {
    if (!bossReady || !bossNodes.Pelvis) return;

    const dxNiko = robot.position.x - bossGroup.position.x;
    const dzNiko = robot.position.z - bossGroup.position.z;
    const distNiko = Math.hypot(dxNiko, dzNiko);
    const dxHome = bossAt.x - bossGroup.position.x;
    const dzHome = bossAt.z - bossGroup.position.z;
    const distHome = Math.hypot(dxHome, dzHome);
    const introActive = Boolean(isIntroLive?.());

    /* 1. Determine active animation state & movement */
    if (bossState.mode === "idle") {
      bossState.state = "idle";
      bossState.punchTime = -1;
    } else if (bossState.mode === "run") {
      bossState.state = "run";
      bossState.punchTime = -1;
      bossState.runPhase = bossState.lockedTime != null ? bossState.lockedTime * 9.5 : bossState.runPhase + dt * 9.5;
      if (!bossState.inPlace && distNiko > 2.1) {
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 2.0, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      }
    } else if (bossState.mode === "punch") {
      bossState.state = "punch";
      if (bossState.lockedTime != null) {
        bossState.punchTime = bossState.lockedTime;
      } else if (bossState.punchTime < 0) {
        bossState.punchTime = 0;
        bossState.impactFired = false;
      } else {
        bossState.punchTime += dt;
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
    } else {
      /* "auto" gameplay mode */
      bossState.punchCooldown = Math.max(0, bossState.punchCooldown - dt);
      if (introActive) {
        bossState.state = "idle";
        bossState.punchTime = -1;
      } else if (bossState.punchTime >= 0) {
        bossState.state = "punch";
        const prevPunchT = bossState.punchTime;
        bossState.punchTime += dt;
        if (bossState.punchTime >= 0.41 && bossState.punchTime <= 0.54 && distNiko > 1.75) {
          const lungeStep = Math.min(distNiko - 1.7, 5.2 * dt);
          const nx = bossGroup.position.x + Math.sin(bossState.yaw) * lungeStep;
          const nz = bossGroup.position.z + Math.cos(bossState.yaw) * lungeStep;
          if (island.nav.walkable(nx, nz)) {
            bossGroup.position.x = nx;
            bossGroup.position.z = nz;
          }
        } else if (bossState.punchTime < 0.36 && distNiko > 0.01) {
          bossState.yaw = dampAngle(bossState.yaw, Math.atan2(dxNiko, dzNiko), 10, dt);
        }
        if (prevPunchT < 0.51 && bossState.punchTime >= 0.51 && !bossState.impactFired) {
          bossState.impactFired = true;
          bossState.impactAge = 0;
          if (distNiko < 5.5) addShake?.(0.14);
        }
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = -1;
          bossState.state = "idle";
          bossState.punchCooldown = 1.9;
        }
      } else if (distNiko <= 2.75 && bossState.punchCooldown <= 0) {
        bossState.state = "punch";
        bossState.punchTime = 0;
        bossState.impactFired = false;
        if (distNiko > 0.01) bossState.yaw = Math.atan2(dxNiko, dzNiko);
      } else if (distNiko > 2.75 && distNiko <= 12.5 && distHome <= 11.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.5;
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 11, dt);
        const step = Math.min(distNiko - 2.2, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + (dxNiko / distNiko) * step;
        const nz = bossGroup.position.z + (dzNiko / distNiko) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else if (distHome > 0.35 && distNiko > 12.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.2;
        const yawHome = Math.atan2(dxHome, dzHome);
        bossState.yaw = dampAngle(bossState.yaw, yawHome, 10, dt);
        const step = Math.min(distHome, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + (dxHome / distHome) * step;
        const nz = bossGroup.position.z + (dzHome / distHome) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else {
        bossState.state = "idle";
        const lookYaw = distNiko < 9.5 && distNiko > 0.01 ? Math.atan2(dxNiko, dzNiko) : bossHomeYaw;
        bossState.yaw = dampAngle(bossState.yaw, lookYaw, 7, dt);
      }
    }

    bossGroup.position.y = island.groundAt(bossGroup.position.x, bossGroup.position.z);
    bossGroup.rotation.y = bossState.yaw;
    bossCollider.x = bossGroup.position.x;
    bossCollider.z = bossGroup.position.z;
    bossDecal.position.set(bossGroup.position.x, bossGroup.position.y + 0.03, bossGroup.position.z);

    /* 2. Apply joint pose */
    const isPunchWhip = bossState.state === "punch" && bossState.punchTime >= 0.40 && bossState.punchTime <= 0.66;
    const poseDamp = bossState.lockedTime != null ? 0 : isPunchWhip ? 38 : bossState.state === "punch" ? 18 : 14;
    const targetPose = computeBossPose(bossState.state, time, bossState.runPhase, bossState.punchTime);

    let whipEnvelope = 0;
    let headT = bossState.punchTime;
    if (isPunchWhip && bossNodes.RightArm && bossNodes.RightForeArm && bossNodes.RightHand) {
      const u = bossState.punchTime;
      whipEnvelope = THREE.MathUtils.smoothstep(u, 0.40, 0.445) * (1 - THREE.MathUtils.smoothstep(u, 0.495, 0.545));
      headT = Math.min(u, 0.515);
      samplePunchArmWS(Math.max(0.41, headT - 0.055), time, tmpLagShoulder, tmpLagElbow, tmpLagFist);
      applyBossPoseDirect(bossNodes, targetPose, 0, dt);
    } else {
      applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
    }

    bossGroup.updateMatrixWorld(true);

    /* 3. Update UE4 SmearFrame + Pixel_Pass vertex smear and sub-frame motion blur on the right arm */
    if (bossNodes.RightArm && bossNodes.RightForeArm && bossNodes.RightHand) {
      bossNodes.RightArm.getWorldPosition(tmpShoulderWS);
      bossNodes.RightForeArm.getWorldPosition(tmpElbowWS);
      bossNodes.RightHand.getWorldPosition(tmpFistWS);

      armSmear.update({
        dt,
        time,
        shoulderWS: tmpShoulderWS,
        elbowWS: tmpElbowWS,
        fistWS: tmpFistWS,
        torsoCenterWS: bossGroup.position,
        analyticLagFistWS: whipEnvelope > 0.001 ? tmpLagFist : null,
        whipEnvelope,
        lockedTime: bossState.lockedTime,
        sampleSubframePose: isPunchWhip
          ? (frac) => computeBossPose("punch", time, bossState.runPhase, Math.max(0.41, headT - frac * 0.048))
          : null,
      });

      /* Wind-up crimson charge glint on the cocked right fist */
      if (bossState.state === "punch" && bossState.punchTime >= 0.10 && bossState.punchTime <= 0.43) {
        const charge = Math.sin(((bossState.punchTime - 0.10) / 0.33) * Math.PI);
        bossChargeHalo.visible = true;
        bossChargeHalo.position.copy(tmpFistWS);
        bossChargeHalo.scale.setScalar(0.55 + charge * 0.75);
        bossChargeHalo.material.opacity = charge * 0.85;
      } else {
        bossChargeHalo.visible = false;
      }

      /* Impact shockwave ring at the punch apex */
      if (bossState.state === "punch" && bossState.punchTime >= 0.50 && bossState.punchTime <= 0.58) {
        if (bossState.lockedTime != null) {
          bossState.impactAge = Math.max(0.02, bossState.punchTime - 0.50) * 2.2;
          bossState.impactOrigin.set(tmpFistWS.x, bossGroup.position.y + 0.06, tmpFistWS.z);
        } else if (bossState.impactAge > 0.4) {
          bossState.impactAge = 0;
          bossState.impactOrigin.set(tmpFistWS.x, bossGroup.position.y + 0.06, tmpFistWS.z);
        }
      }
      if (bossState.impactAge < 0.36) {
        bossState.impactAge += Math.max(dt, 0.016);
        const p = Math.min(1, bossState.impactAge / 0.36);
        bossImpactRing.visible = true;
        bossImpactRing.position.copy(bossState.impactOrigin);
        bossImpactRing.scale.setScalar(0.65 + p * 3.1);
        bossImpactRing.material.opacity = (1 - p) * 0.85;
      } else {
        bossImpactRing.visible = false;
      }
    }
  };

  const debug = (options) => {
    if (options && typeof options === "object") {
      if (options.mode) {
        bossState.mode = options.mode;
        if (options.mode === "punch" && options.time == null) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
      if ("inPlace" in options) bossState.inPlace = Boolean(options.inPlace);
      if ("time" in options) bossState.lockedTime = options.time;
      if (options.yaw != null) bossState.yaw = options.yaw;
      if (options.resetPos) {
        bossGroup.position.copy(bossAt);
        bossState.yaw = bossHomeYaw;
      }
      update(0.016, performance.now() / 1000);
    }
    return {
      ready: bossReady,
      mode: bossState.mode,
      state: bossState.state,
      punchTime: +bossState.punchTime.toFixed(3),
      smearStrength: armSmear.getStrength(),
      smearStylize: armSmear.getStylize(),
      blurGhosts: armSmear.getGhostCount(),
      at: bossGroup.position.toArray().map((n) => +n.toFixed(2)),
      scale: BOSS_SCALE,
    };
  };

  return {
    group: bossGroup,
    update,
    debug,
  };
}

