  /* Create sub-frame motion-blur ghost shells for a limb hierarchy (RightArm + RightForeArm + RightHand) */
  const ghostShells = [];
  const bindLimbGhostBlur = (rootGroup, rightArmNode, rightForeArmNode) => {
    ghostShells.length = 0;
    if (!rootGroup || !rightArmNode || !rightForeArmNode) return;
    for (let g = 0; g < config.ghostCount; g += 1) {
      const ghostArm = new THREE.Group();
      ghostArm.name = `RightArmBlurGhost_${g}`;
      ghostArm.matrixAutoUpdate = false;
      ghostArm.visible = false;

      const ghostFore = new THREE.Group();
      ghostFore.name = `RightForeArmBlurGhost_${g}`;
      ghostFore.position.copy(rightForeArmNode.position);
      ghostArm.add(ghostFore);

      const ghostMats = [];
      const cloneSubtreeInto = (srcNode, dstParent, skipNode = null) => {
        srcNode.children.forEach((child) => {
          if (child === skipNode || child.name?.includes("BlurGhost")) return;
          if (child.isMesh) {
            const gMat = makeGhostMaterial(child.material, g, config.ghostCount);
            ghostMats.push(gMat);
            const m = new THREE.Mesh(child.geometry, gMat);
            m.position.copy(child.position);
            m.quaternion.copy(child.quaternion);
            m.scale.copy(child.scale);
            m.castShadow = false;
            m.receiveShadow = false;
            m.frustumCulled = false;
            m.renderOrder = 2;
            dstParent.add(m);
          } else if (child.children?.length) {
            const grp = new THREE.Group();
            grp.position.copy(child.position);
            grp.quaternion.copy(child.quaternion);
            grp.scale.copy(child.scale);
            dstParent.add(grp);
            cloneSubtreeInto(child, grp, skipNode);
          }
        });
      };
      cloneSubtreeInto(rightArmNode, ghostArm, rightForeArmNode);
      cloneSubtreeInto(rightForeArmNode, ghostFore, null);
      rootGroup.add(ghostArm);
      ghostShells.push({ arm: ghostArm, fore: ghostFore, mats: ghostMats, index: g });
    }
  };

  /* Runtime state for PixelPassSmearEffect velocity tracking */
  const state = {
    samples: [],
    currentOffset: new THREE.Vector3(),
    speedFactor: 0,
  };
  const tmpRawTravel = new THREE.Vector3();
  const tmpTargetOffset = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const tmpArmVec = new THREE.Vector3();

  const reset = () => {
    state.samples.length = 0;
    state.currentOffset.set(0, 0, 0);
    state.speedFactor = 0;
    uniforms.uSmearStrength.value = 0;
    uniforms.uSmearStylize.value = 0;
    ghostShells.forEach((shell) => {
      shell.arm.visible = false;
    });
  };

  const update = ({
    dt,
    time,
    shoulderWS,
    elbowWS,
    fistWS,
    torsoCenterWS,
    analyticLagFistWS = null,
    whipEnvelope = 0,
    lockedTime = null,
    applySubframeShell = null,
  }) => {
    const q = state.samples;
    if (!q.length) {
      for (let i = 0; i <= config.frameLag; i += 1) {
        q.push({ pos: fistWS.clone(), time });
      }
    }
    /* Guard against root teleports (e.g. debug resetPos) */
    if (q.length && fistWS.distanceToSquared(q[q.length - 1].pos) > 3.5) {
      q.length = 0;
      for (let i = 0; i <= config.frameLag; i += 1) {
        q.push({ pos: fistWS.clone(), time });
      }
      state.currentOffset.set(0, 0, 0);
    } else {
      q.push({ pos: fistWS.clone(), time });
      while (q.length > config.frameLag + 1) q.shift();
    }

    const oldest = q[0];
    tmpRawTravel.subVectors(fistWS, oldest.pos);
    const sampleDuration = Math.max(time - oldest.time, 0.0001);
    const travelSpeed = tmpRawTravel.length() / sampleDuration;
    let speedFactor = THREE.MathUtils.clamp(
      (travelSpeed - config.minSpeedForSmear) / Math.max(0.0001, config.speedForMaxSmear - config.minSpeedForSmear),
      0,
      1,
    );
    tmpTargetOffset.copy(tmpRawTravel).multiplyScalar(speedFactor);
    if (tmpTargetOffset.length() > config.maxSmearDistance) {
      tmpTargetOffset.setLength(config.maxSmearDistance);
    }

    let stylizeAmt = 0;
    if (whipEnvelope > 0.001 && analyticLagFistWS) {
      /* Scale the local arc tangent vector up to the smear distance so vertex fibers follow the swing curve */
      const analyticTravel = tmpDir.subVectors(fistWS, analyticLagFistWS);
      if (analyticTravel.lengthSq() > 0.0001) {
