    uniforms,
    depthMaterial,
    enhanceMaterial,
    bindLimbGhostBlur,
    reset,
    update,
    getStrength: () => +uniforms.uSmearStrength.value.toFixed(3),
    getStylize: () => +uniforms.uSmearStylize.value.toFixed(3),
    getGhostCount: () => ghostShells.filter((s) => s.arm.visible).length,
  };
}

