      import path from "node:path";
      import * as THREE from "three";
      import { FBXLoader } from "./.impeccable/fbx/addons/loaders/FBXLoader.js";
      const b = fs.readFileSync(path.join(${JSON.stringify(root)}, "assets/models/y-bot.fbx"));
      const ybot = new FBXLoader().parse(b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength), "");
      const skinned = [];
      ybot.traverse(n => { if (n.isSkinnedMesh) skinned.push(n); });
      const skel = skinned[1].skeleton;
      const byName = {};
      skel.bones.forEach(bone => { byName[bone.name.replace(/^mixamorig/, "")] = bone; });

      const setSwingPose = (t) => {
        const L = THREE.MathUtils.lerp;
        const ss = THREE.MathUtils.smoothstep;
        let whip = 0;
        if (t < 0.36) {
          whip = 0;
        } else if (t < 0.56) {
          const s = (t - 0.36) / 0.20;
          whip = 1 - Math.pow(1 - s, 2.6);
        } else {
          whip = 1;
        }
        byName.Hips.rotation.set(L(0.06, 0.14, whip), L(-0.32, 0.36, whip), 0);
        byName.Spine.rotation.set(L(-0.08, 0.10, whip), L(-0.18, 0.22, whip), 0);
        byName.Spine1.rotation.set(L(0.0, 0.08, whip), L(-0.18, 0.22, whip), 0);
        byName.Spine2.rotation.set(L(0.08, 0.12, whip), L(-0.20, 0.24, whip), 0);
        byName.RightShoulder.rotation.set(1.58, 0.02, L(1.92, 1.55, whip));
        byName.RightArm.rotation.set(
          L(0.16, 0.12, whip) - Math.sin(whip * Math.PI) * 0.08,
          L(0.15, -0.25, whip),
          L(0.88, -1.92, whip)
        );
        byName.RightForeArm.rotation.set(0, 0, L(-0.18, -0.26, whip));
        ybot.updateMatrixWorld(true);
        const pHand = new THREE.Vector3(), pElbow = new THREE.Vector3(), pShoulder = new THREE.Vector3();
        byName.RightArm.getWorldPosition(pShoulder);
        byName.RightForeArm.getWorldPosition(pElbow);
        byName.RightHand.getWorldPosition(pHand);
        return { whip: +whip.toFixed(3), shoulder: pShoulder.toArray().map(v => +v.toFixed(1)), elbow: pElbow.toArray().map(v => +v.toFixed(1)), hand: pHand.toArray().map(v => +v.toFixed(1)) };
      };

      for (const t of [0.36, 0.40, 0.44, 0.48, 0.52, 0.56]) {
        console.log("t=" + t.toFixed(2), JSON.stringify(setSwingPose(t)));
      }
    `,
    resolveDir: root,
    loader: "js"
  },
