import { build } from "esbuild";
import path from "node:path";

const root = path.resolve(process.cwd(), "../..");
const vendor = path.join(root, "vendor/three");
const res = await build({
  stdin: {
    contents: `
      import fs from "node:fs";
      import path from "node:path";
      import * as THREE from "three";
      import { FBXLoader } from "./.impeccable/fbx/addons/loaders/FBXLoader.js";
      const load = (p) => {
        const b = fs.readFileSync(path.join(${JSON.stringify(root)}, p));
        return new FBXLoader().parse(b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength), "");
      };
      const ybot = load("assets/models/y-bot.fbx");
      const idle = load("assets/niko/Idle.fbx");
      const run = load("assets/Running (1).fbx");
      const skinned = [];
      ybot.traverse(n => { if (n.isSkinnedMesh) skinned.push(n); });
      const mainSkel = skinned[1].skeleton;
      const mainBoneSet = new Set(mainSkel.bones);
      skinned[0].bind(mainSkel, skinned[0].bindMatrix);
      ybot.traverse(n => { if (n.isBone && !mainBoneSet.has(n) && n.children.length === 0) n.parent?.remove(n); });

      const mixer = new THREE.AnimationMixer(ybot);
      const idleAct = mixer.clipAction(idle.animations[0]);
      idleAct.play();
      mixer.setTime(0.5);
      ybot.updateMatrixWorld(true);
      const rHand = mainSkel.bones.find(b => b.name === "mixamorigRightHand");
      const lHand = mainSkel.bones.find(b => b.name === "mixamorigLeftHand");
      const rFoot = mainSkel.bones.find(b => b.name === "mixamorigRightFoot");
      const pR = new THREE.Vector3(), pL = new THREE.Vector3(), pF = new THREE.Vector3();
      rHand.getWorldPosition(pR); lHand.getWorldPosition(pL); rFoot.getWorldPosition(pF);
      console.log("Idle at 0.5s - RHand:", pR.toArray().map(x => +x.toFixed(1)), "LHand:", pL.toArray().map(x => +x.toFixed(1)), "RFoot:", pF.toArray().map(x => +x.toFixed(1)));

      idleAct.stop();
      const runAct = mixer.clipAction(run.animations[0]);
      runAct.play();
      mixer.setTime(0.2);
      ybot.updateMatrixWorld(true);
      rHand.getWorldPosition(pR); lHand.getWorldPosition(pL); rFoot.getWorldPosition(pF);
