args.Content:
/* Y Bot Boss Animation Pose & Joint Articulation Handler (world-boss-anim.js)
   Computes procedural martial-arts poses for Mixamo Y Bot (`assets/models/y-bot.fbx`):
   1. "idle"  — poised Sekiro/martial combat guard with rhythmic breathing & weight shift
   2. "run"   — athletic forward sprint with counter-rotating torso and high knee drive
   3. "punch" — wide horizontal right-arm arc swing designed to showcase the Godot
                mesh-smearing (`lag_transform` + `pow(noise, exp)`) forming along the
                curved hand/forearm arc and settling cleanly back into the mesh. */

import * as THREE from "three";

export const BOSS_PUNCH_DURATION = 1.24;

const tmpEuler = new THREE.Euler();
const tmpDeltaQuat = new THREE.Quaternion();
const tmpTargetQuat = new THREE.Quaternion();

export function computeBossPose(state, time, runPhase, punchTime) {
  const ss = THREE.MathUtils.smoothstep;
  const L = THREE.MathUtils.lerp;

  const pose = {
    hipsPos: [0, 0, 0], /* delta in cm relative to restPos [0, 99.79, 0] */
    Hips: [0, 0, 0],
    Spine: [0, 0, 0],
    Spine1: [0, 0, 0],
    Spine2: [0, 0, 0],
    Neck: [0, 0, 0],
    Head: [0, 0, 0],
    LeftShoulder: [0, 0, 0],
    LeftArm: [0, 0, 0],
    LeftForeArm: [0, 0, 0],
    LeftHand: [0, 0, 0],
    RightShoulder: [0, 0, 0],
    RightArm: [0, 0, 0],
    RightForeArm: [0, 0, 0],
    RightHand: [0, 0, 0],
    LeftUpLeg: [0, 0, 0],
    LeftLeg: [0, 0, 0],
    LeftFoot: [0, 0, 0],
    RightUpLeg: [0, 0, 0],
    RightLeg: [0, 0, 0],
    RightFoot: [0, 0, 0],
    fistCurl: 0.35,
  };

  if (state === "run") {
    const p = runPhase;
    const s1 = Math.sin(p);
    const c1 = Math.cos(p);
    const bob = Math.abs(s1);
    pose.hipsPos = [c1 * 1.4, -4.5 + (bob - 0.5) * 4.8, 0];
    pose.Hips = [0.16, -s1 * 0.16, c1 * 0.05];
    pose.Spine = [0.14 + bob * 0.04, s1 * 0.10, -c1 * 0.04];
    pose.Spine1 = [0.10, s1 * 0.10, 0];
    pose.Spine2 = [0.08, s1 * 0.12, 0];
    pose.Neck = [-0.14, -s1 * 0.08, 0];
    pose.Head = [-0.12, -s1 * 0.08, 0];
    /* Pumping arms in athletic sprint */
    pose.LeftArm = [0.98, 0, -s1 * 0.68];
    pose.LeftForeArm = [0, 0, 1.18 + Math.max(0, -s1) * 0.32];
    pose.RightArm = [0.98, 0, -s1 * 0.68];
    pose.RightForeArm = [0, 0, -1.18 - Math.max(0, s1) * 0.32];
    /* High knee drive & shin fold */
    pose.LeftUpLeg = [s1 * 0.72 + 0.12, 0, 0];
    pose.LeftLeg = [-0.22 - Math.max(0, -c1) * 0.92, 0, 0];
    pose.LeftFoot = [0.10 - s1 * 0.22, 0, 0];
    pose.RightUpLeg = [-s1 * 0.72 + 0.12, 0, 0];
    pose.RightLeg = [-0.22 - Math.max(0, c1) * 0.92, 0, 0];
    pose.RightFoot = [0.10 + s1 * 0.22, 0, 0];
    pose.fistCurl = 0.65;
    return pose;
  }

  if (state === "punch") {
    const u = THREE.MathUtils.clamp(punchTime, 0, BOSS_PUNCH_DURATION);
    const idle = computeBossPose("idle", time, runPhase, 0);

    if (u < 0.36) {
      /* Phase 1: Wind-up — coil torso right and open the right arm wide behind the right shoulder */
      const w = ss(u, 0.0, 0.34);
      const blend = (a, b) => [L(a[0], b[0], w), L(a[1], b[1], w), L(a[2], b[2], w)];
      pose.hipsPos = blend(idle.hipsPos, [-2.5, -6.2, -3.5]);
      pose.Hips = blend(idle.Hips, [0.06, -0.34, -0.04]);
      pose.Spine = blend(idle.Spine, [-0.06, -0.18, -0.04]);
      pose.Spine1 = blend(idle.Spine1, [-0.04, -0.20, 0]);
      pose.Spine2 = blend(idle.Spine2, [0.04, -0.22, 0]);
      pose.Neck = blend(idle.Neck, [0.04, 0.32, 0]);
      pose.Head = blend(idle.Head, [0.04, 0.36, 0]);
      /* Left arm guards chest; Right arm extends wide & back at chest level to prepare the arc */
      pose.LeftShoulder = blend(idle.LeftShoulder, [0, 0, -0.08]);
      pose.LeftArm = blend(idle.LeftArm, [0.68, 0, 0.52]);
      pose.LeftForeArm = blend(idle.LeftForeArm, [0, 0, 0.92]);
      pose.RightShoulder = blend(idle.RightShoulder, [0, 0, 0.16]);
      pose.RightArm = blend(idle.RightArm, [0.16, 0.14, 0.92]);
      pose.RightForeArm = blend(idle.RightForeArm, [0, 0, -0.16]);
      pose.RightHand = blend(idle.RightHand, [0, 0, 0]);
      pose.LeftUpLeg = blend(idle.LeftUpLeg, [0.42, 0.08, 0]);
      pose.LeftLeg = blend(idle.LeftLeg, [-0.58, 0, 0]);
      pose.LeftFoot = blend(idle.LeftFoot, [0.22, 0, 0]);
      pose.RightUpLeg = blend(idle.RightUpLeg, [-0.28, -0.08, 0]);
      pose.RightLeg = blend(idle.RightLeg, [-0.36, 0, 0]);
      pose.RightFoot = blend(idle.RightFoot, [0.48, 0, 0]);
      pose.fistCurl = L(idle.fistCurl, 0.15, w);
      return pose;
    }

    if (u < 0.78) {
      /* Phase 2 (0.36..0.56): Wide horizontal-diagonal circular arc swing across the front.
         Phase 3 (0.56..0.78): Follow-through hold while `lag_transform` settles cleanly into the hand mesh. */
      const rawS = THREE.MathUtils.clamp((u - 0.36) / 0.20, 0, 1);
      const whip = 1 - Math.pow(1 - rawS, 2.5);
      pose.hipsPos = [L(-2.5, 3.2, whip), L(-6.2, -7.4, whip), L(-3.5, 6.5, whip)];
      pose.Hips = [L(0.06, 0.14, whip), L(-0.34, 0.36, whip), L(-0.04, 0.06, whip)];
      pose.Spine = [L(-0.06, 0.10, whip), L(-0.18, 0.22, whip), L(-0.04, 0.05, whip)];
      pose.Spine1 = [L(-0.04, 0.08, whip), L(-0.20, 0.24, whip), 0];
      pose.Spine2 = [L(0.04, 0.10, whip), L(-0.22, 0.26, whip), 0];
      pose.Neck = [L(0.04, -0.08, whip), L(0.32, -0.34, whip), 0];
      pose.Head = [L(0.04, -0.08, whip), L(0.36, -0.38, whip), 0];
      /* Left arm pulls back in counter-balance */
      pose.LeftShoulder = [0, 0, L(-0.08, 0.10, whip)];
      pose.LeftArm = [L(0.68, 0.82, whip), 0, L(0.52, -0.48, whip)];
      pose.LeftForeArm = [0, 0, L(0.92, 1.08, whip)];
      /* Right arm sweeps a clean, wide 175-degree circular arc at chest height */
      pose.RightShoulder = [0, 0, L(0.16, -0.22, whip)];
      pose.RightArm = [
        L(0.16, 0.12, whip) - Math.sin(whip * Math.PI) * 0.08,
        L(0.14, -0.22, whip),
        L(0.92, -1.94, whip),
      ];
      pose.RightForeArm = [0, 0, L(-0.16, -0.24, whip)];
      pose.RightHand = [0, 0, 0];
      pose.LeftUpLeg = [L(0.42, 0.52, whip), L(0.08, -0.08, whip), 0];
      pose.LeftLeg = [L(-0.58, -0.66, whip), 0, 0];
      pose.LeftFoot = [L(0.22, 0.20, whip), 0, 0];
      pose.RightUpLeg = [L(-0.28, -0.38, whip), L(-0.08, 0.08, whip), 0];
      pose.RightLeg = [L(-0.36, -0.24, whip), 0, 0];
      pose.RightFoot = [L(0.48, 0.52, whip), 0, 0];
      pose.fistCurl = 0.15;
      return pose;
    }

    /* Phase 4 (0.78..1.24): Smooth recovery back to martial idle stance */
    const rec = ss(u, 0.78, BOSS_PUNCH_DURATION);
    const follow = computeBossPose("punch", time, runPhase, 0.77);
    const blend = (a, b) => [L(a[0], b[0], rec), L(a[1], b[1], rec), L(a[2], b[2], rec)];
    pose.hipsPos = blend(follow.hipsPos, idle.hipsPos);
    pose.Hips = blend(follow.Hips, idle.Hips);
    pose.Spine = blend(follow.Spine, idle.Spine);
    pose.Spine1 = blend(follow.Spine1, idle.Spine1);
    pose.Spine2 = blend(follow.Spine2, idle.Spine2);
    pose.Neck = blend(follow.Neck, idle.Neck);
    pose.Head = blend(follow.Head, idle.Head);
    pose.LeftShoulder = blend(follow.LeftShoulder, idle.LeftShoulder);
    pose.LeftArm = blend(follow.LeftArm, idle.LeftArm);
    pose.LeftForeArm = blend(follow.LeftForeArm, idle.LeftForeArm);
    pose.RightShoulder = blend(follow.RightShoulder, idle.RightShoulder);
    pose.RightArm = blend(follow.RightArm, idle.RightArm);
    pose.RightForeArm = blend(follow.RightForeArm, idle.RightForeArm);
    pose.RightHand = blend(follow.RightHand, idle.RightHand);
    pose.LeftUpLeg = blend(follow.LeftUpLeg, idle.LeftUpLeg);
    pose.LeftLeg = blend(follow.LeftLeg, idle.LeftLeg);
    pose.LeftFoot = blend(follow.LeftFoot, idle.LeftFoot);
    pose.RightUpLeg = blend(follow.RightUpLeg, idle.RightUpLeg);
    pose.RightLeg = blend(follow.RightLeg, idle.RightLeg);
    pose.RightFoot = blend(follow.RightFoot, idle.RightFoot);
    pose.fistCurl = L(follow.fistCurl, idle.fistCurl, rec);
    return pose;
  }

  /* Default: Stylistic martial combat Idle ("idle") */
  const breath = Math.sin(time * 2.4);
  const sway = Math.sin(time * 1.2);
  const crouch = 0.5 - 0.5 * breath;
  pose.hipsPos = [sway * 1.1, -3.2 - crouch * 1.6, 0];
  pose.Hips = [0.04, -0.18 + sway * 0.04, sway * 0.02];
  pose.Spine = [0.06 + breath * 0.025, 0.08 + sway * 0.03, 0];
  pose.Spine1 = [0.04 + breath * 0.02, 0.08, 0];
  pose.Spine2 = [0.04 + breath * 0.02, 0.08, 0];
  pose.Neck = [-0.06 - breath * 0.02, -0.04 - sway * 0.03, 0];
  pose.Head = [-0.06 - breath * 0.02, -0.04 - sway * 0.03, 0];
  /* Lead left hand raised in martial guard, right hand cocked ready */
  pose.LeftArm = [0.96 - breath * 0.04, 0, 0.36];
  pose.LeftForeArm = [0, 0, 1.12 + breath * 0.05];
  pose.RightArm = [1.02 - breath * 0.04, 0, -0.22];
  pose.RightForeArm = [0, 0, -1.18 - breath * 0.05];
  pose.LeftUpLeg = [0.28 + crouch * 0.04, 0.05, 0];
  pose.LeftLeg = [-0.44 - crouch * 0.06, 0, 0];
  pose.LeftFoot = [0.16, 0, 0];
  pose.RightUpLeg = [-0.18 - crouch * 0.04, -0.05, 0];
  pose.RightLeg = [-0.28 - crouch * 0.06, 0, 0];
  pose.RightFoot = [0.42, 0, 0];
  pose.fistCurl = 0.45;
  return pose;
}

const POSE_BONE_KEYS = [
  "Hips",
  "Spine",
  "Spine1",
  "Spine2",
  "Neck",
  "Head",
  "LeftShoulder",
  "LeftArm",
  "LeftForeArm",
  "LeftHand",
  "RightShoulder",
  "RightArm",
  "RightForeArm",
  "RightHand",
  "LeftUpLeg",
  "LeftLeg",
  "LeftFoot",
  "RightUpLeg",
  "RightLeg",
  "RightFoot",
];

export function applyBossPoseDirect(bossNodes, pose, dampRate, dt) {
  if (!bossNodes.Hips) return;
  const alpha = dampRate <= 0 ? 1 : 1 - Math.exp(-dampRate * Math.max(dt, 0.0001));

  const hRest = bossNodes.Hips.userData.restPos;
  if (hRest) {
    bossNodes.Hips.position.x = THREE.MathUtils.lerp(bossNodes.Hips.position.x, hRest.x + pose.hipsPos[0], alpha);
    bossNodes.Hips.position.y = THREE.MathUtils.lerp(bossNodes.Hips.position.y, hRest.y + pose.hipsPos[1], alpha);
    bossNodes.Hips.position.z = THREE.MathUtils.lerp(bossNodes.Hips.position.z, hRest.z + pose.hipsPos[2], alpha);
  }

  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    tmpEuler.set(rot[0], rot[1], rot[2], "XYZ");
    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }

  /* Subtle finger curl on both hands */
  if (bossNodes.fingerBones?.length) {
    const curl = pose.fistCurl ?? 0.35;
    for (const f of bossNodes.fingerBones) {
      tmpEuler.set(0, 0, f.isLeft ? curl : -curl, "XYZ");
      tmpDeltaQuat.setFromEuler(tmpEuler);
      boneQuatHelper(f.bone, tmpDeltaQuat, alpha);
    }
  }
}

function boneQuatHelper(bone, deltaQuat, alpha) {
  if (!bone?.userData?.restQuat) return;
  tmpTargetQuat.copy(bone.userData.restQuat).multiply(deltaQuat);
  if (alpha >= 0.999) bone.quaternion.copy(tmpTargetQuat);
  else bone.quaternion.slerp(tmpTargetQuat, alpha);
}

/* Y Bot Boss Entity, Loader & Combat Mechanic Handler (world-boss.js)
   Uses Mixamo Y Bot (`assets/models/y-bot.fbx`) and coordinates:
   - `world-boss-anim.js` (procedural martial idle, run, and wide right-arm arc swing)
   - `world-smear.js` (Godot `mesh-smearing` per-vertex `lag_transform` + `pow(noise, exp)`
     arc interpolation that forms on the moving hand/arm mesh and settles cleanly back into it) */

import * as THREE from "three";
import { FBXLoader } from "./.impeccable/fbx/addons/loaders/FBXLoader.js";
import yBotFbx from "./assets/models/y-bot.fbx";
import { createSmearHandler } from "./world-smear.js";
import { BOSS_PUNCH_DURATION, computeBossPose, applyBossPoseDirect } from "./world-boss-anim.js";

export function createWerewolfBoss({
  scene,
  island,
  landing,
  robot,
  colliders,
  decal,
  softMapped,
  bakeShadows,
  isIntroLive,
  addShake,
}) {
  const bossAt = landing.clone();
  bossAt.x -= Math.SQRT1_2 * 3.05;
  bossAt.z += Math.SQRT1_2 * 2.05;
  if (!island.nav.walkable(bossAt.x, bossAt.z)) {
    const near = island.nav.nearest(bossAt.x, bossAt.z);
    if (near) bossAt.copy(near);
  }
  bossAt.y = island.groundAt(bossAt.x, bossAt.z);

  const BOSS_SCALE = 1.28;
  const FBX_CM_TO_M = 0.01 * BOSS_SCALE;
  const BOSS_RUN_SPEED = 4.2;

  const bossGroup = new THREE.Group();
  bossGroup.name = "YBotBoss";
  bossGroup.position.copy(bossAt);
  const bossHomeYaw = Math.atan2(landing.x - bossAt.x, landing.z - bossAt.z);
  bossGroup.rotation.y = bossHomeYaw;
  scene.add(bossGroup);

  const bossBody = new THREE.Group();
  bossBody.scale.setScalar(FBX_CM_TO_M);
  bossGroup.add(bossBody);

  const bossDecal = decal(1.15, "#233022", 0.34);
  bossDecal.position.set(bossAt.x, bossAt.y + 0.03, bossAt.z);
  scene.add(bossDecal);

  const bossCollider = { x: bossAt.x, z: bossAt.z, r: 0.78 };
  colliders.push(bossCollider);

  /* Godot mesh-smearing handler (`https://godotshaders.com/shader/mesh-smearing/#main`) */
  const armSmear = createSmearHandler({
    weight: 9.0,
    noiseScale: 0.34,
    noisePower: 3.3,
    stretch: 1.45,
  });

  const bossNodes = { fingerBones: [] };
  let bossReady = false;
  let mainSkeleton = null;

  const dampAngle = (current, target, rate, dt) => {
    const diff = Math.atan2(Math.sin(target - current), Math.cos(target - current));
    return current + diff * (1 - Math.exp(-rate * dt));
  };

  try {
    const ab = yBotFbx.buffer.slice(yBotFbx.byteOffset, yBotFbx.byteOffset + yBotFbx.byteLength);
    const model = new FBXLoader().parse(ab, "");

    const skinnedMeshes = [];
    model.traverse((node) => {
      if (node.isSkinnedMesh) skinnedMeshes.push(node);
    });

    /* Unify Alpha_Surface and Alpha_Joints onto the single 52-bone Mixamo hierarchy skeleton */
    mainSkeleton = skinnedMeshes[1]?.skeleton || skinnedMeshes[0]?.skeleton;
    if (mainSkeleton) {
      const mainBoneSet = new Set(mainSkeleton.bones);
      skinnedMeshes.forEach((mesh) => {
        if (mesh.skeleton !== mainSkeleton) {
          mesh.bind(mainSkeleton, mesh.bindMatrix);
        }
      });
      const duplicateLeaves = [];
      model.traverse((node) => {
        if (node.isBone && !mainBoneSet.has(node) && node.children.length === 0) {
          duplicateLeaves.push(node);
        }
      });
      duplicateLeaves.forEach((leaf) => leaf.parent?.remove(leaf));

      mainSkeleton.bones.forEach((bone) => {
        bone.userData.restPos = bone.position.clone();
        bone.userData.restQuat = bone.quaternion.clone();
        const cleanName = bone.name.replace(/^mixamorig\d*:?/, "");
        bossNodes[cleanName] = bone;
        if (/^(Left|Right)Hand(Index|Middle|Ring|Pinky)[123]$/.test(cleanName)) {
          bossNodes.fingerBones.push({ bone, isLeft: cleanName.startsWith("Left") });
        }
      });

      armSmear.bindSkeleton(mainSkeleton, bossGroup);
    }

    skinnedMeshes.forEach((mesh) => {
      const isJoints = /Joints/i.test(mesh.name);
      const baseColor = isJoints ? "#1f2b2f" : "#22657a";
      const baseMat = softMapped(null);
      baseMat.color.set(baseColor);
      mesh.material = armSmear.enhanceMaterial(baseMat);
      mesh.customDepthMaterial = armSmear.depthMaterial;
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.frustumCulled = false;
    });

    bossBody.add(model);
    bossReady = true;
    bakeShadows();
  } catch (error) {
    console.warn("Y Bot boss model failed", error);
  }

  const bossState = {
    mode: "auto", /* "auto" | "idle" | "run" | "punch" */
    state: "idle", /* current active state: "idle" | "run" | "punch" */
    inPlace: false,
    lockedTime: null,
    runPhase: 0,
    punchTime: -1,
    punchCooldown: 1.15,
    impactFired: false,
    yaw: bossHomeYaw,
  };

  const update = (dt, time) => {
    if (!bossReady || !bossNodes.Hips) return;

    const dxNiko = robot.position.x - bossGroup.position.x;
    const dzNiko = robot.position.z - bossGroup.position.z;
    const distNiko = Math.hypot(dxNiko, dzNiko);
    const dxHome = bossAt.x - bossGroup.position.x;
    const dzHome = bossAt.z - bossGroup.position.z;
    const distHome = Math.hypot(dxHome, dzHome);
    const introActive = Boolean(isIntroLive?.());

    /* 1. Determine active animation state & movement */
    if (bossState.mode === "idle") {
      bossState.state = "idle";
      bossState.punchTime = -1;
    } else if (bossState.mode === "run") {
      bossState.state = "run";
      bossState.punchTime = -1;
      bossState.runPhase = bossState.lockedTime != null ? bossState.lockedTime * 9.5 : bossState.runPhase + dt * 9.5;
      if (!bossState.inPlace && distNiko > 2.1) {
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 2.0, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      }
    } else if (bossState.mode === "punch") {
      bossState.state = "punch";
      if (bossState.lockedTime != null) {
        bossState.punchTime = bossState.lockedTime;
      } else if (bossState.punchTime < 0) {
        bossState.punchTime = 0;
        bossState.impactFired = false;
      } else {
        bossState.punchTime += dt;
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
    } else {
      /* "auto" gameplay mode */
      bossState.punchCooldown = Math.max(0, bossState.punchCooldown - dt);
      if (introActive) {
        bossState.state = "idle";
        bossState.punchTime = -1;
        bossState.yaw = dampAngle(bossState.yaw, bossHomeYaw, 6, dt);
      } else if (bossState.punchTime >= 0) {
        bossState.state = "punch";
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        if (bossState.punchTime < 0.36) {
          bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 9, dt);
        }
        bossState.punchTime += dt;
        if (!bossState.impactFired && bossState.punchTime >= 0.48) {
          bossState.impactFired = true;
          if (distNiko < 5.5) addShake?.(0.24);
        }
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = -1;
          bossState.punchCooldown = 1.35;
          bossState.state = "idle";
        }
      } else if (distNiko <= 2.95 && bossState.punchCooldown <= 0) {
        bossState.state = "punch";
        bossState.punchTime = 0;
        bossState.impactFired = false;
      } else if (distNiko > 2.65 && distNiko < 8.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.5;
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 2.35, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else if (distHome > 0.35 && distNiko >= 8.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.0;
        const yawHome = Math.atan2(dxHome, dzHome);
        bossState.yaw = dampAngle(bossState.yaw, yawHome, 9, dt);
        const step = Math.min(distHome, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + (dxHome / distHome) * step;
        const nz = bossGroup.position.z + (dzHome / distHome) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else {
        bossState.state = "idle";
        const lookYaw = distNiko < 9.5 && distNiko > 0.01 ? Math.atan2(dxNiko, dzNiko) : bossHomeYaw;
        bossState.yaw = dampAngle(bossState.yaw, lookYaw, 7, dt);
      }
    }

    bossGroup.position.y = island.groundAt(bossGroup.position.x, bossGroup.position.z);
    bossGroup.rotation.y = bossState.yaw;
    bossCollider.x = bossGroup.position.x;
    bossCollider.z = bossGroup.position.z;
    bossDecal.position.set(bossGroup.position.x, bossGroup.position.y + 0.03, bossGroup.position.z);

    /* 2. Apply pose and update Godot mesh-smearing (`lag_transform`) */
    if (bossState.state === "punch") {
      const u = bossState.punchTime;
      const getWeightForTime = (t) => (t < 0.35 ? 36.0 : t < 0.56 ? 8.5 : 12.5);

      if (bossState.lockedTime != null) {
        /* Deterministically integrate `lag_transform.interpolate_with(global_transform, weight * dt)`
           up to `lockedTime` so frozen debug/review frames show the exact arc smear & settle. */
        const startT = Math.min(u, 0.34);
        const startPose = computeBossPose("punch", time, bossState.runPhase, startT);
        applyBossPoseDirect(bossNodes, startPose, 0, 0);
        bossGroup.updateMatrixWorld(true);
        armSmear.reset();

        const stepDt = 1 / 120;
        for (let simT = startT + stepDt; simT <= u + 1e-5; simT += stepDt) {
          const clampedT = Math.min(simT, u);
          const p = computeBossPose("punch", time, bossState.runPhase, clampedT);
          applyBossPoseDirect(bossNodes, p, 0, 0);
          bossGroup.updateMatrixWorld(true);
          armSmear.stepLag(stepDt, getWeightForTime(clampedT));
        }
      } else {
        const isSwingOrSettle = u >= 0.35 && u <= 0.82;
        const poseDamp = isSwingOrSettle ? 42 : 18;
        const targetPose = computeBossPose("punch", time, bossState.runPhase, u);
        applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
        bossGroup.updateMatrixWorld(true);
        armSmear.stepLag(dt, getWeightForTime(u));
      }
    } else {
      const poseDamp = bossState.lockedTime != null ? 0 : 14;
      const targetPose = computeBossPose(bossState.state, time, bossState.runPhase, -1);
      applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
      bossGroup.updateMatrixWorld(true);
      armSmear.reset();
    }
  };

  const debug = (options) => {
    if (options && typeof options === "object") {
      if (options.mode) {
        bossState.mode = options.mode;
        if (options.mode === "punch" && options.time == null) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
      if ("inPlace" in options) bossState.inPlace = Boolean(options.inPlace);
      if ("time" in options) bossState.lockedTime = options.time;
      if (options.yaw != null) bossState.yaw = options.yaw;
      if (options.resetPos) {
        bossGroup.position.copy(bossAt);
        bossState.yaw = bossHomeYaw;
        armSmear.reset();
      }
      update(0.016, performance.now() / 1000);
    }
    return {
      ready: bossReady,
      mode: bossState.mode,
      state: bossState.state,
      punchTime: +bossState.punchTime.toFixed(3),
      lagDistance: armSmear.getLagDistance(),
      at: bossGroup.position.toArray().map((n) => +n.toFixed(2)),
      scale: BOSS_SCALE,
    };
  };

  return {
    group: bossGroup,
    update,
    debug,
  };
}

