/* Y Bot Boss Animation Pose & Joint Articulation Handler (world-boss-anim.js)
   Computes procedural martial-arts poses for Mixamo Y Bot (`assets/models/y-bot.fbx`):
   1. "idle"  — poised Sekiro/martial combat guard with rhythmic breathing & weight shift
   2. "run"   — athletic forward sprint with counter-rotating torso and high knee drive
   3. "punch" — wide horizontal right-arm arc swing at chest height designed to showcase the Godot
                mesh-smearing (`lag_transform` + `pow(noise, exp)`) forming along the
                curved hand/forearm arc and settling cleanly back into the mesh. */

import * as THREE from "three";

export const BOSS_PUNCH_DURATION = 1.24;

const tmpEuler = new THREE.Euler();
const tmpDeltaQuat = new THREE.Quaternion();
const tmpTargetQuat = new THREE.Quaternion();

export function computeBossPose(state, time, runPhase, punchTime) {
  const ss = THREE.MathUtils.smoothstep;
  const L = THREE.MathUtils.lerp;

  const pose = {
    hipsPos: [0, 0, 0], /* delta in cm relative to restPos [0, 99.79, 0] */
    Hips: [0, 0, 0],
    Spine: [0, 0, 0],
    Spine1: [0, 0, 0],
    Spine2: [0, 0, 0],
    Neck: [0, 0, 0],
    Head: [0, 0, 0],
    LeftShoulder: [0, 0, 0],
    LeftArm: [0, 0, 0],
    LeftForeArm: [0, 0, 0],
    LeftHand: [0, 0, 0],
    RightShoulder: [0, 0, 0],
    RightArm: [0, 0, 0],
    RightForeArm: [0, 0, 0],
    RightHand: [0, 0, 0],
    LeftUpLeg: [0, 0, 0],
    LeftLeg: [0, 0, 0],
    LeftFoot: [0, 0, 0],
    RightUpLeg: [0, 0, 0],
    RightLeg: [0, 0, 0],
    RightFoot: [0, 0, 0],
    fistCurl: 0.35,
  };

  if (state === "run") {
    const p = runPhase;
    const s1 = Math.sin(p);
    const c1 = Math.cos(p);
    const bob = Math.abs(s1);
    pose.hipsPos = [c1 * 1.4, -4.5 + (bob - 0.5) * 4.8, 0];
    pose.Hips = [0.16, -s1 * 0.16, c1 * 0.05];
    pose.Spine = [0.14 + bob * 0.04, s1 * 0.10, -c1 * 0.04];
    pose.Spine1 = [0.10, s1 * 0.10, 0];
    pose.Spine2 = [0.08, s1 * 0.12, 0];
    pose.Neck = [-0.14, -s1 * 0.08, 0];
    pose.Head = [-0.12, -s1 * 0.08, 0];
    /* Pumping arms in athletic sprint (ZXY order on LeftArm/RightArm) */
    pose.LeftArm = [1.08, 0.25, -s1 * 0.65];
    pose.LeftForeArm = [0, 0, 1.05 + Math.max(0, -s1) * 0.32];
    pose.RightArm = [1.08, -0.25, -s1 * 0.65];
    pose.RightForeArm = [0, 0, -1.05 - Math.max(0, s1) * 0.32];
    /* High knee drive & shin fold */
    pose.LeftUpLeg = [s1 * 0.72 + 0.12, 0, 0];
    pose.LeftLeg = [-0.22 - Math.max(0, -c1) * 0.92, 0, 0];
    pose.LeftFoot = [0.10 - s1 * 0.22, 0, 0];
    pose.RightUpLeg = [-s1 * 0.72 + 0.12, 0, 0];
    pose.RightLeg = [-0.22 - Math.max(0, c1) * 0.92, 0, 0];
    pose.RightFoot = [0.10 + s1 * 0.22, 0, 0];
    pose.fistCurl = 0.65;
    return pose;
  }

  if (state === "punch") {
    const u = THREE.MathUtils.clamp(punchTime, 0, BOSS_PUNCH_DURATION);
    const idle = computeBossPose("idle", time, runPhase, 0);

    if (u < 0.36) {
      /* Phase 1: Wind-up — coil torso right and open the right arm wide behind the right shoulder */
      const w = ss(u, 0.0, 0.34);
      const blend = (a, b) => [L(a[0], b[0], w), L(a[1], b[1], w), L(a[2], b[2], w)];
      pose.hipsPos = blend(idle.hipsPos, [-2.2, -5.8, -3.2]);
      pose.Hips = blend(idle.Hips, [0.04, -0.28, -0.04]);
      pose.Spine = blend(idle.Spine, [-0.04, -0.14, -0.03]);
      pose.Spine1 = blend(idle.Spine1, [-0.02, -0.14, 0]);
      pose.Spine2 = blend(idle.Spine2, [0.02, -0.16, 0]);
      pose.Neck = blend(idle.Neck, [0.02, 0.26, 0]);
      pose.Head = blend(idle.Head, [0.02, 0.30, 0]);
      /* Left arm guards chest; Right arm extends wide & back at chest level to prepare the horizontal arc */
      pose.LeftShoulder = blend(idle.LeftShoulder, [0, 0, -0.06]);
      pose.LeftArm = blend(idle.LeftArm, [0.95, 0.32, 0.42]);
      pose.LeftForeArm = blend(idle.LeftForeArm, [0, 0, 0.88]);
      pose.RightShoulder = blend(idle.RightShoulder, [0, 0, 0.12]);
      pose.RightArm = blend(idle.RightArm, [0.28, 0.10, 0.55]);
      pose.RightForeArm = blend(idle.RightForeArm, [0, 0, -0.18]);
      pose.RightHand = blend(idle.RightHand, [0, 0, 0]);
      pose.LeftUpLeg = blend(idle.LeftUpLeg, [0.38, 0.06, 0]);
      pose.LeftLeg = blend(idle.LeftLeg, [-0.54, 0, 0]);
      pose.LeftFoot = blend(idle.LeftFoot, [0.20, 0, 0]);
      pose.RightUpLeg = blend(idle.RightUpLeg, [-0.26, -0.06, 0]);
      pose.RightLeg = blend(idle.RightLeg, [-0.34, 0, 0]);
      pose.RightFoot = blend(idle.RightFoot, [0.46, 0, 0]);
      pose.fistCurl = L(idle.fistCurl, 0.12, w);
      return pose;
    }

    if (u < 0.78) {
      /* Phase 2 (0.36..0.55): Wide chest-level circular arc swing across the front.
         Phase 3 (0.55..0.78): Follow-through hold in front of chest while `lag_transform` settles cleanly into the hand mesh. */
      const rawS = THREE.MathUtils.clamp((u - 0.36) / 0.19, 0, 1);
      const whip = 1 - Math.pow(1 - rawS, 2.4);
      pose.hipsPos = [L(-2.2, 2.8, whip), L(-5.8, -6.8, whip), L(-3.2, 5.8, whip)];
      pose.Hips = [L(0.04, 0.10, whip), L(-0.28, 0.24, whip), L(-0.04, 0.05, whip)];
      pose.Spine = [L(-0.04, 0.06, whip), L(-0.14, 0.14, whip), L(-0.03, 0.04, whip)];
      pose.Spine1 = [L(-0.02, 0.05, whip), L(-0.14, 0.14, whip), 0];
      pose.Spine2 = [L(0.02, 0.06, whip), L(-0.16, 0.16, whip), 0];
      pose.Neck = [L(0.02, -0.06, whip), L(0.26, -0.24, whip), 0];
      pose.Head = [L(0.02, -0.06, whip), L(0.30, -0.28, whip), 0];
      /* Left arm pulls back to the left side in counter-balance */
      pose.LeftShoulder = [0, 0, L(-0.06, 0.08, whip)];
      pose.LeftArm = [L(0.95, 1.05, whip), L(0.32, 0.18, whip), L(0.42, -0.36, whip)];
      pose.LeftForeArm = [0, 0, L(0.88, 0.96, whip)];
      /* Right arm sweeps a clean, wide circular arc across the front at chest height (Y=116..130 cm) */
      pose.RightShoulder = [0, 0, L(0.12, -0.15, whip)];
      pose.RightArm = [
        L(0.28, 0.22, whip),
        L(0.10, -0.25, whip),
        L(0.55, -1.36, whip),
      ];
      pose.RightForeArm = [0, 0, L(-0.18, -0.32, whip)];
      pose.RightHand = [0, 0, 0];
      pose.LeftUpLeg = [L(0.38, 0.48, whip), L(0.06, -0.06, whip), 0];
      pose.LeftLeg = [L(-0.54, -0.62, whip), 0, 0];
      pose.LeftFoot = [L(0.20, 0.18, whip), 0, 0];
      pose.RightUpLeg = [L(-0.26, -0.34, whip), L(-0.06, 0.06, whip), 0];
      pose.RightLeg = [L(-0.34, -0.24, whip), 0, 0];
      pose.RightFoot = [L(0.46, 0.50, whip), 0, 0];
      pose.fistCurl = 0.12;
      return pose;
    }

    /* Phase 4 (0.78..1.24): Smooth recovery back to martial idle stance */
    const rec = ss(u, 0.78, BOSS_PUNCH_DURATION);
    const follow = computeBossPose("punch", time, runPhase, 0.77);
    const blend = (a, b) => [L(a[0], b[0], rec), L(a[1], b[1], rec), L(a[2], b[2], rec)];
    pose.hipsPos = blend(follow.hipsPos, idle.hipsPos);
    pose.Hips = blend(follow.Hips, idle.Hips);
    pose.Spine = blend(follow.Spine, idle.Spine);
    pose.Spine1 = blend(follow.Spine1, idle.Spine1);
    pose.Spine2 = blend(follow.Spine2, idle.Spine2);
    pose.Neck = blend(follow.Neck, idle.Neck);
    pose.Head = blend(follow.Head, idle.Head);
    pose.LeftShoulder = blend(follow.LeftShoulder, idle.LeftShoulder);
    pose.LeftArm = blend(follow.LeftArm, idle.LeftArm);
    pose.LeftForeArm = blend(follow.LeftForeArm, idle.LeftForeArm);
    pose.RightShoulder = blend(follow.RightShoulder, idle.RightShoulder);
    pose.RightArm = blend(follow.RightArm, idle.RightArm);
    pose.RightForeArm = blend(follow.RightForeArm, idle.RightForeArm);
    pose.RightHand = blend(follow.RightHand, idle.RightHand);
    pose.LeftUpLeg = blend(follow.LeftUpLeg, idle.LeftUpLeg);
    pose.LeftLeg = blend(follow.LeftLeg, idle.LeftLeg);
    pose.LeftFoot = blend(follow.LeftFoot, idle.LeftFoot);
    pose.RightUpLeg = blend(follow.RightUpLeg, idle.RightUpLeg);
    pose.RightLeg = blend(follow.RightLeg, idle.RightLeg);
    pose.RightFoot = blend(follow.RightFoot, idle.RightFoot);
    pose.fistCurl = L(follow.fistCurl, idle.fistCurl, rec);
    return pose;
  }

  /* Default: Natural poised martial Idle ("idle") */
  const breath = Math.sin(time * 2.4);
  const sway = Math.sin(time * 1.2);
  const crouch = 0.5 - 0.5 * breath;
  pose.hipsPos = [sway * 1.1, -3.0 - crouch * 1.5, 0];
  pose.Hips = [0.04, -0.16 + sway * 0.04, sway * 0.02];
  pose.Spine = [0.05 + breath * 0.02, 0.06 + sway * 0.03, 0];
  pose.Spine1 = [0.04 + breath * 0.02, 0.06, 0];
  pose.Spine2 = [0.04 + breath * 0.02, 0.06, 0];
  pose.Neck = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  pose.Head = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  /* Natural poised arms with ZXY order: elbows resting near ribs, forearms angled slightly inward */
  pose.LeftArm = [1.12 - breath * 0.03, 0.35, 0.22];
  pose.LeftForeArm = [0, 0, 0.78 + breath * 0.04];
  pose.RightArm = [1.16 - breath * 0.03, -0.35, -0.14];
  pose.RightForeArm = [0, 0, -0.68 - breath * 0.04];
  pose.LeftUpLeg = [0.24 + crouch * 0.04, 0.05, 0];
  pose.LeftLeg = [-0.40 - crouch * 0.05, 0, 0];
  pose.LeftFoot = [0.16, 0, 0];
  pose.RightUpLeg = [-0.16 - crouch * 0.04, -0.05, 0];
  pose.RightLeg = [-0.26 - crouch * 0.05, 0, 0];
  pose.RightFoot = [0.40, 0, 0];
  pose.fistCurl = 0.42;
  return pose;
}

const POSE_BONE_KEYS = [
  "Hips",
  "Spine",
  "Spine1",
  "Spine2",
  "Neck",
  "Head",
  "LeftShoulder",
  "LeftArm",
  "LeftForeArm",
  "LeftHand",
  "RightShoulder",
  "RightArm",
  "RightForeArm",
  "RightHand",
  "LeftUpLeg",
  "LeftLeg",
  "LeftFoot",
  "RightUpLeg",
  "RightLeg",
  "RightFoot",
];

export function applyBossPoseDirect(bossNodes, pose, dampRate, dt) {
  if (!bossNodes.Hips) return;
  const alpha = dampRate <= 0 ? 1 : 1 - Math.exp(-dampRate * Math.max(dt, 0.0001));

  const hRest = bossNodes.Hips.userData.restPos;
  if (hRest) {
    bossNodes.Hips.position.x = THREE.MathUtils.lerp(bossNodes.Hips.position.x, hRest.x + pose.hipsPos[0], alpha);
    bossNodes.Hips.position.y = THREE.MathUtils.lerp(bossNodes.Hips.position.y, hRest.y + pose.hipsPos[1], alpha);
    bossNodes.Hips.position.z = THREE.MathUtils.lerp(bossNodes.Hips.position.z, hRest.z + pose.hipsPos[2], alpha);
  }

  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    const order = key === "LeftArm" || key === "RightArm" ? "ZXY" : "XYZ";
    tmpEuler.set(rot[0], rot[1], rot[2], order);
    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }

  /* Subtle finger curl on both hands */
  if (bossNodes.fingerBones?.length) {
    const curl = pose.fistCurl ?? 0.35;
    for (const f of bossNodes.fingerBones) {
      tmpEuler.set(0, 0, f.isLeft ? curl : -curl, "XYZ");
      tmpDeltaQuat.setFromEuler(tmpEuler);
      boneQuatHelper(f.bone, tmpDeltaQuat, alpha);
    }
  }
}

function boneQuatHelper(bone, deltaQuat, alpha) {
  if (!bone?.userData?.restQuat) return;
  tmpTargetQuat.copy(bone.userData.restQuat).multiply(deltaQuat);
  if (alpha >= 0.999) bone.quaternion.copy(tmpTargetQuat);
  else bone.quaternion.slerp(tmpTargetQuat, alpha);
}

