import { build } from "esbuild";
import path from "node:path";

const root = path.resolve(process.cwd(), "../..");
const vendor = path.join(root, "vendor/three");
const res = await build({
  stdin: {
    contents: `
      import fs from "node:fs";
      import path from "node:path";
      import * as THREE from "three";
      import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
      const b = fs.readFileSync(path.join(${JSON.stringify(root)}, "assets/models/boss.glb"));
      const ab = b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength);
      const gltf = await new GLTFLoader().parseAsync(ab, "");
      const model = gltf.scene;
      let skel = null;
      model.traverse(n => { if (n.isSkinnedMesh) skel = n.skeleton; });
      const byName = {};
      skel.bones.forEach(bone => {
        bone.userData.restQuat = bone.quaternion.clone();
        bone.userData.restPos = bone.position.clone();
        byName[bone.name] = bone;
      });
      const setDelta = (name, rx, ry, rz, order = "XYZ") => {
        const bone = byName[name];
        const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz, order));
        bone.quaternion.copy(bone.userData.restQuat).multiply(q);
      };
      console.log("Rest RightArm:", byName.RightArm.getWorldPosition(new THREE.Vector3()).toArray().map(x => +x.toFixed(3)),
        "RightForeArm:", byName.RightForeArm.getWorldPosition(new THREE.Vector3()).toArray().map(x => +x.toFixed(3)),
        "RightHand:", byName.RightHand.getWorldPosition(new THREE.Vector3()).toArray().map(x => +x.toFixed(3)));

      const L = THREE.MathUtils.lerp;
      for (const whip of [0, 0.25, 0.5, 0.75, 1.0]) {
        setDelta("Hips", L(0.04, 0.10, whip), L(-0.28, 0.28, whip), 0);
        setDelta("Spine", L(-0.04, 0.08, whip), L(-0.14, 0.16, whip), 0);
        setDelta("Spine1", L(-0.02, 0.06, whip), L(-0.14, 0.16, whip), 0);
        setDelta("Spine2", L(0.02, 0.06, whip), L(-0.16, 0.18, whip), 0);
        // In bind pose, RightArm -> RightForeArm -> RightHand hangs down-right: (-0.135, -0.34, +0.08).
        // Rotating around -Z (-1.05) lifts (-0.135, -0.34) out to horizontal (-0.36, 0)!
        // Then rotating around Y (from -0.75 to +1.15) swings (-0.36, 0) in a horizontal arc from back-right, through wide-right, across the front!
        setDelta("RightArm", L(-0.15, -0.25, whip), L(-0.75, 1.15, whip), L(-1.05, -0.95, whip), "YXZ");
        setDelta("RightForeArm", L(-0.25, -0.35, whip), 0, L(-0.15, -0.20, whip), "YXZ");
        model.updateMatrixWorld(true);
        const pS = byName.RightArm.getWorldPosition(new THREE.Vector3());
        const pE = byName.RightForeArm.getWorldPosition(new THREE.Vector3());
        const pH = byName.RightHand.getWorldPosition(new THREE.Vector3());
        console.log("whip=" + whip.toFixed(2),
          "shoulder=" + JSON.stringify(pS.toArray().map(x => +x.toFixed(3))),
          "elbow=" + JSON.stringify(pE.toArray().map(x => +x.toFixed(3))),
          "hand=" + JSON.stringify(pH.toArray().map(x => +x.toFixed(3))));
      }
    `,
    resolveDir: root,
    loader: "js"
  },
  bundle: true,
  platform: "node",
  format: "esm",
  write: false,
  plugins: [{
    name: "vendored-three",
    setup(b) {
      b.onResolve({ filter: /^three$/ }, () => ({ path: path.join(vendor, "three.module.min.js") }));
      b.onResolve({ filter: /^three\/addons\// }, (args) => ({
        path: path.join(vendor, "addons", args.path.slice("three/addons/".length)),
      }));
    }
  }]
});
await import("data:text/javascript;base64," + Buffer.from(res.outputFiles[0].text).toString("base64"));
