1: /* Mesh-Smearing Handler (world-smear.js)
2:    Implements the Godot "Mesh smearing" technique by celyk:
3:    https://godotshaders.com/shader/mesh-smearing/#main
4:      lag_transform = lag_transform.interpolate_with(global_transform, weight * delta)
5:      float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
6:      MODELVIEW_MATRIX = MODEL_MATRIX + (lag_transform - MODEL_MATRIX) * t;
7:    Adapted for Three.js SkinnedMesh (Mixamo Y Bot):
8:    - Maintains lagging bone transforms (`uLagBoneTexture`) and mid-arc bone transforms (`uMidBoneTexture`)
9:      that smoothly slerp toward the current skeleton pose (`lagQuat.slerp(currQuat, 1 - exp(-weight * dt))`).
10:    - Evaluates continuous 3D gradient noise on the vertex's bind-pose position (`restPos`) so the smear
11:      is 100% seam-free and watertight across both `Alpha_Surface` and `Alpha_Joints`.
12:    - Interpolates each vertex along the curved Quadratic Bezier swing arc `(posCurr -> posMid -> posLag)`
13:      by `t = pow(noise, power) * stretch`, so the smear forms cleanly out of the hand/arm mesh during
14:      the swing and settles smoothly back into the mesh as `lag_transform` catches up. */
15: 
16: import * as THREE from "three";
17: 
18: const SMEAR_SKINNING_PARS_GLSL = /* glsl */ `
19: #ifdef USE_SKINNING
20:   uniform highp sampler2D uMidBoneTexture;
21:   uniform highp sampler2D uLagBoneTexture;
22:   uniform float uSmearNoiseScale;
23:   uniform float uSmearNoisePower;
24:   uniform float uSmearStretch;
25: 
26:   mat4 getSmearBoneMatrix( highp sampler2D tex, const in float i ) {
27:     int size = textureSize( tex, 0 ).x;
28:     int j = int( i ) * 4;
29:     int x = j % size;
30:     int y = j / size;
31:     vec4 v1 = texelFetch( tex, ivec2( x, y ), 0 );
32:     vec4 v2 = texelFetch( tex, ivec2( x + 1, y ), 0 );
33:     vec4 v3 = texelFetch( tex, ivec2( x + 2, y ), 0 );
34:     vec4 v4 = texelFetch( tex, ivec2( x + 3, y ), 0 );
35:     return mat4( v1, v2, v3, v4 );
36:   }
37: 
38:   vec3 smearHash3( vec3 p ) {
39:     p = vec3(
40:       dot( p, vec3( 127.1, 311.7, 74.7 ) ),
41:       dot( p, vec3( 269.5, 183.3, 246.1 ) ),
42:       dot( p, vec3( 113.5, 271.9, 124.6 ) )
43:     );
44:     return -1.0 + 2.0 * fract( sin( p ) * 43758.5453123 );
45:   }
46: 
47:   float smearGradNoise3D( vec3 p ) {
48:     vec3 i = floor( p );
49:     vec3 f = fract( p );
50:     vec3 u = f * f * ( 3.0 - 2.0 * f );
51:     return mix(
52:       mix(
53:         mix( dot( smearHash3( i + vec3( 0.0, 0.0, 0.0 ) ), f - vec3( 0.0, 0.0, 0.0 ) ),
54:              dot( smearHash3( i + vec3( 1.0, 0.0, 0.0 ) ), f - vec3( 1.0, 0.0, 0.0 ) ), u.x ),
55:         mix( dot( smearHash3( i + vec3( 0.0, 1.0, 0.0 ) ), f - vec3( 0.0, 1.0, 0.0 ) ),
56:              dot( smearHash3( i + vec3( 1.0, 1.0, 0.0 ) ), f - vec3( 1.0, 1.0, 0.0 ) ), u.x ),
57:         u.y
58:       ),
59:       mix(
60:         mix( dot( smearHash3( i + vec3( 0.0, 0.0, 1.0 ) ), f - vec3( 0.0, 0.0, 1.0 ) ),
61:              dot( smearHash3( i + vec3( 1.0, 0.0, 1.0 ) ), f - vec3( 1.0, 0.0, 1.0 ) ), u.x ),
62:         mix( dot( smearHash3( i + vec3( 0.0, 1.0, 1.0 ) ), f - vec3( 0.0, 1.0, 1.0 ) ),
63:              dot( smearHash3( i + vec3( 1.0, 1.0, 1.0 ) ), f - vec3( 1.0, 1.0, 1.0 ) ), u.x ),
64:         u.y
65:       ),
66:       u.z
67:     );
68:   }
69: 
70:   float smearFbm( vec3 p ) {
71:     float v = 0.5 + 0.5 * smearGradNoise3D( p );
72:     v = 0.68 * v + 0.32 * ( 0.5 + 0.5 * smearGradNoise3D( p * 2.07 + vec3( 13.7, 29.3, 7.1 ) ) );
73:     /* Normalize noise range so valleys sit at 0.0 and ridges reach 1.0 before pow(n, power) */
74:     return smoothstep( 0.24, 0.78, v );
75:   }
76: #endif
77: `;
