79: const SMEAR_SKINNING_VERTEX_GLSL = /* glsl */ `
80:   float smearTVal = 0.0;
81: #ifdef USE_SKINNING
82:   vec3 restPos = transformed;
83:   vec4 skinVertex = bindMatrix * vec4( transformed, 1.0 );
84:   vec4 skinned = vec4( 0.0 );
85:   skinned += boneMatX * skinVertex * skinWeight.x;
86:   skinned += boneMatY * skinVertex * skinWeight.y;
87:   skinned += boneMatZ * skinVertex * skinWeight.z;
88:   skinned += boneMatW * skinVertex * skinWeight.w;
89: 
90:   /* Right-arm & hand mask in Y Bot bind space (centimeters: shoulder x=-18, elbow x=-46, hand x=-74..-97, y=134..154).
91:      Computed continuously from restPos so there are zero bone steps or cracks between meshes. */
92:   float isRightArm = smoothstep( -14.0, -24.0, restPos.x ) * smoothstep( 128.0, 134.0, restPos.y ) * ( 1.0 - smoothstep( 155.0, 160.0, restPos.y ) );
93:   float armDist = clamp( ( -restPos.x - 18.0 ) / 75.0, 0.0, 1.0 ) * isRightArm;
94:   /* Emphasize the hand and forearm along the arc swing */
95:   float handMask = smoothstep( 0.04, 0.65, armDist ) * ( 0.32 + 0.68 * smoothstep( 0.30, 0.82, armDist ) );
96: 
97:   if ( handMask > 0.001 ) {
98:     mat4 midMatX = getSmearBoneMatrix( uMidBoneTexture, skinIndex.x );
99:     mat4 midMatY = getSmearBoneMatrix( uMidBoneTexture, skinIndex.y );
100:     mat4 midMatZ = getSmearBoneMatrix( uMidBoneTexture, skinIndex.z );
101:     mat4 midMatW = getSmearBoneMatrix( uMidBoneTexture, skinIndex.w );
102:     vec4 skinnedMid = (
103:       midMatX * skinWeight.x +
104:       midMatY * skinWeight.y +
105:       midMatZ * skinWeight.z +
106:       midMatW * skinWeight.w
107:     ) * skinVertex;
108: 
109:     mat4 lagMatX = getSmearBoneMatrix( uLagBoneTexture, skinIndex.x );
110:     mat4 lagMatY = getSmearBoneMatrix( uLagBoneTexture, skinIndex.y );
111:     mat4 lagMatZ = getSmearBoneMatrix( uLagBoneTexture, skinIndex.z );
112:     mat4 lagMatW = getSmearBoneMatrix( uLagBoneTexture, skinIndex.w );
113:     vec4 skinnedLag = (
114:       lagMatX * skinWeight.x +
115:       lagMatY * skinWeight.y +
116:       lagMatZ * skinWeight.z +
117:       lagMatW * skinWeight.w
118:     ) * skinVertex;
119: 
120:     vec3 wakeVec = skinnedLag.xyz - skinned.xyz;
121:     float wakeLen = length( wakeVec );
122:     if ( wakeLen > 0.002 ) {
123:       vec3 wakeDir = wakeVec / wakeLen;
124:       /* Smooth cylindrical outward normal around the bind-pose arm axis (y=143.6, z=-5.8),
125:          rotated into world space so only the trailing side of the moving hand/arm stretches back
126:          while the leading edge stays crisp and watertight. */
127:       vec3 cylNormalBind = normalize( vec3( 0.0, restPos.y - 143.6, restPos.z + 5.8 ) );
128:       vec3 cylNormalWS = normalize( mat3( boneMatX ) * cylNormalBind );
129:       float trailAlign = smoothstep( -0.25, 0.55, dot( cylNormalWS, wakeDir ) );
