  float getRightArmBoneMask( const in float idx ) {
    int b = int( idx + 0.5 );
    if ( b == 13 ) return 1.0;
    if ( b == 12 ) return 0.84;
    if ( b == 11 ) return 0.42;
    if ( b == 10 ) return 0.12;
    return 0.0;
