        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 0.0 ) ), f - vec3( 0.0, 0.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 0.0 ) ), f - vec3( 1.0, 0.0, 0.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 0.0 ) ), f - vec3( 0.0, 1.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 0.0 ) ), f - vec3( 1.0, 1.0, 0.0 ) ), u.x ),
        u.y
      ),
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 1.0 ) ), f - vec3( 0.0, 0.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 1.0 ) ), f - vec3( 1.0, 0.0, 1.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 1.0 ) ), f - vec3( 0.0, 1.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 1.0 ) ), f - vec3( 1.0, 1.0, 1.0 ) ), u.x ),
        u.y
      ),
      u.z
    );
  }

  float smearFbm( vec3 p ) {
    float v = 0.5 + 0.5 * smearGradNoise3D( p );
    v = 0.68 * v + 0.32 * ( 0.5 + 0.5 * smearGradNoise3D( p * 2.07 + vec3( 13.7, 29.3, 7.1 ) ) );
    /* Normalize noise range so valleys sit at 0.0 and ridges reach 1.0 before pow(n, power) */
    return smoothstep( 0.24, 0.78, v );
  }
#endif
`;

const SMEAR_SKINNING_VERTEX_GLSL = /* glsl */ `
  float smearTVal = 0.0;
#ifdef USE_SKINNING
  vec3 restPos = transformed;
  vec4 skinVertex = bindMatrix * vec4( transformed, 1.0 );
  vec4 skinned = vec4( 0.0 );
  skinned += boneMatX * skinVertex * skinWeight.x;
  skinned += boneMatY * skinVertex * skinWeight.y;
  skinned += boneMatZ * skinVertex * skinWeight.z;
  skinned += boneMatW * skinVertex * skinWeight.w;

  /* Right-arm & hand mask in Y Bot bind space (centimeters: shoulder x=-18, elbow x=-46, hand x=-74..-97, y=134..154).
     Computed continuously from restPos so there are zero bone steps or cracks between meshes. */
  float isRightArm = smoothstep( -14.0, -24.0, restPos.x ) * smoothstep( 128.0, 134.0, restPos.y ) * ( 1.0 - smoothstep( 155.0, 160.0, restPos.y ) );
  float armDist = clamp( ( -restPos.x - 18.0 ) / 75.0, 0.0, 1.0 ) * isRightArm;
  /* Emphasize the hand and forearm along the arc swing */
  float handMask = smoothstep( 0.04, 0.65, armDist ) * ( 0.32 + 0.68 * smoothstep( 0.30, 0.82, armDist ) );

  if ( handMask > 0.001 ) {
    mat4 midMatX = getSmearBoneMatrix( uMidBoneTexture, skinIndex.x );
    mat4 midMatY = getSmearBoneMatrix( uMidBoneTexture, skinIndex.y );
    mat4 midMatZ = getSmearBoneMatrix( uMidBoneTexture, skinIndex.z );
    mat4 midMatW = getSmearBoneMatrix( uMidBoneTexture, skinIndex.w );
    vec4 skinnedMid = (
      midMatX * skinWeight.x +
      midMatY * skinWeight.y +
      midMatZ * skinWeight.z +
      midMatW * skinWeight.w
    ) * skinVertex;

    mat4 lagMatX = getSmearBoneMatrix( uLagBoneTexture, skinIndex.x );
    mat4 lagMatY = getSmearBoneMatrix( uLagBoneTexture, skinIndex.y );
    mat4 lagMatZ = getSmearBoneMatrix( uLagBoneTexture, skinIndex.z );
    mat4 lagMatW = getSmearBoneMatrix( uLagBoneTexture, skinIndex.w );
    vec4 skinnedLag = (
      lagMatX * skinWeight.x +
      lagMatY * skinWeight.y +
      lagMatZ * skinWeight.z +
      lagMatW * skinWeight.w
    ) * skinVertex;

    vec3 wakeVec = skinnedLag.xyz - skinned.xyz;
    float wakeLen = length( wakeVec );
    if ( wakeLen > 0.002 ) {
      vec3 wakeDir = wakeVec / wakeLen;
      /* Smooth cylindrical outward normal around the bind-pose arm axis (y=143.6, z=-5.8),
         rotated into world space so only the trailing side of the moving hand/arm stretches
         while the leading edge stays crisp and watertight. */
      vec3 cylNormalBind = normalize( vec3( 0.0, restPos.y - 143.6, restPos.z + 5.8 ) );
      vec3 cylNormalWS = normalize( mat3( boneMatX ) * cylNormalBind );
      float trailAlign = smoothstep( -0.25, 0.55, dot( cylNormalWS, wakeDir ) );

      /* Godot mesh-smearing formula:
         float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
         Evaluated on 3D bind-pose restPos with a cohesive trailing base plus fine longitudinal streaks
         so the smear forms a smooth, unified arc on the hand/forearm and settles cleanly onto the mesh. */
      vec3 noisePos = vec3(
        restPos.x * uSmearNoiseScale * 0.28,
        restPos.y * uSmearNoiseScale * 1.45,
        restPos.z * uSmearNoiseScale * 1.45
      );
      float n = smearFbm( noisePos );
      float streakProfile = 0.20 + 0.80 * pow( n, uSmearNoisePower );
      float t = streakProfile * uSmearStretch * handMask * trailAlign;
      t = clamp( t, 0.0, 1.28 );

      /* Quadratic Bezier interpolation through skinned (t=0), skinnedMid (t=0.5), skinnedLag (t=1.0)
         so the smear curves smoothly along the circular swing arc of the arm and hand! */
      vec3 ctrl = 2.0 * skinnedMid.xyz - 0.5 * ( skinned.xyz + skinnedLag.xyz );
      float u = 1.0 - t;
      vec3 arcWS = u * u * skinned.xyz + 2.0 * u * t * ctrl + t * t * skinnedLag.xyz;
      skinned.xyz = arcWS;
      smearTVal = clamp( t * clamp( wakeLen * 1.6, 0.0, 1.0 ), 0.0, 1.0 );
    }
  }
  transformed = ( bindMatrixInverse * skinned ).xyz;
#endif
`;

export function createSmearHandler(options = {}) {
  const config = {
    weight: options.weight ?? 9.5, /* Godot lag_transform interpolation weight */
    noiseScale: options.noiseScale ?? 0.34,
    noisePower: options.noisePower ?? 3.4,
    stretch: options.stretch ?? 1.42,
  };

args.Content:
/* Mesh-Smearing Handler (world-smear.js)
   Implements the Godot "Mesh smearing" technique by celyk:
   https://godotshaders.com/shader/mesh-smearing/#main
     lag_transform = lag_transform.interpolate_with(global_transform, weight * delta)
     float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
     MODELVIEW_MATRIX = MODEL_MATRIX + (lag_transform - MODEL_MATRIX) * t;
   Adapted for Three.js SkinnedMesh (`assets/models/boss.glb`):
   - Maintains lagging bone transforms (`uLagBoneTexture`) and mid-arc bone transforms (`uMidBoneTexture`)
     that smoothly slerp toward the current skeleton pose (`lagQuat.slerp(currQuat, 1 - exp(-weight * dt))`).
   - Evaluates continuous 3D gradient noise on the vertex's bind-pose position (`restPos`) so the smear
     is 100% seam-free and watertight across UV islands.
   - Interpolates each vertex along the curved Quadratic Bezier swing arc `(posCurr -> posMid -> posLag)`
     by `t = pow(noise, power) * stretch`, so the smear forms cleanly out of the right claw/arm mesh during
     the swing and settles smoothly back into the mesh as `lag_transform` catches up. */

import * as THREE from "three";

const SMEAR_SKINNING_PARS_GLSL = /* glsl */ `
#ifdef USE_SKINNING
  uniform highp sampler2D uMidBoneTexture;
  uniform highp sampler2D uLagBoneTexture;
  uniform float uSmearNoiseScale;
  uniform float uSmearNoisePower;
  uniform float uSmearStretch;

  mat4 getSmearBoneMatrix( highp sampler2D tex, const in float i ) {
    int size = textureSize( tex, 0 ).x;
    int j = int( i ) * 4;
    int x = j % size;
    int y = j / size;
    vec4 v1 = texelFetch( tex, ivec2( x, y ), 0 );
    vec4 v2 = texelFetch( tex, ivec2( x + 1, y ), 0 );
    vec4 v3 = texelFetch( tex, ivec2( x + 2, y ), 0 );
    vec4 v4 = texelFetch( tex, ivec2( x + 3, y ), 0 );
    return mat4( v1, v2, v3, v4 );
  }

  /* Bone indices in assets/models/boss.glb:
     10 = RightShoulder, 11 = RightArm, 12 = RightForeArm, 13 = RightHand */
  float getRightArmBoneMask( const in float idx ) {
    int b = int( idx + 0.5 );
    if ( b == 13 ) return 1.0;
    if ( b == 12 ) return 0.84;
    if ( b == 11 ) return 0.42;
    if ( b == 10 ) return 0.12;
    return 0.0;
  }

  vec3 smearHash3( vec3 p ) {
    p = vec3(
      dot( p, vec3( 127.1, 311.7, 74.7 ) ),
      dot( p, vec3( 269.5, 183.3, 246.1 ) ),
      dot( p, vec3( 113.5, 271.9, 124.6 ) )
    );
    return -1.0 + 2.0 * fract( sin( p ) * 43758.5453123 );
  }

  float smearGradNoise3D( vec3 p ) {
    vec3 i = floor( p );
    vec3 f = fract( p );
    vec3 u = f * f * ( 3.0 - 2.0 * f );
    return mix(
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 0.0 ) ), f - vec3( 0.0, 0.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 0.0 ) ), f - vec3( 1.0, 0.0, 0.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 0.0 ) ), f - vec3( 0.0, 1.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 0.0 ) ), f - vec3( 1.0, 1.0, 0.0 ) ), u.x ),
        u.y
      ),
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 1.0 ) ), f - vec3( 0.0, 0.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 1.0 ) ), f - vec3( 1.0, 0.0, 1.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 1.0 ) ), f - vec3( 0.0, 1.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 1.0 ) ), f - vec3( 1.0, 1.0, 1.0 ) ), u.x ),
        u.y
      ),
      u.z
    );
  }

  float smearFbm( vec3 p ) {
    float v = 0.5 + 0.5 * smearGradNoise3D( p );
    v = 0.68 * v + 0.32 * ( 0.5 + 0.5 * smearGradNoise3D( p * 2.07 + vec3( 13.7, 29.3, 7.1 ) ) );
    /* Normalize noise range so valleys sit at 0.0 and ridges reach 1.0 before pow(n, power) */
    return smoothstep( 0.24, 0.78, v );
  }
#endif
`;

const SMEAR_SKINNING_VERTEX_GLSL = /* glsl */ `
  float smearTVal = 0.0;
#ifdef USE_SKINNING
  vec3 restPos = transformed;
  vec4 skinVertex = bindMatrix * vec4( transformed, 1.0 );
  vec4 skinned = vec4( 0.0 );
  skinned += boneMatX * skinVertex * skinWeight.x;
  skinned += boneMatY * skinVertex * skinWeight.y;
  skinned += boneMatZ * skinVertex * skinWeight.z;
  skinned += boneMatW * skinVertex * skinWeight.w;

  /* Smooth right-arm & claw mask from skin weights (bones 10..13) + bind-pose distal gradient */
  float boneArmMask =
    getRightArmBoneMask( skinIndex.x ) * skinWeight.x +
    getRightArmBoneMask( skinIndex.y ) * skinWeight.y +
    getRightArmBoneMask( skinIndex.z ) * skinWeight.z +
    getRightArmBoneMask( skinIndex.w ) * skinWeight.w;
  float distalBoost = 0.55 + 0.45 * ( 1.0 - smoothstep( 0.22, 0.68, restPos.y ) );
  float handMask = clamp( boneArmMask * distalBoost, 0.0, 1.0 );

  if ( handMask > 0.001 ) {
    mat4 midMatX = getSmearBoneMatrix( uMidBoneTexture, skinIndex.x );
    mat4 midMatY = getSmearBoneMatrix( uMidBoneTexture, skinIndex.y );
    mat4 midMatZ = getSmearBoneMatrix( uMidBoneTexture, skinIndex.z );
    mat4 midMatW = getSmearBoneMatrix( uMidBoneTexture, skinIndex.w );
    vec4 skinnedMid = (
      midMatX * skinWeight.x +
      midMatY * skinWeight.y +
      midMatZ * skinWeight.z +
      midMatW * skinWeight.w
    ) * skinVertex;

    mat4 lagMatX = getSmearBoneMatrix( uLagBoneTexture, skinIndex.x );
    mat4 lagMatY = getSmearBoneMatrix( uLagBoneTexture, skinIndex.y );
    mat4 lagMatZ = getSmearBoneMatrix( uLagBoneTexture, skinIndex.z );
    mat4 lagMatW = getSmearBoneMatrix( uLagBoneTexture, skinIndex.w );
    vec4 skinnedLag = (
      lagMatX * skinWeight.x +
      lagMatY * skinWeight.y +
      lagMatZ * skinWeight.z +
      lagMatW * skinWeight.w
    ) * skinVertex;

    vec3 wakeVec = skinnedLag.xyz - skinned.xyz;
    float wakeLen = length( wakeVec );
    if ( wakeLen > 0.0005 ) {
      vec3 wakeDir = wakeVec / wakeLen;
      /* Smooth cylindrical outward normal around the A-pose right arm axis (x=-0.34, z=0.01),
         rotated by the dominant bone matrix so only the trailing side of the moving claw/arm stretches
         back along the arc while the leading edge stays crisp and watertight. */
      vec3 cylNormalBind = normalize( vec3( restPos.x + 0.34, ( restPos.y - 0.44 ) * 0.25, restPos.z - 0.01 ) );
      vec3 cylNormalWS = normalize( mat3( boneMatX ) * cylNormalBind );
      float trailAlign = smoothstep( -0.22, 0.52, dot( cylNormalWS, wakeDir ) );

      /* Godot mesh-smearing formula:
         float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
         Evaluated on 3D bind-pose restPos with a cohesive trailing base plus fine longitudinal streaks
         so the smear forms a smooth, unified arc on the claw/forearm and settles cleanly onto the mesh. */
      vec3 noisePos = vec3(
        restPos.x * uSmearNoiseScale * 1.35,
        restPos.y * uSmearNoiseScale * 0.52,
        restPos.z * uSmearNoiseScale * 1.35
      );
      float n = smearFbm( noisePos );
      float streakProfile = 0.18 + 0.82 * pow( n, uSmearNoisePower );
      float t = streakProfile * uSmearStretch * handMask * trailAlign;
      t = clamp( t, 0.0, 1.30 );

      /* Quadratic Bezier interpolation through skinned (t=0), skinnedMid (t=0.5), skinnedLag (t=1.0)
         so the smear curves smoothly along the circular swing arc of the arm and claw! */
      vec3 ctrl = 2.0 * skinnedMid.xyz - 0.5 * ( skinned.xyz + skinnedLag.xyz );
      float u = 1.0 - t;
      vec3 arcWS = u * u * skinned.xyz + 2.0 * u * t * ctrl + t * t * skinnedLag.xyz;
      skinned.xyz = arcWS;
      smearTVal = clamp( t * clamp( wakeLen * 4.5, 0.0, 1.0 ), 0.0, 1.0 );
    }
  }
  transformed = ( bindMatrixInverse * skinned ).xyz;
#endif
`;

export function createSmearHandler(options = {}) {
  const config = {
    weight: options.weight ?? 9.5, /* Godot lag_transform interpolation weight */
    noiseScale: options.noiseScale ?? 34.0,
    noisePower: options.noisePower ?? 2.6,
    stretch: options.stretch ?? 1.35,
  };

  /* Fallback 16x16 DataTextures until the skeleton is bound */
  const makeBoneTex = (size) => {
    const data = new Float32Array(size * size * 4);
    const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.FloatType);
    tex.needsUpdate = true;
    return { data, tex };
  };
  let midBuf = makeBoneTex(16);
  let lagBuf = makeBoneTex(16);

  const uniforms = {
    uMidBoneTexture: { value: midBuf.tex },
    uLagBoneTexture: { value: lagBuf.tex },
    uSmearNoiseScale: { value: config.noiseScale },
    uSmearNoisePower: { value: config.noisePower },
    uSmearStretch: { value: config.stretch },
  };

  const depthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
  depthMaterial.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace("#include <skinning_pars_vertex>", `#include <skinning_pars_vertex>\n${SMEAR_SKINNING_PARS_GLSL}`)
      .replace("#include <skinning_vertex>", SMEAR_SKINNING_VERTEX_GLSL);
  };
  depthMaterial.customProgramCacheKey = () => "godot-mesh-smear-depth";

  const enhanceMaterial = (material) => {
    const prev = material.onBeforeCompile;
    const baseKey = material.customProgramCacheKey?.() || "soft-toon";
    material.onBeforeCompile = (shader, renderer) => {
      prev?.(shader, renderer);
      Object.assign(shader.uniforms, uniforms);
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <skinning_pars_vertex>",
          `#include <skinning_pars_vertex>\n${SMEAR_SKINNING_PARS_GLSL}\nvarying float vSmearT;`,
        )
        .replace(
          "#include <skinning_vertex>",
          `${SMEAR_SKINNING_VERTEX_GLSL}\nvSmearT = smearTVal;`,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace("#include <common>", "#include <common>\nvarying float vSmearT;")
        .replace(
          "#include <opaque_fragment>",
          [
            "if (vSmearT > 0.01) {",
            "  /* Subtle ember ridge highlight so the volcanic claw's mesh-smear spikes read clearly */",
            "  float ridge = smoothstep(0.08, 0.78, vSmearT);",
            "  outgoingLight = mix(outgoingLight, outgoingLight * 1.12 + vec3(0.26, 0.08, 0.02), ridge * 0.65);",
            "}",
            "#include <opaque_fragment>",
          ].join("\n"),
        );
    };
    material.customProgramCacheKey = () => `${baseKey}-godot-mesh-smear`;
    return material;
  };

  let boundSkeleton = null;
  let boundRoot = null;
  let boneWeights = [];
  let currPos = [];
  let currQuat = [];
  let lagPos = [];
  let lagQuat = [];
  let initialized = false;
  let handBoneIdx = -1;
  let lastLagDistance = 0;
  const tmpOffsetMat = new THREE.Matrix4();
  const tmpCurrHandWS = new THREE.Vector3();
  const tmpLagHandWS = new THREE.Vector3();

  const bindSkeleton = (skeleton, rootGroup) => {
    boundSkeleton = skeleton;
    boundRoot = rootGroup;
    skeleton.computeBoneTexture();
    const size = skeleton.boneTexture.image.width;
    midBuf = makeBoneTex(size);
    lagBuf = makeBoneTex(size);
    uniforms.uMidBoneTexture.value = midBuf.tex;
    uniforms.uLagBoneTexture.value = lagBuf.tex;

    const count = skeleton.bones.length;
    boneWeights = new Array(count).fill(100);
    currPos = new Array(count);
    currQuat = new Array(count);
    lagPos = new Array(count);
    lagQuat = new Array(count);
    handBoneIdx = -1;

    for (let i = 0; i < count; i += 1) {
      const b = skeleton.bones[i];
      const name = b.name.replace(/^mixamorig\d*:?/, "");
      currPos[i] = b.position.clone();
      currQuat[i] = b.quaternion.clone();
      lagPos[i] = b.position.clone();
      lagQuat[i] = b.quaternion.clone();
      if (name === "RightHand") handBoneIdx = i;

      /* Only the right arm chain + upper spine twist lag behind; legs/hips/left arm stay at 0 */
      if (/^Right(Shoulder|Arm|ForeArm|Hand)/.test(name)) {
        boneWeights[i] = 1.0; /* uses config.weight directly */
      } else if (name === "Spine1" || name === "Spine2") {
        boneWeights[i] = 1.85; /* subtle upper-torso arc follow */
      } else {
        boneWeights[i] = 0; /* 0 means snap immediately to current pose */
      }
    }
    initialized = false;
  };

  const writeBoneMatricesTo = (targetArray) => {
    const bones = boundSkeleton.bones;
    const inverses = boundSkeleton.boneInverses;
    for (let i = 0; i < bones.length; i += 1) {
      tmpOffsetMat.multiplyMatrices(bones[i].matrixWorld, inverses[i]);
      tmpOffsetMat.toArray(targetArray, i * 16);
    }
  };

  const reset = () => {
    if (!boundSkeleton) return;
    const bones = boundSkeleton.bones;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      lagPos[i].copy(bones[i].position);
      lagQuat[i].copy(bones[i].quaternion);
    }
    boundRoot?.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    writeBoneMatricesTo(lagBuf.data);
    midBuf.tex.needsUpdate = true;
    lagBuf.tex.needsUpdate = true;
    lastLagDistance = 0;
    initialized = true;
  };

  /* Advance lag_transform = lag_transform.interpolate_with(global_transform, weight * dt)
     and populate uMidBoneTexture (slerp 0.5) and uLagBoneTexture (slerp 1.0). */
  const stepLag = (dt, weightOverride = null) => {
    if (!boundSkeleton || !boundRoot) return;
    const bones = boundSkeleton.bones;
    if (!initialized) {
      reset();
      return;
    }
    const baseWeight = weightOverride ?? config.weight;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      const mult = boneWeights[i];
      if (mult <= 0 || dt <= 0) {
        lagPos[i].copy(currPos[i]);
        lagQuat[i].copy(currQuat[i]);
      } else {
        const alpha = 1 - Math.exp(-(baseWeight * mult) * dt);
        lagPos[i].lerp(currPos[i], alpha);
        lagQuat[i].slerp(currQuat[i], alpha);
      }
    }

    if (handBoneIdx >= 0) {
      bones[handBoneIdx].getWorldPosition(tmpCurrHandWS);
    }

    /* 1. Compute uLagBoneTexture at lagQuat */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(lagPos[i]);
      bones[i].quaternion.copy(lagQuat[i]);
    }
    boundRoot.updateMatrixWorld(true);
    writeBoneMatricesTo(lagBuf.data);
    lagBuf.tex.needsUpdate = true;
    if (handBoneIdx >= 0) {
      bones[handBoneIdx].getWorldPosition(tmpLagHandWS);
      lastLagDistance = tmpCurrHandWS.distanceTo(tmpLagHandWS);
    }

    /* 2. Compute uMidBoneTexture halfway along the rotational arc (slerp 0.5) */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(lagPos[i]).lerp(currPos[i], 0.5);
      bones[i].quaternion.copy(lagQuat[i]).slerp(currQuat[i], 0.5);
    }
    boundRoot.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    midBuf.tex.needsUpdate = true;

    /* 3. Restore current skeleton pose */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(currPos[i]);
      bones[i].quaternion.copy(currQuat[i]);
    }
    boundRoot.updateMatrixWorld(true);
  };

  return {
    uniforms,
    depthMaterial,
    enhanceMaterial,
    bindSkeleton,
    reset,
    stepLag,
    getLagDistance: () => +lastLagDistance.toFixed(3),
  };
}

/* Boss Animation Pose & Joint Articulation Handler (world-boss-anim.js)
   Computes procedural Sekiro/Soulslike poses for the rigged volcanic colossus (`assets/models/boss.glb`):
   1. "idle"  — heavy, poised colossus combat guard with rhythmic chest heave & weight shift
   2. "run"   — powerful forward charge with counter-rotating torso and heavy stride
   3. "punch" — wide horizontal right-claw arc swing at chest height designed to showcase the Godot
                mesh-smearing (`lag_transform` + `pow(noise, exp)`) forming along the
                curved claw/forearm arc and settling cleanly back into the mesh. */

import * as THREE from "three";

export const BOSS_PUNCH_DURATION = 1.24;

const tmpEuler = new THREE.Euler();
const tmpDeltaQuat = new THREE.Quaternion();
const tmpTargetQuat = new THREE.Quaternion();

export function computeBossPose(state, time, runPhase, punchTime) {
  const ss = THREE.MathUtils.smoothstep;
  const L = THREE.MathUtils.lerp;

  const pose = {
    hipsPos: [0, 0, 0], /* delta in model units relative to Hips restPos [0, 0.48, 0.015] */
    Hips: [0, 0, 0],
    Spine: [0, 0, 0],
    Spine1: [0, 0, 0],
    Spine2: [0, 0, 0],
    Neck: [0, 0, 0],
    Head: [0, 0, 0],
    LeftShoulder: [0, 0, 0],
    LeftArm: [0, 0, 0],
    LeftForeArm: [0, 0, 0],
    LeftHand: [0, 0, 0],
    RightShoulder: [0, 0, 0],
    RightArm: [0, 0, 0],
    RightForeArm: [0, 0, 0],
    RightHand: [0, 0, 0],
    LeftUpLeg: [0, 0, 0],
    LeftLeg: [0, 0, 0],
    LeftFoot: [0, 0, 0],
    RightUpLeg: [0, 0, 0],
    RightLeg: [0, 0, 0],
    RightFoot: [0, 0, 0],
  };

  if (state === "run") {
    const p = runPhase;
    const s1 = Math.sin(p);
    const c1 = Math.cos(p);
    const bob = Math.abs(s1);
    pose.hipsPos = [c1 * 0.014, -0.028 + (bob - 0.5) * 0.036, 0];
    pose.Hips = [0.14, -s1 * 0.16, c1 * 0.05];
    pose.Spine = [0.12 + bob * 0.04, s1 * 0.10, -c1 * 0.04];
    pose.Spine1 = [0.08, s1 * 0.10, 0];
    pose.Spine2 = [0.08, s1 * 0.12, 0];
    pose.Neck = [-0.14, -s1 * 0.08, 0];
    pose.Head = [-0.12, -s1 * 0.08, 0];
    /* Pumping claw arms in heavy charge (YXZ order: rx < 0 swings arm forward +Z, rz lifts outward) */
    pose.LeftArm = [-0.18 + s1 * 0.58, -0.12, 0.16];
    pose.LeftForeArm = [-0.62 - Math.max(0, -s1) * 0.25, 0, 0.10];
    pose.RightArm = [-0.18 - s1 * 0.58, 0.12, -0.16];
    pose.RightForeArm = [-0.62 - Math.max(0, s1) * 0.25, 0, -0.10];
    /* Stride: rx < 0 lifts thigh forward (+Z), rx > 0 bends shin backward (-Z) */
    pose.LeftUpLeg = [-s1 * 0.58 - 0.08, 0, 0];
    pose.LeftLeg = [0.18 + Math.max(0, -c1) * 0.68, 0, 0];
    pose.LeftFoot = [-0.08 + s1 * 0.18, 0, 0];
    pose.RightUpLeg = [s1 * 0.58 - 0.08, 0, 0];
    pose.RightLeg = [0.18 + Math.max(0, c1) * 0.68, 0, 0];
    pose.RightFoot = [-0.08 - s1 * 0.18, 0, 0];
    return pose;
  }

  if (state === "punch") {
    const u = THREE.MathUtils.clamp(punchTime, 0, BOSS_PUNCH_DURATION);
    const idle = computeBossPose("idle", time, runPhase, 0);

    if (u < 0.36) {
      /* Phase 1: Wind-up — coil torso right and raise the giant right claw wide behind the right shoulder */
      const w = ss(u, 0.0, 0.34);
      const blend = (a, b) => [L(a[0], b[0], w), L(a[1], b[1], w), L(a[2], b[2], w)];
      pose.hipsPos = blend(idle.hipsPos, [-0.018, -0.032, -0.025]);
      pose.Hips = blend(idle.Hips, [0.04, -0.28, -0.04]);
      pose.Spine = blend(idle.Spine, [-0.03, -0.14, -0.03]);
      pose.Spine1 = blend(idle.Spine1, [-0.02, -0.15, 0]);
      pose.Spine2 = blend(idle.Spine2, [0.02, -0.16, 0]);
      pose.Neck = blend(idle.Neck, [0.02, 0.24, 0]);
      pose.Head = blend(idle.Head, [0.02, 0.28, 0]);
      /* Left claw guards left flank; Right claw lifts to chest height (rz = -0.96) and opens wide back-right (ry = -0.78) */
      pose.LeftShoulder = blend(idle.LeftShoulder, [0, 0, 0.06]);
      pose.LeftArm = blend(idle.LeftArm, [-0.36, -0.25, 0.28]);
      pose.LeftForeArm = blend(idle.LeftForeArm, [-0.58, 0, 0.18]);
      pose.RightShoulder = blend(idle.RightShoulder, [0, -0.12, -0.10]);
      pose.RightArm = blend(idle.RightArm, [-0.14, -0.78, -0.96]);
      pose.RightForeArm = blend(idle.RightForeArm, [-0.24, 0, -0.16]);
      pose.RightHand = blend(idle.RightHand, [0, 0, -0.08]);
      /* Braced lunge stance */
      pose.LeftUpLeg = blend(idle.LeftUpLeg, [-0.30, 0.05, 0]);
      pose.LeftLeg = blend(idle.LeftLeg, [0.46, 0, 0]);
      pose.LeftFoot = blend(idle.LeftFoot, [-0.16, 0, 0]);
      pose.RightUpLeg = blend(idle.RightUpLeg, [0.22, -0.05, 0]);
      pose.RightLeg = blend(idle.RightLeg, [0.30, 0, 0]);
      pose.RightFoot = blend(idle.RightFoot, [-0.36, 0, 0]);
      return pose;
    }

    if (u < 0.78) {
      /* Phase 2 (0.36..0.55): Wide chest-level circular arc swing across the front (ry: -0.78 -> 0.0 -> +1.44).
         Phase 3 (0.55..0.78): Follow-through hold across chest while `lag_transform` settles cleanly into the claw mesh. */
      const rawS = THREE.MathUtils.clamp((u - 0.36) / 0.19, 0, 1);
      const whip = 1 - Math.pow(1 - rawS, 2.4);
      pose.hipsPos = [L(-0.018, 0.022, whip), L(-0.032, -0.040, whip), L(-0.025, 0.048, whip)];
      pose.Hips = [L(0.04, 0.10, whip), L(-0.28, 0.26, whip), L(-0.04, 0.05, whip)];
      pose.Spine = [L(-0.03, 0.06, whip), L(-0.14, 0.15, whip), L(-0.03, 0.04, whip)];
      pose.Spine1 = [L(-0.02, 0.05, whip), L(-0.15, 0.15, whip), 0];
      pose.Spine2 = [L(0.02, 0.06, whip), L(-0.16, 0.18, whip), 0];
      pose.Neck = [L(0.02, -0.06, whip), L(0.24, -0.24, whip), 0];
      pose.Head = [L(0.02, -0.06, whip), L(0.28, -0.28, whip), 0];
      /* Left arm pulls back to counter-balance the heavy claw sweep */
      pose.LeftShoulder = [0, 0, L(0.06, 0.12, whip)];
      pose.LeftArm = [L(-0.36, 0.24, whip), L(-0.25, 0.32, whip), L(0.28, 0.38, whip)];
      pose.LeftForeArm = [L(-0.58, -0.45, whip), 0, 0.18];
      /* Right claw sweeps a wide horizontal circular arc across the front at chest height */
      pose.RightShoulder = [0, L(-0.12, 0.18, whip), L(-0.10, -0.06, whip)];
      pose.RightArm = [
        L(-0.14, -0.18, whip),
        L(-0.78, 1.44, whip),
        L(-0.96, -0.88, whip),
      ];
      pose.RightForeArm = [L(-0.24, -0.34, whip), 0, L(-0.16, -0.22, whip)];
      pose.RightHand = [0, 0, L(-0.08, -0.12, whip)];
      pose.LeftUpLeg = [L(-0.30, -0.38, whip), L(0.05, -0.05, whip), 0];
      pose.LeftLeg = [L(0.46, 0.54, whip), 0, 0];
      pose.LeftFoot = [L(-0.16, -0.14, whip), 0, 0];
      pose.RightUpLeg = [L(0.22, 0.28, whip), L(-0.05, 0.05, whip), 0];
      pose.RightLeg = [L(0.30, 0.22, whip), 0, 0];
      pose.RightFoot = [L(-0.36, -0.40, whip), 0, 0];
      return pose;
    }

    /* Phase 4 (0.78..1.24): Smooth recovery back to colossus idle stance */
    const rec = ss(u, 0.78, BOSS_PUNCH_DURATION);
    const follow = computeBossPose("punch", time, runPhase, 0.77);
    const blend = (a, b) => [L(a[0], b[0], rec), L(a[1], b[1], rec), L(a[2], b[2], rec)];
    pose.hipsPos = blend(follow.hipsPos, idle.hipsPos);
    pose.Hips = blend(follow.Hips, idle.Hips);
    pose.Spine = blend(follow.Spine, idle.Spine);
    pose.Spine1 = blend(follow.Spine1, idle.Spine1);
    pose.Spine2 = blend(follow.Spine2, idle.Spine2);
    pose.Neck = blend(follow.Neck, idle.Neck);
    pose.Head = blend(follow.Head, idle.Head);
    pose.LeftShoulder = blend(follow.LeftShoulder, idle.LeftShoulder);
    pose.LeftArm = blend(follow.LeftArm, idle.LeftArm);
    pose.LeftForeArm = blend(follow.LeftForeArm, idle.LeftForeArm);
    pose.RightShoulder = blend(follow.RightShoulder, idle.RightShoulder);
    pose.RightArm = blend(follow.RightArm, idle.RightArm);
    pose.RightForeArm = blend(follow.RightForeArm, idle.RightForeArm);
    pose.RightHand = blend(follow.RightHand, idle.RightHand);
    pose.LeftUpLeg = blend(follow.LeftUpLeg, idle.LeftUpLeg);
    pose.LeftLeg = blend(follow.LeftLeg, idle.LeftLeg);
    pose.LeftFoot = blend(follow.LeftFoot, idle.LeftFoot);
    pose.RightUpLeg = blend(follow.RightUpLeg, idle.RightUpLeg);
    pose.RightLeg = blend(follow.RightLeg, idle.RightLeg);
    pose.RightFoot = blend(follow.RightFoot, idle.RightFoot);
    return pose;
  }

  /* Default: Poised volcanic colossus combat Idle ("idle") */
  const breath = Math.sin(time * 2.3);
  const sway = Math.sin(time * 1.15);
  const crouch = 0.5 - 0.5 * breath;
  pose.hipsPos = [sway * 0.009, -0.018 - crouch * 0.012, 0];
  pose.Hips = [0.05, -0.14 + sway * 0.04, sway * 0.02];
  pose.Spine = [0.05 + breath * 0.025, 0.05 + sway * 0.03, 0];
  pose.Spine1 = [0.04 + breath * 0.02, 0.05, 0];
  pose.Spine2 = [0.04 + breath * 0.025, 0.05, 0];
  pose.Neck = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  pose.Head = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  /* Poised claw guard: forearms raised slightly forward (+Z), shoulders broad */
  pose.LeftArm = [-0.26 - breath * 0.03, -0.18, 0.14 + breath * 0.02];
  pose.LeftForeArm = [-0.48 - breath * 0.04, 0, 0.12];
  pose.RightArm = [-0.22 - breath * 0.03, 0.16, -0.16 - breath * 0.02];
  pose.RightForeArm = [-0.52 - breath * 0.04, 0, -0.12];
  pose.LeftUpLeg = [-0.18 - crouch * 0.04, 0.04, 0];
  pose.LeftLeg = [0.32 + crouch * 0.05, 0, 0];
  pose.LeftFoot = [-0.14, 0, 0];
  pose.RightUpLeg = [0.12 + crouch * 0.04, -0.04, 0];
  pose.RightLeg = [0.22 + crouch * 0.05, 0, 0];
  pose.RightFoot = [-0.28, 0, 0];
  return pose;
}

const POSE_BONE_KEYS = [
  "Hips",
  "Spine",
  "Spine1",
  "Spine2",
  "Neck",
  "Head",
  "LeftShoulder",
  "LeftArm",
  "LeftForeArm",
  "LeftHand",
  "RightShoulder",
  "RightArm",
  "RightForeArm",
  "RightHand",
  "LeftUpLeg",
  "LeftLeg",
  "LeftFoot",
  "RightUpLeg",
  "RightLeg",
  "RightFoot",
];

export function applyBossPoseDirect(bossNodes, pose, dampRate, dt) {
  if (!bossNodes.Hips) return;
  const alpha = dampRate <= 0 ? 1 : 1 - Math.exp(-dampRate * Math.max(dt, 0.0001));

  const hRest = bossNodes.Hips.userData.restPos;
  if (hRest) {
    bossNodes.Hips.position.x = THREE.MathUtils.lerp(bossNodes.Hips.position.x, hRest.x + pose.hipsPos[0], alpha);
    bossNodes.Hips.position.y = THREE.MathUtils.lerp(bossNodes.Hips.position.y, hRest.y + pose.hipsPos[1], alpha);
    bossNodes.Hips.position.z = THREE.MathUtils.lerp(bossNodes.Hips.position.z, hRest.z + pose.hipsPos[2], alpha);
  }

  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    const isArm = key === "LeftArm" || key === "RightArm" || key === "LeftForeArm" || key === "RightForeArm";
    const order = isArm ? "YXZ" : "XYZ";
    tmpEuler.set(rot[0], rot[1], rot[2], order);
    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }
}

