1: /* Bundles world.js and the vendored three.js into world.bundle.js, a plain script that also
2:    runs when index.html is opened straight from disk. Run after editing world.js:
3:    node .impeccable/tools/build-world.mjs */
4: 
5: import { build } from "esbuild";
6: import { createHash } from "node:crypto";
7: import fs from "node:fs";
8: import path from "node:path";
9: import { fileURLToPath } from "node:url";
10: 
11: const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
12: const vendor = path.join(root, "vendor/three");
13: 
14: const vendoredThree = {
15:   name: "vendored-three",
16:   setup(b) {
17:     b.onResolve({ filter: /^three$/ }, () => ({ path: path.join(vendor, "three.module.min.js") }));
18:     b.onResolve({ filter: /^three\/addons\// }, (args) => ({
19:       path: path.join(vendor, "addons", args.path.slice("three/addons/".length)),
20:     }));
21:   },
22: };
23: 
24: await build({
25:   entryPoints: [path.join(root, "world.js")],
26:   outfile: path.join(root, "world.bundle.js"),
27:   bundle: true,
28:   format: "iife",
29:   minify: true,
30:   target: "es2020",
31:   legalComments: "eof",
32:   banner: { js: "/* Built from world.js by .impeccable/tools/build-world.mjs. Edit world.js, then rebuild. */" },
33:   plugins: [vendoredThree],
34:   loader: { ".glb": "binary", ".fbx": "binary", ".png": "dataurl" },
35:   logLevel: "info",
36: });
37: 
38: /* Stamp the bundle's hash into index.html so browsers never run a stale copy. */
39: const bundle = fs.readFileSync(path.join(root, "world.bundle.js"));
40: const version = createHash("sha1").update(bundle).digest("hex").slice(0, 8);
41: const indexPath = path.join(root, "index.html");
42: const html = fs.readFileSync(indexPath, "utf8");
43: const stamped = html.replace(/src="\.\/world\.bundle\.js(\?v=[^"]*)?"/, `src="./world.bundle.js?v=${version}"`);
44: 
45: if (stamped === html && !html.includes(`world.bundle.js?v=${version}`)) {
46:   throw new Error("index.html has no world.bundle.js script tag to stamp");
47: }
48: 
49: fs.writeFileSync(indexPath, stamped);
50: console.log(`index.html -> world.bundle.js?v=${version}`);

