/* Mesh-Smearing Handler (world-smear.js)
   Implements the Godot "Mesh smearing" technique by celyk:
   https://godotshaders.com/shader/mesh-smearing/#main
     lag_transform = lag_transform.interpolate_with(global_transform, weight * delta)
     float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
     MODELVIEW_MATRIX = MODEL_MATRIX + (lag_transform - MODEL_MATRIX) * t;
   Adapted for Three.js SkinnedMesh (`assets/models/boss.glb`):
   - Maintains lagging bone transforms (`uLagBoneTexture`) and mid-arc bone transforms (`uMidBoneTexture`)
     that smoothly slerp toward the current skeleton pose (`lagQuat.slerp(currQuat, 1 - exp(-weight * dt))`).
   - Evaluates continuous 3D gradient noise on the vertex's bind-pose position (`restPos`) so the smear
     is 100% seam-free and watertight across UV islands.
   - Interpolates each vertex along the curved Quadratic Bezier swing arc `(posCurr -> posMid -> posLag)`
     by `t = pow(noise, power) * stretch`, so the smear forms cleanly out of the right claw/arm mesh during
     the swing and settles smoothly back into the mesh as `lag_transform` catches up. */

import * as THREE from "three";

const SMEAR_SKINNING_PARS_GLSL = /* glsl */ `
#ifdef USE_SKINNING
  uniform highp sampler2D uMidBoneTexture;
  uniform highp sampler2D uLagBoneTexture;
  uniform float uSmearNoiseScale;
  uniform float uSmearNoisePower;
  uniform float uSmearStretch;

  mat4 getSmearBoneMatrix( highp sampler2D tex, const in float i ) {
    int size = textureSize( tex, 0 ).x;
    int j = int( i ) * 4;
    int x = j % size;
    int y = j / size;
    vec4 v1 = texelFetch( tex, ivec2( x, y ), 0 );
    vec4 v2 = texelFetch( tex, ivec2( x + 1, y ), 0 );
    vec4 v3 = texelFetch( tex, ivec2( x + 2, y ), 0 );
    vec4 v4 = texelFetch( tex, ivec2( x + 3, y ), 0 );
    return mat4( v1, v2, v3, v4 );
  }

  /* Bone indices in assets/models/boss.glb:
     10 = RightShoulder, 11 = RightArm, 12 = RightForeArm, 13 = RightHand */
  float getRightArmBoneMask( const in float idx ) {
    int b = int( idx + 0.5 );
    if ( b == 13 ) return 1.0;
    if ( b == 12 ) return 0.86;
    if ( b == 11 ) return 0.44;
    if ( b == 10 ) return 0.12;
    return 0.0;
  }

  vec3 smearHash3( vec3 p ) {
    p = vec3(
      dot( p, vec3( 127.1, 311.7, 74.7 ) ),
      dot( p, vec3( 269.5, 183.3, 246.1 ) ),
      dot( p, vec3( 113.5, 271.9, 124.6 ) )
    );
    return -1.0 + 2.0 * fract( sin( p ) * 43758.5453123 );
  }

  float smearGradNoise3D( vec3 p ) {
    vec3 i = floor( p );
    vec3 f = fract( p );
    vec3 u = f * f * ( 3.0 - 2.0 * f );
    return mix(
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 0.0 ) ), f - vec3( 0.0, 0.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 0.0 ) ), f - vec3( 1.0, 0.0, 0.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 0.0 ) ), f - vec3( 0.0, 1.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 0.0 ) ), f - vec3( 1.0, 1.0, 0.0 ) ), u.x ),
        u.y
      ),
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 1.0 ) ), f - vec3( 0.0, 0.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 1.0 ) ), f - vec3( 1.0, 0.0, 1.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 1.0 ) ), f - vec3( 0.0, 1.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 1.0 ) ), f - vec3( 1.0, 1.0, 1.0 ) ), u.x ),
        u.y
      ),
      u.z
    );
  }

  float smearFbm( vec3 p ) {
    float v = 0.5 + 0.5 * smearGradNoise3D( p );
    v = 0.68 * v + 0.32 * ( 0.5 + 0.5 * smearGradNoise3D( p * 2.07 + vec3( 13.7, 29.3, 7.1 ) ) );
    /* Normalize noise range so valleys sit at 0.0 and ridges reach 1.0 before pow(n, power) */
    return smoothstep( 0.22, 0.76, v );
  }
#endif
`;

const SMEAR_SKINNING_VERTEX_GLSL = /* glsl */ `
  float smearTVal = 0.0;
#ifdef USE_SKINNING
  vec3 restPos = transformed;
  vec4 skinVertex = bindMatrix * vec4( transformed, 1.0 );
  mat4 currSkinMat =
    boneMatX * skinWeight.x +
    boneMatY * skinWeight.y +
    boneMatZ * skinWeight.z +
    boneMatW * skinWeight.w;
  vec4 skinned = currSkinMat * skinVertex;

  /* Smooth right-arm & claw mask from skin weights (bones 10..13) + bind-pose distal gradient */
  float boneArmMask =
    getRightArmBoneMask( skinIndex.x ) * skinWeight.x +
    getRightArmBoneMask( skinIndex.y ) * skinWeight.y +
    getRightArmBoneMask( skinIndex.z ) * skinWeight.z +
    getRightArmBoneMask( skinIndex.w ) * skinWeight.w;
  float distalBoost = 0.60 + 0.40 * ( 1.0 - smoothstep( 0.22, 0.66, restPos.y ) );
  float handMask = clamp( boneArmMask * distalBoost, 0.0, 1.0 );

  if ( uSmearStretch > 0.001 && handMask > 0.001 ) {
    mat4 midMatX = getSmearBoneMatrix( uMidBoneTexture, skinIndex.x );
    mat4 midMatY = getSmearBoneMatrix( uMidBoneTexture, skinIndex.y );
    mat4 midMatZ = getSmearBoneMatrix( uMidBoneTexture, skinIndex.z );
    mat4 midMatW = getSmearBoneMatrix( uMidBoneTexture, skinIndex.w );
    vec4 skinnedMid = (
      midMatX * skinWeight.x +
      midMatY * skinWeight.y +
      midMatZ * skinWeight.z +
      midMatW * skinWeight.w
    ) * skinVertex;

    mat4 lagMatX = getSmearBoneMatrix( uLagBoneTexture, skinIndex.x );
    mat4 lagMatY = getSmearBoneMatrix( uLagBoneTexture, skinIndex.y );
    mat4 lagMatZ = getSmearBoneMatrix( uLagBoneTexture, skinIndex.z );
    mat4 lagMatW = getSmearBoneMatrix( uLagBoneTexture, skinIndex.w );
    vec4 skinnedLag = (
      lagMatX * skinWeight.x +
      lagMatY * skinWeight.y +
      lagMatZ * skinWeight.z +
      lagMatW * skinWeight.w
    ) * skinVertex;

    vec3 wakeVec = skinnedLag.xyz - skinned.xyz;
    float wakeLen = length( wakeVec );
    if ( wakeLen > 0.0005 ) {
      vec3 wakeDir = wakeVec / wakeLen;
      /* Cross-sectional outward normal around the A-pose right arm/claw centerline,
         rotated by currSkinMat so the trailing half of the claw/forearm stretches back
         along the swing arc while the leading front face stays crisp and intact. */
      float yFrac = clamp( ( restPos.y - 0.20 ) / 0.52, 0.0, 1.0 );
      float armCenterX = mix( -0.382, -0.24, yFrac );
      float armCenterZ = mix( 0.072, -0.03, clamp( ( restPos.y - 0.28 ) / 0.28, 0.0, 1.0 ) );
      vec3 cylNormalBind = normalize( vec3( ( restPos.x - armCenterX ) * 0.65, 0.0, restPos.z - armCenterZ ) );
      vec3 cylNormalWS = normalize( mat3( currSkinMat ) * cylNormalBind );
      float trailAlign = smoothstep( -0.38, 0.35, dot( cylNormalWS, wakeDir ) );

      /* Godot mesh-smearing formula:
         float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
         Evaluated on 3D bind-pose restPos with a cohesive trailing base plus fine longitudinal streaks
         so the smear forms a smooth, unified arc on the claw/forearm and settles cleanly onto the mesh. */
      vec3 noisePos = vec3(
        restPos.x * uSmearNoiseScale * 1.35,
        restPos.y * uSmearNoiseScale * 0.55,
        restPos.z * uSmearNoiseScale * 1.35
      );
      float n = smearFbm( noisePos );
      float streakProfile = 0.24 + 0.86 * pow( n, uSmearNoisePower );
      float t = streakProfile * uSmearStretch * handMask * trailAlign;
      t = clamp( t, 0.0, 1.32 );

      /* Quadratic Bezier interpolation through skinned (t=0), skinnedMid (t=0.5), skinnedLag (t=1.0)
         so the smear curves smoothly along the circular swing arc of the arm and claw! */
      vec3 ctrl = 2.0 * skinnedMid.xyz - 0.5 * ( skinned.xyz + skinnedLag.xyz );
      float u = 1.0 - t;
      vec3 arcWS = u * u * skinned.xyz + 2.0 * u * t * ctrl + t * t * skinnedLag.xyz;
      skinned.xyz = arcWS;
      smearTVal = clamp( t * clamp( wakeLen * 4.5, 0.0, 1.0 ), 0.0, 1.0 );
    }
  }
  transformed = ( bindMatrixInverse * skinned ).xyz;
#endif
`;

export function createSmearHandler(options = {}) {
  const config = {
    weight: options.weight ?? 8.0, /* Godot lag_transform interpolation weight */
    noiseScale: options.noiseScale ?? 34.0,
    noisePower: options.noisePower ?? 2.4,
    stretch: options.stretch ?? 1.45,
  };

  /* Fallback 16x16 DataTextures until the skeleton is bound */
  const makeBoneTex = (size) => {
    const data = new Float32Array(size * size * 4);
    const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.FloatType);
    tex.needsUpdate = true;
    return { data, tex };
  };
  let midBuf = makeBoneTex(16);
  let lagBuf = makeBoneTex(16);

  const uniforms = {
    uMidBoneTexture: { value: midBuf.tex },
    uLagBoneTexture: { value: lagBuf.tex },
    uSmearNoiseScale: { value: config.noiseScale },
    uSmearNoisePower: { value: config.noisePower },
    uSmearStretch: { value: 0 },
  };

  const depthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
  depthMaterial.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace("#include <skinning_pars_vertex>", `#include <skinning_pars_vertex>\n${SMEAR_SKINNING_PARS_GLSL}`)
      .replace("#include <skinning_vertex>", SMEAR_SKINNING_VERTEX_GLSL);
  };
  depthMaterial.customProgramCacheKey = () => "godot-mesh-smear-depth";

  const enhanceMaterial = (material) => {
    const prev = material.onBeforeCompile;
    const baseKey = material.customProgramCacheKey?.() || "soft-toon";
    material.onBeforeCompile = (shader, renderer) => {
      prev?.(shader, renderer);
      Object.assign(shader.uniforms, uniforms);
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <skinning_pars_vertex>",
          `#include <skinning_pars_vertex>\n${SMEAR_SKINNING_PARS_GLSL}\nvarying float vSmearT;`,
        )
        .replace(
          "#include <skinning_vertex>",
          `${SMEAR_SKINNING_VERTEX_GLSL}\nvSmearT = smearTVal;`,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace("#include <common>", "#include <common>\nvarying float vSmearT;")
        .replace(
          "#include <opaque_fragment>",
          [
            "if (vSmearT > 0.01) {",
            "  /* Subtle ember ridge highlight so the volcanic claw's mesh-smear spikes read clearly */",
            "  float ridge = smoothstep(0.08, 0.78, vSmearT);",
            "  outgoingLight = mix(outgoingLight, outgoingLight * 1.14 + vec3(0.28, 0.09, 0.02), ridge * 0.68);",
            "}",
            "#include <opaque_fragment>",
          ].join("\n"),
        );
    };
    material.customProgramCacheKey = () => `${baseKey}-godot-mesh-smear`;
    return material;
  };

  let boundSkeleton = null;
  let boundRoot = null;
  let boneWeights = [];
  let currPos = [];
  let currQuat = [];
  let lagPos = [];
  let lagQuat = [];
  let initialized = false;
  let handBoneIdx = -1;
  let lastLagDistance = 0;
  const tmpOffsetMat = new THREE.Matrix4();
  const tmpCurrHandWS = new THREE.Vector3();
  const tmpLagHandWS = new THREE.Vector3();

  const bindSkeleton = (skeleton, rootGroup) => {
    boundSkeleton = skeleton;
    boundRoot = rootGroup;
    skeleton.computeBoneTexture();
    const size = skeleton.boneTexture.image.width;
    midBuf = makeBoneTex(size);
    lagBuf = makeBoneTex(size);
    uniforms.uMidBoneTexture.value = midBuf.tex;
    uniforms.uLagBoneTexture.value = lagBuf.tex;

    const count = skeleton.bones.length;
    boneWeights = new Array(count).fill(100);
    currPos = new Array(count);
    currQuat = new Array(count);
    lagPos = new Array(count);
    lagQuat = new Array(count);
    handBoneIdx = -1;

    for (let i = 0; i < count; i += 1) {
      const b = skeleton.bones[i];
      const name = b.name.replace(/^mixamorig\d*:?/, "");
      currPos[i] = b.position.clone();
      currQuat[i] = b.quaternion.clone();
      lagPos[i] = b.position.clone();
      lagQuat[i] = b.quaternion.clone();
      if (name === "RightHand") handBoneIdx = i;

      /* Only the right arm chain + upper spine twist lag behind; legs/hips/left arm stay at 0 */
      if (/^Right(Shoulder|Arm|ForeArm|Hand)/.test(name)) {
        boneWeights[i] = 1.0; /* uses config.weight directly */
      } else if (name === "Spine1" || name === "Spine2") {
        boneWeights[i] = 1.85; /* subtle upper-torso arc follow */
      } else {
        boneWeights[i] = 0; /* 0 means snap immediately to current pose */
      }
    }
    initialized = false;
  };

  const writeBoneMatricesTo = (targetArray) => {
    const bones = boundSkeleton.bones;
    const inverses = boundSkeleton.boneInverses;
    for (let i = 0; i < bones.length; i += 1) {
      tmpOffsetMat.multiplyMatrices(bones[i].matrixWorld, inverses[i]);
      tmpOffsetMat.toArray(targetArray, i * 16);
    }
  };

  const reset = () => {
    if (!boundSkeleton) return;
    const bones = boundSkeleton.bones;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      lagPos[i].copy(bones[i].position);
      lagQuat[i].copy(bones[i].quaternion);
    }
    boundRoot?.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    writeBoneMatricesTo(lagBuf.data);
    midBuf.tex.needsUpdate = true;
    lagBuf.tex.needsUpdate = true;
    uniforms.uSmearStretch.value = 0;
    lastLagDistance = 0;
    initialized = true;
  };

  /* Advance lag_transform = lag_transform.interpolate_with(global_transform, weight * dt)
     and populate uMidBoneTexture (slerp 0.5) and uLagBoneTexture (slerp 1.0). */
  const stepLag = (dt, weightOverride = null, stretchScale = 1.0) => {
    if (!boundSkeleton || !boundRoot) return;
    if (stretchScale <= 0.001) {
      reset();
      return;
    }
    const bones = boundSkeleton.bones;
    if (!initialized) {
      reset();
    }
    uniforms.uSmearStretch.value = config.stretch * stretchScale;
    const baseWeight = weightOverride ?? config.weight;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      const mult = boneWeights[i];
      if (mult <= 0 || dt <= 0) {
        lagPos[i].copy(currPos[i]);
        lagQuat[i].copy(currQuat[i]);
      } else {
        const alpha = 1 - Math.exp(-(baseWeight * mult) * dt);
        lagPos[i].lerp(currPos[i], alpha);
        lagQuat[i].slerp(currQuat[i], alpha);
      }
    }

    if (handBoneIdx >= 0) {
      bones[handBoneIdx].getWorldPosition(tmpCurrHandWS);
    }

    /* 1. Compute uLagBoneTexture at lagQuat */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(lagPos[i]);
      bones[i].quaternion.copy(lagQuat[i]);
    }
    boundRoot.updateMatrixWorld(true);
    writeBoneMatricesTo(lagBuf.data);
    lagBuf.tex.needsUpdate = true;
    if (handBoneIdx >= 0) {
      bones[handBoneIdx].getWorldPosition(tmpLagHandWS);
      lastLagDistance = tmpCurrHandWS.distanceTo(tmpLagHandWS);
    }

    /* 2. Compute uMidBoneTexture halfway along the rotational arc (slerp 0.5) */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(lagPos[i]).lerp(currPos[i], 0.5);
      bones[i].quaternion.copy(lagQuat[i]).slerp(currQuat[i], 0.5);
    }
    boundRoot.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    midBuf.tex.needsUpdate = true;

    /* 3. Restore current skeleton pose */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(currPos[i]);
      bones[i].quaternion.copy(currQuat[i]);
    }
    boundRoot.updateMatrixWorld(true);
  };

  return {
    uniforms,
    depthMaterial,
    enhanceMaterial,
    bindSkeleton,
    reset,
    stepLag,
    getLagDistance: () => +lastLagDistance.toFixed(3),
  };
}

/* Boss Entity, Loader & Combat Mechanic Handler (world-boss.js)
   Uses the retopologized & rigged volcanic colossus (`assets/models/boss.glb`) and coordinates:
   - `world-boss-anim.js` (procedural martial idle, run, and wide right-claw arc swing)
   - `world-smear.js` (Godot `mesh-smearing` per-vertex `lag_transform` + `pow(noise, exp)`
     arc interpolation that forms on the moving claw/arm mesh and settles cleanly back into it) */

import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import bossGlb from "./assets/models/boss.glb";
import { createSmearHandler } from "./world-smear.js";
import { BOSS_PUNCH_DURATION, computeBossPose, applyBossPoseDirect } from "./world-boss-anim.js";

export function createWerewolfBoss({
  scene,
  island,
  landing,
  robot,
  colliders,
  decal,
  softMapped,
  bakeShadows,
  isIntroLive,
  addShake,
}) {
  const bossAt = landing.clone();
  bossAt.x -= Math.SQRT1_2 * 3.15;
  bossAt.z += Math.SQRT1_2 * 2.15;
  if (!island.nav.walkable(bossAt.x, bossAt.z)) {
    const near = island.nav.nearest(bossAt.x, bossAt.z);
    if (near) bossAt.copy(near);
  }
  bossAt.y = island.groundAt(bossAt.x, bossAt.z);

  const BOSS_SCALE = 2.65; /* 0.92m bind height * 2.65 = ~2.44m colossus height */
  const BOSS_RUN_SPEED = 4.2;

  const bossGroup = new THREE.Group();
  bossGroup.name = "ColossusBoss";
  bossGroup.position.copy(bossAt);
  const bossHomeYaw = Math.atan2(landing.x - bossAt.x, landing.z - bossAt.z);
  bossGroup.rotation.y = bossHomeYaw;
  scene.add(bossGroup);

  const bossBody = new THREE.Group();
  bossBody.scale.setScalar(BOSS_SCALE);
  bossGroup.add(bossBody);

  decal(bossGroup, { color: "#233022", size: 2.35, y: 0.03, opacity: 0.36 });

  const bossCollider = { x: bossAt.x, z: bossAt.z, r: 0.85 };
  colliders.push(bossCollider);

  /* Godot mesh-smearing handler (`https://godotshaders.com/shader/mesh-smearing/#main`) */
  const armSmear = createSmearHandler({
    weight: 6.8,
    noiseScale: 34.0,
    noisePower: 2.35,
    stretch: 1.48,
  });

  const bossNodes = {};
  let bossReady = false;
  let mainSkeleton = null;

  const dampAngle = (current, target, rate, dt) => {
    const diff = Math.atan2(Math.sin(target - current), Math.cos(target - current));
    return current + diff * (1 - Math.exp(-rate * dt));
  };

  const bossState = {
    mode: "auto", /* "auto" | "idle" | "run" | "punch" */
    state: "idle", /* current active state: "idle" | "run" | "punch" */
    inPlace: false,
    lockedTime: null,
    runPhase: 0,
    punchTime: -1,
    punchCooldown: 1.15,
    impactFired: false,
    yaw: bossHomeYaw,
  };

  (async () => {
    try {
      const ab = bossGlb.buffer.slice(bossGlb.byteOffset, bossGlb.byteOffset + bossGlb.byteLength);
      const gltf = await new GLTFLoader().parseAsync(ab, "");
      const model = gltf.scene;

      const skinnedMeshes = [];
      model.traverse((node) => {
        if (node.isSkinnedMesh) skinnedMeshes.push(node);
      });

      mainSkeleton = skinnedMeshes[0]?.skeleton || null;
      if (mainSkeleton) {
        mainSkeleton.bones.forEach((bone) => {
          bone.userData.restPos = bone.position.clone();
          bone.userData.restQuat = bone.quaternion.clone();
          const cleanName = bone.name.replace(/^mixamorig\d*:?/, "");
          bossNodes[cleanName] = bone;
        });
        armSmear.bindSkeleton(mainSkeleton, bossGroup);
      }

      skinnedMeshes.forEach((mesh) => {
        const tex = mesh.material?.map || null;
        if (tex) {
          tex.colorSpace = THREE.SRGBColorSpace;
        }
        const baseMat = softMapped(tex);
        mesh.material = armSmear.enhanceMaterial(baseMat);
        mesh.customDepthMaterial = armSmear.depthMaterial;
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.frustumCulled = false;
      });

      bossBody.add(model);
      bossReady = true;
      update(0.016, performance.now() / 1000);
      bakeShadows();
    } catch (error) {
      console.warn("Boss model failed to load", error);
    }
  })();

  const update = (dt, time) => {
    if (!bossReady || !bossNodes.Hips) return;

    const dxNiko = robot.position.x - bossGroup.position.x;
    const dzNiko = robot.position.z - bossGroup.position.z;
    const distNiko = Math.hypot(dxNiko, dzNiko);
    const dxHome = bossAt.x - bossGroup.position.x;
    const dzHome = bossAt.z - bossGroup.position.z;
    const distHome = Math.hypot(dxHome, dzHome);
    const introActive = Boolean(isIntroLive?.());

    /* 1. Determine active animation state & movement */
    if (bossState.mode === "idle") {
      bossState.state = "idle";
      bossState.punchTime = -1;
    } else if (bossState.mode === "run") {
      bossState.state = "run";
      bossState.punchTime = -1;
      bossState.runPhase = bossState.lockedTime != null ? bossState.lockedTime * 9.5 : bossState.runPhase + dt * 9.5;
      if (!bossState.inPlace && distNiko > 2.2) {
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 2.1, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      }
    } else if (bossState.mode === "punch") {
      bossState.state = "punch";
      if (bossState.lockedTime != null) {
        bossState.punchTime = bossState.lockedTime;
      } else if (bossState.punchTime < 0) {
        bossState.punchTime = 0;
        bossState.impactFired = false;
      } else {
        bossState.punchTime += dt;
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
    } else {
      /* "auto" gameplay mode */
      bossState.punchCooldown = Math.max(0, bossState.punchCooldown - dt);
      if (introActive) {
        bossState.state = "idle";
        bossState.punchTime = -1;
        bossState.yaw = dampAngle(bossState.yaw, bossHomeYaw, 6, dt);
      } else if (bossState.punchTime >= 0) {
        bossState.state = "punch";
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        if (bossState.punchTime < 0.36) {
          bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 9, dt);
        }
        bossState.punchTime += dt;
        if (!bossState.impactFired && bossState.punchTime >= 0.48) {
          bossState.impactFired = true;
          if (distNiko < 5.5) addShake?.(0.24);
        }
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = -1;
          bossState.punchCooldown = 1.35;
          bossState.state = "idle";
        }
      } else if (distNiko <= 3.05 && bossState.punchCooldown <= 0) {
        bossState.state = "punch";
        bossState.punchTime = 0;
        bossState.impactFired = false;
      } else if (distNiko > 2.75 && distNiko < 8.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.5;
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 2.45, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else if (distHome > 0.35 && distNiko >= 8.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.0;
        const yawHome = Math.atan2(dxHome, dzHome);
        bossState.yaw = dampAngle(bossState.yaw, yawHome, 9, dt);
        const step = Math.min(distHome, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + (dxHome / distHome) * step;
        const nz = bossGroup.position.z + (dzHome / distHome) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else {
        bossState.state = "idle";
        const lookYaw = distNiko < 9.5 && distNiko > 0.01 ? Math.atan2(dxNiko, dzNiko) : bossHomeYaw;
        bossState.yaw = dampAngle(bossState.yaw, lookYaw, 7, dt);
      }
    }

    bossGroup.position.y = island.groundAt(bossGroup.position.x, bossGroup.position.z);
    bossGroup.rotation.y = bossState.yaw;
    bossCollider.x = bossGroup.position.x;
    bossCollider.z = bossGroup.position.z;

    /* 2. Apply pose and update Godot mesh-smearing (`lag_transform`) only during the forward arc swing & hold settle.
          Smear is strictly disabled (`reset()`) during wind-up (u < 0.35), during recovery back to idle (u >= 0.72),
          and in "idle" or "run" states so the hand never smears while returning to rest or running. */
    if (bossState.state === "punch") {
      const u = bossState.punchTime;
      const getWeightForTime = (t) => (t < 0.35 ? 36.0 : t < 0.54 ? 6.4 : 16.5);
      const getSmearScaleForTime = (t) => {
        if (t < 0.35 || t >= 0.72) return 0;
        if (t <= 0.58) return 1;
        return 1 - THREE.MathUtils.smoothstep(t, 0.58, 0.72);
      };

      if (bossState.lockedTime != null) {
        /* Deterministically integrate `lag_transform.interpolate_with(global_transform, weight * dt)`
           up to `lockedTime` so frozen debug/review frames show the exact arc smear & settle. */
        const smearScale = getSmearScaleForTime(u);
        if (smearScale <= 0) {
          const p = computeBossPose("punch", time, bossState.runPhase, u);
          applyBossPoseDirect(bossNodes, p, 0, 0);
          bossGroup.updateMatrixWorld(true);
          armSmear.reset();
        } else {
          const startT = 0.34;
          const startPose = computeBossPose("punch", time, bossState.runPhase, startT);
          applyBossPoseDirect(bossNodes, startPose, 0, 0);
          bossGroup.updateMatrixWorld(true);
          armSmear.reset();

          const stepDt = 1 / 120;
          for (let simT = startT + stepDt; simT <= u + 1e-5; simT += stepDt) {
            const clampedT = Math.min(simT, u);
            const p = computeBossPose("punch", time, bossState.runPhase, clampedT);
            applyBossPoseDirect(bossNodes, p, 0, 0);
            bossGroup.updateMatrixWorld(true);
            armSmear.stepLag(stepDt, getWeightForTime(clampedT), getSmearScaleForTime(clampedT));
          }
        }
      } else {
        const smearScale = getSmearScaleForTime(u);
        const isSwingOrSettle = u >= 0.35 && u < 0.72;
        const poseDamp = isSwingOrSettle ? 42 : 18;
        const targetPose = computeBossPose("punch", time, bossState.runPhase, u);
        applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
        bossGroup.updateMatrixWorld(true);
        if (smearScale > 0) {
          armSmear.stepLag(dt, getWeightForTime(u), smearScale);
        } else {
          armSmear.reset();
        }
      }
    } else {
      const poseDamp = bossState.lockedTime != null ? 0 : 14;
      const targetPose = computeBossPose(bossState.state, time, bossState.runPhase, -1);
      applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
      bossGroup.updateMatrixWorld(true);
      armSmear.reset();
    }
  };

  const debug = (options) => {
    if (options && typeof options === "object") {
      if (options.mode) {
        bossState.mode = options.mode;
        if (options.mode === "punch" && options.time == null) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
      if ("inPlace" in options) bossState.inPlace = Boolean(options.inPlace);
      if ("time" in options) bossState.lockedTime = options.time;
      if (options.yaw != null) bossState.yaw = options.yaw;
      if (options.resetPos) {
        bossGroup.position.copy(bossAt);
        bossState.yaw = bossHomeYaw;
        armSmear.reset();
      }
      update(0.016, performance.now() / 1000);
    }
    return {
      ready: bossReady,
      mode: bossState.mode,
      state: bossState.state,
      punchTime: +bossState.punchTime.toFixed(3),
      lagDistance: armSmear.getLagDistance(),
      at: bossGroup.position.toArray().map((n) => +n.toFixed(2)),
      scale: BOSS_SCALE,
    };
  };

  return {
    group: bossGroup,
    update,
    debug,
  };
}

/* Boss Animation Pose & Joint Articulation Handler (world-boss-anim.js)
   Computes procedural Sekiro/Soulslike poses for the rigged volcanic colossus (`assets/models/boss.glb`):
   1. "idle"  — heavy, poised colossus combat guard with planted lower body & rhythmic chest heave
   2. "run"   — powerful forward charge with counter-rotating torso and heavy stride
   3. "punch" — planted-stance wide horizontal right-claw arc swing with full arm/hand extension
                designed to showcase the Godot mesh-smearing (`lag_transform` + `pow(noise, exp)`). */

import * as THREE from "three";

export const BOSS_PUNCH_DURATION = 1.24;

const tmpEuler = new THREE.Euler();
const tmpDeltaQuat = new THREE.Quaternion();
const tmpTargetQuat = new THREE.Quaternion();

/* Planted lower-body stance shared by "idle" and "punch" so the pelvis, legs, and feet
   never drift or slide during the hand swing. */
const PLANTED_LOWER_BODY = {
  hipsPos: [0, -0.022, 0],
  Hips: [0.04, -0.10, 0],
  LeftUpLeg: [-0.20, 0.04, 0],
  LeftLeg: [0.34, 0, 0],
  LeftFoot: [-0.14, 0, 0],
  RightUpLeg: [0.14, -0.04, 0],
  RightLeg: [0.24, 0, 0],
  RightFoot: [-0.28, 0, 0],
};

export function computeBossPose(state, time, runPhase, punchTime) {
  const ss = THREE.MathUtils.smoothstep;
  const L = THREE.MathUtils.lerp;

  const pose = {
    hipsPos: [...PLANTED_LOWER_BODY.hipsPos],
    Hips: [...PLANTED_LOWER_BODY.Hips],
    Spine: [0, 0, 0],
    Spine1: [0, 0, 0],
    Spine2: [0, 0, 0],
    Neck: [0, 0, 0],
    Head: [0, 0, 0],
    LeftShoulder: [0, 0, 0],
    LeftArm: [0, 0, 0],
    LeftForeArm: [0, 0, 0],
    LeftHand: [0, 0, 0],
    RightShoulder: [0, 0, 0],
    RightArm: [0, 0, 0],
    RightForeArm: [0, 0, 0],
    RightHand: [0, 0, 0],
    LeftUpLeg: [...PLANTED_LOWER_BODY.LeftUpLeg],
    LeftLeg: [...PLANTED_LOWER_BODY.LeftLeg],
    LeftFoot: [...PLANTED_LOWER_BODY.LeftFoot],
    RightUpLeg: [...PLANTED_LOWER_BODY.RightUpLeg],
    RightLeg: [...PLANTED_LOWER_BODY.RightLeg],
    RightFoot: [...PLANTED_LOWER_BODY.RightFoot],
    armExtend: 0, /* 0..1 reach extension along RightArm / RightForeArm / RightHand */
  };

  if (state === "run") {
    const p = runPhase;
    const s1 = Math.sin(p);
    const c1 = Math.cos(p);
    const bob = Math.abs(s1);
    pose.hipsPos = [c1 * 0.014, -0.028 + (bob - 0.5) * 0.036, 0];
    pose.Hips = [0.14, -s1 * 0.16, c1 * 0.05];
    pose.Spine = [0.12 + bob * 0.04, s1 * 0.10, -c1 * 0.04];
    pose.Spine1 = [0.08, s1 * 0.10, 0];
    pose.Spine2 = [0.08, s1 * 0.12, 0];
    pose.Neck = [-0.14, -s1 * 0.08, 0];
    pose.Head = [-0.12, -s1 * 0.08, 0];
    /* Pumping claw arms in heavy charge (YXZ order: rx < 0 swings arm forward +Z, rz lifts outward) */
    pose.LeftArm = [-0.18 + s1 * 0.58, -0.12, 0.16];
    pose.LeftForeArm = [-0.62 - Math.max(0, -s1) * 0.25, 0, 0.10];
    pose.RightArm = [-0.18 - s1 * 0.58, 0.12, -0.16];
    pose.RightForeArm = [-0.62 - Math.max(0, s1) * 0.25, 0, -0.10];
    /* Stride: rx < 0 lifts thigh forward (+Z), rx > 0 bends shin backward (-Z) */
    pose.LeftUpLeg = [-s1 * 0.58 - 0.08, 0, 0];
    pose.LeftLeg = [0.18 + Math.max(0, -c1) * 0.68, 0, 0];
    pose.LeftFoot = [-0.08 + s1 * 0.18, 0, 0];
    pose.RightUpLeg = [s1 * 0.58 - 0.08, 0, 0];
    pose.RightLeg = [0.18 + Math.max(0, c1) * 0.68, 0, 0];
    pose.RightFoot = [-0.08 - s1 * 0.18, 0, 0];
    return pose;
  }

  if (state === "punch") {
    const u = THREE.MathUtils.clamp(punchTime, 0, BOSS_PUNCH_DURATION);
    const idle = computeBossPose("idle", time, runPhase, 0);

    if (u < 0.36) {
      /* Phase 1: Wind-up — lower body stays 100% planted while upper spine coils right
         and raises the right claw wide behind the right shoulder */
      const w = ss(u, 0.0, 0.34);
      const blend = (a, b) => [L(a[0], b[0], w), L(a[1], b[1], w), L(a[2], b[2], w)];
      pose.Spine = blend(idle.Spine, [-0.04, -0.22, -0.03]);
      pose.Spine1 = blend(idle.Spine1, [-0.03, -0.24, -0.02]);
      pose.Spine2 = blend(idle.Spine2, [0.02, -0.26, 0]);
      pose.Neck = blend(idle.Neck, [0.02, 0.26, 0]);
      pose.Head = blend(idle.Head, [0.02, 0.30, 0]);
      /* Left claw guards left flank; Right claw lifts to chest height (rz = -0.98) and opens wide back-right (ry = -0.82) */
      pose.LeftShoulder = blend(idle.LeftShoulder, [0, 0, 0.05]);
      pose.LeftArm = blend(idle.LeftArm, [-0.30, -0.20, 0.20]);
      pose.LeftForeArm = blend(idle.LeftForeArm, [-0.52, 0, 0.14]);
      pose.RightShoulder = blend(idle.RightShoulder, [0, -0.22, -0.10]);
      pose.RightArm = blend(idle.RightArm, [-0.10, -0.82, -0.98]);
      pose.RightForeArm = blend(idle.RightForeArm, [-0.16, 0, -0.10]);
      pose.RightHand = blend(idle.RightHand, [0, 0, -0.06]);
      pose.armExtend = L(0, 0.18, w);
      return pose;
    }

    if (u < 0.78) {
      /* Phase 2 (0.36..0.55): Wide chest-level circular arc swing across the front with full arm/hand reach extension.
         Phase 3 (0.55..0.78): Follow-through hold across chest while `lag_transform` settles cleanly into the claw mesh.
         Lower body (Hips & Legs) stays 100% locked to PLANTED_LOWER_BODY so feet never slide or drift. */
      const rawS = THREE.MathUtils.clamp((u - 0.36) / 0.19, 0, 1);
      const whip = 1 - Math.pow(1 - rawS, 2.4);
      pose.Spine = [L(-0.04, 0.12, whip), L(-0.22, 0.22, whip), L(-0.03, 0.04, whip)];
      pose.Spine1 = [L(-0.03, 0.12, whip), L(-0.24, 0.24, whip), L(-0.02, 0.02, whip)];
      pose.Spine2 = [L(0.02, 0.14, whip), L(-0.26, 0.28, whip), 0];
      pose.Neck = [L(0.02, -0.08, whip), L(0.26, -0.26, whip), 0];
      pose.Head = [L(0.02, -0.08, whip), L(0.30, -0.30, whip), 0];
      /* Left arm stays in a compact low counter-guard by the left ribcage */
      pose.LeftShoulder = [0, 0, L(0.05, 0.08, whip)];
      pose.LeftArm = [L(-0.30, -0.08, whip), L(-0.20, -0.04, whip), L(0.20, 0.24, whip)];
      pose.LeftForeArm = [L(-0.52, -0.46, whip), 0, 0.14];
      /* Right shoulder drives forward and elbow straightens out so the whole arm & hand extend long across the arc */
      pose.RightShoulder = [0, L(-0.22, 0.34, whip), L(-0.10, -0.04, whip)];
      pose.RightArm = [
        L(-0.10, -0.14, whip),
        L(-0.82, 1.48, whip),
        L(-0.98, -0.94, whip),
      ];
      pose.RightForeArm = [L(-0.16, -0.03, whip), 0, L(-0.10, -0.04, whip)];
      pose.RightHand = [0, 0, L(-0.06, -0.04, whip)];
      pose.armExtend = L(0.18, 1.0, whip);
      return pose;
    }

    /* Phase 4 (0.78..1.24): Smooth upper-body recovery back to idle stance while lower body stays planted */
    const rec = ss(u, 0.78, BOSS_PUNCH_DURATION);
    const follow = computeBossPose("punch", time, runPhase, 0.77);
    const blend = (a, b) => [L(a[0], b[0], rec), L(a[1], b[1], rec), L(a[2], b[2], rec)];
    pose.Spine = blend(follow.Spine, idle.Spine);
    pose.Spine1 = blend(follow.Spine1, idle.Spine1);
    pose.Spine2 = blend(follow.Spine2, idle.Spine2);
    pose.Neck = blend(follow.Neck, idle.Neck);
    pose.Head = blend(follow.Head, idle.Head);
    pose.LeftShoulder = blend(follow.LeftShoulder, idle.LeftShoulder);
    pose.LeftArm = blend(follow.LeftArm, idle.LeftArm);
    pose.LeftForeArm = blend(follow.LeftForeArm, idle.LeftForeArm);
    pose.RightShoulder = blend(follow.RightShoulder, idle.RightShoulder);
    pose.RightArm = blend(follow.RightArm, idle.RightArm);
    pose.RightForeArm = blend(follow.RightForeArm, idle.RightForeArm);
    pose.RightHand = blend(follow.RightHand, idle.RightHand);
    pose.armExtend = L(follow.armExtend, 0, rec);
    return pose;
  }

  /* Default: Poised volcanic colossus combat Idle ("idle") with planted lower body */
  const breath = Math.sin(time * 2.3);
  const sway = Math.sin(time * 1.15);
  pose.Spine = [0.05 + breath * 0.025, 0.05 + sway * 0.03, 0];
  pose.Spine1 = [0.04 + breath * 0.02, 0.05, 0];
  pose.Spine2 = [0.04 + breath * 0.025, 0.05, 0];
  pose.Neck = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  pose.Head = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  /* Poised claw guard: forearms raised slightly forward (+Z), shoulders broad */
  pose.LeftArm = [-0.26 - breath * 0.03, -0.18, 0.14 + breath * 0.02];
  pose.LeftForeArm = [-0.48 - breath * 0.04, 0, 0.12];
  pose.RightArm = [-0.22 - breath * 0.03, 0.16, -0.16 - breath * 0.02];
  pose.RightForeArm = [-0.52 - breath * 0.04, 0, -0.12];
  return pose;
}

const POSE_BONE_KEYS = [
  "Hips",
  "Spine",
  "Spine1",
  "Spine2",
  "Neck",
  "Head",
  "LeftShoulder",
  "LeftArm",
  "LeftForeArm",
  "LeftHand",
  "RightShoulder",
  "RightArm",
  "RightForeArm",
  "RightHand",
  "LeftUpLeg",
  "LeftLeg",
  "LeftFoot",
  "RightUpLeg",
  "RightLeg",
  "RightFoot",
];

const ARM_EXTEND_SCALES = [
  ["RightArm", 0.24],
  ["RightForeArm", 0.42],
  ["RightHand", 0.46],
];

export function applyBossPoseDirect(bossNodes, pose, dampRate, dt) {
  if (!bossNodes.Hips) return;
  const alpha = dampRate <= 0 ? 1 : 1 - Math.exp(-dampRate * Math.max(dt, 0.0001));

  const hRest = bossNodes.Hips.userData.restPos;
  if (hRest) {
    bossNodes.Hips.position.x = THREE.MathUtils.lerp(bossNodes.Hips.position.x, hRest.x + pose.hipsPos[0], alpha);
    bossNodes.Hips.position.y = THREE.MathUtils.lerp(bossNodes.Hips.position.y, hRest.y + pose.hipsPos[1], alpha);
    bossNodes.Hips.position.z = THREE.MathUtils.lerp(bossNodes.Hips.position.z, hRest.z + pose.hipsPos[2], alpha);
  }

  /* Stylistic reach extension along the right arm/forearm/hand during the swing */
  const ext = pose.armExtend ?? 0;
  for (const [bName, mult] of ARM_EXTEND_SCALES) {
    const b = bossNodes[bName];
    const rPos = b?.userData?.restPos;
    if (!b || !rPos) continue;
    const s = 1 + ext * mult;
    b.position.x = THREE.MathUtils.lerp(b.position.x, rPos.x * s, alpha);
    b.position.y = THREE.MathUtils.lerp(b.position.y, rPos.y * s, alpha);
    b.position.z = THREE.MathUtils.lerp(b.position.z, rPos.z * s, alpha);
  }

  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    const isArm = key === "LeftArm" || key === "RightArm" || key === "LeftForeArm" || key === "RightForeArm";
    const order = isArm ? "YXZ" : "XYZ";
    tmpEuler.set(rot[0], rot[1], rot[2], order);
    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }
}

/* Boss Entity, Loader & Combat Mechanic Handler (world-boss.js)
   Uses the retopologized & rigged volcanic colossus (`assets/models/boss.glb`) and coordinates:
   - `world-boss-anim.js` (procedural martial idle, run, and wide right-claw arc swing)
   - `world-smear.js` (Godot `mesh-smearing` per-vertex `lag_transform` + `pow(noise, exp)`
     arc interpolation that forms on the moving claw/arm mesh and settles cleanly back into it) */

import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import bossGlb from "./assets/models/boss.glb";
import { createSmearHandler } from "./world-smear.js";
import { BOSS_PUNCH_DURATION, computeBossPose, applyBossPoseDirect } from "./world-boss-anim.js";

export function createWerewolfBoss({
  scene,
  island,
  landing,
  robot,
  colliders,
  decal,
  softMapped,
  bakeShadows,
  isIntroLive,
  addShake,
}) {
  const bossAt = landing.clone();
  bossAt.x -= Math.SQRT1_2 * 3.15;
  bossAt.z += Math.SQRT1_2 * 2.15;
  if (!island.nav.walkable(bossAt.x, bossAt.z)) {
    const near = island.nav.nearest(bossAt.x, bossAt.z);
    if (near) bossAt.copy(near);
  }
  bossAt.y = island.groundAt(bossAt.x, bossAt.z);

  const BOSS_SCALE = 2.65; /* 0.92m bind height * 2.65 = ~2.44m colossus height */
  const BOSS_RUN_SPEED = 4.2;

  const bossGroup = new THREE.Group();
  bossGroup.name = "ColossusBoss";
  bossGroup.position.copy(bossAt);
  const bossHomeYaw = Math.atan2(landing.x - bossAt.x, landing.z - bossAt.z);
  bossGroup.rotation.y = bossHomeYaw;
  scene.add(bossGroup);

  const bossBody = new THREE.Group();
  bossBody.scale.setScalar(BOSS_SCALE);
  bossGroup.add(bossBody);

  decal(bossGroup, { color: "#233022", size: 2.35, y: 0.03, opacity: 0.36 });

  const bossCollider = { x: bossAt.x, z: bossAt.z, r: 0.85 };
  colliders.push(bossCollider);

  /* Godot mesh-smearing handler (`https://godotshaders.com/shader/mesh-smearing/#main`) */
  const armSmear = createSmearHandler({
    weight: 6.8,
    noiseScale: 34.0,
    noisePower: 2.35,
    stretch: 1.48,
  });

  const bossNodes = {};
  let bossReady = false;
  let mainSkeleton = null;
  const tmpWristWS = new THREE.Vector3();
  const tmpClawTipWS = new THREE.Vector3();

  const dampAngle = (current, target, rate, dt) => {
    const diff = Math.atan2(Math.sin(target - current), Math.cos(target - current));
    return current + diff * (1 - Math.exp(-rate * dt));
  };

  const bossState = {
    mode: "auto", /* "auto" | "idle" | "run" | "punch" */
    state: "idle", /* current active state: "idle" | "run" | "punch" */
    inPlace: false,
    lockedTime: null,
    runPhase: 0,
    punchTime: -1,
    punchCooldown: 1.15,
    impactFired: false,
    yaw: bossHomeYaw,
  };

  (async () => {
    try {
      const ab = bossGlb.buffer.slice(bossGlb.byteOffset, bossGlb.byteOffset + bossGlb.byteLength);
      const gltf = await new GLTFLoader().parseAsync(ab, "");
      const model = gltf.scene;

      const skinnedMeshes = [];
      model.traverse((node) => {
        if (node.isSkinnedMesh) skinnedMeshes.push(node);
      });

      mainSkeleton = skinnedMeshes[0]?.skeleton || null;
      if (mainSkeleton) {
        mainSkeleton.bones.forEach((bone) => {
          bone.userData.restPos = bone.position.clone();
          bone.userData.restQuat = bone.quaternion.clone();
          const cleanName = bone.name.replace(/^mixamorig\d*:?/, "");
          bossNodes[cleanName] = bone;
        });
        armSmear.bindSkeleton(mainSkeleton, bossGroup);
      }

      skinnedMeshes.forEach((mesh) => {
        const tex = mesh.material?.map || null;
        if (tex) {
          tex.colorSpace = THREE.SRGBColorSpace;
        }
        const baseMat = softMapped(tex);
        mesh.material = armSmear.enhanceMaterial(baseMat);
        mesh.customDepthMaterial = armSmear.depthMaterial;
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.frustumCulled = false;
      });

      bossBody.add(model);
      bossReady = true;
      update(0.016, performance.now() / 1000);
      bakeShadows();
    } catch (error) {
      console.warn("Boss model failed to load", error);
    }
  })();

  const update = (dt, time) => {
    if (!bossReady || !bossNodes.Hips) return;

    const dxNiko = robot.position.x - bossGroup.position.x;
    const dzNiko = robot.position.z - bossGroup.position.z;
    const distNiko = Math.hypot(dxNiko, dzNiko);
    const dxHome = bossAt.x - bossGroup.position.x;
    const dzHome = bossAt.z - bossGroup.position.z;
    const distHome = Math.hypot(dxHome, dzHome);
    const introActive = Boolean(isIntroLive?.());

    /* 1. Determine active animation state & movement */
    if (bossState.mode === "idle") {
      bossState.state = "idle";
      bossState.punchTime = -1;
    } else if (bossState.mode === "run") {
      bossState.state = "run";
      bossState.punchTime = -1;
      bossState.runPhase = bossState.lockedTime != null ? bossState.lockedTime * 9.5 : bossState.runPhase + dt * 9.5;
      if (!bossState.inPlace && distNiko > 2.05) {
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 1.95, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      }
    } else if (bossState.mode === "punch") {
      bossState.state = "punch";
      if (bossState.lockedTime != null) {
        bossState.punchTime = bossState.lockedTime;
      } else if (bossState.punchTime < 0) {
        bossState.punchTime = 0;
        bossState.impactFired = false;
      } else {
        bossState.punchTime += dt;
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
    } else {
      /* "auto" gameplay mode */
      bossState.punchCooldown = Math.max(0, bossState.punchCooldown - dt);
      if (introActive) {
        bossState.state = "idle";
        bossState.punchTime = -1;
        bossState.yaw = dampAngle(bossState.yaw, bossHomeYaw, 6, dt);
      } else if (bossState.punchTime >= 0) {
        /* Keep bossState.yaw locked during the punch so the planted lower body never slides or rotates in place */
        bossState.state = "punch";
        bossState.punchTime += dt;
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {
          bossState.punchTime = -1;
          bossState.punchCooldown = 1.35;
          bossState.state = "idle";
        }
      } else if (distNiko <= 2.45 && bossState.punchCooldown <= 0) {
        bossState.state = "punch";
        bossState.punchTime = 0;
        bossState.impactFired = false;
        if (distNiko > 0.01) {
          bossState.yaw = Math.atan2(dxNiko, dzNiko);
        }
      } else if (distNiko > 2.25 && distNiko < 8.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.5;
        const yawToNiko = Math.atan2(dxNiko, dzNiko);
        bossState.yaw = dampAngle(bossState.yaw, yawToNiko, 10, dt);
        const step = Math.min(distNiko - 2.05, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + Math.sin(bossState.yaw) * step;
        const nz = bossGroup.position.z + Math.cos(bossState.yaw) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else if (distHome > 0.35 && distNiko >= 8.5) {
        bossState.state = "run";
        bossState.runPhase += dt * 9.0;
        const yawHome = Math.atan2(dxHome, dzHome);
        bossState.yaw = dampAngle(bossState.yaw, yawHome, 9, dt);
        const step = Math.min(distHome, BOSS_RUN_SPEED * dt);
        const nx = bossGroup.position.x + (dxHome / distHome) * step;
        const nz = bossGroup.position.z + (dzHome / distHome) * step;
        if (island.nav.walkable(nx, nz)) {
          bossGroup.position.x = nx;
          bossGroup.position.z = nz;
        }
      } else {
        bossState.state = "idle";
        const lookYaw = distNiko < 9.5 && distNiko > 0.01 ? Math.atan2(dxNiko, dzNiko) : bossHomeYaw;
        bossState.yaw = dampAngle(bossState.yaw, lookYaw, 7, dt);
      }
    }

    bossGroup.position.y = island.groundAt(bossGroup.position.x, bossGroup.position.z);
    bossGroup.rotation.y = bossState.yaw;
    bossCollider.x = bossGroup.position.x;
    bossCollider.z = bossGroup.position.z;

    /* 2. Apply pose and update Godot mesh-smearing (`lag_transform`) only during the forward arc swing & hold settle.
          Smear is strictly disabled (`reset()`) during wind-up (u < 0.35), during recovery back to idle (u >= 0.72),
          and in "idle" or "run" states so the hand never smears while returning to rest or running. */
    if (bossState.state === "punch") {
      const u = bossState.punchTime;
      const getWeightForTime = (t) => (t < 0.35 ? 36.0 : t < 0.54 ? 6.4 : 16.5);
      const getSmearScaleForTime = (t) => {
        if (t < 0.35 || t >= 0.72) return 0;
        if (t <= 0.58) return 1;
        return 1 - THREE.MathUtils.smoothstep(t, 0.58, 0.72);
      };

      if (bossState.lockedTime != null) {
        /* Deterministically integrate `lag_transform.interpolate_with(global_transform, weight * dt)`
           up to `lockedTime` so frozen debug/review frames show the exact arc smear & settle. */
        const smearScale = getSmearScaleForTime(u);
        if (smearScale <= 0) {
          const p = computeBossPose("punch", time, bossState.runPhase, u);
          applyBossPoseDirect(bossNodes, p, 0, 0);
          bossGroup.updateMatrixWorld(true);
          armSmear.reset();
        } else {
          const startT = 0.34;
          const startPose = computeBossPose("punch", time, bossState.runPhase, startT);
          applyBossPoseDirect(bossNodes, startPose, 0, 0);
          bossGroup.updateMatrixWorld(true);
          armSmear.reset();

          const stepDt = 1 / 120;
          for (let simT = startT + stepDt; simT <= u + 1e-5; simT += stepDt) {
            const clampedT = Math.min(simT, u);
            const p = computeBossPose("punch", time, bossState.runPhase, clampedT);
            applyBossPoseDirect(bossNodes, p, 0, 0);
            bossGroup.updateMatrixWorld(true);
            armSmear.stepLag(stepDt, getWeightForTime(clampedT), getSmearScaleForTime(clampedT));
          }
        }
      } else {
        const smearScale = getSmearScaleForTime(u);
        const isSwingOrSettle = u >= 0.35 && u < 0.72;
        const poseDamp = isSwingOrSettle ? 42 : 18;
        const targetPose = computeBossPose("punch", time, bossState.runPhase, u);
        applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
        bossGroup.updateMatrixWorld(true);
        if (smearScale > 0) {
          armSmear.stepLag(dt, getWeightForTime(u), smearScale);
        } else {
          armSmear.reset();
        }

        /* Trigger screen shake ONLY when the swinging right claw actually makes contact with Niko */
        if (!bossState.impactFired && u >= 0.38 && u <= 0.56 && bossNodes.RightHand && !introActive) {
          bossNodes.RightHand.getWorldPosition(tmpWristWS);
          tmpClawTipWS.set(0, -0.16, 0.06).applyMatrix4(bossNodes.RightHand.matrixWorld);
          const wristDist = Math.hypot(robot.position.x - tmpWristWS.x, robot.position.z - tmpWristWS.z);
          const tipDist = Math.hypot(robot.position.x - tmpClawTipWS.x, robot.position.z - tmpClawTipWS.z);
          if (Math.min(wristDist, tipDist) <= 0.95) {
            bossState.impactFired = true;
            addShake?.(0.24);
          }
        }
      }
    } else {
      const poseDamp = bossState.lockedTime != null ? 0 : 14;
      const targetPose = computeBossPose(bossState.state, time, bossState.runPhase, -1);
      applyBossPoseDirect(bossNodes, targetPose, poseDamp, dt);
      bossGroup.updateMatrixWorld(true);
      armSmear.reset();
    }
  };

  const debug = (options) => {
    if (options && typeof options === "object") {
      if (options.mode) {
        bossState.mode = options.mode;
        if (options.mode === "punch" && options.time == null) {
          bossState.punchTime = 0;
          bossState.impactFired = false;
        }
      }
      if ("inPlace" in options) bossState.inPlace = Boolean(options.inPlace);
      if ("time" in options) bossState.lockedTime = options.time;
      if (options.yaw != null) bossState.yaw = options.yaw;
      if (options.resetPos) {
        bossGroup.position.copy(bossAt);
        bossState.yaw = bossHomeYaw;
        armSmear.reset();
      }
      update(0.016, performance.now() / 1000);
    }
    return {
      ready: bossReady,
      mode: bossState.mode,
      state: bossState.state,
      punchTime: +bossState.punchTime.toFixed(3),
      lagDistance: armSmear.getLagDistance(),
      at: bossGroup.position.toArray().map((n) => +n.toFixed(2)),
      scale: BOSS_SCALE,
    };
  };

  return {
    group: bossGroup,
    update,
    debug,
  };
}

/* Boss Animation Pose & Joint Articulation Handler (world-boss-anim.js)
   Computes procedural Sekiro/Soulslike poses for the rigged volcanic colossus (`assets/models/boss.glb`):
   1. "idle"  — heavy, poised colossus combat guard with planted lower body & rhythmic chest heave
   2. "run"   — powerful forward charge with counter-rotating torso and heavy stride
   3. "punch" — planted-stance wide horizontal right-claw arc swing with full arm/hand extension
                designed to showcase the Godot mesh-smearing (`lag_transform` + `pow(noise, exp)`). */

import * as THREE from "three";

export const BOSS_PUNCH_DURATION = 1.24;

const tmpEuler = new THREE.Euler();
const tmpDeltaQuat = new THREE.Quaternion();
const tmpTargetQuat = new THREE.Quaternion();

/* Planted lower-body stance shared by "idle" and "punch" so the pelvis, legs, and feet
   never drift or slide during the hand swing. */
const PLANTED_LOWER_BODY = {
  hipsPos: [0, -0.022, 0],
  Hips: [0.04, -0.10, 0],
  LeftUpLeg: [-0.20, 0.04, 0],
  LeftLeg: [0.34, 0, 0],
  LeftFoot: [-0.14, 0, 0],
  RightUpLeg: [0.14, -0.04, 0],
  RightLeg: [0.24, 0, 0],
  RightFoot: [-0.28, 0, 0],
};

export function computeBossPose(state, time, runPhase, punchTime) {
  const ss = THREE.MathUtils.smoothstep;
  const L = THREE.MathUtils.lerp;

  const pose = {
    hipsPos: [...PLANTED_LOWER_BODY.hipsPos],
    Hips: [...PLANTED_LOWER_BODY.Hips],
    Spine: [0, 0, 0],
    Spine1: [0, 0, 0],
    Spine2: [0, 0, 0],
    Neck: [0, 0, 0],
    Head: [0, 0, 0],
    LeftShoulder: [0, 0, 0],
    LeftArm: [0, 0, 0],
    LeftForeArm: [0, 0, 0],
    LeftHand: [0, 0, 0],
    RightShoulder: [0, 0, 0],
    RightArm: [0, 0, 0],
    RightForeArm: [0, 0, 0],
    RightHand: [0, 0, 0],
    LeftUpLeg: [...PLANTED_LOWER_BODY.LeftUpLeg],
    LeftLeg: [...PLANTED_LOWER_BODY.LeftLeg],
    LeftFoot: [...PLANTED_LOWER_BODY.LeftFoot],
    RightUpLeg: [...PLANTED_LOWER_BODY.RightUpLeg],
    RightLeg: [...PLANTED_LOWER_BODY.RightLeg],
    RightFoot: [...PLANTED_LOWER_BODY.RightFoot],
    armExtend: 0, /* 0..1 reach extension along RightArm / RightForeArm / RightHand */
  };

  if (state === "run") {
    const p = runPhase;
    const s1 = Math.sin(p);
    const c1 = Math.cos(p);
    const bob = Math.abs(s1);
    pose.hipsPos = [c1 * 0.014, -0.028 + (bob - 0.5) * 0.036, 0];
    pose.Hips = [0.14, -s1 * 0.16, c1 * 0.05];
    pose.Spine = [0.12 + bob * 0.04, s1 * 0.10, -c1 * 0.04];
    pose.Spine1 = [0.08, s1 * 0.10, 0];
    pose.Spine2 = [0.08, s1 * 0.12, 0];
    pose.Neck = [-0.14, -s1 * 0.08, 0];
    pose.Head = [-0.12, -s1 * 0.08, 0];
    /* Pumping claw arms in heavy charge (YXZ order: rx < 0 swings arm forward +Z, rz lifts outward) */
    pose.LeftArm = [-0.18 + s1 * 0.58, -0.12, 0.16];
    pose.LeftForeArm = [-0.62 - Math.max(0, -s1) * 0.25, 0, 0.10];
    pose.RightArm = [-0.18 - s1 * 0.58, 0.12, -0.16];
    pose.RightForeArm = [-0.62 - Math.max(0, s1) * 0.25, 0, -0.10];
    /* Stride: rx < 0 lifts thigh forward (+Z), rx > 0 bends shin backward (-Z) */
    pose.LeftUpLeg = [-s1 * 0.58 - 0.08, 0, 0];
    pose.LeftLeg = [0.18 + Math.max(0, -c1) * 0.68, 0, 0];
    pose.LeftFoot = [-0.08 + s1 * 0.18, 0, 0];
    pose.RightUpLeg = [s1 * 0.58 - 0.08, 0, 0];
    pose.RightLeg = [0.18 + Math.max(0, c1) * 0.68, 0, 0];
    pose.RightFoot = [-0.08 - s1 * 0.18, 0, 0];
    return pose;
  }

  if (state === "punch") {
    const u = THREE.MathUtils.clamp(punchTime, 0, BOSS_PUNCH_DURATION);
    const idle = computeBossPose("idle", time, runPhase, 0);

    if (u < 0.36) {
      /* Phase 1: Wind-up — lower body stays 100% planted while upper spine coils right
         and raises the right claw wide behind the right shoulder */
      const w = ss(u, 0.0, 0.34);
      const blend = (a, b) => [L(a[0], b[0], w), L(a[1], b[1], w), L(a[2], b[2], w)];
      pose.Spine = blend(idle.Spine, [-0.04, -0.22, -0.03]);
      pose.Spine1 = blend(idle.Spine1, [-0.03, -0.24, -0.02]);
      pose.Spine2 = blend(idle.Spine2, [0.02, -0.26, 0]);
      pose.Neck = blend(idle.Neck, [0.02, 0.26, 0]);
      pose.Head = blend(idle.Head, [0.02, 0.30, 0]);
      /* Left claw guards left flank; Right claw lifts to chest height (rz = -0.98) and opens wide back-right (ry = -0.82) */
      pose.LeftShoulder = blend(idle.LeftShoulder, [0, 0, 0.05]);
      pose.LeftArm = blend(idle.LeftArm, [-0.30, -0.20, 0.20]);
      pose.LeftForeArm = blend(idle.LeftForeArm, [-0.52, 0, 0.14]);
      pose.RightShoulder = blend(idle.RightShoulder, [0, -0.22, -0.10]);
      pose.RightArm = blend(idle.RightArm, [-0.10, -0.82, -0.98]);
      pose.RightForeArm = blend(idle.RightForeArm, [-0.14, 0, -0.08]);
      pose.RightHand = blend(idle.RightHand, [0, 0, -0.06]);
      pose.armExtend = L(0, 0.22, w);
      return pose;
    }

    if (u < 0.78) {
      /* Phase 2 (0.36..0.55): Wide chest-level circular arc swing across the front with full arm/hand reach extension.
         Phase 3 (0.55..0.78): Follow-through hold across chest while `lag_transform` settles cleanly into the claw mesh.
         Lower body (Hips & Legs) stays 100% locked to PLANTED_LOWER_BODY so feet never slide or drift. */
      const rawS = THREE.MathUtils.clamp((u - 0.36) / 0.19, 0, 1);
      const whip = 1 - Math.pow(1 - rawS, 2.4);
      pose.Spine = [L(-0.04, 0.12, whip), L(-0.22, 0.22, whip), L(-0.03, 0.04, whip)];
      pose.Spine1 = [L(-0.03, 0.12, whip), L(-0.24, 0.24, whip), L(-0.02, 0.02, whip)];
      pose.Spine2 = [L(0.02, 0.14, whip), L(-0.26, 0.28, whip), 0];
      pose.Neck = [L(0.02, -0.08, whip), L(0.26, -0.26, whip), 0];
      pose.Head = [L(0.02, -0.08, whip), L(0.30, -0.30, whip), 0];
      /* Left arm stays in a compact low counter-guard by the left ribcage */
      pose.LeftShoulder = [0, 0, L(0.05, 0.08, whip)];
      pose.LeftArm = [L(-0.30, -0.08, whip), L(-0.20, -0.04, whip), L(0.20, 0.24, whip)];
      pose.LeftForeArm = [L(-0.52, -0.46, whip), 0, 0.14];
      /* Right shoulder drives forward and elbow straightens out so the whole arm & hand extend long across the arc */
      pose.RightShoulder = [0, L(-0.22, 0.34, whip), L(-0.10, -0.04, whip)];
      pose.RightArm = [
        L(-0.10, -0.14, whip),
        L(-0.82, 1.48, whip),
        L(-0.98, -0.94, whip),
      ];
      pose.RightForeArm = [L(-0.14, -0.02, whip), 0, L(-0.08, -0.03, whip)];
      pose.RightHand = [0, 0, L(-0.06, -0.04, whip)];
      pose.armExtend = L(0.22, 1.0, whip);
      return pose;
    }

    /* Phase 4 (0.78..1.24): Smooth upper-body recovery back to idle stance while lower body stays planted */
    const rec = ss(u, 0.78, BOSS_PUNCH_DURATION);
    const follow = computeBossPose("punch", time, runPhase, 0.77);
    const blend = (a, b) => [L(a[0], b[0], rec), L(a[1], b[1], rec), L(a[2], b[2], rec)];
    pose.Spine = blend(follow.Spine, idle.Spine);
    pose.Spine1 = blend(follow.Spine1, idle.Spine1);
    pose.Spine2 = blend(follow.Spine2, idle.Spine2);
    pose.Neck = blend(follow.Neck, idle.Neck);
    pose.Head = blend(follow.Head, idle.Head);
    pose.LeftShoulder = blend(follow.LeftShoulder, idle.LeftShoulder);
    pose.LeftArm = blend(follow.LeftArm, idle.LeftArm);
    pose.LeftForeArm = blend(follow.LeftForeArm, idle.LeftForeArm);
    pose.RightShoulder = blend(follow.RightShoulder, idle.RightShoulder);
    pose.RightArm = blend(follow.RightArm, idle.RightArm);
    pose.RightForeArm = blend(follow.RightForeArm, idle.RightForeArm);
    pose.RightHand = blend(follow.RightHand, idle.RightHand);
    pose.armExtend = L(follow.armExtend, 0, rec);
    return pose;
  }

  /* Default: Poised volcanic colossus combat Idle ("idle") with planted lower body */
  const breath = Math.sin(time * 2.3);
  const sway = Math.sin(time * 1.15);
  pose.Spine = [0.05 + breath * 0.025, 0.05 + sway * 0.03, 0];
  pose.Spine1 = [0.04 + breath * 0.02, 0.05, 0];
  pose.Spine2 = [0.04 + breath * 0.025, 0.05, 0];
  pose.Neck = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  pose.Head = [-0.05 - breath * 0.02, -0.04 - sway * 0.03, 0];
  /* Poised claw guard: forearms raised slightly forward (+Z), shoulders broad */
  pose.LeftArm = [-0.26 - breath * 0.03, -0.18, 0.14 + breath * 0.02];
  pose.LeftForeArm = [-0.48 - breath * 0.04, 0, 0.12];
  pose.RightArm = [-0.22 - breath * 0.03, 0.16, -0.16 - breath * 0.02];
  pose.RightForeArm = [-0.52 - breath * 0.04, 0, -0.12];
  return pose;
}

const POSE_BONE_KEYS = [
  "Hips",
  "Spine",
  "Spine1",
  "Spine2",
  "Neck",
  "Head",
  "LeftShoulder",
  "LeftArm",
  "LeftForeArm",
  "LeftHand",
  "RightShoulder",
  "RightArm",
  "RightForeArm",
  "RightHand",
  "LeftUpLeg",
  "LeftLeg",
  "LeftFoot",
  "RightUpLeg",
  "RightLeg",
  "RightFoot",
];

const ARM_EXTEND_SCALES = [
  ["RightArm", 0.26],
  ["RightForeArm", 0.45],
  ["RightHand", 0.50],
];

export function applyBossPoseDirect(bossNodes, pose, dampRate, dt) {
  if (!bossNodes.Hips) return;
  const alpha = dampRate <= 0 ? 1 : 1 - Math.exp(-dampRate * Math.max(dt, 0.0001));

  const hRest = bossNodes.Hips.userData.restPos;
  if (hRest) {
    bossNodes.Hips.position.x = THREE.MathUtils.lerp(bossNodes.Hips.position.x, hRest.x + pose.hipsPos[0], alpha);
    bossNodes.Hips.position.y = THREE.MathUtils.lerp(bossNodes.Hips.position.y, hRest.y + pose.hipsPos[1], alpha);
    bossNodes.Hips.position.z = THREE.MathUtils.lerp(bossNodes.Hips.position.z, hRest.z + pose.hipsPos[2], alpha);
  }

  /* Stylistic reach extension along the right arm/forearm/hand during the swing */
  const ext = pose.armExtend ?? 0;
  for (const [bName, mult] of ARM_EXTEND_SCALES) {
    const b = bossNodes[bName];
    const rPos = b?.userData?.restPos;
    if (!b || !rPos) continue;
    const s = 1 + ext * mult;
    b.position.x = THREE.MathUtils.lerp(b.position.x, rPos.x * s, alpha);
    b.position.y = THREE.MathUtils.lerp(b.position.y, rPos.y * s, alpha);
    b.position.z = THREE.MathUtils.lerp(b.position.z, rPos.z * s, alpha);
  }
  if (bossNodes.RightHand) {
    const hs = 1 + ext * 0.22;
    const hy = 1 + ext * 0.36;
    bossNodes.RightHand.scale.set(
      THREE.MathUtils.lerp(bossNodes.RightHand.scale.x, hs, alpha),
      THREE.MathUtils.lerp(bossNodes.RightHand.scale.y, hy, alpha),
      THREE.MathUtils.lerp(bossNodes.RightHand.scale.z, hs, alpha),
    );
  }

  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    const isArm = key === "LeftArm" || key === "RightArm" || key === "LeftForeArm" || key === "RightForeArm";
    const order = isArm ? "YXZ" : "XYZ";
    tmpEuler.set(rot[0], rot[1], rot[2], order);
    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }
}

/* Mesh-Smearing Handler (world-smear.js)
   Implements the Godot "Mesh smearing" technique by celyk:
   https://godotshaders.com/shader/mesh-smearing/#main
     lag_transform = lag_transform.interpolate_with(global_transform, weight * delta)
     float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
     MODELVIEW_MATRIX = MODEL_MATRIX + (lag_transform - MODEL_MATRIX) * t;
   Adapted for Three.js SkinnedMesh (`assets/models/boss.glb`):
   - Maintains lagging bone transforms (`uLagBoneTexture`) and mid-arc bone transforms (`uMidBoneTexture`)
     that smoothly slerp toward the current skeleton pose (`lagQuat.slerp(currQuat, 1 - exp(-weight * dt))`).
   - Evaluates continuous 3D gradient noise on the vertex's bind-pose position (`restPos`) so the smear
     is 100% seam-free and watertight across UV islands.
   - Interpolates each vertex along the curved Quadratic Bezier swing arc `(posCurr -> posMid -> posLag)`
     by `t = pow(noise, power) * stretch`, so the smear forms cleanly out of the right claw/arm mesh during
     the swing and settles smoothly back into the mesh as `lag_transform` catches up. */

import * as THREE from "three";

const SMEAR_SKINNING_PARS_GLSL = /* glsl */ `
#ifdef USE_SKINNING
  uniform highp sampler2D uMidBoneTexture;
  uniform highp sampler2D uLagBoneTexture;
  uniform float uSmearNoiseScale;
  uniform float uSmearNoisePower;
  uniform float uSmearStretch;

  mat4 getSmearBoneMatrix( highp sampler2D tex, const in float i ) {
    int size = textureSize( tex, 0 ).x;
    int j = int( i ) * 4;
    int x = j % size;
    int y = j / size;
    vec4 v1 = texelFetch( tex, ivec2( x, y ), 0 );
    vec4 v2 = texelFetch( tex, ivec2( x + 1, y ), 0 );
    vec4 v3 = texelFetch( tex, ivec2( x + 2, y ), 0 );
    vec4 v4 = texelFetch( tex, ivec2( x + 3, y ), 0 );
    return mat4( v1, v2, v3, v4 );
  }

  /* Bone indices in assets/models/boss.glb:
     10 = RightShoulder, 11 = RightArm, 12 = RightForeArm, 13 = RightHand */
  float getRightArmBoneMask( const in float idx ) {
    int b = int( idx + 0.5 );
    if ( b == 13 ) return 1.0;
    if ( b == 12 ) return 0.86;
    if ( b == 11 ) return 0.44;
    if ( b == 10 ) return 0.12;
    return 0.0;
  }

  vec3 smearHash3( vec3 p ) {
    p = vec3(
      dot( p, vec3( 127.1, 311.7, 74.7 ) ),
      dot( p, vec3( 269.5, 183.3, 246.1 ) ),
      dot( p, vec3( 113.5, 271.9, 124.6 ) )
    );
    return -1.0 + 2.0 * fract( sin( p ) * 43758.5453123 );
  }

  float smearGradNoise3D( vec3 p ) {
    vec3 i = floor( p );
    vec3 f = fract( p );
    vec3 u = f * f * ( 3.0 - 2.0 * f );
    return mix(
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 0.0 ) ), f - vec3( 0.0, 0.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 0.0 ) ), f - vec3( 1.0, 0.0, 0.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 0.0 ) ), f - vec3( 0.0, 1.0, 0.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 0.0 ) ), f - vec3( 1.0, 1.0, 0.0 ) ), u.x ),
        u.y
      ),
      mix(
        mix( dot( smearHash3( i + vec3( 0.0, 0.0, 1.0 ) ), f - vec3( 0.0, 0.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 0.0, 1.0 ) ), f - vec3( 1.0, 0.0, 1.0 ) ), u.x ),
        mix( dot( smearHash3( i + vec3( 0.0, 1.0, 1.0 ) ), f - vec3( 0.0, 1.0, 1.0 ) ),
             dot( smearHash3( i + vec3( 1.0, 1.0, 1.0 ) ), f - vec3( 1.0, 1.0, 1.0 ) ), u.x ),
        u.y
      ),
      u.z
    );
  }

  float smearFbm( vec3 p ) {
    float v = 0.5 + 0.5 * smearGradNoise3D( p );
    v = 0.68 * v + 0.32 * ( 0.5 + 0.5 * smearGradNoise3D( p * 2.07 + vec3( 13.7, 29.3, 7.1 ) ) );
    /* Normalize noise range so valleys sit at 0.0 and ridges reach 1.0 before pow(n, power) */
    return smoothstep( 0.22, 0.76, v );
  }
#endif
`;

const SMEAR_SKINNING_VERTEX_GLSL = /* glsl */ `
  float smearTVal = 0.0;
#ifdef USE_SKINNING
  vec3 restPos = transformed;
  vec4 skinVertex = bindMatrix * vec4( transformed, 1.0 );
  mat4 currSkinMat =
    boneMatX * skinWeight.x +
    boneMatY * skinWeight.y +
    boneMatZ * skinWeight.z +
    boneMatW * skinWeight.w;
  vec4 skinned = currSkinMat * skinVertex;

  /* Smooth right-arm & claw mask from skin weights (bones 10..13) + bind-pose distal gradient */
  float boneArmMask =
    getRightArmBoneMask( skinIndex.x ) * skinWeight.x +
    getRightArmBoneMask( skinIndex.y ) * skinWeight.y +
    getRightArmBoneMask( skinIndex.z ) * skinWeight.z +
    getRightArmBoneMask( skinIndex.w ) * skinWeight.w;
  float distalBoost = 0.60 + 0.40 * ( 1.0 - smoothstep( 0.22, 0.66, restPos.y ) );
  float handMask = clamp( boneArmMask * distalBoost, 0.0, 1.0 );

  if ( uSmearStretch > 0.001 && handMask > 0.001 ) {
    mat4 midMatX = getSmearBoneMatrix( uMidBoneTexture, skinIndex.x );
    mat4 midMatY = getSmearBoneMatrix( uMidBoneTexture, skinIndex.y );
    mat4 midMatZ = getSmearBoneMatrix( uMidBoneTexture, skinIndex.z );
    mat4 midMatW = getSmearBoneMatrix( uMidBoneTexture, skinIndex.w );
    vec4 skinnedMid = (
      midMatX * skinWeight.x +
      midMatY * skinWeight.y +
      midMatZ * skinWeight.z +
      midMatW * skinWeight.w
    ) * skinVertex;

    mat4 lagMatX = getSmearBoneMatrix( uLagBoneTexture, skinIndex.x );
    mat4 lagMatY = getSmearBoneMatrix( uLagBoneTexture, skinIndex.y );
    mat4 lagMatZ = getSmearBoneMatrix( uLagBoneTexture, skinIndex.z );
    mat4 lagMatW = getSmearBoneMatrix( uLagBoneTexture, skinIndex.w );
    vec4 skinnedLag = (
      lagMatX * skinWeight.x +
      lagMatY * skinWeight.y +
      lagMatZ * skinWeight.z +
      lagMatW * skinWeight.w
    ) * skinVertex;

    vec3 wakeVec = skinnedLag.xyz - skinned.xyz;
    float wakeLen = length( wakeVec );
    if ( wakeLen > 0.0005 ) {
      vec3 wakeDir = wakeVec / wakeLen;
      /* Cross-sectional outward normal around the A-pose right arm/claw centerline,
         rotated by currSkinMat so the trailing half of the claw/forearm stretches back
         along the swing arc while the leading front face stays crisp and intact. */
      float yFrac = clamp( ( restPos.y - 0.20 ) / 0.52, 0.0, 1.0 );
      float armCenterX = mix( -0.382, -0.24, yFrac );
      float armCenterZ = mix( 0.072, -0.03, clamp( ( restPos.y - 0.28 ) / 0.28, 0.0, 1.0 ) );
      vec3 cylNormalBind = normalize( vec3( ( restPos.x - armCenterX ) * 0.65, 0.0, restPos.z - armCenterZ ) );
      vec3 cylNormalWS = normalize( mat3( currSkinMat ) * cylNormalBind );
      float trailAlign = smoothstep( -0.38, 0.35, dot( cylNormalWS, wakeDir ) );

      /* Godot mesh-smearing formula:
         float t = pow(texture(noise, UV * 5.0).x, 6.5) * 2.0;
         Evaluated on 3D bind-pose restPos with a cohesive trailing base plus fine longitudinal streaks
         so the smear forms a smooth, unified arc on the claw/forearm and settles cleanly onto the mesh. */
      vec3 noisePos = vec3(
        restPos.x * uSmearNoiseScale * 1.35,
        restPos.y * uSmearNoiseScale * 0.55,
        restPos.z * uSmearNoiseScale * 1.35
      );
      float n = smearFbm( noisePos );
      float streakProfile = 0.24 + 0.86 * pow( n, uSmearNoisePower );
      float t = streakProfile * uSmearStretch * handMask * trailAlign;
      t = clamp( t, 0.0, 1.32 );

      /* Quadratic Bezier interpolation through skinned (t=0), skinnedMid (t=0.5), skinnedLag (t=1.0)
         so the smear curves smoothly along the circular swing arc of the arm and claw! */
      vec3 ctrl = 2.0 * skinnedMid.xyz - 0.5 * ( skinned.xyz + skinnedLag.xyz );
      float u = 1.0 - t;
      vec3 arcWS = u * u * skinned.xyz + 2.0 * u * t * ctrl + t * t * skinnedLag.xyz;
      skinned.xyz = arcWS;
      smearTVal = clamp( t * clamp( wakeLen * 4.5, 0.0, 1.0 ), 0.0, 1.0 );
    }
  }
  transformed = ( bindMatrixInverse * skinned ).xyz;
#endif
`;

export function createSmearHandler(options = {}) {
  const config = {
    weight: options.weight ?? 8.0, /* Godot lag_transform interpolation weight */
    noiseScale: options.noiseScale ?? 34.0,
    noisePower: options.noisePower ?? 2.4,
    stretch: options.stretch ?? 1.45,
  };

  /* Fallback 16x16 DataTextures until the skeleton is bound */
  const makeBoneTex = (size) => {
    const data = new Float32Array(size * size * 4);
    const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.FloatType);
    tex.needsUpdate = true;
    return { data, tex };
  };
  let midBuf = makeBoneTex(16);
  let lagBuf = makeBoneTex(16);

  const uniforms = {
    uMidBoneTexture: { value: midBuf.tex },
    uLagBoneTexture: { value: lagBuf.tex },
    uSmearNoiseScale: { value: config.noiseScale },
    uSmearNoisePower: { value: config.noisePower },
    uSmearStretch: { value: 0 },
  };

  const depthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
  depthMaterial.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace("#include <skinning_pars_vertex>", `#include <skinning_pars_vertex>\n${SMEAR_SKINNING_PARS_GLSL}`)
      .replace("#include <skinning_vertex>", SMEAR_SKINNING_VERTEX_GLSL);
  };
  depthMaterial.customProgramCacheKey = () => "godot-mesh-smear-depth";

  const enhanceMaterial = (material) => {
    const prev = material.onBeforeCompile;
    const baseKey = material.customProgramCacheKey?.() || "soft-toon";
    material.onBeforeCompile = (shader, renderer) => {
      prev?.(shader, renderer);
      Object.assign(shader.uniforms, uniforms);
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <skinning_pars_vertex>",
          `#include <skinning_pars_vertex>\n${SMEAR_SKINNING_PARS_GLSL}\nvarying float vSmearT;`,
        )
        .replace(
          "#include <skinning_vertex>",
          `${SMEAR_SKINNING_VERTEX_GLSL}\nvSmearT = smearTVal;`,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace("#include <common>", "#include <common>\nvarying float vSmearT;")
        .replace(
          "#include <opaque_fragment>",
          [
            "if (vSmearT > 0.01) {",
            "  /* Subtle ember ridge highlight so the volcanic claw's mesh-smear spikes read clearly */",
            "  float ridge = smoothstep(0.08, 0.78, vSmearT);",
            "  outgoingLight = mix(outgoingLight, outgoingLight * 1.14 + vec3(0.28, 0.09, 0.02), ridge * 0.68);",
            "}",
            "#include <opaque_fragment>",
          ].join("\n"),
        );
    };
    material.customProgramCacheKey = () => `${baseKey}-godot-mesh-smear`;
    return material;
  };

  let boundSkeleton = null;
  let boundRoot = null;
  let boneWeights = [];
  let currPos = [];
  let currQuat = [];
  let currScale = [];
  let lagPos = [];
  let lagQuat = [];
  let lagScale = [];
  let initialized = false;
  let handBoneIdx = -1;
  let lastLagDistance = 0;
  const tmpOffsetMat = new THREE.Matrix4();
  const tmpCurrHandWS = new THREE.Vector3();
  const tmpLagHandWS = new THREE.Vector3();

  const bindSkeleton = (skeleton, rootGroup) => {
    boundSkeleton = skeleton;
    boundRoot = rootGroup;
    skeleton.computeBoneTexture();
    const size = skeleton.boneTexture.image.width;
    midBuf = makeBoneTex(size);
    lagBuf = makeBoneTex(size);
    uniforms.uMidBoneTexture.value = midBuf.tex;
    uniforms.uLagBoneTexture.value = lagBuf.tex;

    const count = skeleton.bones.length;
    boneWeights = new Array(count).fill(100);
    currPos = new Array(count);
    currQuat = new Array(count);
    currScale = new Array(count);
    lagPos = new Array(count);
    lagQuat = new Array(count);
    lagScale = new Array(count);
    handBoneIdx = -1;

    for (let i = 0; i < count; i += 1) {
      const b = skeleton.bones[i];
      const name = b.name.replace(/^mixamorig\d*:?/, "");
      currPos[i] = b.position.clone();
      currQuat[i] = b.quaternion.clone();
      currScale[i] = b.scale.clone();
      lagPos[i] = b.position.clone();
      lagQuat[i] = b.quaternion.clone();
      lagScale[i] = b.scale.clone();
      if (name === "RightHand") handBoneIdx = i;

      /* Only the right arm chain + upper spine twist lag behind; legs/hips/left arm stay at 0 */
      if (/^Right(Shoulder|Arm|ForeArm|Hand)/.test(name)) {
        boneWeights[i] = 1.0; /* uses config.weight directly */
      } else if (name === "Spine1" || name === "Spine2") {
        boneWeights[i] = 1.85; /* subtle upper-torso arc follow */
      } else {
        boneWeights[i] = 0; /* 0 means snap immediately to current pose */
      }
    }
    initialized = false;
  };

  const writeBoneMatricesTo = (targetArray) => {
    const bones = boundSkeleton.bones;
    const inverses = boundSkeleton.boneInverses;
    for (let i = 0; i < bones.length; i += 1) {
      tmpOffsetMat.multiplyMatrices(bones[i].matrixWorld, inverses[i]);
      tmpOffsetMat.toArray(targetArray, i * 16);
    }
  };

  const reset = () => {
    if (!boundSkeleton) return;
    const bones = boundSkeleton.bones;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      currScale[i].copy(bones[i].scale);
      lagPos[i].copy(bones[i].position);
      lagQuat[i].copy(bones[i].quaternion);
      lagScale[i].copy(bones[i].scale);
    }
    boundRoot?.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    writeBoneMatricesTo(lagBuf.data);
    midBuf.tex.needsUpdate = true;
    lagBuf.tex.needsUpdate = true;
    uniforms.uSmearStretch.value = 0;
    lastLagDistance = 0;
    initialized = true;
  };

  /* Advance lag_transform = lag_transform.interpolate_with(global_transform, weight * dt)
     and populate uMidBoneTexture (slerp 0.5) and uLagBoneTexture (slerp 1.0). */
  const stepLag = (dt, weightOverride = null, stretchScale = 1.0) => {
    if (!boundSkeleton || !boundRoot) return;
    if (stretchScale <= 0.001) {
      reset();
      return;
    }
    const bones = boundSkeleton.bones;
    if (!initialized) {
      reset();
    }
    uniforms.uSmearStretch.value = config.stretch * stretchScale;
    const baseWeight = weightOverride ?? config.weight;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      currScale[i].copy(bones[i].scale);
      const mult = boneWeights[i];
      if (mult <= 0 || dt <= 0) {
        lagPos[i].copy(currPos[i]);
        lagQuat[i].copy(currQuat[i]);
        lagScale[i].copy(currScale[i]);
      } else {
        const alpha = 1 - Math.exp(-(baseWeight * mult) * dt);
        lagPos[i].lerp(currPos[i], alpha);
        lagQuat[i].slerp(currQuat[i], alpha);
        lagScale[i].lerp(currScale[i], alpha);
      }
    }

    if (handBoneIdx >= 0) {
      bones[handBoneIdx].getWorldPosition(tmpCurrHandWS);
    }

    /* 1. Compute uLagBoneTexture at lagQuat */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(lagPos[i]);
      bones[i].quaternion.copy(lagQuat[i]);
      bones[i].scale.copy(lagScale[i]);
    }
    boundRoot.updateMatrixWorld(true);
    writeBoneMatricesTo(lagBuf.data);
    lagBuf.tex.needsUpdate = true;
    if (handBoneIdx >= 0) {
      bones[handBoneIdx].getWorldPosition(tmpLagHandWS);
      lastLagDistance = tmpCurrHandWS.distanceTo(tmpLagHandWS);
    }

    /* 2. Compute uMidBoneTexture halfway along the rotational arc (slerp 0.5) */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(lagPos[i]).lerp(currPos[i], 0.5);
      bones[i].quaternion.copy(lagQuat[i]).slerp(currQuat[i], 0.5);
      bones[i].scale.copy(lagScale[i]).lerp(currScale[i], 0.5);
    }
    boundRoot.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    midBuf.tex.needsUpdate = true;

    /* 3. Restore current skeleton pose */
    for (let i = 0; i < bones.length; i += 1) {
      bones[i].position.copy(currPos[i]);
      bones[i].quaternion.copy(currQuat[i]);
      bones[i].scale.copy(currScale[i]);
    }
    boundRoot.updateMatrixWorld(true);
  };

  return {
    uniforms,
    depthMaterial,
    enhanceMaterial,
    bindSkeleton,
    reset,
    stepLag,
    getLagDistance: () => +lastLagDistance.toFixed(3),
  };
}

