    const targetUniformScaleR = 1 + extR * 0.58;
    const nextScaleR = THREE.MathUtils.lerp(bossNodes.RightHand.scale.x, targetUniformScaleR, scaleAlpha);
    bossNodes.RightHand.scale.setScalar(nextScaleR);
