  'export function applyBossPoseDirect(bossNodes, pose, dampRate, dt, headLookOffset = null) {'
);

const oldBoneLoop = `  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    const isArm = key === "LeftArm" || key === "RightArm" || key === "LeftForeArm" || key === "RightForeArm";
    const order = isArm ? "YXZ" : "XYZ";
    tmpEuler.set(rot[0], rot[1], rot[2], order);
    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }`;

const newBoneLoop = `  for (const key of POSE_BONE_KEYS) {
    const bone = bossNodes[key];
    const rot = pose[key];
    if (!bone || !rot || !bone.userData.restQuat) continue;
    const isArm = key === "LeftArm" || key === "RightArm" || key === "LeftForeArm" || key === "RightForeArm";
    const order = isArm ? "YXZ" : "XYZ";
    tmpEuler.set(rot[0], rot[1], rot[2], order);

    /* Head-Lock: Head and Neck smoothly orient directly toward target/player bearing,
       while the torso/arms/legs execute the un-jittered core animation */
    if (headLookOffset) {
      const p = headLookOffset.pitch || 0;
      const y = headLookOffset.yaw || 0;
      if (key === "Neck") {
        tmpEuler.x += p * 0.35;
        tmpEuler.y += y * 0.35;
      } else if (key === "Head") {
        tmpEuler.x += p * 0.65;
        tmpEuler.y += y * 0.65;
      }
    }

    tmpDeltaQuat.setFromEuler(tmpEuler);
    tmpTargetQuat.copy(bone.userData.restQuat).multiply(tmpDeltaQuat);
    if (alpha >= 0.999) {
      bone.quaternion.copy(tmpTargetQuat);
    } else {
      bone.quaternion.slerp(tmpTargetQuat, alpha);
    }
  }`;

