      const nikoChestY = robot.position.y + 1.05;\r
      const bossChestY = bossGroup.position.y + 1.85;\r
      const vertDist = nikoChestY - bossChestY;\r
      const horizDist = Math.max(0.4, distNiko);\r
      const targetPitch = THREE.MathUtils.clamp(-Math.atan2(vertDist, horizDist), -0.45, 0.45);\r
\r
      let targetRelYaw = Math.atan2(dxNiko, dzNiko) - bossState.yaw;\r
      while (targetRelYaw > Math.PI) targetRelYaw -= Math.PI * 2;\r
      while (targetRelYaw < -Math.PI) targetRelYaw += Math.PI * 2;\r
      const clampedRelYaw = THREE.MathUtils.clamp(targetRelYaw, -1.25, 1.25);\r
\r
      headLookOffset = {\r
        pitch: targetPitch,\r
        yaw: clampedRelYaw,\r
      };\r
