      /* "auto" gameplay mode */\r
      bossState.punchCooldown = Math.max(0, bossState.punchCooldown - dt);\r
      if (introActive) {\r
        bossState.state = "idle";\r
        bossState.punchTime = -1;\r
        bossState.yaw = dampAngle(bossState.yaw, bossHomeYaw, 6, dt);\r
