        /* Keep bossState.yaw locked during the punch so the planted lower body never slides or rotates in place */\r
        bossState.state = "punch";\r
        bossState.punchTime += dt;\r
        if (bossState.punchTime >= BOSS_PUNCH_DURATION) {\r
          bossState.punchTime = -1;\r
          bossState.punchCooldown = 1.35;\r
          bossState.state = "idle";\r
        }\r
      } else if (distNiko <= 2.45 && bossState.punchCooldown <= 0) {\r
        bossState.state = "punch";\r
