        const lookYaw = distNiko < 9.5 && distNiko > 0.01 ? Math.atan2(dxNiko, dzNiko) : bossHomeYaw;\r
        bossState.yaw = dampAngle(bossState.yaw, lookYaw, 6.0, dt);\r
      }\r
    }`;

