const fs = require('fs');

let smear = fs.readFileSync('world-smear.js', 'utf8');

// 1. Update getArmBoneMask in SMEAR_SKINNING_PARS_GLSL
const oldArmMaskGLSL = `  float getArmBoneMask( const in float idx ) {
    int b = int( idx + 0.5 );
    if ( uSmearArmSide > 0.5 ) {
      /* Right Arm only (Hit 1) */
      if ( b == 13 ) return 1.0;
      if ( b == 12 ) return 0.86;
      if ( b == 11 ) return 0.44;
      if ( b == 10 ) return 0.12;
      return 0.0;
    } else if ( uSmearArmSide < -0.5 ) {
      /* Left Arm only (Hit 2) */
      if ( b == 9 ) return 1.0;
      if ( b == 8 ) return 0.86;
      if ( b == 7 ) return 0.44;
      if ( b == 6 ) return 0.12;
      return 0.0;
    }
    if ( b == 9 || b == 13 ) return 1.0;
    if ( b == 8 || b == 12 ) return 0.86;
    if ( b == 7 || b == 11 ) return 0.44;
    if ( b == 6 || b == 10 ) return 0.12;
    return 0.0;
  }`;

const newArmMaskGLSL = `  float getArmBoneMask( const in float idx ) {
    int b = int( idx + 0.5 );
    if ( uSmearArmSide > 0.5 ) {
      /* Right Arm active (bones 10..13) */
      if ( b == 13 ) return 1.0;
      if ( b == 12 ) return 0.88;
      if ( b == 11 ) return 0.50;
      if ( b == 10 ) return 0.15;
      return 0.0;
    } else if ( uSmearArmSide < -0.5 ) {
      /* Left Arm active (bones 6..9) */
      if ( b == 9 ) return 1.0;
      if ( b == 8 ) return 0.88;
      if ( b == 7 ) return 0.50;
      if ( b == 6 ) return 0.15;
      return 0.0;
    }
    /* Fallback if both arms */
    if ( b == 9 || b == 13 ) return 1.0;
    if ( b == 8 || b == 12 ) return 0.88;
    if ( b == 7 || b == 11 ) return 0.50;
    if ( b == 6 || b == 10 ) return 0.15;
    return 0.0;
  }`;

smear = smear.replace(oldArmMaskGLSL, newArmMaskGLSL);

// 2. In SMEAR_SKINNING_VERTEX_GLSL, remove the restPos.x clamp on handMask
const oldHandMask = `  float boneArmMask =
    getArmBoneMask( skinIndex.x ) * skinWeight.x +
    getArmBoneMask( skinIndex.y ) * skinWeight.y +
    getArmBoneMask( skinIndex.z ) * skinWeight.z +
    getArmBoneMask( skinIndex.w ) * skinWeight.w;
  float distalBoost = 0.60 + 0.40 * ( 1.0 - smoothstep( 0.22, 0.66, restPos.y ) );
  float handMask = clamp( boneArmMask * distalBoost, 0.0, 1.0 );
  if ( ( uSmearArmSide > 0.5 && restPos.x > 0.05 ) || ( uSmearArmSide < -0.5 && restPos.x < -0.05 ) ) handMask = 0.0;`;

const newHandMask = `  float boneArmMask =
    getArmBoneMask( skinIndex.x ) * skinWeight.x +
    getArmBoneMask( skinIndex.y ) * skinWeight.y +
    getArmBoneMask( skinIndex.z ) * skinWeight.z +
    getArmBoneMask( skinIndex.w ) * skinWeight.w;
  float distalBoost = 0.60 + 0.40 * ( 1.0 - smoothstep( 0.22, 0.66, restPos.y ) );
  float handMask = clamp( boneArmMask * distalBoost, 0.0, 1.0 );`;

smear = smear.replace(oldHandMask, newHandMask);

// 3. Update armSign in SMEAR_SKINNING_VERTEX_GLSL
const oldArmSign = `      float yFrac = clamp( ( restPos.y - 0.20 ) / 0.52, 0.0, 1.0 );
      float armSign = restPos.x >= 0.0 ? 1.0 : -1.0;
      float armCenterX = armSign * mix( 0.382, 0.24, yFrac );
      float armCenterZ = mix( 0.072, -0.03, clamp( ( restPos.y - 0.28 ) / 0.28, 0.0, 1.0 ) );
      vec3 cylNormalBind = normalize( vec3( ( restPos.x - armCenterX ) * 0.65, 0.0, restPos.z - armCenterZ ) );
      vec3 cylNormalWS = normalize( mat3( currSkinMat ) * cylNormalBind );
      float trailAlign = smoothstep( -0.38, 0.35, dot( cylNormalWS, wakeDir ) );`;

const newArmSign = `      float yFrac = clamp( ( restPos.y - 0.20 ) / 0.52, 0.0, 1.0 );
      float armSign = uSmearArmSide < -0.5 ? 1.0 : -1.0;
      float armCenterX = armSign * mix( 0.382, 0.24, yFrac );
      float armCenterZ = mix( 0.072, -0.03, clamp( ( restPos.y - 0.28 ) / 0.28, 0.0, 1.0 ) );
      vec3 cylNormalBind = normalize( vec3( ( restPos.x - armCenterX ) * 0.65, 0.0, restPos.z - armCenterZ ) );
      vec3 cylNormalWS = normalize( mat3( currSkinMat ) * cylNormalBind );
      float trailAlign = smoothstep( -0.45, 0.35, dot( cylNormalWS, wakeDir ) );`;

smear = smear.replace(oldArmSign, newArmSign);

// 4. Update reset in JS to support armSide
const oldReset = `  const reset = () => {
    if (!boundSkeleton) return;
    const bones = boundSkeleton.bones;
    for (let i = 0; i < bones.length; i += 1) {
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      currScale[i].copy(bones[i].scale);
      lagPos[i].copy(bones[i].position);
      lagQuat[i].copy(bones[i].quaternion);
      lagScale[i].copy(bones[i].scale);
    }
    boundRoot?.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    writeBoneMatricesTo(lagBuf.data);
    midBuf.tex.needsUpdate = true;
    lagBuf.tex.needsUpdate = true;
    uniforms.uSmearStretch.value = 0;
    lastLagDistance = 0;
    initialized = true;
  };`;

const newReset = `  const reset = (armSide = null) => {
    if (!boundSkeleton) return;
    const bones = boundSkeleton.bones;
    for (let i = 0; i < bones.length; i += 1) {
      if (armSide === "right" && !(i >= 10 && i <= 13)) continue;
      if (armSide === "left" && !(i >= 6 && i <= 9)) continue;
      currPos[i].copy(bones[i].position);
      currQuat[i].copy(bones[i].quaternion);
      currScale[i].copy(bones[i].scale);
      lagPos[i].copy(bones[i].position);
      lagQuat[i].copy(bones[i].quaternion);
      lagScale[i].copy(bones[i].scale);
    }
    boundRoot?.updateMatrixWorld(true);
    writeBoneMatricesTo(midBuf.data);
    writeBoneMatricesTo(lagBuf.data);
    midBuf.tex.needsUpdate = true;
    lagBuf.tex.needsUpdate = true;
    if (!armSide) {
      uniforms.uSmearStretch.value = 0;
      lastLagDistance = 0;
    }
    initialized = true;
  };`;

smear = smear.replace(oldReset, newReset);

fs.writeFileSync('world-smear.js', smear, 'utf8');
console.log('world-smear.js successfully patched!');
