import fs from "fs";

let s = fs.readFileSync("world-smear.js", "utf8");

// Parse color helper and default to vec3(0.28, 0.09, 0.02)
const parseHelper = `const parseSheenColor = (c) => {
  if (c instanceof THREE.Color) return c.clone();
  if (Array.isArray(c)) return new THREE.Color(c[0], c[1], c[2]);
  if (typeof c === "string") return new THREE.Color(c);
  return new THREE.Color(0.28, 0.09, 0.02);
};
`;

if (!s.includes("parseSheenColor")) {
  s = s.replace(
    'export function createSmearHandler(options = {}) {',
    `${parseHelper}\r\nexport function createSmearHandler(options = {}) {`
  );
}

// Config sheenColor default
s = s.replace(
  /sheenColor: options\.sheenColor \?\? [^,]+,/,
  'sheenColor: options.sheenColor ?? new THREE.Color(0.28, 0.09, 0.02),'
);

// Uniforms
s = s.replace(
  /uSmearSheenColor: \{ value: new THREE\.Color\(config\.sheenColor\) \},/,
  'uSmearSheenColor: { value: parseSheenColor(config.sheenColor) },'
);

// Fragment shader equation back to exact old repo formulation
s = s.replace(
  'outgoingLight = mix(outgoingLight, outgoingLight * 1.15 + uSmearSheenColor, ridge * 0.72);',
  '/* Subtle ember ridge highlight from original repo (vec3(0.28, 0.09, 0.02)) */\r\n            outgoingLight = mix(outgoingLight, outgoingLight * 1.14 + uSmearSheenColor, ridge * 0.68);'
);

// setSheenColor support
const setSheenTarget = `    setSheenColor: (color) => {
      uniforms.uSmearSheenColor.value.set(color);
    },`;
const setSheenReplacement = `    setSheenColor: (color) => {
      if (color instanceof THREE.Color) {
        uniforms.uSmearSheenColor.value.copy(color);
      } else if (Array.isArray(color)) {
        uniforms.uSmearSheenColor.value.setRGB(color[0], color[1], color[2]);
      } else {
        uniforms.uSmearSheenColor.value.set(color);
      }
    },`;

s = s.replace(setSheenTarget, setSheenReplacement);

fs.writeFileSync("world-smear.js", s, "utf8");
console.log("world-smear.js restored to original repo color formulation");

