  bones: boneDataList,
};

fs.writeFileSync("assets/niko/one-punch.json", JSON.stringify(outJson));
console.log("Saved assets/niko/one-punch.json, size:", fs.statSync("assets/niko/one-punch.json").size, "bytes");
