const retargetedClip = retargetMixamo("onePunch", punchGroup, idleGroup, targetBones);

const boneDataList = [];
for (const track of retargetedClip.tracks) {
  const parts = track.name.split(".");
  const name = parts[0];
  const prop = parts[1];
  let b = boneDataList.find((item) => item.name === name);
  if (!b) {
    b = { name };
    boneDataList.push(b);
  }
  if (prop === "quaternion") {
    boneData.times = Array.from(track.times).map((t) => Math.round(t * 10000) / 10000);
    boneData.q = Array.from(track.values).map((v) => Math.round(v * 10000) / 10000);
  } else if (prop === "position") {
    boneData.posTimes = Array.from(track.times).map((t) => Math.round(t * 10000) / 10000);
    // pos in meters (curvesClip multiplies by 100)
    boneData.pos = Array.from(track.values).map((v) => Math.round((v / 100) * 10000) / 10000);
  }
}

const outJson = {
  name: "onePunch",
  duration: Math.round(retargetedClip.duration * 10000) / 10000,
