import fs from "fs";

let s = fs.readFileSync("world.js", "utf8");

// 1. Import onePunchClipData
s = s.replace(
  'import punchClipData from "./assets/niko/punch.json";',
  'import punchClipData from "./assets/niko/punch.json";\r\nimport onePunchClipData from "./assets/niko/one-punch.json";'
);

// 2. Add punchType to state
s = s.replace(
  '    punching: false,\r\n    punchTimer: 0,',
  '    punching: false,\r\n    punchType: null,\r\n    punchTimer: 0,'
);

// 3. Register onePunch action in useNikoModel
const punchActionSetup = `    restorePose();
    idleSource.animations = [curvesClip(punchClipData, false)];
    const punchAction = mixer.clipAction(retargeted("punch", idleSource));
    punchAction.setLoop(THREE.LoopOnce, 1);
    punchAction.clampWhenFinished = false;
    punchAction.setEffectiveWeight(0);
    punchAction.setEffectiveTimeScale(1.5);
    punchAction.play();
    actions.punch = punchAction;`;

const punchActionReplacement = `    restorePose();
    idleSource.animations = [curvesClip(punchClipData, false)];
    const punchAction = mixer.clipAction(retargeted("punch", idleSource));
    punchAction.setLoop(THREE.LoopOnce, 1);
    punchAction.clampWhenFinished = false;
    punchAction.setEffectiveWeight(0);
    punchAction.setEffectiveTimeScale(1.5);
    punchAction.play();
    actions.punch = punchAction;

    restorePose();
    idleSource.animations = [curvesClip(onePunchClipData, false)];
    const onePunchAction = mixer.clipAction(retargeted("onePunch", idleSource));
    onePunchAction.setLoop(THREE.LoopOnce, 1);
    onePunchAction.clampWhenFinished = false;
    onePunchAction.setEffectiveWeight(0);
    onePunchAction.setEffectiveTimeScale(1.0);
    onePunchAction.play();
    actions.onePunch = onePunchAction;`;

s = s.replace(punchActionSetup.replace(/\n/g, "\r\n"), punchActionReplacement.replace(/\n/g, "\r\n"));

// 4. Add RightHand hitbox helper in useNikoModel
const hitboxSetup = `    if (bones.LeftHand) {
      const helper = new THREE.Mesh(
        new THREE.BoxGeometry(0.35, 0.35, 0.35),
        new THREE.MeshBasicMaterial({ color: 0xff2222, wireframe: true, visible: false })
      );
      helper.name = "LeftHandHitboxHelper";
      bones.LeftHand.add(helper);
      punchHitbox.helper = helper;
    }`;

const hitboxReplacement = `    if (bones.LeftHand) {
      const helper = new THREE.Mesh(
        new THREE.BoxGeometry(0.35, 0.35, 0.35),
        new THREE.MeshBasicMaterial({ color: 0xff2222, wireframe: true, visible: false })
      );
      helper.name = "LeftHandHitboxHelper";
      bones.LeftHand.add(helper);
      punchHitbox.helper = helper;
    }
    if (bones.RightHand) {
      const rHelper = new THREE.Mesh(
        new THREE.BoxGeometry(0.35, 0.35, 0.35),
        new THREE.MeshBasicMaterial({ color: 0x22ff22, wireframe: true, visible: false })
      );
      rHelper.name = "RightHandHitboxHelper";
      bones.RightHand.add(rHelper);
      punchHitbox.rightHelper = rHelper;
    }`;

s = s.replace(hitboxSetup.replace(/\n/g, "\r\n"), hitboxReplacement.replace(/\n/g, "\r\n"));

// 5. Match hemisphere for onePunch action
s = s.replace(
  'matchHemisphere(actions.punch.getClip(), idleClip, 8, 0);',
  'matchHemisphere(actions.punch.getClip(), idleClip, 8, 0);\r\n    matchHemisphere(actions.onePunch.getClip(), idleClip, 8, 0);'
);

// 6. Define triggerOnePunch function
const triggerPunchCode = `  const triggerPunch = () => {
    if (!bot.actions?.punch) return;
    if (state.punching) return;
    state.punching = true;
    state.punchTimer = 0;
    state.punchHitboxActive = false;
    punchHitbox.active = false;
    punchHitbox.frame = -1;
    state.path = [];
    state.pending = null;
    bot.actions.punch.reset();
    bot.actions.punch.setLoop(THREE.LoopOnce, 1);
    bot.actions.punch.clampWhenFinished = false;
    bot.actions.punch.setEffectiveTimeScale(1.5);
    bot.actions.punch.play();
  };`;

const triggerPunchReplacement = `  const triggerPunch = () => {
    if (!bot.actions?.punch) return;
    if (state.punching) return;
    state.punching = true;
    state.punchType = "flyingKnee";
    state.punchTimer = 0;
    state.punchHitboxActive = false;
    punchHitbox.active = false;
    punchHitbox.frame = -1;
    state.path = [];
    state.pending = null;
    bot.actions.punch.reset();
    bot.actions.punch.setLoop(THREE.LoopOnce, 1);
    bot.actions.punch.clampWhenFinished = false;
    bot.actions.punch.setEffectiveTimeScale(1.5);
    bot.actions.punch.play();
  };

  const triggerOnePunch = () => {
    if (!bot.actions?.onePunch) return;
    if (state.punching) return;
    state.punching = true;
    state.punchType = "onePunch";
    state.punchTimer = 0;
    state.punchHitboxActive = false;
    punchHitbox.active = false;
    punchHitbox.frame = -1;
    state.path = [];
    state.pending = null;
    bot.actions.onePunch.reset();
    bot.actions.onePunch.setLoop(THREE.LoopOnce, 1);
    bot.actions.onePunch.clampWhenFinished = false;
    bot.actions.onePunch.setEffectiveTimeScale(1.0);
    bot.actions.onePunch.play();
  };`;

s = s.replace(triggerPunchCode.replace(/\n/g, "\r\n"), triggerPunchReplacement.replace(/\n/g, "\r\n"));

// 7. Update animation loop for both punches
const animLoopCode = `      if (state.punching && actions.punch) {
        state.punchTimer += dt * 1.5;
        const dur = actions.punch.getClip().duration;

