          let smearScale = 1.0;
          if (punchFrame < 36) {
            smearScale = THREE.MathUtils.clamp((punchFrame - 33) / 3.0, 0.4, 1.0);
          } else if (punchFrame > 40) {
            smearScale = THREE.MathUtils.clamp((42 - punchFrame) / 2.0, 0.3, 1.0);
          }
          nikoSmear.stepLag(dt, 7.5, smearScale, -1.0);
        } else {
