const scriptSource = `
global.window = global;
global.self = global;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: () => {} }),
};
global.HTMLImageElement = function() {};

import fs from "fs";
import * as THREE from "three";
import { FBXLoader } from "./.impeccable/fbx/addons/loaders/FBXLoader.js";

const fbxLoader = new FBXLoader();
const idleBuf = fs.readFileSync("assets/niko/Idle.fbx");
const idleSource = fbxLoader.parse(idleBuf.buffer.slice(idleBuf.byteOffset, idleBuf.byteOffset + idleBuf.byteLength), "");

const onePunchClipData = JSON.parse(fs.readFileSync("assets/niko/one-punch.json"));

const stripMixamo = (name) => name.replace(/^mixamorig\\d*:?/, "");

const sourceName = {};
idleSource.traverse((node) => {
  if (node.isBone) sourceName[stripMixamo(node.name)] = node.name;
});

const curvesClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    const nodeName = sourceName[bone.name];
    if (!nodeName) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(nodeName + ".quaternion", new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) {
      const pos = bone.pos.map((value) => value * 100);
      tracks.push(new THREE.VectorKeyframeTrack(nodeName + ".position", new Float32Array(bone.posTimes), new Float32Array(pos)));
    }
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

// Apply clip to idleSource
idleSource.animations = [curvesClip(onePunchClipData)];
const clip = idleSource.animations[0];
console.log("curvesClip created tracks:", clip.tracks.length);

