const root = path.resolve(".");
const vendor = path.join(root, "vendor/three");

const vendoredThree = {
  name: "vendored-three",
  setup(b) {
    b.onResolve({ filter: /^three$/ }, () => ({ path: path.join(vendor, "three.module.min.js") }));
    b.onResolve({ filter: /^three\/addons\// }, (args) => ({
      path: path.join(vendor, "addons", args.path.slice("three/addons/".length)),
    }));
  },
};

const scriptSource = `
global.window = global;
global.self = global;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: () => {} }),
};
global.HTMLImageElement = function() {};

import fs from "fs";
import * as THREE from "three";
import { FBXLoader } from "./.impeccable/fbx/addons/loaders/FBXLoader.js";
import { GLTFLoader } from "./vendor/three/addons/loaders/GLTFLoader.js";

const fbxLoader = new FBXLoader();
const punchGroup = fbxLoader.parse(fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/one punch.fbx").buffer, "");
const idleSource = fbxLoader.parse(fs.readFileSync("assets/niko/Idle.fbx").buffer, "");

const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(fs.readFileSync("assets/niko/niko-final-clean.glb").buffer, "");
const nikoModel = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\\d*:?/, "");
nikoModel.traverse(n => { if (n.isBone) n.name = stripMixamo(n.name); });
const nikoBones = {};
nikoModel.traverse(n => { if (n.isBone) nikoBones[n.name] = n; });

console.log("Niko bones count:", Object.keys(nikoBones).length);

// Let's implement retargetMixamo exactly as in world.js:
const retargetMixamo = (clipName, sourceGroup, model, bones) => {
  const srcBones = {};
  sourceGroup.traverse((node) => {
    if (node.isBone) srcBones[stripMixamo(node.name)] = node;
  });
  const names = Object.keys(bones).filter((name) => srcBones[name]);
  const armAcross = (map) => {
    const left = new THREE.Vector3();
    const right = new THREE.Vector3();
    map.LeftArm.getWorldPosition(left);
    map.RightArm.getWorldPosition(right);
    return left.sub(right).setY(0).normalize();
  };
  const savedYaw = model.rotation.y;
  model.rotation.y = 0;
  model.updateMatrixWorld(true);
  sourceGroup.updateMatrixWorld(true);
  const align = new THREE.Quaternion().setFromUnitVectors(armAcross(srcBones), armAcross(bones));
  const alignInv = align.clone().invert();
  const worldOf = (bone) => bone.getWorldQuaternion(new THREE.Quaternion());
  const srcRest = {};
  const tgtRest = {};
  for (const name of names) {
    srcRest[name] = worldOf(srcBones[name]);
    tgtRest[name] = worldOf(bones[name]);
  }
  const srcHipRest = new THREE.Vector3();
  srcBones.Hips.getWorldPosition(srcHipRest);
  const tgtHipRest = bones.Hips.position.clone();
  const hipScale = tgtHipRest.y / (Math.abs(srcHipRest.y) > 1e-4 ? srcHipRest.y : 1);
  model.rotation.y = savedYaw;
  const srcMixer = new THREE.AnimationMixer(sourceGroup);
  const srcClip = sourceGroup.animations[0];
  srcMixer.clipAction(srcClip).play();
  const frames = Math.max(2, Math.round(srcClip.duration * 30));
  const times = new Float32Array(frames);
  const quats = Object.fromEntries(names.map((name) => [name, new Float32Array(frames * 4)]));
  const hips = new Float32Array(frames * 3);
  const currSrcHip = new THREE.Vector3();

  for (let frame = 0; frame < frames; frame += 1) {
    const time = (srcClip.duration * frame) / (frames - 1);
    times[frame] = time;
    srcMixer.setTime(time);
    sourceGroup.updateMatrixWorld(true);
    const posed = {};
    for (const name of names) {
      const delta = worldOf(srcBones[name]).multiply(srcRest[name].clone().invert());
      posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
    }
    for (const name of names) {
      const parent = bones[name].parent;
      const local = parent && posed[parent.name]
        ? posed[parent.name].clone().invert().multiply(posed[name])
        : posed[name].clone();
      if (frame > 0) {
        const prev = (frame - 1) * 4;
        const values = quats[name];
        const dot = values[prev] * local.x + values[prev + 1] * local.y + values[prev + 2] * local.z + values[prev + 3] * local.w;
        if (dot < 0) local.set(-local.x, -local.y, -local.z, -local.w);
      }
      quats[name].set([local.x, local.y, local.z, local.w], frame * 4);
    }
    srcBones.Hips.getWorldPosition(currSrcHip);
    hips[frame * 3] = tgtHipRest.x;
    hips[frame * 3 + 1] = tgtHipRest.y + (currSrcHip.y - srcHipRest.y) * hipScale;
    hips[frame * 3 + 2] = tgtHipRest.z;
  }
  const tracks = names.map((name) => new THREE.QuaternionKeyframeTrack(name + ".quaternion", times, quats[name]));
  tracks.push(new THREE.VectorKeyframeTrack("Hips.position", times, hips));
  return new THREE.AnimationClip(clipName, srcClip.duration, tracks);
};

// TEST 1: Retarget punchGroup directly to Niko
console.log("\n=== TEST 1: Retarget punchGroup directly to Niko ===");
const directClip = retargetMixamo("onePunchDirect", punchGroup, nikoModel, nikoBones);

// TEST 2: Current world.js pipeline (double retargeting)
console.log("\n=== TEST 2: Current world.js pipeline (double retargeting) ===");
const onePunchClipData = JSON.parse(fs.readFileSync("assets/niko/one-punch.json"));
const sourceName = {};
idleSource.traverse((node) => {
  if (node.isBone) sourceName[stripMixamo(node.name)] = node.name;
});
const curvesClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    const nodeName = sourceName[bone.name];
    if (!nodeName) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(nodeName + ".quaternion", new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) {
      const pos = bone.pos.map((value) => value * 100);
      tracks.push(new THREE.VectorKeyframeTrack(nodeName + ".position", new Float32Array(bone.posTimes), new Float32Array(pos)));
    }
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};
idleSource.animations = [curvesClip(onePunchClipData)];
const doubleClip = retargetMixamo("onePunchDouble", idleSource, nikoModel, nikoBones);

// Now sample Niko's RightHand and RightArm in both clips on nikoModel:
const nikoMixer = new THREE.AnimationMixer(nikoModel);
const act1 = nikoMixer.clipAction(directClip);
const act2 = nikoMixer.clipAction(doubleClip);

const rHand = nikoBones.RightHand;
const rArm = nikoBones.RightArm;
const hBone = nikoBones.Hips;
const rPos = new THREE.Vector3();
const hPos = new THREE.Vector3();

console.log("\n--- TEST 1 (Direct retarget from FBX to Niko) ---");
act1.play();
act2.stop();
[0, 0.3, 0.6, 0.9, 1.16].forEach(time => {
  nikoMixer.setTime(time);
  nikoModel.updateMatrixWorld(true);
  rHand.getWorldPosition(rPos);
  hBone.getWorldPosition(hPos);
  const relZ = rPos.z - hPos.z;
  const relY = rPos.y - hPos.y;
  const relX = rPos.x - hPos.x;
  console.log("t=" + time.toFixed(2) + " RHand rel to Hips -> x:" + relX.toFixed(3) + " y:" + relY.toFixed(3) + " z(fwd):" + relZ.toFixed(3));
});

console.log("\n--- TEST 2 (Double retarget in current world.js) ---");
act1.stop();
act2.play();
[0, 0.3, 0.6, 0.9, 1.16].forEach(time => {
  nikoMixer.setTime(time);
  nikoModel.updateMatrixWorld(true);
  rHand.getWorldPosition(rPos);
  hBone.getWorldPosition(hPos);
  const relZ = rPos.z - hPos.z;
  const relY = rPos.y - hPos.y;
  const relX = rPos.x - hPos.x;
  console.log("t=" + time.toFixed(2) + " RHand rel to Hips -> x:" + relX.toFixed(3) + " y:" + relY.toFixed(3) + " z(fwd):" + relZ.toFixed(3));
});
`;

