import { build } from "esbuild";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const vendor = path.join(root, "vendor/three");

const vendoredThree = {
  name: "vendored-three",
  setup(b) {
    b.onResolve({ filter: /^three$/ }, () => ({ path: path.join(vendor, "three.module.min.js") }));
    b.onResolve({ filter: /^three\/addons\// }, (args) => ({
      path: path.join(vendor, "addons", args.path.slice("three/addons/".length)),
    }));
  },
};

const script = process.argv[2];
if (!script) {
  console.error("Usage: node .impeccable/tools/run-tool.mjs <script.mjs>");
  process.exit(1);
}

const out = path.join(root, ".temp-tool.mjs");
await build({
  entryPoints: [path.resolve(script)],
  outfile: out,
  bundle: true,
  format: "esm",
  platform: "node",
  target: "node18",
  plugins: [vendoredThree],
  loader: { ".glb": "binary", ".fbx": "binary", ".json": "json" },
  logLevel: "error",
});

const res = spawnSync("node", [out, ...process.argv.slice(3)], { stdio: "inherit" });
process.exit(res.status || 0);

import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

global.window = global;
global.self = global;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: () => {} }),
};
global.HTMLImageElement = function() {};

const loader = new FBXLoader();

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
const parseFbx = (buf) => loader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");

const retargetMixamo = (clipName, sourceGroup, model, bones) => {
  const srcBones = {};
  sourceGroup.traverse((node) => {
    if (node.isBone) srcBones[stripMixamo(node.name)] = node;
  });
  const names = Object.keys(bones).filter((name) => srcBones[name]);
  const armAcross = (map) => {
    const left = new THREE.Vector3();
    const right = new THREE.Vector3();
    map.LeftArm.getWorldPosition(left);
    map.RightArm.getWorldPosition(right);
    return left.sub(right).setY(0).normalize();
  };
  const savedYaw = model.rotation.y;
  model.rotation.y = 0;
  model.updateMatrixWorld(true);
  sourceGroup.updateMatrixWorld(true);
  const align = new THREE.Quaternion().setFromUnitVectors(armAcross(srcBones), armAcross(bones));
  const alignInv = align.clone().invert();
  const worldOf = (bone) => bone.getWorldQuaternion(new THREE.Quaternion());
  const srcRest = {};
  const tgtRest = {};
  for (const name of names) {
    srcRest[name] = worldOf(srcBones[name]);
    tgtRest[name] = worldOf(bones[name]);
  }
  const srcHipRest = new THREE.Vector3();
  srcBones.Hips.getWorldPosition(srcHipRest);
  const tgtHipRest = bones.Hips.position.clone();
  const hipScale = tgtHipRest.y / (Math.abs(srcHipRest.y) > 1e-4 ? srcHipRest.y : 1);
  model.rotation.y = savedYaw;
  const srcMixer = new THREE.AnimationMixer(sourceGroup);
  const srcClip = sourceGroup.animations[0];
  srcMixer.clipAction(srcClip).play();
  const frames = Math.max(2, Math.round(srcClip.duration * 30));
  const times = new Float32Array(frames);
  const quats = Object.fromEntries(names.map((name) => [name, new Float32Array(frames * 4)]));
  const hips = new Float32Array(frames * 3);
  const currSrcHip = new THREE.Vector3();

  for (let frame = 0; frame < frames; frame += 1) {
    const time = (srcClip.duration * frame) / (frames - 1);
    times[frame] = time;
    srcMixer.setTime(time);
    sourceGroup.updateMatrixWorld(true);
    const posed = {};
    for (const name of names) {
      const delta = worldOf(srcBones[name]).multiply(srcRest[name].clone().invert());
      posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
    }
    for (const name of names) {
      const parent = bones[name].parent;
      const local = parent && posed[parent.name]
        ? posed[parent.name].clone().invert().multiply(posed[name])
        : posed[name].clone();
      if (frame > 0) {
        const prev = (frame - 1) * 4;
        const values = quats[name];
        const dot = values[prev] * local.x + values[prev + 1] * local.y + values[prev + 2] * local.z + values[prev + 3] * local.w;
        if (dot < 0) local.set(-local.x, -local.y, -local.z, -local.w);
      }
      quats[name].set([local.x, local.y, local.z, local.w], frame * 4);
    }
    srcBones.Hips.getWorldPosition(currSrcHip);
    hips[frame * 3] = tgtHipRest.x;
    hips[frame * 3 + 1] = tgtHipRest.y + (currSrcHip.y - srcHipRest.y) * hipScale;
    hips[frame * 3 + 2] = tgtHipRest.z;
  }
  const tracks = names.map((name) => new THREE.QuaternionKeyframeTrack(name + ".quaternion", times, quats[name]));
  tracks.push(new THREE.VectorKeyframeTrack("Hips.position", times, hips));
  return new THREE.AnimationClip(clipName, srcClip.duration, tracks);
};

// Test retargeting one punch.fbx onto idleGroup
const idleBuf = fs.readFileSync("assets/niko/Idle.fbx");
const idleGroup = parseFbx(idleBuf);
const bones = {};
idleGroup.traverse(n => {
  if (n.isBone) bones[stripMixamo(n.name)] = n;
});

const onePunchBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/one punch.fbx");
const onePunchGroup = parseFbx(onePunchBuf);

console.log("Retargeting one punch.fbx directly onto idle bones...");
const clip = retargetMixamo("onePunch", onePunchGroup, idleGroup, bones);

console.log(`Generated clip: duration=${clip.duration}, tracks=${clip.tracks.length}`);

// Now test playing this clip on idleGroup and inspect bone world positions at frame 0, mid punch (frame 18), and end!
const testMixer = new THREE.AnimationMixer(idleGroup);
const action = testMixer.clipAction(clip);
action.play();

for (const t of [0, 0.3, 0.6, 0.9, 1.16]) {
  testMixer.setTime(t);
  idleGroup.updateMatrixWorld(true);
  const headPos = new THREE.Vector3();
  const rightHandPos = new THREE.Vector3();
  const leftHandPos = new THREE.Vector3();
  const hipsPos = new THREE.Vector3();
  bones.Head.getWorldPosition(headPos);
  bones.RightHand.getWorldPosition(rightHandPos);
  bones.LeftHand.getWorldPosition(leftHandPos);
  bones.Hips.getWorldPosition(hipsPos);
  console.log(`Time ${t.toFixed(2)}s: Hips=[${hipsPos.toArray().map(v=>v.toFixed(1))}], Head=[${headPos.toArray().map(v=>v.toFixed(1))}], RightHand=[${rightHandPos.toArray().map(v=>v.toFixed(1))}], LeftHand=[${leftHandPos.toArray().map(v=>v.toFixed(1))}]`);
}

