const onePunchSource = parseFbx(onePunchBuf);
const onePunchClip = retargetMixamo("onePunch", onePunchSource, model, bones);

// Convert onePunchClip to clean JSON
const boneEntries = [];
for (const track of onePunchClip.tracks) {
  const [boneName, prop] = track.name.split(".");
  let b = boneEntries.find((item) => item.name === boneName);
  if (!b) {
    b = { name: boneName };
    boneEntries.push(b);
  }
  if (prop === "quaternion") {
    b.times = Array.from(track.times).map((t) => Math.round(t * 10000) / 10000);
    b.q = Array.from(track.values).map((v) => Math.round(v * 10000) / 10000);
  } else if (prop === "position") {
    b.posTimes = Array.from(track.times).map((t) => Math.round(t * 10000) / 10000);
    b.pos = Array.from(track.values).map((v) => Math.round(v * 10000) / 10000);
  }
}

const onePunchExport = {
  name: "onePunch",
  duration: Math.round(onePunchClip.duration * 10000) / 10000,
  bones: boneEntries,
};

fs.writeFileSync("assets/niko/one-punch.json", JSON.stringify(onePunchExport));
console.log(`Saved assets/niko/one-punch.json (${(fs.statSync("assets/niko/one-punch.json").size / 1024).toFixed(1)} KB)`);

// Now verify direct loading using directClip
const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    if (!bones[bone.name]) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) {
      tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
    }
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

