const idleBuf = fs.readFileSync("assets/niko/Idle.fbx");
const idleSource = parseFbx(idleBuf);
const idleClip = retargetMixamo("idle", idleSource, model, bones);

// Function matchHemisphere from world.js
const quatAt = (track, u) => {
  const times = track.times;
  const values = track.values;
  const last = times.length - 1;
  const time = u * times[last];
  let index = 0;
  while (index < last && times[index + 1] < time) index += 1;
  const next = Math.min(index + 1, last);
  const useNext = next !== index && time - times[index] > times[next] - time;
  const offset = (useNext ? next : index) * 4;
  return [values[offset], values[offset + 1], values[offset + 2], values[offset + 3]];
};
const matchHemisphere = (clip, reference, samples = 8, referenceAt = null) => {
  for (const track of clip.tracks) {
    if (!track.name.endsWith(".quaternion")) continue;
    const refTrack = reference.tracks.find((candidate) => candidate.name === track.name);
    if (!refTrack) continue;
    let sum = 0;
    for (let sample = 0; sample < samples; sample += 1) {
      const u = sample / (samples - 1 || 1);
      const a = quatAt(track, u);
      const b = quatAt(refTrack, referenceAt ?? u);
      sum += a[0] * b[0] + a[1] * b[1] + a[2] * b[2] + a[3] * b[3];
    }
    if (sum < 0) {
      const values = track.values;
      for (let index = 0; index < values.length; index += 1) values[index] = -values[index];
    }
  }
};

const loadedClip = directClip(JSON.parse(fs.readFileSync("assets/niko/one-punch.json", "utf8")));
matchHemisphere(loadedClip, idleClip, 8, 0);

