  bones.Head.getWorldPosition(head);
  bones.RightHand.getWorldPosition(rightHand);
  bones.LeftHand.getWorldPosition(leftHand);
  bones.Hips.getWorldPosition(hips);
  console.log(`t=${t.toFixed(2)}s (frame ${Math.round(t*30).toString().padStart(2)}): Hips=[${hips.toArray().map(v=>v.toFixed(3))}], Head=[${head.toArray().map(v=>v.toFixed(3))}], RHand=[${rightHand.toArray().map(v=>v.toFixed(3))}], LHand=[${leftHand.toArray().map(v=>v.toFixed(3))}]`);
}

