import fs from "fs";

let text = fs.readFileSync("world.js", "utf8");

const target = `    restorePose();
    idleSource.animations = [curvesClip(onePunchClipData, false)];
    const onePunchAction = mixer.clipAction(retargeted("onePunch", idleSource));
    onePunchAction.setLoop(THREE.LoopOnce, 1);
    onePunchAction.clampWhenFinished = false;
    onePunchAction.setEffectiveWeight(0);
    onePunchAction.setEffectiveTimeScale(1.0);
    onePunchAction.play();
    actions.onePunch = onePunchAction;`;

const replacement = `    const directClip = (entry) => {
      const tracks = [];
      for (const bone of entry.bones) {
        if (!bones[bone.name]) continue;
        tracks.push(new THREE.QuaternionKeyframeTrack(\`\${bone.name}.quaternion\`, new Float32Array(bone.times), new Float32Array(bone.q)));
        if (bone.pos) {
          tracks.push(new THREE.VectorKeyframeTrack(\`\${bone.name}.position\`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
        }
      }
      return new THREE.AnimationClip(entry.name, entry.duration, tracks);
    };
    const onePunchAction = mixer.clipAction(directClip(onePunchClipData));
    onePunchAction.setLoop(THREE.LoopOnce, 1);
    onePunchAction.clampWhenFinished = false;
    onePunchAction.setEffectiveWeight(0);
    onePunchAction.setEffectiveTimeScale(1.0);
    onePunchAction.play();
    actions.onePunch = onePunchAction;`;

// Handle CRLF vs LF:
const targetCRLF = target.replace(/\r?\n/g, "\r\n");
const targetLF = target.replace(/\r?\n/g, "\n");
const isCRLF = text.includes("\r\n");

if (text.includes(targetCRLF)) {
  text = text.replace(targetCRLF, replacement.replace(/\r?\n/g, "\r\n"));
  fs.writeFileSync("world.js", text, "utf8");
  console.log("Successfully patched world.js (CRLF)");
} else if (text.includes(targetLF)) {
  text = text.replace(targetLF, replacement.replace(/\r?\n/g, isCRLF ? "\r\n" : "\n"));
  fs.writeFileSync("world.js", text, "utf8");
  console.log("Successfully patched world.js (LF)");
} else {
  console.error("Target block not found in world.js!");
  process.exit(1);
}

import fs from "fs";

try {
  const code = fs.readFileSync("world.bundle.js", "utf8");
  new Function(code);
  console.log("Bundle syntax verified successfully!");
} catch (e) {
  console.error("Bundle syntax error:", e);
  process.exit(1);
}

