import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

global.window = global;
global.self = global;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: () => {} }),
};
global.HTMLImageElement = function() {};

const gltfLoader = new GLTFLoader();
const fbxLoader = new FBXLoader();
const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");

async function inspectGlb(file) {
  console.log(`\n=== Inspecting ${file} ===`);
  const buf = fs.readFileSync(file);
  const gltf = await gltfLoader.parseAsync(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  const model = gltf.scene;
  model.traverse((node) => {
    if (node.isBone) node.name = stripMixamo(node.name);
  });
  const bones = {};
  model.traverse((node) => {
    if (node.isBone) bones[node.name] = node;
  });

  console.log("Total bones:", Object.keys(bones).length);
  console.log("Root children:", model.children.map(c => `${c.name} (${c.type}) rot=[${c.rotation.toArray().slice(0,3).map(v=>(v*180/Math.PI).toFixed(1))}] scale=[${c.scale.toArray().map(v=>v.toFixed(3))}]`));

  if (bones.Hips) {
    let p = bones.Hips.parent;
    const chain = [];
    while (p) {
      chain.push(`${p.name}(rot=[${p.rotation.toArray().slice(0,3).map(v=>(v*180/Math.PI).toFixed(1))}], quat=[${p.quaternion.toArray().map(v=>v.toFixed(3))}], scale=[${p.scale.toArray().map(v=>v.toFixed(2))}])`);
      p = p.parent;
    }
    console.log("Hips parent chain:", chain.join(" -> "));
    console.log("Hips local pos:", bones.Hips.position.toArray().map(v=>v.toFixed(3)));
    console.log("Hips local quat:", bones.Hips.quaternion.toArray().map(v=>v.toFixed(3)));
    model.updateMatrixWorld(true);
    const wq = new THREE.Quaternion();
    const wp = new THREE.Vector3();
    bones.Hips.getWorldQuaternion(wq);
    bones.Hips.getWorldPosition(wp);
    console.log("Hips world pos:", wp.toArray().map(v=>v.toFixed(3)));
    console.log("Hips world quat:", wq.toArray().map(v=>v.toFixed(3)));
  }

  for (const bName of ["Spine", "Head", "LeftArm", "RightArm", "LeftHand", "RightHand", "LeftUpLeg", "RightUpLeg"]) {
    if (bones[bName]) {
      const wq = new THREE.Quaternion();
      const wp = new THREE.Vector3();
      bones[bName].getWorldQuaternion(wq);
      bones[bName].getWorldPosition(wp);
      console.log(`  ${bName}: localQ=[${bones[bName].quaternion.toArray().map(v=>v.toFixed(3))}] worldQ=[${wq.toArray().map(v=>v.toFixed(3))}] worldP=[${wp.toArray().map(v=>v.toFixed(3))}]`);
    }
  }
}

