import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";

globalThis.self = globalThis;
const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

console.log("=== Niko final clean bones ===");
console.log("Total bones:", Object.keys(bones).length);
console.log("Hips position:", bones.Hips.position.toArray().map(v=>v.toFixed(3)));
console.log("Hips quaternion:", bones.Hips.quaternion.toArray().map(v=>v.toFixed(3)));
model.updateMatrixWorld(true);
const wp = new THREE.Vector3();
bones.Hips.getWorldPosition(wp);
console.log("Hips world position:", wp.toArray().map(v=>v.toFixed(3)));

for (const b of ["Spine", "Head", "LeftArm", "RightArm", "LeftHand", "RightHand"]) {
  if (bones[b]) {
    const p = new THREE.Vector3();
    bones[b].getWorldPosition(p);
    console.log(`${b}: pos=[${bones[b].position.toArray().map(v=>v.toFixed(3))}] world=[${p.toArray().map(v=>v.toFixed(3))}]`);
  }
}

import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

const fbxPath = "c:/Users/Rigel/Desktop/Cascadeur/one_punch_anim_only.fbx";
const fbxBuf = fs.readFileSync(fbxPath);
const fbxLoader = new FBXLoader();
const sourceGroup = fbxLoader.parse(fbxBuf.buffer.slice(fbxBuf.byteOffset, fbxBuf.byteOffset + fbxBuf.byteLength), "");
const srcClip = sourceGroup.animations[0];

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
const srcBones = {};
sourceGroup.traverse((node) => {
  if (node.isBone) srcBones[stripMixamo(node.name)] = node;
});

const mixer = new THREE.AnimationMixer(sourceGroup);
mixer.clipAction(srcClip).play();

console.log(`Inspecting sourceGroup Hips & RightHand over ${srcClip.duration}s:`);
for (let t = 0; t <= srcClip.duration; t += 0.1) {
  mixer.setTime(t);
  sourceGroup.updateMatrixWorld(true);
  const localPos = srcBones.Hips.position;
  const worldPos = new THREE.Vector3();
  srcBones.Hips.getWorldPosition(worldPos);

  const rHandWorld = new THREE.Vector3();
  srcBones.RightHand.getWorldPosition(rHandWorld);

  const rHandLocal = srcBones.RightHand.position;

  console.log(`t=${t.toFixed(2)}s: Hips local=[${localPos.toArray().map(v=>v.toFixed(3))}] | Hips world=[${worldPos.toArray().map(v=>v.toFixed(3))}] | RHand world=[${rHandWorld.toArray().map(v=>v.toFixed(3))}]`);
}

import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";

globalThis.self = globalThis;
const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const fbxPath = "c:/Users/Rigel/Desktop/Cascadeur/one_punch_anim_only.fbx";
const fbxBuf = fs.readFileSync(fbxPath);
const fbxLoader = new FBXLoader();
const sourceGroup = fbxLoader.parse(fbxBuf.buffer.slice(fbxBuf.byteOffset, fbxBuf.byteOffset + fbxBuf.byteLength), "");
const srcClip = sourceGroup.animations[0];

const srcBones = {};
sourceGroup.traverse((node) => {
  if (node.isBone) srcBones[stripMixamo(node.name)] = node;
});

const names = Object.keys(bones).filter((name) => srcBones[name]);
console.log(`Matching bones: ${names.length} of ${Object.keys(bones).length}`);

const armAcross = (map) => {
  const left = new THREE.Vector3();
  const right = new THREE.Vector3();
  map.LeftArm.getWorldPosition(left);
  map.RightArm.getWorldPosition(right);
  return left.sub(right).setY(0).normalize();
};

const savedYaw = model.rotation.y;
model.rotation.y = 0;
model.updateMatrixWorld(true);
sourceGroup.updateMatrixWorld(true);

const align = new THREE.Quaternion().setFromUnitVectors(armAcross(srcBones), armAcross(bones));
const alignInv = align.clone().invert();
const worldOf = (bone) => bone.getWorldQuaternion(new THREE.Quaternion());

const srcRest = {};
const tgtRest = {};
for (const name of names) {
  srcRest[name] = worldOf(srcBones[name]);
  tgtRest[name] = worldOf(bones[name]);
}

const srcHipRest = new THREE.Vector3();
srcBones.Hips.getWorldPosition(srcHipRest);
const tgtHipRest = bones.Hips.position.clone();
const hipScale = tgtHipRest.y / (Math.abs(srcHipRest.y) > 1e-4 ? srcHipRest.y : 1);
model.rotation.y = savedYaw;

const srcMixer = new THREE.AnimationMixer(sourceGroup);
srcMixer.clipAction(srcClip).play();

const frames = Math.max(2, Math.round(srcClip.duration * 30));
const times = new Float32Array(frames);
const quats = Object.fromEntries(names.map((name) => [name, new Float32Array(frames * 4)]));
const hips = new Float32Array(frames * 3);
const currSrcHip = new THREE.Vector3();

for (let frame = 0; frame < frames; frame += 1) {
  const time = (srcClip.duration * frame) / (frames - 1);
  times[frame] = time;
  srcMixer.setTime(time);
  sourceGroup.updateMatrixWorld(true);

  const posed = {};
  for (const name of names) {
    const delta = worldOf(srcBones[name]).multiply(srcRest[name].clone().invert());
    posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
  }

  for (const name of names) {
    const parent = bones[name].parent;
    const local = parent && posed[parent.name]
      ? posed[parent.name].clone().invert().multiply(posed[name])
      : posed[name].clone();
    if (frame > 0) {
      const prev = (frame - 1) * 4;
      const values = quats[name];
      const dot = values[prev] * local.x + values[prev + 1] * local.y + values[prev + 2] * local.z + values[prev + 3] * local.w;
