import fs from "fs";

let text = fs.readFileSync("world.js", "utf8");

const target = `          // Forward lunge propulsion during explosive punch thrust (frames 10-18):
          if (punchFrame >= 10 && punchFrame <= 18) {
            const forward = new THREE.Vector3(Math.sin(robot.rotation.y), 0, Math.cos(robot.rotation.y));
            const leapBefore = robot.position.clone();
            robot.position.addScaledVector(forward, 3.5 * dt);
            resolveCollisions(robot.position);
            stepTo(leapBefore, robot.position);
          }

          // RightHand hitbox active during impact window: frames 16-22
          const hitboxActive = punchFrame >= 16 && punchFrame <= 22;
          punchHitbox.active = hitboxActive;
          punchHitbox.frame = punchFrame;
          state.punchHitboxActive = hitboxActive;
          if (hitboxActive && bot.bones?.RightHand) {
            bot.bones.RightHand.getWorldPosition(punchHitbox.position);
            punchHitbox.sphere.center.copy(punchHitbox.position);
            punchHitbox.sphere.radius = punchHitbox.radius;
            punchHitbox.box.setFromCenterAndSize(punchHitbox.position, punchHitbox.size);
          }

          // Right arm mesh-smearing effect during punch extension (frames 13-22):
          const smearActive = punchFrame >= 13 && punchFrame <= 22;
          if (smearActive) {
            let smearScale = 1.0;
            if (punchFrame < 16) {
              smearScale = THREE.MathUtils.clamp((punchFrame - 13) / 3.0, 0.4, 1.0);
            } else if (punchFrame > 19) {
              smearScale = THREE.MathUtils.clamp((22 - punchFrame) / 3.0, 0.3, 1.0);
            }
            nikoSmear.stepLag(dt, 7.5, smearScale, 1.0); // 1.0 = Right arm
          } else {
            nikoSmear.reset();
          }`;

const replacement = `          // Forward lunge propulsion during explosive punch thrust (frames 12-21):
          if (punchFrame >= 12 && punchFrame <= 21) {
            const forward = new THREE.Vector3(Math.sin(robot.rotation.y), 0, Math.cos(robot.rotation.y));
            const leapBefore = robot.position.clone();
            robot.position.addScaledVector(forward, 3.8 * dt);
            resolveCollisions(robot.position);
            stepTo(leapBefore, robot.position);
          }

          // RightHand hitbox active during impact window: frames 17-23
          const hitboxActive = punchFrame >= 17 && punchFrame <= 23;
          punchHitbox.active = hitboxActive;
          punchHitbox.frame = punchFrame;
          state.punchHitboxActive = hitboxActive;
          if (hitboxActive && bot.bones?.RightHand) {
            bot.bones.RightHand.getWorldPosition(punchHitbox.position);
            punchHitbox.sphere.center.copy(punchHitbox.position);
            punchHitbox.sphere.radius = punchHitbox.radius;
            punchHitbox.box.setFromCenterAndSize(punchHitbox.position, punchHitbox.size);
          }

          // Right arm mesh-smearing effect during punch extension (frames 14-23):
          const smearActive = punchFrame >= 14 && punchFrame <= 23;
          if (smearActive) {
            let smearScale = 1.0;
            if (punchFrame < 17) {
              smearScale = THREE.MathUtils.clamp((punchFrame - 14) / 3.0, 0.4, 1.0);
            } else if (punchFrame > 20) {
              smearScale = THREE.MathUtils.clamp((23 - punchFrame) / 3.0, 0.3, 1.0);
            }
            nikoSmear.stepLag(dt, 7.5, smearScale, 1.0); // 1.0 = Right arm
          } else {
            nikoSmear.reset();
          }`;

const targetCRLF = target.replace(/\r?\n/g, "\r\n");
const targetLF = target.replace(/\r?\n/g, "\n");
const isCRLF = text.includes("\r\n");

if (text.includes(targetCRLF)) {
  text = text.replace(targetCRLF, replacement.replace(/\r?\n/g, "\r\n"));
  fs.writeFileSync("world.js", text, "utf8");
  console.log("Updated world.js timing (CRLF)");
} else if (text.includes(targetLF)) {
  text = text.replace(targetLF, replacement.replace(/\r?\n/g, isCRLF ? "\r\n" : "\n"));
  fs.writeFileSync("world.js", text, "utf8");
  console.log("Updated world.js timing (LF)");
} else {
  console.error("Target block not found in world.js");
  process.exit(1);
}

