args.Content:
import fs from "fs";

let text = fs.readFileSync("world.js", "utf8");

const target = `      /* Diagonal backward: turn the hips into the backward run while keeping the chest on the target. */
      if (lockTarget && Math.abs(lockBackYaw) > 0.02 && bot.bones?.Hips && bot.bones?.Spine2) {
        const yawWorld = (bone, radians) => {
          const parent = bone.parent;
          if (!parent) return;
          bone.updateWorldMatrix(true, false);
          const world = bone.getWorldQuaternion(posedQ);
          keyA.setFromAxisAngle(worldUp, radians);
          world.premultiply(keyA);
          parent.getWorldQuaternion(keyB);
          bone.quaternion.copy(keyB.invert()).multiply(world);
        };
        yawWorld(bot.bones.Hips, lockBackYaw);
        yawWorld(bot.bones.Spine2, -lockBackYaw);
      }
      /* Standing still, pitch the chest and head up toward the camera. Mixamo's local axes are not the old rig's, so this is a world-axis pitch around his right. */
      if (state.faceUp > 0.01 && bot.bones.Head && bot.model) {`;

const replacement = `      /* Diagonal backward: turn the hips into the backward run while keeping the chest on the target. */
      if (!state.punching && lockTarget && Math.abs(lockBackYaw) > 0.02 && bot.bones?.Hips && bot.bones?.Spine2) {
        const yawWorld = (bone, radians) => {
          const parent = bone.parent;
          if (!parent) return;
          bone.updateWorldMatrix(true, false);
          const world = bone.getWorldQuaternion(posedQ);
          keyA.setFromAxisAngle(worldUp, radians);
          world.premultiply(keyA);
          parent.getWorldQuaternion(keyB);
          bone.quaternion.copy(keyB.invert()).multiply(world);
        };
        yawWorld(bot.bones.Hips, lockBackYaw);
        yawWorld(bot.bones.Spine2, -lockBackYaw);
      }
      /* Standing still, pitch the chest and head up toward the camera. Mixamo's local axes are not the old rig's, so this is a world-axis pitch around his right. */
      if (!state.punching && state.faceUp > 0.01 && bot.bones.Head && bot.model) {`;

const targetCRLF = target.replace(/\r?\n/g, "\r\n");
const targetLF = target.replace(/\r?\n/g, "\n");
const isCRLF = text.includes("\r\n");

if (text.includes(targetCRLF)) {
  text = text.replace(targetCRLF, replacement.replace(/\r?\n/g, "\r\n"));
  fs.writeFileSync("world.js", text, "utf8");
  console.log("Updated world.js unconstrained punch (CRLF)");
} else if (text.includes(targetLF)) {
  text = text.replace(targetLF, replacement.replace(/\r?\n/g, isCRLF ? "\r\n" : "\n"));
  fs.writeFileSync("world.js", text, "utf8");
  console.log("Updated world.js unconstrained punch (LF)");
} else {
  console.error("Target block not found");
  process.exit(1);
}

