import fs from "fs";
import { execSync } from "child_process";
import * as THREE from "../../vendor/three/three.module.min.js";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";

globalThis.self = globalThis;
const gltfLoader = new GLTFLoader();

async function inspect(buf, label) {
  console.log(`\n=== Inspecting ${label} (size: ${buf.length} bytes) ===`);
  const gltf = await gltfLoader.parseAsync(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  const scene = gltf.scene;

  const bones = [];
  const meshes = [];
  const materials = new Set();
  const textures = new Set();

  scene.traverse(node => {
    if (node.isBone) bones.push(node.name);
    if (node.isMesh) {
      meshes.push(`${node.name} (${node.type})`);
      if (node.material) {
        materials.add(node.material.name || "unnamed");
        if (node.material.map) textures.add(node.material.map.name || "has_map");
      }
    }
  });

  console.log("Root children:", scene.children.map(c => `${c.name} (${c.type}) rot=[${c.rotation.toArray().slice(0,3).map(v => (v*180/Math.PI).toFixed(1))}] scale=[${c.scale.toArray().map(v=>v.toFixed(3))}]`));
  console.log("Meshes count:", meshes.length, meshes);
  console.log("Materials:", Array.from(materials));
  console.log("Textures:", Array.from(textures));
  console.log("Bones count:", bones.length);
  console.log("Sample bone names (first 10):", bones.slice(0, 10));
}

const currentBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
await inspect(currentBuf, "CURRENT WORKING TREE niko-final-clean.glb");

