  const scene = gltf.scene;

  const bones = [];
  const meshes = [];
  const materials = new Set();

  scene.traverse(node => {
    if (node.isBone) bones.push(node.name);
    if (node.isMesh) {
      meshes.push(`${node.name} (${node.type})`);
      if (node.material) {
        materials.add(node.material.name || "unnamed");
        console.log(`Mesh material: name=${node.material.name}, map=${Boolean(node.material.map)}, color=${node.material.color?.getHexString()}`);
      }
    }
  });

  console.log("Root children:", scene.children.map(c => `${c.name} (${c.type}) rot=[${c.rotation.toArray().slice(0,3).map(v => (v*180/Math.PI).toFixed(1))}] scale=[${c.scale.toArray().map(v=>v.toFixed(3))}]`));
  console.log("Meshes count:", meshes.length, meshes);
  console.log("Materials:", Array.from(materials));
  console.log("Bones count:", bones.length);

  let hips = null;
  scene.traverse(n => { if (n.name.toLowerCase().includes("hips")) hips = n; });
  if (hips) {
    scene.updateMatrixWorld(true);
    const wp = new THREE.Vector3();
    const wq = new THREE.Quaternion();
    hips.getWorldPosition(wp);
    hips.getWorldQuaternion(wq);
    console.log(`Hips name: ${hips.name}, local pos: [${hips.position.toArray().map(v=>v.toFixed(3))}], rot: [${hips.rotation.toArray().slice(0,3).map(v=>(v*180/Math.PI).toFixed(1))}], world pos: [${wp.toArray().map(v=>v.toFixed(3))}]`);
  }
}

