import fs from "fs";
import { execSync } from "child_process";

function inspectGlbStructure(buf, label) {
  console.log(`\n=== GLB JSON for ${label} ===`);
  const magic = buf.readUInt32LE(0);
  const version = buf.readUInt32LE(4);
  const length = buf.readUInt32LE(8);
  const jsonChunkLength = buf.readUInt32LE(12);
  const jsonChunkType = buf.readUInt32LE(16);
  const jsonStr = buf.toString("utf8", 20, 20 + jsonChunkLength);
  const gltf = JSON.parse(jsonStr);

  console.log("Images count:", gltf.images?.length);
  if (gltf.images) {
    for (let i = 0; i < gltf.images.length; i++) {
      const img = gltf.images[i];
      const bv = gltf.bufferViews[img.bufferView];
      console.log(`  Image ${i}: name=${img.name}, mimeType=${img.mimeType}, bufferView=${img.bufferView}, byteLength=${bv?.byteLength}`);
    }
  }

  console.log("Materials count:", gltf.materials?.length);
  if (gltf.materials) {
    for (let i = 0; i < gltf.materials.length; i++) {
      const mat = gltf.materials[i];
      console.log(`  Material ${i}: name=${mat.name}, pbrMetallicRoughness=${JSON.stringify(mat.pbrMetallicRoughness)}`);
    }
  }

  console.log("Textures count:", gltf.textures?.length);
  if (gltf.textures) {
    for (let i = 0; i < gltf.textures.length; i++) {
      console.log(`  Texture ${i}:`, gltf.textures[i]);
    }
  }
}

