for (let i = 0; i < chunks.length; i += 2) {
  const header = chunks[i].trim();
  const body = chunks[i+1];
  console.log(`\n--- Chunk [${header}] ---`);
  const lines = body.split("\n").filter(l => l.startsWith("+") || l.startsWith("-")).slice(0, 10);
  console.log(lines.join("\n"));
}

