import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => {
    const el = {
      style: {},
      addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
      removeEventListener: () => {},
    };
    setTimeout(() => { if (el.onload) el.onload(); }, 1);
    return el;
  },
  createElement: () => {
    const el = {
      style: {},
      getContext: () => null,
      addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
      removeEventListener: () => {},
      set src(v) {
        setTimeout(() => { if (this.onload) this.onload(); }, 1);
      }
    };
    return el;
  }
};
global.HTMLImageElement = function() {};

const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const fbxLoader = new FBXLoader();
const bindBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/niko-cascadeur-clean.fbx");
const bindGroup = fbxLoader.parse(bindBuf.buffer.slice(bindBuf.byteOffset, bindBuf.byteOffset + bindBuf.byteLength), "");
const bindBones = {};
bindGroup.traverse((node) => {
  if (node.isBone) bindBones[stripMixamo(node.name)] = node;
});

const animBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/one_punch_anim_only.fbx");
const animGroup = fbxLoader.parse(animBuf.buffer.slice(animBuf.byteOffset, animBuf.byteOffset + animBuf.byteLength), "");
const animClip = animGroup.animations[0];
const animBones = {};
animGroup.traverse((node) => {
  if (node.isBone) animBones[stripMixamo(node.name)] = node;
});

const names = Object.keys(bones).filter((name) => bindBones[name] && animBones[name]);

const armAcross = (map) => {
  const left = new THREE.Vector3();
  const right = new THREE.Vector3();
  map.LeftArm.getWorldPosition(left);
  map.RightArm.getWorldPosition(right);
  return left.sub(right).setY(0).normalize();
};

const savedYaw = model.rotation.y;
model.rotation.y = 0;
model.updateMatrixWorld(true);
bindGroup.updateMatrixWorld(true);

const align = new THREE.Quaternion().setFromUnitVectors(armAcross(bindBones), armAcross(bones));
const alignInv = align.clone().invert();
const worldOf = (bone) => bone.getWorldQuaternion(new THREE.Quaternion());

const srcRest = {};
const tgtRest = {};
for (const name of names) {
  srcRest[name] = worldOf(bindBones[name]);
  tgtRest[name] = worldOf(bones[name]);
}

const srcHipRest = new THREE.Vector3();
bindBones.Hips.getWorldPosition(srcHipRest);
const tgtHipRest = bones.Hips.position.clone();
const hipScale = tgtHipRest.y / (Math.abs(srcHipRest.y) > 1e-4 ? srcHipRest.y : 1);
model.rotation.y = savedYaw;

console.log("srcHipRest:", srcHipRest.toArray());
console.log("tgtHipRest:", tgtHipRest.toArray());
console.log("hipScale:", hipScale);

const srcMixer = new THREE.AnimationMixer(animGroup);
srcMixer.clipAction(animClip).play();

// Test at frame 0, frame 12 (coil), frame 20 (apex), frame 36 (end)
const testFrames = [0, 12, 20, 36];

for (const frame of testFrames) {
  const time = (animClip.duration * frame) / 36;
  srcMixer.setTime(time);
  animGroup.updateMatrixWorld(true);

  const posed = {};
  for (const name of names) {
    const delta = worldOf(animBones[name]).multiply(srcRest[name].clone().invert());
    posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
  }

  // Apply to test model
  for (const name of names) {
    const parent = bones[name].parent;
    const local = parent && posed[parent.name]
      ? posed[parent.name].clone().invert().multiply(posed[name])
      : posed[name].clone();
    bones[name].quaternion.copy(local);
  }

  const currSrcHip = new THREE.Vector3();
  animBones.Hips.getWorldPosition(currSrcHip);

  // CORRECT HIP Y:
  const correctHipY = tgtHipRest.y + (currSrcHip.y - srcHipRest.y) * hipScale;
  bones.Hips.position.set(tgtHipRest.x, correctHipY, tgtHipRest.z);

  model.updateMatrixWorld(true);

  const rHandWorld = new THREE.Vector3();
  const lHandWorld = new THREE.Vector3();
  const headWorld = new THREE.Vector3();
  const hipsWorld = new THREE.Vector3();

  bones.RightHand.getWorldPosition(rHandWorld);
  bones.LeftHand.getWorldPosition(lHandWorld);
  bones.Head.getWorldPosition(headWorld);
  bones.Hips.getWorldPosition(hipsWorld);

  console.log(`\n--- Frame ${frame} (t=${time.toFixed(3)}s) ---`);
  console.log(`Hips local Y: ${correctHipY.toFixed(4)} (world Y: ${hipsWorld.y.toFixed(4)})`);
  console.log(`Hips pos:     [${hipsWorld.x.toFixed(3)}, ${hipsWorld.y.toFixed(3)}, ${hipsWorld.z.toFixed(3)}]`);
  console.log(`Head pos:     [${headWorld.x.toFixed(3)}, ${headWorld.y.toFixed(3)}, ${headWorld.z.toFixed(3)}]`);
  console.log(`RightHand:    [${rHandWorld.x.toFixed(3)}, ${rHandWorld.y.toFixed(3)}, ${rHandWorld.z.toFixed(3)}]`);
  console.log(`LeftHand:     [${lHandWorld.x.toFixed(3)}, ${lHandWorld.y.toFixed(3)}, ${lHandWorld.z.toFixed(3)}]`);
}

