model.rotation.y = savedYaw;

function retargetAndSample(fbxPath, label) {
  console.log(`\n=================== ${label} ===================`);
  const buf = fs.readFileSync(fbxPath);
  const group = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  const clip = group.animations[0];
  const srcBones = {};
  group.traverse((n) => { if (n.isBone) srcBones[stripMixamo(n.name)] = n; });

  const mixer = new THREE.AnimationMixer(group);
  mixer.clipAction(clip).play();

  // Test at t=0, t=coil (~35%), t=apex (~58%), t=end (100%)
  const times = [0, clip.duration * 0.35, clip.duration * 0.58, clip.duration];

  for (const t of times) {
    mixer.setTime(t);
    group.updateMatrixWorld(true);

    const posed = {};
    for (const name of names) {
      if (!srcBones[name]) continue;
      const delta = worldOf(srcBones[name]).multiply(srcRest[name].clone().invert());
      posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
    }
    for (const name of names) {
      if (!posed[name]) continue;
      const parent = bones[name].parent;
      const local = parent && posed[parent.name]
        ? posed[parent.name].clone().invert().multiply(posed[name])
        : posed[name].clone();
      bones[name].quaternion.copy(local);
    }

    const currSrcHip = new THREE.Vector3();
    srcBones.Hips.getWorldPosition(currSrcHip);
    const correctHipY = tgtHipRest.y + (currSrcHip.y - srcHipRest.y) * hipScale;
    bones.Hips.position.set(tgtHipRest.x, correctHipY, tgtHipRest.z);

    // Apply model rotation as in game: model.rotation.y = -Math.PI / 2
    model.rotation.y = -Math.PI / 2;
    model.updateMatrixWorld(true);

    const rHand = new THREE.Vector3();
    const lHand = new THREE.Vector3();
    const head = new THREE.Vector3();
    const hips = new THREE.Vector3();
    bones.RightHand.getWorldPosition(rHand);
    bones.LeftHand.getWorldPosition(lHand);
    bones.Head.getWorldPosition(head);
    bones.Hips.getWorldPosition(hips);

    console.log(`t=${t.toFixed(2)}s (game world coords, model.rotation.y = -90°):`);
    console.log(`  Hips:      [${hips.x.toFixed(3)}, ${hips.y.toFixed(3)}, ${hips.z.toFixed(3)}]`);
    console.log(`  Head:      [${head.x.toFixed(3)}, ${head.y.toFixed(3)}, ${head.z.toFixed(3)}]`);
    console.log(`  RightHand: [${rHand.x.toFixed(3)}, ${rHand.y.toFixed(3)}, ${rHand.z.toFixed(3)}]`);
    console.log(`  LeftHand:  [${lHand.x.toFixed(3)}, ${lHand.y.toFixed(3)}, ${lHand.z.toFixed(3)}]`);
  }
}

