import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({
    style: {},
    addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
    removeEventListener: () => {},
  }),
  createElement: () => ({
    style: {},
    getContext: () => null,
    addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
    removeEventListener: () => {},
    set src(v) { setTimeout(() => { if (this.onload) this.onload(); }, 1); }
  })
};
global.HTMLImageElement = function() {};

// Load niko-final-clean.glb
const gltfLoader = new GLTFLoader();
const buf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltf = await gltfLoader.parseAsync(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const robot = new THREE.Group();
robot.add(model);

const PREVIOUS_HEIGHT = 1.0;
const span = new THREE.Box3().setFromObject(model);
const s = PREVIOUS_HEIGHT / Math.max(0.001, span.max.y - span.min.y);
model.scale.setScalar(s);
model.position.set(0, 0, 0);
model.updateMatrixWorld(true);
const planted = new THREE.Box3().setFromObject(model);
if (Number.isFinite(planted.min.y)) model.position.y -= planted.min.y;
model.rotation.y = -Math.PI / 2;
robot.updateMatrixWorld(true);

// Idle setup
const fbxLoader = new FBXLoader();
const idleBuf = fs.readFileSync("assets/niko/Idle.fbx");
const idleGroup = fbxLoader.parse(idleBuf.buffer.slice(idleBuf.byteOffset, idleBuf.byteOffset + idleBuf.byteLength), "");

const armAcross = (map) => {
  const left = new THREE.Vector3();
  const right = new THREE.Vector3();
  map.LeftArm.getWorldPosition(left);
  map.RightArm.getWorldPosition(right);
  return left.sub(right).setY(0).normalize();
};

const srcBones = {};
idleGroup.traverse((node) => { if (node.isBone) srcBones[stripMixamo(node.name)] = node; });
const names = Object.keys(bones).filter((name) => srcBones[name]);

const savedYaw = model.rotation.y;
model.rotation.y = 0;
model.updateMatrixWorld(true);
idleGroup.updateMatrixWorld(true);

const align = new THREE.Quaternion().setFromUnitVectors(armAcross(srcBones), armAcross(bones));
const alignInv = align.clone().invert();
const worldOf = (bone) => bone.getWorldQuaternion(new THREE.Quaternion());
const srcRest = {};
const tgtRest = {};
for (const name of names) {
  srcRest[name] = worldOf(srcBones[name]);
  tgtRest[name] = worldOf(bones[name]);
}
const srcHipRest = srcBones.Hips.position.clone();
const tgtHipRest = bones.Hips.position.clone();
const hipScale = tgtHipRest.y / (Math.abs(srcHipRest.y) > 1e-4 ? srcHipRest.y : 1);
model.rotation.y = savedYaw;

const idleSrcMixer = new THREE.AnimationMixer(idleGroup);
const idleSrcClip = idleGroup.animations[0];
idleSrcMixer.clipAction(idleSrcClip).play();

const idleFrames = Math.max(2, Math.round(idleSrcClip.duration * 30));
const idleTimes = new Float32Array(idleFrames);
const idleQuats = Object.fromEntries(names.map((name) => [name, new Float32Array(idleFrames * 4)]));
const idleHips = new Float32Array(idleFrames * 3);

for (let frame = 0; frame < idleFrames; frame += 1) {
  const time = (idleSrcClip.duration * frame) / (idleFrames - 1);
  idleTimes[frame] = time;
  idleSrcMixer.setTime(time);
  idleGroup.updateMatrixWorld(true);
  const posed = {};
  for (const name of names) {
    const delta = worldOf(srcBones[name]).multiply(srcRest[name].clone().invert());
    posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
  }
  for (const name of names) {
    const parent = bones[name].parent;
    const local = parent && posed[parent.name]
      ? posed[parent.name].clone().invert().multiply(posed[name])
      : posed[name].clone();
    if (frame > 0) {
      const prev = (frame - 1) * 4;
      const values = idleQuats[name];
      const dot = values[prev] * local.x + values[prev + 1] * local.y + values[prev + 2] * local.z + values[prev + 3] * local.w;
      if (dot < 0) local.set(-local.x, -local.y, -local.z, -local.w);
    }
    idleQuats[name].set([local.x, local.y, local.z, local.w], frame * 4);
  }
  idleHips[frame * 3] = tgtHipRest.x;
  idleHips[frame * 3 + 1] = tgtHipRest.y + (srcBones.Hips.position.y - srcHipRest.y) * hipScale;
  idleHips[frame * 3 + 2] = tgtHipRest.z;
}

const idleTracks = names.map((name) => new THREE.QuaternionKeyframeTrack(`${name}.quaternion`, idleTimes, idleQuats[name]));
idleTracks.push(new THREE.VectorKeyframeTrack("Hips.position", idleTimes, idleHips));
const idleClip = new THREE.AnimationClip("idle", idleSrcClip.duration, idleTracks);

// Load one-punch.json
const onePunchClipData = JSON.parse(fs.readFileSync("assets/niko/one-punch.json"));
const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    if (!bones[bone.name]) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) {
      tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
    }
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};
const onePunchClip = directClip(onePunchClipData);

// matchHemisphere as world.js does:
const matchHemisphere = (clip, ref, kRef = 0, kClip = 0) => {
  const refTracks = Object.fromEntries(ref.tracks.map((t) => [t.name, t]));
  for (const track of clip.tracks) {
    if (!track.name.endsWith(".quaternion")) continue;
    const rt = refTracks[track.name];
    if (!rt) continue;
    const rx = rt.values[kRef * 4];
    const ry = rt.values[kRef * 4 + 1];
    const rz = rt.values[kRef * 4 + 2];
    const rw = rt.values[kRef * 4 + 3];
    const cx = track.values[kClip * 4];
    const cy = track.values[kClip * 4 + 1];
    const cz = track.values[kClip * 4 + 2];
    const cw = track.values[kClip * 4 + 3];
    if (rx * cx + ry * cy + rz * cz + rw * cw < 0) {
      for (let i = 0; i < track.values.length; i += 1) track.values[i] = -track.values[i];
    }
  }
};
matchHemisphere(onePunchClip, idleClip, 8, 0);

const mixer = new THREE.AnimationMixer(model);
const idleAction = mixer.clipAction(idleClip);
idleAction.play();
idleAction.setEffectiveWeight(1);

const punchAction = mixer.clipAction(onePunchClip);
punchAction.play();
punchAction.setEffectiveWeight(0);

console.log("=== Testing Game Animation Blend ===");

// 1. Idle frame
mixer.setTime(0);
robot.updateMatrixWorld(true);
const h0 = new THREE.Vector3();
bones.Hips.getWorldPosition(h0);
const head0 = new THREE.Vector3();
bones.Head.getWorldPosition(head0);
console.log(`Idle: Hips Y=${h0.y.toFixed(3)}, Head Y=${head0.y.toFixed(3)}`);

// 2. Punch triggered (weight=1, idle weight=0)
idleAction.setEffectiveWeight(0);
punchAction.setEffectiveWeight(1);

const samplePoints = [0, 0.40, 0.70, 1.20];
for (const t of samplePoints) {
  punchAction.time = t;
  mixer.setTime(t);
  robot.updateMatrixWorld(true);

  const hw = new THREE.Vector3();
  const rHandw = new THREE.Vector3();
  const headw = new THREE.Vector3();
  bones.Hips.getWorldPosition(hw);
  bones.RightHand.getWorldPosition(rHandw);
  bones.Head.getWorldPosition(headw);

  console.log(`Punch t=${t.toFixed(2)}s:`);
  console.log(`  Hips:      [${hw.x.toFixed(3)}, ${hw.y.toFixed(3)}, ${hw.z.toFixed(3)}] (Delta Y from idle: ${(hw.y - h0.y).toFixed(3)}m)`);
  console.log(`  Head:      [${headw.x.toFixed(3)}, ${headw.y.toFixed(3)}, ${headw.z.toFixed(3)}]`);
  console.log(`  RightHand: [${rHandw.x.toFixed(3)}, ${rHandw.y.toFixed(3)}, ${rHandw.z.toFixed(3)}]`);
}

