import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "./world-map.js";
import { parts as groundParts } from "./world-ground.js";

console.log("=== Spots ===");
for (const [k, v] of Object.entries(spots)) {
  const [x, z] = toXZ(v[0], v[1]);
  const g = groundAt(x, z);
  const reg = terrainAtUV(v[0], v[1]).region?.name;
  console.log(`${k.padEnd(10)}: uv=[${v[0].toFixed(2)}, ${v[1].toFixed(2)}] xz=[${x.toFixed(2)}, ${z.toFixed(2)}] y=${g.toFixed(2)} region=${reg}`);
}

const landingUV = spots.landing;
const [lx, lz] = toXZ(landingUV[0], landingUV[1]);
console.log(`\nLanding: uv=[${landingUV[0].toFixed(2)}, ${landingUV[1].toFixed(2)}] xz=[${lx.toFixed(2)}, ${lz.toFixed(2)}] y=${groundAt(lx, lz).toFixed(2)}`);

// Current boss position:
const S = Math.SQRT1_2;
const curBossX = lx - S * 3.15;
const curBossZ = lz + S * 2.15;
const [curBossU, curBossV] = toUV(curBossX, curBossZ);
console.log(`Current boss: uv=[${curBossU.toFixed(2)}, ${curBossV.toFixed(2)}] xz=[${curBossX.toFixed(2)}, ${curBossZ.toFixed(2)}] y=${groundAt(curBossX, curBossZ).toFixed(2)} region=${terrainAtUV(curBossU, curBossV).region?.name}`);

// Dummy position:
const dummyX = lx - S * 3.2;
const dummyZ = lz - S * 3.2;
const [dummyU, dummyV] = toUV(dummyX, dummyZ);
console.log(`Dummy: uv=[${dummyU.toFixed(2)}, ${dummyV.toFixed(2)}] xz=[${dummyX.toFixed(2)}, ${dummyZ.toFixed(2)}] y=${groundAt(dummyX, dummyZ).toFixed(2)} region=${terrainAtUV(dummyU, dummyV).region?.name}`);

import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "../../world-map.js";
import { parts as groundParts } from "../../world-ground.js";

console.log("=== Spots ===");
for (const [k, v] of Object.entries(spots)) {
  const [x, z] = toXZ(v[0], v[1]);
  const g = groundAt(x, z);
  const reg = terrainAtUV(v[0], v[1]).region?.name;
  console.log(`${k.padEnd(10)}: uv=[${v[0].toFixed(2)}, ${v[1].toFixed(2)}] xz=[${x.toFixed(2)}, ${z.toFixed(2)}] y=${g.toFixed(2)} region=${reg}`);
}

const landingUV = spots.landing;
const [lx, lz] = toXZ(landingUV[0], landingUV[1]);
console.log(`\nLanding: uv=[${landingUV[0].toFixed(2)}, ${landingUV[1].toFixed(2)}] xz=[${lx.toFixed(2)}, ${lz.toFixed(2)}] y=${groundAt(lx, lz).toFixed(2)}`);

// Current boss position:
const S = Math.SQRT1_2;
const curBossX = lx - S * 3.15;
const curBossZ = lz + S * 2.15;
const [curBossU, curBossV] = toUV(curBossX, curBossZ);
console.log(`Current boss: uv=[${curBossU.toFixed(2)}, ${curBossV.toFixed(2)}] xz=[${curBossX.toFixed(2)}, ${curBossZ.toFixed(2)}] y=${groundAt(curBossX, curBossZ).toFixed(2)} region=${terrainAtUV(curBossU, curBossV).region?.name}`);

// Dummy position:
const dummyX = lx - S * 3.2;
const dummyZ = lz - S * 3.2;
const [dummyU, dummyV] = toUV(dummyX, dummyZ);
console.log(`Dummy: uv=[${dummyU.toFixed(2)}, ${dummyV.toFixed(2)}] xz=[${dummyX.toFixed(2)}, ${dummyZ.toFixed(2)}] y=${groundAt(dummyX, dummyZ).toFixed(2)} region=${terrainAtUV(dummyU, dummyV).region?.name}`);

import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "../../world-map.js";
import { parts as groundParts } from "../../world-ground.js";

// Let's sample a grid in UV space to find all walkable points on region "ground"
console.log("Sampling region 'ground' points...");
const groundPoints = [];
for (let u = -35; u <= 10; u += 0.5) {
  for (let v = 0; v <= 35; v += 0.5) {
    const t = terrainAtUV(u, v);
    if (t.region?.name === "ground") {
      const [x, z] = toXZ(u, v);
      groundPoints.push({ u, v, x, z, h: t.h });
    }
  }
}

console.log(`Found ${groundPoints.length} points in ground region.`);
const minU = Math.min(...groundPoints.map(p => p.u));
const maxU = Math.max(...groundPoints.map(p => p.u));
const minV = Math.min(...groundPoints.map(p => p.v));
const maxV = Math.max(...groundPoints.map(p => p.v));

console.log(`U bounds: [${minU.toFixed(1)}, ${maxU.toFixed(1)}]`);
console.log(`V bounds: [${minV.toFixed(1)}, ${maxV.toFixed(1)}]`);

// Find the "top" in screen terms (-v) on the ground level
// In screen terms, v is down, -v is top of screen!
// What is the smallest v (highest up the screen) where region is ground?
const topPoints = groundPoints.filter(p => p.v <= minV + 2);
console.log(`Topmost ground points (smallest v): count=${topPoints.length}`);
topPoints.slice(0, 10).forEach(p => console.log(`  uv=[${p.u.toFixed(2)}, ${p.v.toFixed(2)}] xz=[${p.x.toFixed(2)}, ${p.z.toFixed(2)}]`));

// Also let's check around cove: uv=[-22.97, 3.43]
console.log("\nCove spot:", spots.cove);
console.log("Stairs to next level (meadow/low):");
import { stairs } from "../../world-map.js";
stairs.forEach(s => console.log(`  from=${s.from} to=${s.to} a=${s.a} b=${s.b}`));

