import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt, stairs } from "../../world-map.js";
import { parts as groundParts } from "../../world-ground.js";

const [lx, lz] = toXZ(spots.landing[0], spots.landing[1]);
console.log(`Niko landing: uv=[${spots.landing[0].toFixed(2)}, ${spots.landing[1].toFixed(2)}] xz=[${lx.toFixed(2)}, ${lz.toFixed(2)}]`);

// Check stairs from ground (beach: 0.5) to meadow (low: 3.0)
const groundStairs = stairs.filter(s => s.from === LEVEL.beach);
console.log("Stairs from ground to meadow:", groundStairs);

// Check ground bounds
console.log("Ground parts count in world-ground.js:", groundParts.length);
// Let's print the ellipses defining the ground region
console.log("Ground ellipses in world-map.js:");
// [ell(-10, 10.6, 10.8, 7.2), ell(0.4, 14.6, 8.4, 4), ell(-17.2, 2.6, 4.6, 5.6), ell(-15.4, 6.4, 5.4, 4.2), ...groundParts]

// Let's map out the walkable cells of region "ground"
const groundCells = [];
for (let u = -30; u <= 5; u += 1) {
  for (let v = 0; v <= 30; v += 1) {
    const t = terrainAtUV(u, v);
    if (t.region?.name === "ground" && t.h >= 0.4 && t.h <= 0.6) {
      const [x, z] = toXZ(u, v);
      groundCells.push({ u, v, x, z });
    }
  }
}

// Group ground cells by v (screen Y / top to bottom)
const vGroups = {};
for (const c of groundCells) {
  const vKey = Math.round(c.v);
  if (!vGroups[vKey]) vGroups[vKey] = [];
  vGroups[vKey].push(c);
}

console.log("\nGround cells summary by v (smaller v = higher on screen, larger v = lower / closer to camera):");
const sortedV = Object.keys(vGroups).map(Number).sort((a,b) => a - b);
for (const v of sortedV) {
  const cells = vGroups[v];
  const uVals = cells.map(c => c.u);
  const minU = Math.min(...uVals);
  const maxU = Math.max(...uVals);
  const avgX = cells.reduce((s, c) => s + c.x, 0) / cells.length;
  const avgZ = cells.reduce((s, c) => s + c.z, 0) / cells.length;
  console.log(`v=${v.toString().padStart(2)}: count=${cells.length.toString().padStart(2)} u=[${minU.toFixed(1)}, ${maxU.toFixed(1)}] avgXZ=[${avgX.toFixed(1)}, ${avgZ.toFixed(1)}]`);
}

