import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "../../world-map.js";
import { parts as groundParts } from "../../world-ground.js";

const S = Math.SQRT1_2;
const screenUp = [-S, -S];
const screenRight = [S, -S];

const [lx, lz] = toXZ(spots.landing[0], spots.landing[1]);
console.log(`Landing at x=${lx.toFixed(2)}, z=${lz.toFixed(2)}`);

// Let's march along screenUp from landing:
console.log("\nMarching in screenUp direction from landing (upwards on screen):");
for (let d = 0; d <= 25; d += 2) {
  const x = lx + screenUp[0] * d;
  const z = lz + screenUp[1] * d;
  const [u, v] = toUV(x, z);
  const t = terrainAtUV(u, v);
  const g = groundAt(x, z);
  console.log(`d=${d.toString().padStart(2)}: xz=[${x.toFixed(2)}, ${z.toFixed(2)}] uv=[${u.toFixed(2)}, ${v.toFixed(2)}] y=${g.toFixed(2)} region=${t.region?.name}`);
}

// Let's inspect the entire ground level map in screen coords (u, v):
// Remember: u = screen right, v = screen down (so smaller v is top of screen!)
// Niko is at landing: u = -13.73, v = 13.99
// What regions exist for v < 14 and region == "ground"?
console.log("\nSearching for all areas in region 'ground' with v < 14 (above Niko on screen):");
const aboveNiko = [];
for (let u = -32; u <= 5; u += 1) {
  for (let v = 0; v <= 14; v += 1) {
    const t = terrainAtUV(u, v);
    if (t.region?.name === "ground" && Math.abs(t.h - LEVEL.beach) < 0.2) {
      const [x, z] = toXZ(u, v);
      aboveNiko.push({ u, v, x, z });
    }
  }
}

console.log(`Total ground cells above Niko: ${aboveNiko.length}`);
// Find clusters or bounds
const minU = Math.min(...aboveNiko.map(p => p.u));
const maxU = Math.max(...aboveNiko.map(p => p.u));
const minV = Math.min(...aboveNiko.map(p => p.v));
const maxV = Math.max(...aboveNiko.map(p => p.v));
console.log(`U range: [${minU}, ${maxU}], V range: [${minV}, ${maxV}]`);

// Topmost cells (smallest v = highest up on screen):
console.log("\nTopmost cells in ground region:");
aboveNiko.filter(p => p.v <= minV + 2).forEach(p => {
  console.log(`  uv=[${p.u.toFixed(1)}, ${p.v.toFixed(1)}] xz=[${p.x.toFixed(2)}, ${p.z.toFixed(2)}]`);
});

import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "../../world-map.js";

console.log("=== All spots on first ground level (LEVEL.beach = 0.5) ===");
for (const [name, uv] of Object.entries(spots)) {
  const [x, z] = toXZ(uv[0], uv[1]);
  const g = groundAt(x, z);
  const t = terrainAtUV(uv[0], uv[1]);
  if (t.region?.name === "ground") {
    console.log(`${name.padEnd(10)}: uv=[${uv[0].toFixed(2)}, ${uv[1].toFixed(2)}] xz=[${x.toFixed(2)}, ${z.toFixed(2)}] y=${g.toFixed(2)}`);
  }
}

