import { buildIsland } from "../../world-island.js";
import * as THREE from "../../vendor/three/three.module.min.js";
import { toUV, toXZ, spots } from "../../world-map.js";

const scene = new THREE.Scene();
const island = buildIsland({ scene });
island.nav.build([]);

console.log("=== Checking Walkable Areas on First Ground Level ===");

const [lx, lz] = toXZ(spots.landing[0], spots.landing[1]);
console.log(`Niko landing: [${lx.toFixed(2)}, ${lz.toFixed(2)}], walkable: ${island.nav.walkable(lx, lz)}`);

// Let's sample walkable points with groundAt == 0.50
const walkableGround = [];
for (let x = -25; x <= 15; x += 0.5) {
  for (let z = 5; z <= 40; z += 0.5) {
    if (island.nav.walkable(x, z)) {
      const g = island.groundAt(x, z);
      if (Math.abs(g - 0.5) < 0.2) {
        const [u, v] = toUV(x, z);
        walkableGround.push({ x, z, u, v, g });
      }
    }
  }
}

console.log(`Found ${walkableGround.length} walkable ground points.`);
const sortedByV = [...walkableGround].sort((a, b) => a.v - b.v);
console.log("\nTop 15 walkable ground points (smallest v = highest on screen):");
sortedByV.slice(0, 15).forEach(p => {
  console.log(`  xz=[${p.x.toFixed(2)}, ${p.z.toFixed(2)}] uv=[${p.u.toFixed(2)}, ${p.v.toFixed(2)}] y=${p.g.toFixed(2)}`);
});

// Also check points directly top-ward from Niko (smaller v, same u or slightly varied)
console.log("\nWalkable points directly 'up' on screen from Niko (u ~ -14, v < 14):");
walkableGround
  .filter(p => Math.abs(p.u - spots.landing[0]) < 3.0 && p.v < spots.landing[1])
  .sort((a, b) => a.v - b.v)
  .forEach(p => {
    console.log(`  xz=[${p.x.toFixed(2)}, ${p.z.toFixed(2)}] uv=[${p.u.toFixed(2)}, ${p.v.toFixed(2)}] distFromLanding=${Math.hypot(p.x - lx, p.z - lz).toFixed(2)}`);
  });

// Also check around the upper cove area (u ~ -20 to -24, v ~ 2 to 6)
console.log("\nWalkable points around cove area (u < -18, v < 7):");
walkableGround
  .filter(p => p.u < -18 && p.v < 7)
  .sort((a, b) => a.v - b.v)
  .slice(0, 10)
  .forEach(p => {
    console.log(`  xz=[${p.x.toFixed(2)}, ${p.z.toFixed(2)}] uv=[${p.u.toFixed(2)}, ${p.v.toFixed(2)}]`);
  });

