import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "../../world-map.js";
import { parts as groundParts } from "../../world-ground.js";

const S = Math.SQRT1_2;
const [lx, lz] = toXZ(spots.landing[0], spots.landing[1]);

console.log("Landing spot (Niko spawn):", lx.toFixed(2), lz.toFixed(2), "UV:", spots.landing.map(v=>v.toFixed(2)));

// Candidate 1: Top of the spawn court (in front of Niko / past dummy)
// Dummy is at landing + screenUp * 3.2
// If we place boss further along screenUp (e.g. d = 6.0 to 7.0):
for (let d = 4.5; d <= 8.5; d += 0.5) {
  const x = lx - S * d;
  const z = lz - S * d;
  const [u, v] = toUV(x, z);
  const t = terrainAtUV(u, v);
  const g = groundAt(x, z);
  console.log(`Court Top d=${d.toFixed(1)}: xz=[${x.toFixed(2)}, ${z.toFixed(2)}] uv=[${u.toFixed(2)}, ${v.toFixed(2)}] y=${g.toFixed(2)} region=${t.region?.name}`);
}

// Candidate 2: Upper ground plateau / cove area (topmost area of the ground level)
console.log("\nUpper ground region (smallest v on ground level):");
// Around cove:
const [cx, cz] = toXZ(spots.cove[0], spots.cove[1]);
console.log(`Cove spot: xz=[${cx.toFixed(2)}, ${cz.toFixed(2)}] uv=[${spots.cove[0].toFixed(2)}, ${spots.cove[1].toFixed(2)}] y=${groundAt(cx, cz).toFixed(2)}`);

// Let's sample a few spots around cove / upper ground:
const upperGroundSpots = [
  { name: "Near cove", uv: [-20.0, 5.0] },
  { name: "Cove center", uv: [-22.5, 4.0] },
  { name: "Upper ground north", uv: [-21.0, 3.0] },
  { name: "Upper ground flat", uv: [-18.5, 4.5] },
  { name: "Mid-upper ground", uv: [-17.0, 6.5] },
];

upperGroundSpots.forEach(s => {
  const [x, z] = toXZ(s.uv[0], s.uv[1]);
  const g = groundAt(x, z);
  const t = terrainAtUV(s.uv[0], s.uv[1]);
  console.log(`${s.name.padEnd(20)}: uv=[${s.uv[0].toFixed(1)}, ${s.uv[1].toFixed(1)}] xz=[${x.toFixed(2)}, ${z.toFixed(2)}] y=${g.toFixed(2)} region=${t.region?.name}`);
});

