import { spots, LEVEL, terrainAtUV, toUV, toXZ, groundAt } from "../../world-map.js";

// Generate a text map of the first ground level in UV coordinates
// U runs horizontally (-32 to 5), V runs vertically (0 to 30)
// Remember: v=0 is TOP of screen, v=30 is BOTTOM of screen!
const uMin = -30, uMax = 2, vMin = 0, vMax = 28;
const uStep = 1.0, vStep = 1.0;

const [lx, lz] = toXZ(spots.landing[0], spots.landing[1]);
const [dx, dz] = [lx - Math.SQRT1_2 * 3.2, lz - Math.SQRT1_2 * 3.2];
const [du, dv] = toUV(dx, dz);

console.log("=== FIRST GROUND LEVEL MAP (UV coords: U -> right, V v down) ===");
console.log("Legend: '.' = ground (0.5), 'N' = Niko landing, 'D' = Dummy, 'M' = Mailbox, 'S' = Shack, 'C' = Cove, '#' = higher levels (meadow), ' ' = sea/void\n");

const lines = [];
for (let v = vMin; v <= vMax; v += vStep) {
  let line = `${v.toString().padStart(2)} | `;
  for (let u = uMin; u <= uMax; u += uStep) {
    // Check if close to key spots
    if (Math.hypot(u - spots.landing[0], v - spots.landing[1]) < 0.8) {
      line += "N";
    } else if (Math.hypot(u - du, v - dv) < 0.8) {
      line += "D";
    } else if (Math.hypot(u - spots.cove[0], v - spots.cove[1]) < 0.8) {
      line += "C";
    } else if (Math.hypot(u - spots.shack[0], v - spots.shack[1]) < 0.8) {
      line += "S";
    } else if (Math.hypot(u - spots.mail[0], v - spots.mail[1]) < 0.8) {
