import { build } from "esbuild";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const vendor = path.join(root, "vendor/three");

const vendoredThree = {
  name: "vendored-three",
  setup(b) {
    b.onResolve({ filter: /^three$/ }, () => ({ path: path.join(vendor, "three.module.min.js") }));
    b.onResolve({ filter: /^three\/addons\// }, (args) => ({
      path: path.join(vendor, "addons", args.path.slice("three/addons/".length)),
    }));
  },
};

const script = process.argv[2];
if (!script) {
  console.error("Usage: node .impeccable/tools/run-tool.mjs <script.mjs>");
  process.exit(1);
}

const out = path.join(root, ".temp-tool.mjs");
await build({
  entryPoints: [path.resolve(script)],
  outfile: out,
  bundle: true,
  format: "esm",
  platform: "node",
  target: "node18",
  plugins: [vendoredThree],
  loader: { ".glb": "binary", ".fbx": "binary", ".json": "json" },
  logLevel: "error",
});

const res = spawnSync("node", [out, ...process.argv.slice(3)], { stdio: "inherit" });
process.exit(res.status || 0);

import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: () => {} })
};
global.HTMLImageElement = function() {};

const fbxPath = "c:/Users/Rigel/Desktop/Cascadeur/niko-punch-exported-blend-v1.fbx";
console.log("Loading", fbxPath);
const buf = fs.readFileSync(fbxPath);
const loader = new FBXLoader();
const group = loader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");

console.log("=== FBX SUMMARY ===");
console.log("Animations count:", group.animations.length);
for (let i = 0; i < group.animations.length; i++) {
  const clip = group.animations[i];
  console.log(`Clip ${i}: name="${clip.name}", duration=${clip.duration.toFixed(4)}s, tracks=${clip.tracks.length}`);
  const trackSample = clip.tracks.slice(0, 5).map(t => t.name);
  console.log(`  Sample tracks:`, trackSample);
}

let boneCount = 0;
const bones = [];
let meshCount = 0;
const meshes = [];

group.traverse((n) => {
  if (n.isBone) {
    boneCount++;
    bones.push(n.name);
  }
  if (n.isMesh || n.isSkinnedMesh) {
    meshCount++;
    meshes.push({ name: n.name, type: n.type });
  }
});

console.log(`Bones (${boneCount}):`, bones.slice(0, 15));
console.log(`Meshes (${meshCount}):`, meshes);

const armature = group.getObjectByName("Armature");
if (armature) {
  console.log("Armature position:", armature.position);
  console.log("Armature rotation:", armature.rotation);
  console.log("Armature scale:", armature.scale);
}

// Let's check Hips position track in animations
if (group.animations.length > 0) {
  const clip = group.animations[0];
  const hipsPosTrack = clip.tracks.find(t => t.name.includes("Hips.position"));
  if (hipsPosTrack) {
    console.log("Hips.position track found! Times count:", hipsPosTrack.times.length);
    console.log("Initial pos:", Array.from(hipsPosTrack.values.slice(0, 3)));
    console.log("Mid pos:", Array.from(hipsPosTrack.values.slice(Math.floor(hipsPosTrack.values.length / 2), Math.floor(hipsPosTrack.values.length / 2) + 3)));
    console.log("End pos:", Array.from(hipsPosTrack.values.slice(-3)));
  } else {
    console.log("No Hips.position track found in clip.");
  }
}

