// Load Niko's in-game model
const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
const gameBones = {};
model.traverse((node) => {
  if (node.isBone) gameBones[stripMixamo(node.name)] = node;
});
console.log("Game deform bones count:", Object.keys(gameBones).length);

// Load niko-punch-exported-blend-v1.fbx
const fbxLoader = new FBXLoader();
const punchBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/niko-punch-exported-blend-v1.fbx");
const punchGroup = fbxLoader.parse(punchBuf.buffer.slice(punchBuf.byteOffset, punchBuf.byteOffset + punchBuf.byteLength), "");

const punchBones = {};
punchGroup.traverse((node) => {
  if (node.isBone) {
    const cleanName = stripMixamo(node.name);
    // If multiple bones have the same clean name (e.g. duplicate nodes), keep track
    if (!punchBones[cleanName]) punchBones[cleanName] = node;
    else console.log("Duplicate bone name:", node.name, "vs", punchBones[cleanName].name);
  }
});
console.log("Punch deform bones found:", Object.keys(punchBones).length);

const matched = Object.keys(gameBones).filter(name => punchBones[name]);
console.log(`Matched with game: ${matched.length} of ${Object.keys(gameBones).length}`);
const missing = Object.keys(gameBones).filter(name => !punchBones[name]);
console.log("Missing bones from game:", missing);

// Check bind reference niko-cascadeur-clean.fbx
const bindBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/niko-cascadeur-clean.fbx");
const bindGroup = fbxLoader.parse(bindBuf.buffer.slice(bindBuf.byteOffset, bindBuf.byteOffset + bindBuf.byteLength), "");
const bindBones = {};
bindGroup.traverse((node) => {
  if (node.isBone) {
    const cleanName = stripMixamo(node.name);
    if (!bindBones[cleanName]) bindBones[cleanName] = node;
  }
});

console.log("Bind bones count:", Object.keys(bindBones).length);
const matchedBind = Object.keys(gameBones).filter(name => bindBones[name] && punchBones[name]);
console.log(`Matched with both bind and game: ${matchedBind.length}`);

