import fs from "fs";

// Simulate the logic in world.js for onePunch
const dur = 1.1667;
const dt = 1 / 60; // 60 fps simulation
let punchTimer = 0;
let punching = true;

console.log("Simulating 60fps frame loop of onePunch:");
console.log("Time  | Frame (30fps) | punchWeight | idleWeight | runWeight | Other actions active?");
console.log("------+---------------+-------------+------------+-----------+----------------------");

let framesChecked = 0;
while (punching) {
  punchTimer += dt;
  const punchFrame = Math.floor(punchTimer * 30);
  let punchWeight = 0;
  if (punchTimer >= dur) {
    punching = false;
    punchWeight = 0;
  } else {
    const timeLeft = dur - punchTimer;
    punchWeight = timeLeft < 0.12 ? Math.max(0, timeLeft / 0.12) : 1.0;
  }

  const idleWeight = (1 - 0) * (1 - punchWeight);
  const runWeight = 0 * (1 - punchWeight);

  if (framesChecked % 10 === 0 || !punching || timeLeft < 0.13) {
    console.log(
      `${punchTimer.toFixed(3)}s | ${String(punchFrame).padStart(13)} | ${punchWeight.toFixed(3).padStart(11)} | ${idleWeight.toFixed(3).padStart(10)} | ${runWeight.toFixed(3).padStart(9)} | None (all procedural overrides disabled)`
    );
  }

  framesChecked++;
}

