const targetBones = {};
idleGroup.traverse((n) => {
  if (n.isBone) targetBones[stripMixamo(n.name)] = n;
});

const retargetedClip = retargetMixamo("onePunch", punchGroup, idleGroup, targetBones);

const boneDataList = [];
for (const track of retargetedClip.tracks) {
  const parts = track.name.split(".");
  const name = parts[0];
  const prop = parts[1];
  let b = boneDataList.find((item) => item.name === name);
  if (!b) {
