  const buf = fs.readFileSync(filePath);
  const group = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  const clip = group.animations[0];
  console.log(`Duration: ${clip.duration}s, Tracks count: ${clip.tracks.length}`);

  const bones = {};
  group.traverse((n) => {
