  });
  console.log(`Bones found: ${Object.keys(bones).length}`);

  // Check scale tracks
  const scaleTracks = clip.tracks.filter((t) => t.name.endsWith(".scale"));
  const nonOneScales = [];
  for (const st of scaleTracks) {
    let maxDiff = 0;
    for (let i = 0; i < st.values.length; i++) {
      const diff = Math.abs(st.values[i] - 1.0);
      if (diff > maxDiff) maxDiff = diff;
