  const hipsPos = new THREE.Vector3();
  const handScale = new THREE.Vector3();

  console.log("\nFrame samples (every 2 frames):");
  for (let f = 0; f < frames; f += 2) {
    const t = (clip.duration * f) / (frames - 1);
    mixer.setTime(t);
    group.updateMatrixWorld(true);

    if (bones.RightHand) bones.RightHand.getWorldPosition(handPos);
    if (bones.Hips) bones.Hips.getWorldPosition(hipsPos);
    if (bones.RightHand) bones.RightHand.getWorldScale(handScale);

