      `hipsY=${hipsPos.y.toFixed(3)} ` +
      `hand=(x:${handPos.x.toFixed(3)}, y:${handPos.y.toFixed(3)}, z:${handPos.z.toFixed(3)}) ` +
      `handScale=${handScale.y.toFixed(2)}`
    );
  }
}

