import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

const fbxLoader = new FBXLoader();
const buf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/niko-punch-squash-stretch-anim-only.fbx");
const group = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
const clip = group.animations[0];

const hipsTrack = clip.tracks.find(t => t.name.includes("Hips.position"));
console.log("Hips track:", hipsTrack?.name);
if (hipsTrack) {
  console.log("Keyframes:", hipsTrack.times.length);
  for (let i = 0; i < hipsTrack.times.length; i++) {
    const t = hipsTrack.times[i];
    const x = hipsTrack.values[i * 3 + 0];
    const y = hipsTrack.values[i * 3 + 1];
    const z = hipsTrack.values[i * 3 + 2];
    console.log(`f=${i} t=${t.toFixed(3)}s pos=(${x.toFixed(3)}, ${y.toFixed(3)}, ${z.toFixed(3)})`);
  }
}

import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
const fbxLoader = new FBXLoader();
const buf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/niko-punch-squash-stretch-anim-only.fbx");
const group = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
const clip = group.animations[0];

const bones = {};
group.traverse((n) => {
  if (n.isBone) bones[stripMixamo(n.name)] = n;
});

const mixer = new THREE.AnimationMixer(group);
mixer.clipAction(clip).play();

const frames = Math.max(2, Math.round(clip.duration * 30));
const hipsPos = new THREE.Vector3();
const leftFootPos = new THREE.Vector3();
const rightFootPos = new THREE.Vector3();

console.log("Frame | Hips Z (fwd) | LeftFoot Z | RightFoot Z");
for (let f = 0; f < frames; f += 2) {
  const t = (clip.duration * f) / (frames - 1);
  mixer.setTime(t);
  group.updateMatrixWorld(true);

  bones.Hips.getWorldPosition(hipsPos);
  bones.LeftFoot.getWorldPosition(leftFootPos);
  bones.RightFoot.getWorldPosition(rightFootPos);

  console.log(`f=${String(f).padStart(2)} | hips: ${hipsPos.z.toFixed(2)} | LFoot: ${leftFootPos.z.toFixed(2)} | RFoot: ${rightFootPos.z.toFixed(2)}`);
}

