import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
const fbxLoader = new FBXLoader();
const buf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/niko-punch-squash-stretch-anim-only.fbx");
const group = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
const clip = group.animations[0];

const bones = {};
group.traverse((n) => {
  if (n.isBone) bones[stripMixamo(n.name)] = n;
});

const mixer = new THREE.AnimationMixer(group);
mixer.clipAction(clip).play();

const frames = Math.max(2, Math.round(clip.duration * 30));
const hipsPos = new THREE.Vector3();
const zValues = [];

for (let f = 0; f < frames; f++) {
  const t = (clip.duration * f) / (frames - 1);
  mixer.setTime(t);
  group.updateMatrixWorld(true);
  bones.Hips.getWorldPosition(hipsPos);
  zValues.push(hipsPos.z);
}

const z0 = zValues[0];
const relZ = zValues.map(z => z - z0);
const maxZ = Math.max(...relZ);
const normZ = relZ.map(z => Math.max(0, z / maxZ));

console.log("Frame | Rel Z (cm) | Normalized (0..1)");
for (let f = 0; f < frames; f++) {
  console.log(`${String(f).padStart(2)}    | ${relZ[f].toFixed(2).padStart(6)}cm    | ${normZ[f].toFixed(4)}`);
}

