const ONE_PUNCH_STEP_DIST = 1.05;
const ONE_PUNCH_STEP_CURVE = [
  0.0000, 0.0000, 0.0006, 0.0026, 0.0067, 0.0134,
  0.0236, 0.0374, 0.0552, 0.0769, 0.1030, 0.1420,
  0.2168, 0.3243, 0.4430, 0.5632, 0.6887, 0.8053,
  0.9050, 0.9847, 1.0000, 0.9669, 0.9131, 0.8477,
  0.7648, 0.6633, 0.5689, 0.5007, 0.4366, 0.3686,
  0.3142, 0.2487, 0.1727, 0.0806, 0.0442, 0.0000
];

const dur = 1.20;
console.log("Simulating One Punch movement step-by-step:");
console.log("Frame | Time(s) | Disp(m) | Normalized | Status");

for (let frame = 0; frame <= 35; frame++) {
  const t = (dur * frame) / 35;
  const frameFloat = Math.min(35, Math.max(0, (t / dur) * 35));
  const f0 = Math.floor(frameFloat);
  const f1 = Math.min(35, f0 + 1);
  const frac = frameFloat - f0;
  const curveVal = ONE_PUNCH_STEP_CURVE[f0] * (1 - frac) + ONE_PUNCH_STEP_CURVE[f1] * frac;
  const disp = ONE_PUNCH_STEP_DIST * curveVal;

  let status = "";
  if (frame === 0) status = "At Origin (Ready)";
  else if (frame === 1) status = "Movement Starts";
  else if (frame >= 12 && frame <= 15) status = "Explosive Forward Surge";
  else if (frame >= 16 && frame <= 18) status = "Peak Stretch Strike";
  else if (frame >= 20 && frame <= 22) status = "Apex Hold (1 Step Forward)";
  else if (frame === 24) status = "Recoil Return Starts";
  else if (frame >= 25 && frame <= 34) status = "Returning Back to Origin";
  else if (frame === 35) status = "Back At Exact Origin";

  console.log(
