  console.log(`${name}: line ${line}`);
}
check("target1", `import { createSmearHandler } from "./world-smear.js";`);
check("target2", `  const liteParam = new URLSearchParams(location.search).get("lite");`);
check("target3", `  const island = buildIsland({`);
check("target5", `  const landing = island.spot("landing");\r\n  robot.position.copy(landing);`);
check("target6", `    lookTarget.set(THREE.MathUtils.clamp(robot.position.x, -38, 38), robot.position.y, THREE.MathUtils.clamp(robot.position.z, -38, 38));`);
check("target7", `  function reveal() {`);
