import fs from "fs";

let s = fs.readFileSync("world.js", "utf8");

// 1. Add import for buildDevMap
const target1 = `import { createSmearHandler } from "./world-smear.js";`;
const repl1 = `import { createSmearHandler } from "./world-smear.js";
import { buildDevMap } from "./world-dev-map.js";`;

const target1Crlf = target1.replace(/\n/g, "\r\n");
const repl1Crlf = repl1.replace(/\n/g, "\r\n");
if (!s.includes(target1Crlf)) throw new Error("target1 not found in world.js");
s = s.replace(target1Crlf, repl1Crlf);

// 2. Define isDevMap in start()
const target2 = `  const liteParam = new URLSearchParams(location.search).get("lite");`;
const repl2 = `  const devParam = new URLSearchParams(location.search);
  const isDevMap = devParam.get("map") === "dev" || devParam.get("dev") === "1" || devParam.has("dev") || devParam.has("devmap");
  const liteParam = new URLSearchParams(location.search).get("lite");`;

const target2Crlf = target2.replace(/\n/g, "\r\n");
const repl2Crlf = repl2.replace(/\n/g, "\r\n");
if (!s.includes(target2Crlf)) throw new Error("target2 not found in world.js");
s = s.replace(target2Crlf, repl2Crlf);

// 3. Build island with dev map branch
const target3 = `  const island = buildIsland({
    scene,
    withRim,
    coarse,
    clear: defs
      .filter((def) => def.action)
      .flatMap((def) => {
        const facing = THREE.MathUtils.degToRad(def.facing || 0);
        return [
          { x: def.x, z: def.z, r: 2.6 },
          { x: def.x + Math.sin(facing) * 2.2, z: def.z + Math.cos(facing) * 2.2, r: 2.2 },
        ];
      }),
  });
  const wind = calm ? null : windLines({ scene, groundAt: island.groundAt, count: coarse ? 4 : 6 });
  const windPixels = new THREE.Vector2();
  const rain = calm || lite ? null : makeRain({ scene, lite: coarse });
  const rays = calm ? null : makeRays({ scene, groundAt: island.groundAt, sun, shadowSize: SHADOW_SIZE, lite: lite || coarse });`;

const repl3 = `  const island = isDevMap
    ? buildDevMap({ scene, withRim, ramp, colliders: [] })
    : buildIsland({
        scene,
        withRim,
        coarse,
        clear: defs
          .filter((def) => def.action)
          .flatMap((def) => {
            const facing = THREE.MathUtils.degToRad(def.facing || 0);
            return [
              { x: def.x, z: def.z, r: 2.6 },
              { x: def.x + Math.sin(facing) * 2.2, z: def.z + Math.cos(facing) * 2.2, r: 2.2 },
            ];
          }),
      });
  const wind = (calm || isDevMap) ? null : windLines({ scene, groundAt: island.groundAt, count: coarse ? 4 : 6 });
  const windPixels = new THREE.Vector2();
  const rain = (calm || lite || isDevMap) ? null : makeRain({ scene, lite: coarse });
  const rays = (calm || isDevMap) ? null : makeRays({ scene, groundAt: island.groundAt, sun, shadowSize: SHADOW_SIZE, lite: lite || coarse });`;

const target3Crlf = target3.replace(/\n/g, "\r\n");
const repl3Crlf = repl3.replace(/\n/g, "\r\n");
if (!s.includes(target3Crlf)) throw new Error("target3 not found in world.js");
s = s.replace(target3Crlf, repl3Crlf);

// 4. Wrap defs.forEach in !isDevMap check and register colliders for dev map
const target4 = `  defs.forEach((def) => {
    const build = builders[def.kind] || builders.pedestal;
    const built = build(def, def.kind === "monolith" ? cabinetOrder++ : 0);
    const group = built.group;
    const facing = THREE.MathUtils.degToRad(def.facing || 0);
    const floor = island.groundAt(def.x, def.z);
    group.position.set(def.x, floor, def.z);
    group.rotation.set(0, facing, THREE.MathUtils.degToRad(def.lean || 0), "YXZ");

    if (def.scale && !def.model) {
      group.scale.setScalar(def.scale);
    }

    scene.add(group);
    mergeStatic(group);

    const radius = def.radius || built.radius || 0.8;
    colliders.push({ x: def.x, z: def.z, r: radius });
    decal(scene, { color: "#2a3a2a", size: radius * 2.9, x: def.x, z: def.z, y: floor + 0.03, opacity: 0.3 });

    if (!def.action) {
      if (def.model) {
        loadModel({ def, group });
      }
      return;
    }

    const reach = built.reach || radius + 0.8;
    const forward = new THREE.Vector3(Math.sin(facing), 0, Math.cos(facing));
    const obj = {
      def,
      group,
      radius,
      react: built.react,
      spot: new THREE.Vector3(def.x, floor, def.z).addScaledVector(forward, reach),
      labelAt: new THREE.Vector3(def.x, floor + (built.labelY || 2.6), def.z),
      hover: 0,
      plate: null,
    };
    group.userData.worldObject = obj;

    const plate = document.createElement("button");
    plate.type = "button";
    plate.className = "world-plate";
    plate.textContent = def.label;
    plate.setAttribute("aria-label", \`Walk to \${def.label}\`);
    plate.style.setProperty("--i", objects.length);
    plate.addEventListener("click", () => goToObject(obj));
    labelsEl.append(plate);
    obj.plate = plate;

    objects.push(obj);
    byId.set(def.id, obj);

    if (def.model) {
      loadModel(obj);
    }
  });`;

const repl4 = `  if (isDevMap) {
    // Register dev map obstacles into colliders array
    if (island.pick) {
      island.pick.forEach((mesh) => {
        if (mesh.name && mesh.name.startsWith("DevPillar_")) {
          colliders.push({ x: mesh.position.x, z: mesh.position.z, r: 1.0 });
        }
      });
    }
  } else {
    defs.forEach((def) => {
      const build = builders[def.kind] || builders.pedestal;
      const built = build(def, def.kind === "monolith" ? cabinetOrder++ : 0);
      const group = built.group;
      const facing = THREE.MathUtils.degToRad(def.facing || 0);
      const floor = island.groundAt(def.x, def.z);
      group.position.set(def.x, floor, def.z);
      group.rotation.set(0, facing, THREE.MathUtils.degToRad(def.lean || 0), "YXZ");

      if (def.scale && !def.model) {
        group.scale.setScalar(def.scale);
      }

      scene.add(group);
      mergeStatic(group);

      const radius = def.radius || built.radius || 0.8;
      colliders.push({ x: def.x, z: def.z, r: radius });
      decal(scene, { color: "#2a3a2a", size: radius * 2.9, x: def.x, z: def.z, y: floor + 0.03, opacity: 0.3 });

      if (!def.action) {
        if (def.model) {
          loadModel({ def, group });
        }
        return;
      }

      const reach = built.reach || radius + 0.8;
      const forward = new THREE.Vector3(Math.sin(facing), 0, Math.cos(facing));
      const obj = {
        def,
        group,
        radius,
        react: built.react,
        spot: new THREE.Vector3(def.x, floor, def.z).addScaledVector(forward, reach),
        labelAt: new THREE.Vector3(def.x, floor + (built.labelY || 2.6), def.z),
        hover: 0,
        plate: null,
      };
      group.userData.worldObject = obj;

      const plate = document.createElement("button");
      plate.type = "button";
      plate.className = "world-plate";
      plate.textContent = def.label;
      plate.setAttribute("aria-label", \`Walk to \${def.label}\`);
      plate.style.setProperty("--i", objects.length);
      plate.addEventListener("click", () => goToObject(obj));
      labelsEl.append(plate);
      obj.plate = plate;

      objects.push(obj);
      byId.set(def.id, obj);

      if (def.model) {
        loadModel(obj);
      }
    });
  }`;

const target4Crlf = target4.replace(/\n/g, "\r\n");
const repl4Crlf = repl4.replace(/\n/g, "\r\n");
if (!s.includes(target4Crlf)) throw new Error("target4 not found in world.js");
s = s.replace(target4Crlf, repl4Crlf);

// 5. Add Dev Gym Badge around landing
const target5 = `  const landing = island.spot("landing");
  robot.position.copy(landing);`;

const repl5 = `  const landing = island.spot("landing");
  robot.position.copy(landing);

  if (isDevMap) {
    root.classList.add("world-dev-mode");
    const badge = document.createElement("div");
    badge.className = "dev-gym-badge";
