import fs from "fs";

// 1. Update world-dev-map.js
let devMap = fs.readFileSync("world-dev-map.js", "utf8");
devMap = devMap.replace(
  "export function buildDevMap({ scene, withRim, ramp, colliders }) {",
  "export function buildDevMap({ scene, withRim, ramp, colliders }) {\n  const devColliders = colliders || [];"
);
devMap = devMap.replaceAll("if (colliders) colliders.push(", "devColliders.push(");
devMap = devMap.replace(
  "    pick: pickables,",
  "    pick: pickables,\n    colliders: devColliders,"
);
// Ensure CRLF
devMap = devMap.replace(/\r?\n/g, "\r\n");
fs.writeFileSync("world-dev-map.js", devMap, "utf8");
console.log("Updated world-dev-map.js");

// 2. Update world.js
let world = fs.readFileSync("world.js", "utf8");
const target = `  if (isDevMap) {
    // Register dev map obstacles into colliders array
    if (island.pick) {
      island.pick.forEach((mesh) => {
        if (mesh.name && mesh.name.startsWith("DevPillar_")) {
          colliders.push({ x: mesh.position.x, z: mesh.position.z, r: 1.0 });
        }
      });
    }
  }`;

const repl = `  if (isDevMap) {
    // Register all dev map obstacles into colliders array
    if (island.colliders) {
      colliders.push(...island.colliders);
    }
  }`;

const targetCrlf = target.replace(/\n/g, "\r\n");
const replCrlf = repl.replace(/\n/g, "\r\n");

if (!world.includes(targetCrlf)) throw new Error("target not found in world.js");
world = world.replace(targetCrlf, replCrlf);
world = world.replace(/\r?\n/g, "\r\n");
fs.writeFileSync("world.js", world, "utf8");
console.log("Updated world.js");

