import fs from "fs";

// 1. Update styles.css
let css = fs.readFileSync("styles.css", "utf8");
const targetCss = `.dev-gym-badge {
  position: absolute;
  top: 18px;
  left: 20px;
  z-index: 100;`;

const replCss = `.world-dev-mode .world-help {
  display: none !important;
}

.dev-gym-badge {
  position: absolute;
  top: calc(var(--hud-h, 68px) + 14px);
  left: 20px;
  z-index: 30;`;

// Normalize matching regardless of CRLF/LF
if (!css.includes(targetCss) && !css.includes(targetCss.replace(/\n/g, "\r\n"))) {
  throw new Error("targetCss not found in styles.css");
}

if (css.includes(targetCss.replace(/\n/g, "\r\n"))) {
  css = css.replace(targetCss.replace(/\n/g, "\r\n"), replCss.replace(/\n/g, "\r\n"));
} else {
  css = css.replace(targetCss, replCss);
}
fs.writeFileSync("styles.css", css, "utf8");
console.log("Updated styles.css successfully!");

// 2. Update world.js
let world = fs.readFileSync("world.js", "utf8");

// 2a. Update badge text from [WASD / Click] to [WASD]
const targetBadge = `<span><b>[WASD / Click]</b> Move</span>`;
const replBadge = `<span><b>[WASD]</b> Move</span>`;
if (!world.includes(targetBadge)) throw new Error("targetBadge not found in world.js");
world = world.replace(targetBadge, replBadge);

// 2b. Remove click movement from pointerup
const targetPointerUp = `    if (!press || Math.hypot(event.clientX - press.x, event.clientY - press.y) > 10) {
      press = null;
      return;
    }

    press = null;
    const hit = castAt(event.clientX, event.clientY);

    if (hit.obj) {
      goToObject(hit.obj);
    } else if (hit.point) {
      goTo(hit.point);
    }`;

const replPointerUp = `    if (!press || Math.hypot(event.clientX - press.x, event.clientY - press.y) > 10) {
      press = null;
      return;
    }

    press = null;
    /* Click movement system removed: clicking on the game canvas does not move Niko */`;

const targetPointerUpCrlf = targetPointerUp.replace(/\n/g, "\r\n");
const replPointerUpCrlf = replPointerUp.replace(/\n/g, "\r\n");

if (!world.includes(targetPointerUpCrlf)) throw new Error("targetPointerUp not found in world.js");
world = world.replace(targetPointerUpCrlf, replPointerUpCrlf);

fs.writeFileSync("world.js", world, "utf8");
console.log("Updated world.js successfully!");

// 3. Update index.html control hints
let html = fs.readFileSync("index.html", "utf8");
const targetHtml = `<span class="world-controls-fine">Click to walk, or use <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd>.`;
const replHtml = `<span class="world-controls-fine">Move with <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd>.`;
if (html.includes(targetHtml)) {
  html = html.replace(targetHtml, replHtml);
  fs.writeFileSync("index.html", html, "utf8");
  console.log("Updated index.html successfully!");
}

