import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

// Polyfill minimal browser DOM
globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({
    style: {},
    addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
    removeEventListener: () => {},
  }),
  createElement: () => ({
    style: {},
    getContext: () => null,
    addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
    removeEventListener: () => {},
    set src(v) { setTimeout(() => { if (this.onload) this.onload(); }, 1); }
  })
};
global.HTMLImageElement = function() {};

const fbxPath = "c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx";

if (!fs.existsSync(fbxPath)) {
  console.error("File does not exist:", fbxPath);
  process.exit(1);
}

const buf = fs.readFileSync(fbxPath);
console.log("File size:", buf.length, "bytes");

const loader = new FBXLoader();
const group = loader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");

console.log("Animations count:", group.animations?.length || 0);

if (group.animations && group.animations.length > 0) {
  group.animations.forEach((anim, i) => {
    console.log(`\n--- Animation [${i}]: "${anim.name}" ---`);
    console.log(`Duration: ${anim.duration.toFixed(3)}s`);
    console.log(`Tracks count: ${anim.tracks.length}`);

    // Check FPS or keyframe samples
    if (anim.tracks[0]) {
      const times = anim.tracks[0].times;
      console.log(`Keyframe count on track 0: ${times.length}`);
      if (times.length > 1) {
        const dt = times[1] - times[0];
        console.log(`Frame dt: ~${dt.toFixed(4)}s (${Math.round(1 / dt)} fps)`);
      }
      console.log(`First keyframe time: ${times[0]}, Last keyframe time: ${times[times.length - 1]}`);
    }

    // Inspect bone tracks
    const boneNames = new Set();
    const positionTracks = [];
    const scaleTracks = [];
    anim.tracks.forEach(t => {
      const parts = t.name.split(".");
      boneNames.add(parts[0]);
      if (parts[1] === "position") positionTracks.push(t.name);
      if (parts[1] === "scale") scaleTracks.push(t.name);
    });

    console.log(`Unique bones animated: ${boneNames.size}`);
    console.log(`Position tracks (${positionTracks.length}):`, positionTracks.slice(0, 10));
    console.log(`Scale tracks (${scaleTracks.length}):`, scaleTracks.slice(0, 10));

    // Check Hips position (root motion vs in-place)
    const hipsPosTrack = anim.tracks.find(t => t.name.includes("Hips.position") || t.name.includes("mixamorig:Hips.position"));
    if (hipsPosTrack) {
      console.log(`Hips position track found: ${hipsPosTrack.name}`);
      const vals = hipsPosTrack.values;
      const count = hipsPosTrack.times.length;
      const startPos = [vals[0], vals[1], vals[2]];
      const midPos = [vals[Math.floor(count/2)*3], vals[Math.floor(count/2)*3+1], vals[Math.floor(count/2)*3+2]];
      const endPos = [vals[(count-1)*3], vals[(count-1)*3+1], vals[(count-1)*3+2]];
      console.log(`  Start Hips pos: [${startPos.map(n => n.toFixed(3)).join(", ")}]`);
      console.log(`  Mid Hips pos:   [${midPos.map(n => n.toFixed(3)).join(", ")}]`);
      console.log(`  End Hips pos:   [${endPos.map(n => n.toFixed(3)).join(", ")}]`);
      const deltaX = Math.abs(endPos[0] - startPos[0]);
      const deltaZ = Math.abs(endPos[2] - startPos[2]);
      console.log(`  Horizontal drift: dX=${deltaX.toFixed(4)}, dZ=${deltaZ.toFixed(4)} (in-place: ${deltaX < 0.1 && deltaZ < 0.1})`);
    } else {
      console.log("No Hips position track found!");
    }
  });
}

// Check bones in hierarchy
const bones = [];
group.traverse(node => {
  if (node.isBone) bones.push(node.name);
});
console.log(`\nTotal bones in FBX hierarchy: ${bones.length}`);
console.log("First 15 bones:", bones.slice(0, 15));

