import fs from "fs";

function summarize(filePath) {
  if (!fs.existsSync(filePath)) return `${filePath} not found`;
  const buf = fs.readFileSync(filePath);
  const size = buf.length;
  const str = buf.toString("latin1");
  const hasObjects = str.includes("Objects:");
  const takes = [...str.matchAll(/Take:\s*([^\r\n]+)/g)].map(m => m[1]);
  const animStacks = [...str.matchAll(/AnimationStack[^\n\r]*"([^"]+)"/g)].map(m => m[1]);
  const modelNodes = [...str.matchAll(/Model:\s*"([^"]+)"/g)].map(m => m[1]);
  const curveNodes = [...str.matchAll(/AnimCurveNode/g)].length;
  const curves = [...str.matchAll(/AnimCurve/g)].length;

  return {
    filePath,
    size: `${(size / 1024).toFixed(1)} KB`,
    hasObjects,
    takes,
    animStacks,
    modelCount: modelNodes.length,
    sampleModels: modelNodes.slice(0, 5),
    curveNodes,
    curves
  };
}

console.log("in place running.fbx:", summarize("c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx"));
