  })
};
global.HTMLImageElement = function() {};

const fbxPath = "c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx";
const buf = fs.readFileSync(fbxPath);
console.log(`Loaded ${fbxPath}: ${buf.length} bytes (${(buf.length / 1024).toFixed(1)} KB)`);

const loader = new FBXLoader();
const group = loader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");

console.log("\n=== FBX PARSE RESULTS ===");
console.log(`Animations count: ${group.animations?.length || 0}`);

if (!group.animations || group.animations.length === 0) {
  console.log("No animations found!");
  process.exit(1);
}

const clip = group.animations[0];
console.log(`Clip name: "${clip.name}"`);
console.log(`Duration: ${clip.duration.toFixed(4)}s`);
console.log(`Total tracks: ${clip.tracks.length}`);

// Keyframes / FPS
if (clip.tracks[0]) {
  const times = clip.tracks[0].times;
  const frameCount = times.length;
  console.log(`Keyframe samples: ${frameCount}`);
  if (frameCount > 1) {
    const dt = times[1] - times[0];
    console.log(`Time per frame: ${dt.toFixed(4)}s (~${Math.round(1 / dt)} FPS)`);
  }
}

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");

const boneTracks = new Map();
clip.tracks.forEach((track) => {
  const parts = track.name.split(".");
  const rawBone = parts[0];
  const prop = parts[1];
  const cleanBone = stripMixamo(rawBone);
  if (!boneTracks.has(cleanBone)) boneTracks.set(cleanBone, {});
  boneTracks.get(cleanBone)[prop] = track;
});

console.log(`Unique bones animated: ${boneTracks.size}`);

// Check against Niko's in-game GLB bones
const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const nikoBones = {};
gltf.scene.traverse((node) => {
  if (node.isBone) nikoBones[stripMixamo(node.name)] = node;
});

const matchedBones = Object.keys(nikoBones).filter((name) => boneTracks.has(name));
console.log(`Matched Niko deform bones: ${matchedBones.length} of ${Object.keys(nikoBones).length}`);

const missingBones = Object.keys(nikoBones).filter((name) => !boneTracks.has(name));
if (missingBones.length > 0) {
  console.log("Missing bones from Niko's skeleton:", missingBones.slice(0, 10));
}

// Check Hips root motion vs in-place
const hipsData = boneTracks.get("Hips");
if (hipsData && hipsData.position) {
  const vals = hipsData.position.values;
  const times = hipsData.position.times;
  const count = times.length;
  const p0 = [vals[0], vals[1], vals[2]];
  const pMid = [vals[Math.floor(count / 2) * 3], vals[Math.floor(count / 2) * 3 + 1], vals[Math.floor(count / 2) * 3 + 2]];
  const pEnd = [vals[(count - 1) * 3], vals[(count - 1) * 3 + 1], vals[(count - 1) * 3 + 2]];

  console.log("\n=== HIPS MOTION CHECK ===");
  console.log(`Start Hips Pos: [${p0.map((v) => v.toFixed(3)).join(", ")}]`);
  console.log(`Mid Hips Pos:   [${pMid.map((v) => v.toFixed(3)).join(", ")}]`);
  console.log(`End Hips Pos:   [${pEnd.map((v) => v.toFixed(3)).join(", ")}]`);

  const deltaX = Math.abs(pEnd[0] - p0[0]);
  const deltaZ = Math.abs(pEnd[2] - p0[2]);
  const deltaY = Math.abs(pEnd[1] - p0[1]);
  const rangeY = Math.max(...Array.from(times).map((_, i) => vals[i * 3 + 1])) - Math.min(...Array.from(times).map((_, i) => vals[i * 3 + 1]));

  console.log(`Horizontal drift: dX = ${deltaX.toFixed(4)}, dZ = ${deltaZ.toFixed(4)}`);
  console.log(`Vertical bob range: ${rangeY.toFixed(4)}`);
  const isInPlace = deltaX < 0.2 && deltaZ < 0.2;
  console.log(`=> IS IN-PLACE RUNNING: ${isInPlace ? "YES (True In-Place)" : "NO (Has root motion drift)"}`);
} else {
  console.log("\nNo Hips position track (quaternion only). Pure in-place!");
}

// Check limb motions (Feet & Hands)
const keyLimbs = ["LeftFoot", "RightFoot", "LeftHand", "RightHand", "LeftUpLeg", "RightUpLeg", "LeftArm", "RightArm"];
console.log("\n=== KEY LIMBS CHECK ===");
keyLimbs.forEach((limb) => {
  const data = boneTracks.get(limb);
  if (data) {
    const hasQ = Boolean(data.quaternion);
    const hasP = Boolean(data.position);
    const hasS = Boolean(data.scale);
    console.log(`  ${limb}: quaternion=${hasQ}, position=${hasP}, scale=${hasS}`);
  } else {
    console.log(`  ${limb}: NOT ANIMATED`);
  }
});

