const replImport = `import onePunchClipData from "./assets/niko/one-punch.json";
import cascadeurRunData from "./assets/niko/cascadeur-run.json";`;

const targetImportCrlf = targetImport.replace(/\n/g, "\r\n");
const replImportCrlf = replImport.replace(/\n/g, "\r\n");
if (!world.includes(targetImportCrlf)) throw new Error("targetImport not found in world.js");
world = world.replace(targetImportCrlf, replImportCrlf);

// 2. Initialize sprintAction
const targetAction = `    const onePunchAction = mixer.clipAction(directClip(onePunchClipData));
    onePunchAction.setLoop(THREE.LoopOnce, 1);
    onePunchAction.clampWhenFinished = false;
    onePunchAction.setEffectiveWeight(0);
    onePunchAction.setEffectiveTimeScale(1.0);
    onePunchAction.play();
    actions.onePunch = onePunchAction;`;

const replAction = `    const onePunchAction = mixer.clipAction(directClip(onePunchClipData));
    onePunchAction.setLoop(THREE.LoopOnce, 1);
    onePunchAction.clampWhenFinished = false;
    onePunchAction.setEffectiveWeight(0);
    onePunchAction.setEffectiveTimeScale(1.0);
    onePunchAction.play();
    actions.onePunch = onePunchAction;

    const sprintAction = mixer.clipAction(directClip(cascadeurRunData));
    sprintAction.setEffectiveWeight(0);
    sprintAction.play();
    actions.sprint = sprintAction;`;

const targetActionCrlf = targetAction.replace(/\n/g, "\r\n");
const replActionCrlf = replAction.replace(/\n/g, "\r\n");
if (!world.includes(targetActionCrlf)) throw new Error("targetAction not found in world.js");
world = world.replace(targetActionCrlf, replActionCrlf);

// 3. Set sprint weight to 0 during lock-on
const targetLock = `        lockSpeed = THREE.MathUtils.damp(lockSpeed, targetSpeed, 5, dt);
        const runT = lockMag;
        actions.run.setEffectiveWeight(0);`;

const replLock = `        lockSpeed = THREE.MathUtils.damp(lockSpeed, targetSpeed, 5, dt);
        const runT = lockMag;
        actions.run.setEffectiveWeight(0);
        if (actions.sprint) actions.sprint.setEffectiveWeight(0);`;

const targetLockCrlf = targetLock.replace(/\n/g, "\r\n");
const replLockCrlf = replLock.replace(/\n/g, "\r\n");
if (!world.includes(targetLockCrlf)) throw new Error("targetLock not found in world.js");
