const targetBlend = `      } else {
        actions.idle.setEffectiveWeight((1 - state.walk) * (1 - punchWeight));
        actions.run.setEffectiveWeight(state.walk * (1 - punchWeight));
        actions.run.setEffectiveTimeScale(1.2 * state.pace * state.sprintMul);
