import fs from "fs";

let world = fs.readFileSync("world.js", "utf8");

// 1. Add SPRINT_SPEED and SPRINT_ANIM_SCALE after SPEED
const targetSpeed = `  const SPEED = 4.6;`;
const replSpeed = `  const SPEED = 4.6;
  let SPRINT_SPEED = 10.5;
  let SPRINT_ANIM_SCALE = 0.72;`;

const targetSpeedCrlf = targetSpeed.replace(/\n/g, "\r\n");
const replSpeedCrlf = replSpeed.replace(/\n/g, "\r\n");
if (!world.includes(targetSpeedCrlf)) throw new Error("targetSpeed not found in world.js");
world = world.replace(targetSpeedCrlf, replSpeedCrlf);

// 2. Update sprintMul calculation
const targetMul = `    const isSprint = (state.keys.has("shift") || state.keys.has("shiftleft") || state.keys.has("shiftright")) && input.lengthSq() > 0.0001;
    const targetSprint = isSprint ? 1.0 : 0.0;
    state.sprint = THREE.MathUtils.damp(state.sprint, targetSprint, 12, dt);
    state.sprintMul = 1.0 + state.sprint * 0.85;`;

const replMul = `    const isSprint = (state.keys.has("shift") || state.keys.has("shiftleft") || state.keys.has("shiftright")) && input.lengthSq() > 0.0001;
    const targetSprint = isSprint ? 1.0 : 0.0;
    state.sprint = THREE.MathUtils.damp(state.sprint, targetSprint, 10, dt);
    const sprintRatio = SPRINT_SPEED / SPEED;
    state.sprintMul = 1.0 + state.sprint * (sprintRatio - 1.0);`;

const targetMulCrlf = targetMul.replace(/\n/g, "\r\n");
const replMulCrlf = replMul.replace(/\n/g, "\r\n");
if (!world.includes(targetMulCrlf)) throw new Error("targetMul not found in world.js");
world = world.replace(targetMulCrlf, replMulCrlf);

// 3. Update actions.sprint effective timescale and phase
const targetBlend = `        actions.idle.setEffectiveWeight((1 - state.walk) * (1 - punchWeight));
        actions.run.setEffectiveWeight(jogWeight);
        if (actions.sprint) {
          actions.sprint.setEffectiveWeight(sprintWeight);
          actions.sprint.setEffectiveTimeScale(1.15 * state.pace * state.sprintMul);
        }
        actions.run.setEffectiveTimeScale(1.2 * state.pace * state.sprintMul);`;

const replBlend = `        actions.idle.setEffectiveWeight((1 - state.walk) * (1 - punchWeight));
        actions.run.setEffectiveWeight(jogWeight);
        if (actions.sprint) {
          actions.sprint.setEffectiveWeight(sprintWeight);
          actions.sprint.setEffectiveTimeScale(SPRINT_ANIM_SCALE * state.pace);
        }
        actions.run.setEffectiveTimeScale(1.15 * state.pace);`;

const targetBlendCrlf = targetBlend.replace(/\n/g, "\r\n");
const replBlendCrlf = replBlend.replace(/\n/g, "\r\n");
if (!world.includes(targetBlendCrlf)) throw new Error("targetBlend not found in world.js");
world = world.replace(targetBlendCrlf, replBlendCrlf);

const targetPhase = `state.phase += dt * 10 * state.walk * state.pace * state.sprintMul;`;
const replPhase = `state.phase += dt * 10 * state.walk * state.pace * (1.0 + state.sprint * 0.35);`;

const targetPhaseCrlf = targetPhase.replace(/\n/g, "\r\n");
const replPhaseCrlf = replPhase.replace(/\n/g, "\r\n");
if (!world.includes(targetPhaseCrlf)) throw new Error("targetPhase not found in world.js");
world = world.replace(targetPhaseCrlf, replPhaseCrlf);

// 4. Add debug hook for sprint
const targetDebug = `      triggerOnePunch,`;
const replDebug = `      triggerOnePunch,
      sprint: (opts) => {
        if (opts) {
          if (opts.speed != null) SPRINT_SPEED = opts.speed;
          if (opts.animSpeed != null) SPRINT_ANIM_SCALE = opts.animSpeed;
        }
        return { speed: SPRINT_SPEED, animSpeed: SPRINT_ANIM_SCALE };
      },`;

const targetDebugCrlf = targetDebug.replace(/\n/g, "\r\n");
const replDebugCrlf = replDebug.replace(/\n/g, "\r\n");
if (!world.includes(targetDebugCrlf)) throw new Error("targetDebug not found in world.js");
world = world.replace(targetDebugCrlf, replDebugCrlf);

fs.writeFileSync("world.js", world, "utf8");
console.log("Successfully balanced sprint animation and player speed in world.js!");

