import * as THREE from "../../vendor/three/three.module.min.js";

const root = new THREE.Object3D();
const bone = new THREE.Bone();
bone.name = "Hips";
root.add(bone);
const track = new THREE.VectorKeyframeTrack("Hips.position", [0, 0.25, 0.5], [0, 0, 0, 0, 5, 0, 0, 0, 0]);
const clip = new THREE.AnimationClip("run", 0.5, [track]);
const mixer = new THREE.AnimationMixer(root);
const action = mixer.clipAction(clip);
action.play();

let phase = 0;
const FPS = 12;
const cycleSec = 0.5 / 0.72; // ~0.694s
const steps = Math.max(4, Math.round((cycleSec * FPS) / 2) * 2);
console.log("steps per cycle:", steps);

for (let f = 0; f < 20; f++) {
  const dt = 0.01667;
  phase = (phase + dt * (0.72 / 0.5)) % 1.0;
  const steppedPhase = Math.floor(phase * steps) / steps;
  action.time = steppedPhase * 0.5;
  action.setEffectiveTimeScale(0);
  mixer.update(dt);
  console.log(`frame ${f} (t=${(f * dt).toFixed(3)}s): phase=${phase.toFixed(3)}, stepped=${steppedPhase.toFixed(3)}, hips.y=${bone.position.y.toFixed(2)}`);
}

