import fs from "fs";

let world = fs.readFileSync("world.js", "utf8");

// 1. Add SPRINT_ANIME_FPS, sprintAnimPhase, jogAnimPhase after SPRINT_ANIM_SCALE
const targetVars = `  let SPRINT_SPEED = 10.5;
  let SPRINT_ANIM_SCALE = 0.72;`.replace(/\n/g, "\r\n");

const replVars = `  let SPRINT_SPEED = 10.5;
  let SPRINT_ANIM_SCALE = 0.72;
  const fpsParam = devParam.get("animefps") || devParam.get("fps");
  let SPRINT_ANIME_FPS = fpsParam != null ? parseInt(fpsParam, 10) : 12;
  let sprintAnimPhase = 0;
  let jogAnimPhase = 0;`.replace(/\n/g, "\r\n");

if (!world.includes(targetVars)) throw new Error("targetVars not found in world.js");
world = world.replace(targetVars, replVars);

// 2. Update lock-on anime fps stepping
const targetLock = `          const gaitWeight = gait === "run" ? runT : 0;
          group.forEach((move, index) => {
            const weight = THREE.MathUtils.damp(move.action.getEffectiveWeight(), weights[index] * gaitWeight, 8, dt);
            move.action.setEffectiveWeight(weight * (1 - punchWeight));
            move.action.setEffectiveTimeScale(0);
            move.action.time = lockPhase * move.action.getClip().duration;
            posed += weight;
          });`.replace(/\n/g, "\r\n");

const replLock = `          const gaitWeight = gait === "run" ? runT : 0;
          const lockCycleSec = 0.7 / (state.sprintMul || 1);
          const lockSteps = SPRINT_ANIME_FPS > 0
            ? Math.max(4, Math.round((lockCycleSec * SPRINT_ANIME_FPS) / 2) * 2)
            : 0;
          const steppedLockPhase = lockSteps > 0
            ? Math.floor(lockPhase * lockSteps) / lockSteps
            : lockPhase;
          group.forEach((move, index) => {
            const weight = THREE.MathUtils.damp(move.action.getEffectiveWeight(), weights[index] * gaitWeight, 8, dt);
            move.action.setEffectiveWeight(weight * (1 - punchWeight));
            move.action.setEffectiveTimeScale(0);
            move.action.time = steppedLockPhase * move.action.getClip().duration;
            posed += weight;
          });`.replace(/\n/g, "\r\n");

if (!world.includes(targetLock)) throw new Error("targetLock not found in world.js");
world = world.replace(targetLock, replLock);

// 3. Update normal locomotion running & sprinting
const targetBlend = `        actions.idle.setEffectiveWeight((1 - state.walk) * (1 - punchWeight));
        actions.run.setEffectiveWeight(jogWeight);
        if (actions.sprint) {
          actions.sprint.setEffectiveWeight(sprintWeight);
          actions.sprint.setEffectiveTimeScale(SPRINT_ANIM_SCALE * state.pace);
        }
        actions.run.setEffectiveTimeScale(1.15 * state.pace);`.replace(/\n/g, "\r\n");

const replBlend = `        actions.idle.setEffectiveWeight((1 - state.walk) * (1 - punchWeight));
        actions.run.setEffectiveWeight(jogWeight);

        if (moving && state.pace > 0.001) {
          if (actions.sprint) {
            const sprintDur = actions.sprint.getClip().duration;
            sprintAnimPhase = (sprintAnimPhase + dt * (SPRINT_ANIM_SCALE / sprintDur) * state.pace) % 1.0;
          }
          const jogDur = actions.run.getClip().duration;
          jogAnimPhase = (jogAnimPhase + dt * (1.15 / jogDur) * state.pace) % 1.0;
        }

        if (SPRINT_ANIME_FPS > 0) {
          if (actions.sprint) {
            const sprintDur = actions.sprint.getClip().duration;
            const sprintCycleSec = sprintDur / SPRINT_ANIM_SCALE;
            const steps = Math.max(4, Math.round((sprintCycleSec * SPRINT_ANIME_FPS) / 2) * 2);
            const steppedPhase = Math.floor(sprintAnimPhase * steps) / steps;
            actions.sprint.time = steppedPhase * sprintDur;
            actions.sprint.setEffectiveTimeScale(0);
            actions.sprint.setEffectiveWeight(sprintWeight);
          }
          const jogDur = actions.run.getClip().duration;
          const jogCycleSec = jogDur / 1.15;
          const jogSteps = Math.max(4, Math.round((jogCycleSec * SPRINT_ANIME_FPS) / 2) * 2);
          const steppedJogPhase = Math.floor(jogAnimPhase * jogSteps) / jogSteps;
          actions.run.time = steppedJogPhase * jogDur;
          actions.run.setEffectiveTimeScale(0);
        } else {
          if (actions.sprint) {
            const sprintDur = actions.sprint.getClip().duration;
            actions.sprint.time = sprintAnimPhase * sprintDur;
            actions.sprint.setEffectiveTimeScale(0);
            actions.sprint.setEffectiveWeight(sprintWeight);
          }
          const jogDur = actions.run.getClip().duration;
          actions.run.time = jogAnimPhase * jogDur;
          actions.run.setEffectiveTimeScale(0);
        }`.replace(/\n/g, "\r\n");

if (!world.includes(targetBlend)) throw new Error("targetBlend not found in world.js");
world = world.replace(targetBlend, replBlend);

// 4. Update PortfolioWorld.sprint and add animeFps
const targetPw = `    sprint: (opts) => {
      if (opts) {
        if (opts.speed != null) SPRINT_SPEED = opts.speed;
        if (opts.animSpeed != null) SPRINT_ANIM_SCALE = opts.animSpeed;
      }
      return { speed: SPRINT_SPEED, animSpeed: SPRINT_ANIM_SCALE };
    },`.replace(/\n/g, "\r\n");

const replPw = `    sprint: (opts) => {
      if (opts) {
        if (opts.speed != null) SPRINT_SPEED = opts.speed;
        if (opts.animSpeed != null) SPRINT_ANIM_SCALE = opts.animSpeed;
        if (opts.animeFps !== undefined) SPRINT_ANIME_FPS = opts.animeFps;
      }
      return { speed: SPRINT_SPEED, animSpeed: SPRINT_ANIM_SCALE, animeFps: SPRINT_ANIME_FPS };
    },
    animeFps: (fps) => {
      if (fps !== undefined) SPRINT_ANIME_FPS = fps;
      return SPRINT_ANIME_FPS;
    },`.replace(/\n/g, "\r\n");

if (!world.includes(targetPw)) throw new Error("targetPw not found in world.js");
world = world.replace(targetPw, replPw);

// 5. Update PortfolioWorld.debug.sprint and add animeFps
const targetDebug = `      sprint: (opts) => {
        if (opts) {
          if (opts.speed != null) SPRINT_SPEED = opts.speed;
          if (opts.animSpeed != null) SPRINT_ANIM_SCALE = opts.animSpeed;
        }
        return { speed: SPRINT_SPEED, animSpeed: SPRINT_ANIM_SCALE };
      },`.replace(/\n/g, "\r\n");

const replDebug = `      sprint: (opts) => {
        if (opts) {
          if (opts.speed != null) SPRINT_SPEED = opts.speed;
          if (opts.animSpeed != null) SPRINT_ANIM_SCALE = opts.animSpeed;
          if (opts.animeFps !== undefined) SPRINT_ANIME_FPS = opts.animeFps;
        }
        return { speed: SPRINT_SPEED, animSpeed: SPRINT_ANIM_SCALE, animeFps: SPRINT_ANIME_FPS };
      },
      animeFps: (fps) => {
        if (fps !== undefined) SPRINT_ANIME_FPS = fps;
        return SPRINT_ANIME_FPS;
      },`.replace(/\n/g, "\r\n");

if (!world.includes(targetDebug)) throw new Error("targetDebug not found in world.js");
world = world.replace(targetDebug, replDebug);

fs.writeFileSync("world.js", world, "utf8");
console.log("Successfully applied stylistic anime stepped frame rate to running in world.js!");

