      const end = [v[v.length-3].toFixed(2), v[v.length-2].toFixed(2), v[v.length-1].toFixed(2)];
      console.log(`      Start pos: [${start.join(", ")}]`);
      console.log(`      Mid pos:   [${mid.join(", ")}]`);
      console.log(`      End pos:   [${end.join(", ")}]`);
