import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";

const idleData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-idle.json"));
const punchData = JSON.parse(fs.readFileSync("assets/niko/one-punch.json"));

const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) {
      tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
    }
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

const idleClip = directClip(idleData);
const punchClip = directClip(punchData);

const quatMap = (clip) => {
  const map = {};
  for (const track of clip.tracks) {
    if (track.name.endsWith(".quaternion")) map[track.name.slice(0, -11)] = track;
  }
  return map;
};

const matchHemisphere = (clip, refClip, samples = 8, startFrac = 0) => {
  const refMap = quatMap(refClip);
  for (const track of clip.tracks) {
    if (!track.name.endsWith(".quaternion")) continue;
    const name = track.name.slice(0, -11);
    const ref = refMap[name];
    if (!ref) continue;
    let dotSum = 0;
    const count = Math.min(samples, Math.floor(track.values.length / 4));
    for (let i = 0; i < count; i++) {
      const o = i * 4;
      dotSum += track.values[o] * ref.values[o] + track.values[o+1] * ref.values[o+1] + track.values[o+2] * ref.values[o+2] + track.values[o+3] * ref.values[o+3];
    }
    if (dotSum < 0) {
      for (let i = 0; i < track.values.length; i++) track.values[i] = -track.values[i];
    }
  }
};

matchHemisphere(punchClip, idleClip);
console.log("matchHemisphere succeeded with directClip idle!");

