import fs from "fs";

let world = fs.readFileSync("world.js", "utf8");

// 1. Add wasRunning to state
const targetState = `    sprint: 0,
    sprintMul: 1,
    stopping: false,`.replace(/\n/g, "\r\n");

const replState = `    sprint: 0,
    sprintMul: 1,
    wasRunning: false,
    stopping: false,`.replace(/\n/g, "\r\n");

if (!world.includes(targetState)) throw new Error("targetState not found");
world = world.replace(targetState, replState);

// 2. Fix the locomotion loop references to bot.actions and only trigger stopping when stopping from running mode
const targetLoop = `    if (input.lengthSq() > 0.0001) {
      state.path = [];
      state.pending = null;
      robot.position.addScaledVector(input, SPEED * state.sprintMul * dt);
      resolveCollisions(robot.position);
      stepTo(before, robot.position);
      state.yaw = Math.atan2(input.x, input.z);
      state.pace = THREE.MathUtils.damp(state.pace, input.length(), 10, dt);
      moving = true;
      if (state.stopping) {
        state.stopping = false;
        state.stopTimer = 0;
        if (actions.stop) actions.stop.setEffectiveWeight(0);
      }
    } else if (state.path.length) {
