import fs from "fs";
import path from "path";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";

// Polyfill minimal browser DOM for FBXLoader / GLTFLoader
globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {} }),
  createElement: () => ({
    style: {},
    getContext: () => null,
    addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); },
    removeEventListener: () => {},
    set src(v) { setTimeout(() => { if (this.onload) this.onload(); }, 1); }
  })
};
global.HTMLImageElement = function() {};

const idleFbxPath = "c:/Users/Rigel/Desktop/Cascadeur/idle-animation.fbx";
const runFbxPath = "c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx";
const stopFbxPath = "c:/Users/Rigel/Desktop/Cascadeur/running+stopping.fbx";
const bindFbxPath = "c:/Users/Rigel/Desktop/Cascadeur/niko-cascadeur-clean.fbx";

if (!fs.existsSync(idleFbxPath)) { console.error(`Not found: ${idleFbxPath}`); process.exit(1); }
if (!fs.existsSync(runFbxPath)) { console.error(`Not found: ${runFbxPath}`); process.exit(1); }
if (!fs.existsSync(stopFbxPath)) { console.error(`Not found: ${stopFbxPath}`); process.exit(1); }
if (!fs.existsSync(bindFbxPath)) { console.error(`Not found: ${bindFbxPath}`); process.exit(1); }

// 1. Load Niko's in-game model
const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

// 2. Load the bind pose reference from niko-cascadeur-clean.fbx
const fbxLoader = new FBXLoader();
const toArrayBuffer = (buf) => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
const bindGroup = fbxLoader.parse(toArrayBuffer(fs.readFileSync(bindFbxPath)), "");
const bindBones = {};
bindGroup.traverse((node) => {
  if (node.isBone) {
    const clean = stripMixamo(node.name);
    if (!bindBones[clean] || (node.parent && node.parent.name !== node.name)) {
      bindBones[clean] = node;
    }
  }
});

const armAcross = (map) => {
  const left = new THREE.Vector3();
  const right = new THREE.Vector3();
  map.LeftArm.getWorldPosition(left);
  map.RightArm.getWorldPosition(right);
  return left.sub(right).setY(0).normalize();
};

const savedYaw = model.rotation.y;
model.rotation.y = 0;
model.updateMatrixWorld(true);
bindGroup.updateMatrixWorld(true);

const align = new THREE.Quaternion().setFromUnitVectors(armAcross(bindBones), armAcross(bones));
const alignInv = align.clone().invert();
const worldOf = (bone) => bone.getWorldQuaternion(new THREE.Quaternion());

const srcRest = {};
const tgtRest = {};
const names = Object.keys(bones).filter((name) => bindBones[name]);
console.log(`Matched deform bones in bind pose: ${names.length} of ${Object.keys(bones).length}`);

for (const name of names) {
  srcRest[name] = worldOf(bindBones[name]);
  tgtRest[name] = worldOf(bones[name]);
}

const srcHipRest = new THREE.Vector3();
bindBones.Hips.getWorldPosition(srcHipRest);
const tgtHipRest = bones.Hips.position.clone();
const hipScale = tgtHipRest.y / (Math.abs(srcHipRest.y) > 1e-4 ? srcHipRest.y : 1);
model.rotation.y = savedYaw;

console.log(`srcHipRest: [${srcHipRest.toArray().map(v=>v.toFixed(3))}], tgtHipRest: [${tgtHipRest.toArray().map(v=>v.toFixed(3))}], hipScale: ${hipScale.toFixed(4)}`);

// Retarget function for any FBX clip with a frame range [startFrame, endFrame]
function retargetClipRange(clipName, fbxGroup, startFrame, endFrame, fps, lockOptions = {}) {
  const srcClip = fbxGroup.animations[0];
  const animBones = {};
  fbxGroup.traverse((node) => {
    if (node.isBone) {
      const clean = stripMixamo(node.name);
      if (!animBones[clean] || (node.parent && node.parent.name !== node.name)) {
        animBones[clean] = node;
      }
    }
  });

  const matchedNames = names.filter(n => animBones[n]);
  const srcMixer = new THREE.AnimationMixer(fbxGroup);
  srcMixer.clipAction(srcClip).play();

  const numFrames = endFrame - startFrame + 1;
  const duration = (numFrames - 1) / fps;
  const times = new Float32Array(numFrames);
  const quats = Object.fromEntries(matchedNames.map((name) => [name, new Float32Array(numFrames * 4)]));
  const hips = new Float32Array(numFrames * 3);
  const scales = Object.fromEntries(matchedNames.map((name) => [name, new Float32Array(numFrames * 3)]));
  const currSrcHip = new THREE.Vector3();

  let firstHipX = 0;
  let firstHipZ = 0;

  for (let idx = 0; idx < numFrames; idx++) {
    const frameNumber = startFrame + idx;
    const srcTime = frameNumber / fps;
    const clipTime = idx / fps;
    times[idx] = clipTime;

    srcMixer.setTime(srcTime);
    fbxGroup.updateMatrixWorld(true);

    const posed = {};
    for (const name of matchedNames) {
      const delta = worldOf(animBones[name]).multiply(srcRest[name].clone().invert());
      posed[name] = align.clone().multiply(delta).multiply(alignInv).multiply(tgtRest[name].clone()).normalize();
    }

    for (const name of matchedNames) {
      const parent = bones[name].parent;
      const local = parent && posed[parent.name]
        ? posed[parent.name].clone().invert().multiply(posed[name])
        : posed[name].clone();
      if (idx > 0) {
        const prev = (idx - 1) * 4;
        const values = quats[name];
        const dot = values[prev] * local.x + values[prev + 1] * local.y + values[prev + 2] * local.z + values[prev + 3] * local.w;
        if (dot < 0) local.set(-local.x, -local.y, -local.z, -local.w);
      }
      quats[name].set([local.x, local.y, local.z, local.w], idx * 4);

      const s = animBones[name].scale;
      scales[name][idx * 3] = s.x;
      scales[name][idx * 3 + 1] = s.y;
      scales[name][idx * 3 + 2] = s.z;
    }

    // Hips Position - 100% In-Place:
    animBones.Hips.getWorldPosition(currSrcHip);
    if (idx === 0) {
      firstHipX = currSrcHip.x;
      firstHipZ = currSrcHip.z;
    }

    // X: lateral sway or lock to 0
    if (lockOptions.lockX) {
      hips[idx * 3] = tgtHipRest.x;
    } else {
      hips[idx * 3] = tgtHipRest.x + (currSrcHip.x - firstHipX) * hipScale;
    }

    // Y: Vertical breathing/bounce
    hips[idx * 3 + 1] = tgtHipRest.y + (currSrcHip.y - srcHipRest.y) * hipScale;

    // Z: Forward drift locked strictly to 0
    if (lockOptions.lockZ) {
      hips[idx * 3 + 2] = tgtHipRest.z;
    } else {
      hips[idx * 3 + 2] = tgtHipRest.z + (currSrcHip.z - firstHipZ) * hipScale;
    }
  }

  const tracks = matchedNames.map((name) => new THREE.QuaternionKeyframeTrack(`${name}.quaternion`, times, quats[name]));
  tracks.push(new THREE.VectorKeyframeTrack("Hips.position", times, hips));

  const scaleBones = [];
  for (const name of matchedNames) {
    const arr = scales[name];
    let hasScale = false;
    for (let i = 0; i < arr.length; i++) {
      if (Math.abs(arr[i] - 1.0) > 0.005) {
        hasScale = true;
        break;
      }
    }
    if (hasScale) {
      tracks.push(new THREE.VectorKeyframeTrack(`${name}.scale`, times, arr));
      scaleBones.push(name);
    }
  }

  console.log(`[${clipName}] Duration: ${duration.toFixed(4)}s (${numFrames} frames at ${fps} fps). Scale tracks: ${scaleBones.length}`);

  const retargetedClip = new THREE.AnimationClip(clipName, duration, tracks);
  const boneEntries = [];
  for (const track of retargetedClip.tracks) {
    const [boneName, prop] = track.name.split(".");
    let b = boneEntries.find((item) => item.name === boneName);
    if (!b) {
      b = { name: boneName };
      boneEntries.push(b);
    }
    if (prop === "quaternion") {
      b.times = Array.from(track.times).map((n) => +n.toFixed(4));
      b.q = Array.from(track.values).map((n) => +n.toFixed(4));
    } else if (prop === "position") {
      b.posTimes = Array.from(track.times).map((n) => +n.toFixed(4));
      b.pos = Array.from(track.values).map((n) => +n.toFixed(4));
    } else if (prop === "scale") {
      b.scaleTimes = Array.from(track.times).map((n) => +n.toFixed(4));
      b.scale = Array.from(track.values).map((n) => +n.toFixed(4));
    }
  }

  return {
    name: clipName,
    duration: +duration.toFixed(4),
    bones: boneEntries,
  };
}

// 3. Export New Idle (40 frames, 30 fps) - 100% In-Place (X=0, Z=0 locked)
console.log("\n--- Exporting cascadeur-idle.json ---");
const idleGroup = fbxLoader.parse(toArrayBuffer(fs.readFileSync(idleFbxPath)), "");
const idleData = retargetClipRange("idle", idleGroup, 0, 39, 30, { lockX: true, lockZ: true });
fs.writeFileSync("assets/niko/cascadeur-idle.json", JSON.stringify(idleData), "utf8");
console.log(`Wrote assets/niko/cascadeur-idle.json (${(fs.statSync("assets/niko/cascadeur-idle.json").size / 1024).toFixed(1)} KB)`);

// 4. Export Running Animation (frames 0 to 29, 60 fps) - 100% In-Place (Z=0 locked)
console.log("\n--- Exporting cascadeur-run.json ---");
const runGroup = fbxLoader.parse(toArrayBuffer(fs.readFileSync(runFbxPath)), "");
const runData = retargetClipRange("run", runGroup, 0, 29, 60, { lockX: false, lockZ: true });
fs.writeFileSync("assets/niko/cascadeur-run.json", JSON.stringify(runData), "utf8");
console.log(`Wrote assets/niko/cascadeur-run.json (${(fs.statSync("assets/niko/cascadeur-run.json").size / 1024).toFixed(1)} KB)`);

// 5. Export Sudden Stop Animation from running+stopping.fbx (30 frames, 60 fps) - 100% In-Place (Z=0 locked)
console.log("\n--- Exporting cascadeur-stop.json from running+stopping.fbx ---");
const stopGroup = fbxLoader.parse(toArrayBuffer(fs.readFileSync(stopFbxPath)), "");
const stopData = retargetClipRange("stop", stopGroup, 0, 29, 60, { lockX: false, lockZ: true });
fs.writeFileSync("assets/niko/cascadeur-stop.json", JSON.stringify(stopData), "utf8");
console.log(`Wrote assets/niko/cascadeur-stop.json (${(fs.statSync("assets/niko/cascadeur-stop.json").size / 1024).toFixed(1)} KB)`);

console.log("\nAll animations successfully retargeted and exported 100% in place!");

