let keys = new Set();
let moving = false;
let sprint = 0;
let walk = 0;
let wasRunning = false;
let wasMoving = false;
let stopping = false;
let stopTimer = 0;
let pace = 0;
const dt = 1 / 60;
const SPEED = 4.6;
const SPRINT_SPEED = 10.5;

function step(label) {
  const isSprint = (keys.has("shift") || keys.has("shiftleft") || keys.has("shiftright")) && keys.has("w");
  const targetSprint = isSprint ? 1.0 : 0.0;
  // Damp: 10
  sprint += (targetSprint - sprint) * (1 - Math.exp(-10 * dt));
  const sprintRatio = SPRINT_SPEED / SPEED;
  const sprintMul = 1.0 + sprint * (sprintRatio - 1.0);

  const hasInput = keys.has("w");
  moving = hasInput;
  if (hasInput) {
    pace += (1 - pace) * (1 - Math.exp(-10 * dt));
    if (isSprint && sprint > 0.4) {
      wasRunning = true;
    }
    if (stopping) {
      stopping = false;
      stopTimer = 0;
    }
  } else {
    if (wasMoving && wasRunning && !stopping) {
      stopping = true;
      stopTimer = 0;
    }
    wasRunning = false;
    pace += (0 - pace) * (1 - Math.exp(-10 * dt));
  }
  wasMoving = moving;

  if (stopping) {
    stopTimer += dt;
    if (stopTimer >= 0.4833) {
      stopping = false;
      stopTimer = 0;
