import fs from "fs";
import * as THREE from "three";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = { createElementNS: () => ({ style: {} }), createElement: () => ({ style: {}, getContext: () => null }) };
global.HTMLImageElement = function() {};

const loader = new FBXLoader();
const toAB = buf => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);

const fbx = loader.parse(toAB(fs.readFileSync('c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx')), '');
const clip = fbx.animations[0];
const mixer = new THREE.AnimationMixer(fbx);
mixer.clipAction(clip).play();

const bones = [];
fbx.traverse(n => { if (n.isBone) bones.push(n); });

// Set to frame 0
mixer.setTime(0);
fbx.updateMatrixWorld(true);
const f0Quats = bones.map(b => b.quaternion.clone());

console.log(`Comparing each frame against frame 0 in ${fbx.animations[0].name} (total frames=${Math.round(clip.duration * 60)}):`);

let bestFrame = -1;
let bestDiff = 999;

for (let f = 1; f <= Math.round(clip.duration * 60); f++) {
  mixer.setTime(f / 60);
  fbx.updateMatrixWorld(true);
  let totalDiff = 0;
  bones.forEach((b, i) => {
    totalDiff += b.quaternion.angleTo(f0Quats[i]);
  });
  if (totalDiff < bestDiff) {
    bestDiff = totalDiff;
    bestFrame = f;
  }
  if (f % 5 === 0 || f === Math.round(clip.duration * 60)) {
    console.log(`frame ${f}: totalAngleDiff = ${totalDiff.toFixed(2)} rad`);
  }
}

console.log(`\nBest match to frame 0 is frame ${bestFrame} with totalDiff = ${bestDiff.toFixed(2)} rad`);

import fs from "fs";
