const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const cascadeurRunData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-run.json", "utf8"));
const cascadeurIdleData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-idle.json", "utf8"));
const cascadeurStopData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-stop.json", "utf8"));

const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    if (!bones[bone.name]) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
    if (bone.scale) tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.scale`, new Float32Array(bone.scaleTimes || bone.times), new Float32Array(bone.scale)));
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

const mixer = new THREE.AnimationMixer(model);
const idleAction = mixer.clipAction(directClip(cascadeurIdleData));
idleAction.play();
idleAction.setEffectiveWeight(1);

const sprintAction = mixer.clipAction(directClip(cascadeurRunData));
sprintAction.play();
sprintAction.setEffectiveWeight(0);

const stopAction = mixer.clipAction(directClip(cascadeurStopData));
stopAction.play();
stopAction.setEffectiveWeight(0);

console.log("=== IDLE POSE (t=0) ===");
mixer.update(0.016);
console.log("Hips:", bones.Hips.quaternion.toArray().map(v=>+v.toFixed(3)));
console.log("LeftArm:", bones.LeftArm.quaternion.toArray().map(v=>+v.toFixed(3)));
console.log("LeftUpLeg:", bones.LeftUpLeg.quaternion.toArray().map(v=>+v.toFixed(3)));

console.log("\n=== SPRINT POSE (t=0.1s, weight=1) ===");
idleAction.setEffectiveWeight(0);
sprintAction.setEffectiveWeight(1);
sprintAction.time = 0.1;
sprintAction.setEffectiveTimeScale(0);
mixer.update(0.016);
console.log("Hips:", bones.Hips.quaternion.toArray().map(v=>+v.toFixed(3)));
console.log("LeftArm:", bones.LeftArm.quaternion.toArray().map(v=>+v.toFixed(3)));
console.log("LeftUpLeg:", bones.LeftUpLeg.quaternion.toArray().map(v=>+v.toFixed(3)));

console.log("\n=== SPRINT POSE (t=0.3s, weight=1) ===");
sprintAction.time = 0.3;
mixer.update(0.016);
console.log("Hips:", bones.Hips.quaternion.toArray().map(v=>+v.toFixed(3)));
console.log("LeftArm:", bones.LeftArm.quaternion.toArray().map(v=>+v.toFixed(3)));
console.log("LeftUpLeg:", bones.LeftUpLeg.quaternion.toArray().map(v=>+v.toFixed(3)));

