console.log("stopFbx duration:", stopFbx.animations[0].duration, "frames:", Math.round(stopFbx.animations[0].duration * 60));

const inspectLegs = (fbx, label) => {
  const mixer = new THREE.AnimationMixer(fbx);
  mixer.clipAction(fbx.animations[0]).play();
  let lFoot, rFoot, hips;
  fbx.traverse(n => {
    if (n.name.includes("LeftFoot")) lFoot = n;
    if (n.name.includes("RightFoot")) rFoot = n;
    if (n.name.includes("Hips")) hips = n;
  });
  console.log(`\n=== ${label} ===`);
  const frames = Math.round(fbx.animations[0].duration * 60);
  for (let f = 0; f <= frames; f++) {
    mixer.setTime(f / 60);
    fbx.updateMatrixWorld(true);
    const lp = new THREE.Vector3(); lFoot.getWorldPosition(lp);
    const rp = new THREE.Vector3(); rFoot.getWorldPosition(rp);
    const hp = new THREE.Vector3(); hips.getWorldPosition(hp);
    // Print foot contact and stride
    const lContact = lp.y < 11 ? "GROUND" : "AIR   ";
    const rContact = rp.y < 11 ? "GROUND" : "AIR   ";
    console.log(`F${f.toString().padStart(2, '0')}: Hips=[${hp.x.toFixed(1)}, ${hp.y.toFixed(1)}, ${hp.z.toFixed(1)}] | LFoot: ${lContact} Z=${lp.z.toFixed(1)} | RFoot: ${rContact} Z=${rp.z.toFixed(1)}`);
  }
};

inspectLegs(runFbx, "in place running.fbx");
inspectLegs(stopFbx, "running+stopping.fbx");

