const loader = new FBXLoader();
const toAB = buf => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);

const runFbx = loader.parse(toAB(fs.readFileSync('c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx')), '');
const clip = runFbx.animations[0];
const mixer = new THREE.AnimationMixer(runFbx);
mixer.clipAction(clip).play();

const bones = {};
runFbx.traverse(n => { if (n.isBone) bones[n.name.replace(/^mixamorig\d*:?/, "")] = n; });

// Compare joint angles relative to parent (local rotations)
const getLocalQuats = (f) => {
  mixer.setTime(f / 60);
  runFbx.updateMatrixWorld(true);
  const map = {};
  for (const name in bones) {
    map[name] = bones[name].quaternion.clone();
  }
  return map;
};

// Check candidate start frames (e.g. F0 to F10) against candidate end frames (F18 to F30)
console.log("Searching for closest repeating run cycle frames in in place running.fbx:");
let bestPair = null;
let minError = 999;

const testBones = ["Hips", "LeftUpLeg", "LeftLeg", "LeftFoot", "RightUpLeg", "RightLeg", "RightFoot", "Spine", "Spine1", "Spine2", "LeftArm", "RightArm"];

for (let start = 0; start <= 6; start++) {
  const qStart = getLocalQuats(start);
  for (let end = start + 16; end <= Math.min(start + 28, 59); end++) {
    const qEnd = getLocalQuats(end);
    let diff = 0;
    for (const b of testBones) {
      if (qStart[b] && qEnd[b]) {
        diff += qStart[b].angleTo(qEnd[b]);
      }
    }
    if (diff < minError) {
      minError = diff;
      bestPair = { start, end, diff };
    }
  }
}

console.log(`Best repeating cycle: Frame ${bestPair.start} -> Frame ${bestPair.end} (duration = ${(bestPair.end - bestPair.start) / 60}s, ${bestPair.end - bestPair.start} frames), total error = ${bestPair.diff.toFixed(3)} rad`);

// Also test each candidate around the best pair
console.log(`\nDetailed comparisons around start=${bestPair.start}:`);
const q0 = getLocalQuats(bestPair.start);
for (let end = bestPair.start + 18; end <= bestPair.start + 26; end++) {
  const qEnd = getLocalQuats(end);
  let diff = 0;
  for (const b of testBones) {
    if (q0[b] && qEnd[b]) diff += q0[b].angleTo(qEnd[b]);
  }
  console.log(`  Start ${bestPair.start} -> End ${end} (${end - bestPair.start} frames): error = ${diff.toFixed(3)} rad`);
}

