const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const cascadeurRunData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-run.json", "utf8"));
const cascadeurIdleData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-idle.json", "utf8"));

const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    if (!bones[bone.name]) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

const idleClip = directClip(cascadeurIdleData);
const sprintClip = directClip(cascadeurRunData);

// Check hemisphere match between sprint and idle:
let flippedCount = 0;
for (const track of sprintClip.tracks) {
  if (!track.name.endsWith(".quaternion")) continue;
  const idleTrack = idleClip.tracks.find(t => t.name === track.name);
  if (!idleTrack) continue;
  const dot = track.values[0] * idleTrack.values[0] + track.values[1] * idleTrack.values[1] + track.values[2] * idleTrack.values[2] + track.values[3] * idleTrack.values[3];
  if (dot < 0) {
    flippedCount++;
    console.log(`Opposite hemisphere detected on ${track.name}: dot = ${dot.toFixed(3)}`);
  }
}
console.log(`Total opposite hemisphere tracks in sprintClip: ${flippedCount} of ${sprintClip.tracks.length}`);

