import fs from "fs";
import * as THREE from "three";
import { GLTFLoader } from "../../vendor/three/addons/loaders/GLTFLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => {
    const el = { style: {}, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {} };
    setTimeout(() => { if (el.onload) el.onload(); }, 1);
    return el;
  },
  createElement: () => {
    const el = { style: {}, getContext: () => null, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {}, set src(v) { setTimeout(() => { if (this.onload) this.onload(); }, 1); } };
    return el;
  }
};
global.HTMLImageElement = function() {};

const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const cascadeurRunData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-run.json", "utf8"));
const cascadeurIdleData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-idle.json", "utf8"));

const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    if (!bones[bone.name]) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

const mixer = new THREE.AnimationMixer(model);
const idleAction = mixer.clipAction(directClip(cascadeurIdleData));
idleAction.play();
idleAction.setEffectiveWeight(0);

const sprintAction = mixer.clipAction(directClip(cascadeurRunData));
sprintAction.play();
sprintAction.setEffectiveWeight(1);

let sprintAnimPhase = 0;
const SPRINT_ANIM_SCALE = 0.72;
const SPRINT_ANIME_FPS = 12;
const sprintDur = sprintAction.getClip().duration;
const sprintCycleSec = sprintDur / SPRINT_ANIM_SCALE;
const steps = Math.max(4, Math.round((sprintCycleSec * SPRINT_ANIME_FPS) / 2) * 2);
const dt = 1 / 60;

console.log(`sprintDur: ${sprintDur}, steps: ${steps}`);

for (let frame = 0; frame < 30; frame++) {
  sprintAnimPhase = (sprintAnimPhase + dt * (SPRINT_ANIM_SCALE / sprintDur) * 1.0) % 1.0;
  const steppedPhase = Math.floor(sprintAnimPhase * steps) / steps;
  sprintAction.time = steppedPhase * sprintDur;
  sprintAction.setEffectiveTimeScale(0);
  sprintAction.setEffectiveWeight(1);

  mixer.update(dt);
  model.updateMatrixWorld(true);

  const lp = new THREE.Vector3(); bones.LeftFoot.getWorldPosition(lp);
  const rp = new THREE.Vector3(); bones.RightFoot.getWorldPosition(rp);
  if (frame % 5 === 0) {
    console.log(`Frame ${frame}: phase=${sprintAnimPhase.toFixed(3)}, stepped=${steppedPhase.toFixed(3)}, time=${sprintAction.time.toFixed(3)} | LFoot=[${lp.x.toFixed(2)}, ${lp.y.toFixed(2)}, ${lp.z.toFixed(2)}] | RFoot=[${rp.x.toFixed(2)}, ${rp.y.toFixed(2)}, ${rp.z.toFixed(2)}]`);
  }
}

import fs from "fs";
import * as THREE from "three";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = { createElementNS: () => ({ style: {} }), createElement: () => ({ style: {}, getContext: () => null }) };
global.HTMLImageElement = function() {};

const loader = new FBXLoader();
const toAB = buf => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);

const runFbx = loader.parse(toAB(fs.readFileSync('c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx')), '');
const clip = runFbx.animations[0];
const mixer = new THREE.AnimationMixer(runFbx);
mixer.clipAction(clip).play();

let lFoot, rFoot;
runFbx.traverse(n => {
  if (n.name.includes("LeftFoot")) lFoot = n;
  if (n.name.includes("RightFoot")) rFoot = n;
});

console.log("Stride analysis (LFoot.z - RFoot.z relative to character):");
for (let f = 0; f <= Math.round(clip.duration * 60); f++) {
  mixer.setTime(f / 60);
  runFbx.updateMatrixWorld(true);
  const lp = new THREE.Vector3(); lFoot.getWorldPosition(lp);
  const rp = new THREE.Vector3(); rFoot.getWorldPosition(rp);
  const sep = lp.z - rp.z;
  console.log(`F${f.toString().padStart(2, '0')}: sepZ = ${sep.toFixed(1).padStart(6)} (L.y=${lp.y.toFixed(1)}, R.y=${rp.y.toFixed(1)})`);
}

