import fs from "fs";
import * as THREE from "three";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = { createElementNS: () => ({ style: {} }), createElement: () => ({ style: {}, getContext: () => null }) };
global.HTMLImageElement = function() {};

const loader = new FBXLoader();
const toAB = buf => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);

const runFbx = loader.parse(toAB(fs.readFileSync('c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx')), '');
const clip = runFbx.animations[0];
const mixer = new THREE.AnimationMixer(runFbx);
mixer.clipAction(clip).play();

const bones = {};
runFbx.traverse(n => { if (n.isBone) bones[n.name.replace(/^mixamorig\d*:?/, "")] = n; });
const boneNames = Object.keys(bones);

const numFrames = 60;
const frames = [];
for (let f = 0; f < numFrames; f++) {
  mixer.setTime(f / 60);
  runFbx.updateMatrixWorld(true);
  const qMap = {};
  for (const name of boneNames) {
    qMap[name] = bones[name].quaternion.clone();
  }
  frames.push(qMap);
}

let bestPair = null;
let minMaxDiff = 999;

for (let i = 0; i < numFrames - 10; i++) {
  for (let j = i + 10; j < numFrames; j++) {
    let maxDiff = 0;
    for (const name of ["Hips", "LeftUpLeg", "RightUpLeg", "LeftArm", "RightArm", "LeftLeg", "RightLeg"]) {
      const diff = frames[i][name].angleTo(frames[j][name]);
      if (diff > maxDiff) maxDiff = diff;
    }
    if (maxDiff < minMaxDiff) {
      minMaxDiff = maxDiff;
      bestPair = { i, j, diffDeg: THREE.MathUtils.radToDeg(maxDiff) };
    }
  }
}

console.log("Best looping pair in 'in place running.fbx':", bestPair);

