function alignHemispheres(targetClipData, refClipData) {
  const refMap = Object.fromEntries(
    refClipData.bones.filter((b) => b.q).map((b) => [b.name, new THREE.Quaternion(b.q[0], b.q[1], b.q[2], b.q[3])])
  );
  let flipped = 0;
  for (const b of targetClipData.bones) {
    if (!b.q || !refMap[b.name]) continue;
    const refQ = refMap[b.name];
    let neg = 0, pos = 0;
    const nKeys = b.q.length / 4;
    for (let k = 0; k < nKeys; k++) {
      const dot = b.q[k * 4] * refQ.x + b.q[k * 4 + 1] * refQ.y + b.q[k * 4 + 2] * refQ.z + b.q[k * 4 + 3] * refQ.w;
      if (dot < 0) neg++;
      else pos++;
    }
    if (neg > pos) {
      flipped++;
      for (let i = 0; i < b.q.length; i++) b.q[i] = -b.q[i];
    }
  }
  console.log(`[${targetClipData.name}] Aligned hemisphere to idle: ${flipped} bone tracks flipped.`);
}

