import fs from "fs";
import * as THREE from "three";

const idle = JSON.parse(fs.readFileSync("assets/niko/cascadeur-idle.json"));
const run = JSON.parse(fs.readFileSync("assets/niko/cascadeur-run.json"));
const stop = JSON.parse(fs.readFileSync("assets/niko/cascadeur-stop.json"));

function checkSeam(name, data) {
  let maxAng = 0;
  let worst = "";
  for (const b of data.bones) {
    if (!b.q) continue;
    const q0 = new THREE.Quaternion(b.q[0], b.q[1], b.q[2], b.q[3]);
    const last = b.q.length - 4;
    const qEnd = new THREE.Quaternion(b.q[last], b.q[last+1], b.q[last+2], b.q[last+3]);
    const ang = THREE.MathUtils.radToDeg(q0.angleTo(qEnd));
    if (ang > maxAng) {
      maxAng = ang;
      worst = b.name;
    }
  }
  console.log(`[${name}] Loop seam: worst bone is ${worst} with ${maxAng.toFixed(3)}°`);
}

checkSeam("idle", idle);
checkSeam("run", run);

const idleMap = Object.fromEntries(idle.bones.filter(b=>b.q).map(b => [b.name, new THREE.Quaternion(b.q[0], b.q[1], b.q[2], b.q[3])]));

function checkHemisphere(name, data) {
  let negCount = 0;
  for (const b of data.bones) {
    if (!b.q || !idleMap[b.name]) continue;
    const q0 = new THREE.Quaternion(b.q[0], b.q[1], b.q[2], b.q[3]);
    const dot = q0.dot(idleMap[b.name]);
    if (dot < 0) negCount++;
  }
  console.log(`[${name}] Opposite hemisphere bones vs idle: ${negCount}`);
}

checkHemisphere("run", run);
checkHemisphere("stop", stop);

