import fs from "fs";

let s = fs.readFileSync("world.js", "utf8");

const targetDown = `    } else if (key === "shift" || key === "shiftleft" || key === "shiftright") {\r\n      state.keys.add("shift");`;
const replDown = `    } else if (key === "shift" || key === "shiftleft" || key === "shiftright" || event.shiftKey) {\r\n      state.keys.add("shift");`;

const targetUp = `  window.addEventListener("keyup", (event) => {\r\n    state.keys.delete(event.key.toLowerCase());\r\n    if (event.key === "Shift" || event.key.toLowerCase() === "shift") {\r\n      state.keys.delete("shift");\r\n    }\r\n  });`;
const replUp = `  window.addEventListener("keyup", (event) => {\r\n    state.keys.delete(event.key.toLowerCase());\r\n    if (event.key === "Shift" || event.key.toLowerCase() === "shift" || !event.shiftKey) {\r\n      state.keys.delete("shift");\r\n      state.keys.delete("shiftleft");\r\n      state.keys.delete("shiftright");\r\n    }\r\n  });`;

if (!s.includes(targetDown)) throw new Error("targetDown not found");
if (!s.includes(targetUp)) throw new Error("targetUp not found");

s = s.replace(targetDown, replDown).replace(targetUp, replUp);
fs.writeFileSync("world.js", s, "utf8");
console.log("Successfully updated Shift event listeners in world.js");

