import fs from "fs";

const bundle = fs.readFileSync("world.bundle.js", "utf8");

// Check for dangerous reference errors or missing declarations
console.log("Bundle size:", (bundle.length / 1024 / 1024).toFixed(2), "MB");

// Check if actions.stop or bot.actions?.stop has any direct unbound `actions.` calls outside `if (bot.mixer)`
const lines = bundle.split("\n");
let count = 0;
lines.forEach((l, idx) => {
  if (l.includes("actions.stop") || l.includes("actions.sprint") || l.includes("actions.idle")) {
    count++;
  }
});
console.log("Action references in bundle:", count);

// Test syntax
try {
  new Function(bundle);
  console.log("Bundle syntax parsed successfully!");
} catch (e) {
  // It might fail on DOM / window which is expected in node, but check syntax
  if (e.name === "SyntaxError") {
    console.error("SYNTAX ERROR in bundle:", e);
    process.exit(1);
  } else {
    console.log("Syntax is valid (ReferenceError in node global is normal for browser code):", e.message);
  }
}

