global.HTMLImageElement = function() {};

const nikoBuf = fs.readFileSync("assets/niko/niko-final-clean.glb");
const gltfLoader = new GLTFLoader();
const gltf = await gltfLoader.parseAsync(nikoBuf.buffer.slice(nikoBuf.byteOffset, nikoBuf.byteOffset + nikoBuf.byteLength), "");
const model = gltf.scene;

const stripMixamo = (name) => name.replace(/^mixamorig\d*:?/, "");
model.traverse((node) => {
  if (node.isBone) node.name = stripMixamo(node.name);
});
const bones = {};
model.traverse((node) => {
  if (node.isBone) bones[node.name] = node;
});

const idleData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-idle.json"));
const runData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-run.json"));
const stopData = JSON.parse(fs.readFileSync("assets/niko/cascadeur-stop.json"));

const directClip = (entry) => {
  const tracks = [];
  for (const bone of entry.bones) {
    if (!bones[bone.name]) continue;
    tracks.push(new THREE.QuaternionKeyframeTrack(`${bone.name}.quaternion`, new Float32Array(bone.times), new Float32Array(bone.q)));
    if (bone.pos) tracks.push(new THREE.VectorKeyframeTrack(`${bone.name}.position`, new Float32Array(bone.posTimes), new Float32Array(bone.pos)));
  }
  return new THREE.AnimationClip(entry.name, entry.duration, tracks);
};

const mixer = new THREE.AnimationMixer(model);
const actions = {
  idle: mixer.clipAction(directClip(idleData)),
  sprint: mixer.clipAction(directClip(runData)),
  stop: mixer.clipAction(directClip(stopData)),
};

actions.idle.play();
actions.sprint.play();
actions.stop.play();
actions.stop.setLoop(THREE.LoopOnce, 1);
actions.stop.clampWhenFinished = true;

const SPEED = 4.6;
const SPRINT_SPEED = 10.5;
const SPRINT_ANIM_SCALE = 0.72;
const SPRINT_ANIME_FPS = 12;

const state = {
  keys: new Set(),
  walk: 0,
  pace: 0,
  sprint: 0,
  sprintMul: 1,
  wasMoving: false,
  wasRunning: false,
  stopping: false,
  stopTimer: 0,
  stopSpeed: 0,
  stopDir: new THREE.Vector3(),
  pos: new THREE.Vector3(),
  yaw: 0,
};

let sprintAnimPhase = 0;
const dt = 1 / 60;

function tick(inputX, inputZ, isHoldingShift) {
  const input = new THREE.Vector3(inputX, 0, inputZ);
  if (input.lengthSq() > 1) input.normalize();

  const isSprint = isHoldingShift && input.lengthSq() > 0.0001;
  const targetSprint = isSprint ? 1.0 : 0.0;
  state.sprint = THREE.MathUtils.damp(state.sprint, targetSprint, 10, dt);
  const sprintRatio = SPRINT_SPEED / SPEED;
  state.sprintMul = 1.0 + state.sprint * (sprintRatio - 1.0);

  let moving = false;
  if (input.lengthSq() > 0.0001) {
    state.pos.addScaledVector(input, SPEED * state.sprintMul * dt);
    state.yaw = Math.atan2(input.x, input.z);
    state.pace = THREE.MathUtils.damp(state.pace, input.length(), 10, dt);
    moving = true;
    if (isSprint && state.sprint > 0.4) {
      state.wasRunning = true;
    }
    if (state.stopping) {
      state.stopping = false;
      state.stopTimer = 0;
      actions.stop.setEffectiveWeight(0);
    }
  } else {
    if (state.wasMoving && state.wasRunning && !state.stopping) {
      state.stopping = true;
      state.stopTimer = 0;
      state.stopSpeed = SPEED * state.sprintMul;
      state.stopDir.set(Math.sin(state.yaw), 0, Math.cos(state.yaw));
      actions.stop.reset();
      actions.stop.play();
    }
    state.wasRunning = false;
    state.pace = THREE.MathUtils.damp(state.pace, 0, 10, dt);
  }
  state.wasMoving = moving;

  const stopDur = actions.stop.getClip().duration;
  if (state.stopping) {
    state.stopTimer += dt;
    if (state.stopTimer < 0.22) {
      const decel = Math.pow(Math.max(0, 1 - state.stopTimer / 0.22), 2);
      const skidStep = state.stopSpeed * decel * dt * 0.35;
      state.pos.addScaledVector(state.stopDir, skidStep);
    }
    if (state.stopTimer >= stopDur) {
      state.stopping = false;
      state.stopTimer = 0;
    }
  }

  state.walk = THREE.MathUtils.damp(state.walk, moving ? 1 : 0, 10, dt);

  const sprintT = THREE.MathUtils.clamp(state.sprint, 0, 1);
  const sprintWeight = sprintT * state.walk;

  let stopWeight = 0;
  if (state.stopping) {
    const t = state.stopTimer / stopDur;
    stopWeight = t < 0.7 ? 1.0 : Math.max(0, 1.0 - (t - 0.7) / 0.3);
  }

  const idleWeight = Math.max(0, 1 - Math.max(state.walk, stopWeight));
  actions.idle.setEffectiveWeight(idleWeight);

  if (moving && state.pace > 0.001) {
    const sprintDur = actions.sprint.getClip().duration;
    sprintAnimPhase = (sprintAnimPhase + dt * (SPRINT_ANIM_SCALE / sprintDur) * state.pace) % 1.0;
  }

  actions.stop.setEffectiveWeight(stopWeight);
  if (state.stopping) {
    const stopSteps = Math.max(4, Math.round((stopDur * SPRINT_ANIME_FPS) / 2) * 2);
    const steppedStopPhase = Math.min(1.0, Math.floor((state.stopTimer / stopDur) * stopSteps) / stopSteps);
    actions.stop.time = steppedStopPhase * stopDur;
    actions.stop.setEffectiveTimeScale(0);
  }

  if (actions.sprint) {
    const sprintDur = actions.sprint.getClip().duration;
    const sprintCycleSec = sprintDur / SPRINT_ANIM_SCALE;
    const steps = Math.max(4, Math.round((sprintCycleSec * SPRINT_ANIME_FPS) / 2) * 2);
    const steppedPhase = Math.floor(sprintAnimPhase * steps) / steps;
    actions.sprint.time = steppedPhase * sprintDur;
    actions.sprint.setEffectiveTimeScale(0);
    actions.sprint.setEffectiveWeight(sprintWeight * (1 - stopWeight));
  }

  mixer.update(dt);
  return {
    idleW: +actions.idle.getEffectiveWeight().toFixed(2),
    sprintW: +actions.sprint.getEffectiveWeight().toFixed(2),
    stopW: +actions.stop.getEffectiveWeight().toFixed(2),
    posZ: +state.pos.z.toFixed(2),
    stopping: state.stopping,
  };
}

console.log("=== PHASE 1: IDLE (Standing still) ===");
for (let i = 0; i < 5; i++) {
  const res = tick(0, 0, false);
  if (i === 4) console.log("Idle frame:", res);
}

console.log("\n=== PHASE 2: SPRINTING (Holding W + Shift for 40 frames) ===");
for (let i = 0; i < 40; i++) {
  const res = tick(0, 1, true);
  if (i === 10 || i === 30 || i === 39) console.log(`Sprint frame ${i}:`, res);
}

console.log("\n=== PHASE 3: RELEASING W+Shift (Triggering Sudden Stop) ===");
for (let i = 0; i < 35; i++) {
  const res = tick(0, 0, false);
  if (i === 1 || i === 10 || i === 20 || i === 30 || i === 34) console.log(`Stop frame ${i}:`, res);
}

console.log("\n=== PHASE 4: NORMAL JOG (Holding W without Shift) ===");
for (let i = 0; i < 20; i++) {
  const res = tick(0, 1, false);
  if (i === 15) console.log(`Jog frame ${i}:`, res);
}

console.log("\n=== PHASE 5: RELEASING W from normal jog (NO SUDDEN STOP) ===");
for (let i = 0; i < 20; i++) {
  const res = tick(0, 0, false);
  if (i === 5 || i === 15) console.log(`Normal release frame ${i}:`, res);
}

console.log("\nVerification complete! All locomotion transitions verified accurately.");

