import { build } from "esbuild";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const vendor = path.join(root, "vendor/three");

const vendoredThree = {
  name: "vendored-three",
  setup(b) {
    b.onResolve({ filter: /^three$/ }, () => ({ path: path.join(vendor, "three.module.min.js") }));
    b.onResolve({ filter: /^three\/addons\// }, (args) => ({
      path: path.join(vendor, "addons", args.path.slice("three/addons/".length)),
    }));
  },
};

const code = `
import fs from "fs";
import * as THREE from "three";
import { FBXLoader } from "./.impeccable/fbx/addons/loaders/FBXLoader.js";

globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: () => {}, removeEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: () => {}, removeEventListener: () => {} }),
};
global.HTMLImageElement = function() {};

const loader = new FBXLoader();
for (const f of ["idle-animation.fbx", "in place running.fbx", "running+stopping.fbx"]) {
  const buf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/" + f);
  const g = loader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  console.log("=== FILE:", f, "(size:", buf.byteLength, "bytes) ===");
  for (const a of g.animations) {
    console.log("  Clip:", a.name, "duration:", a.duration.toFixed(4) + "s", "frames(30fps):", Math.round(a.duration * 30), "frames(60fps):", Math.round(a.duration * 60), "tracks:", a.tracks.length);
    const hipPos = a.tracks.find(t => /Hips\\.position/.test(t.name));
    if (hipPos) {
      const n = hipPos.times.length;
      console.log("  Hips.pos keyframes:", n, "times[0..last]:", hipPos.times[0].toFixed(4), "->", hipPos.times[n - 1].toFixed(4));
      for (let i = 0; i < n; i += Math.max(1, Math.floor(n / 12))) {
        console.log("    frame " + i + " (t=" + hipPos.times[i].toFixed(3) + "s): [" + hipPos.values[i*3].toFixed(2) + ", " + hipPos.values[i*3+1].toFixed(2) + ", " + hipPos.values[i*3+2].toFixed(2) + "]");
      }
      const last = n - 1;
      console.log("    frame " + last + " (t=" + hipPos.times[last].toFixed(3) + "s): [" + hipPos.values[last*3].toFixed(2) + ", " + hipPos.values[last*3+1].toFixed(2) + ", " + hipPos.values[last*3+2].toFixed(2) + "]");
    }
    const scaleTracks = a.tracks.filter(t => /\\.scale$/.test(t.name));
    for (const st of scaleTracks) {
      let minS = Infinity, maxS = -Infinity;
      for (let v of st.values) {
        if (v < minS) minS = v;
        if (v > maxS) maxS = v;
      }
      if (Math.abs(maxS - 1) > 0.01 || Math.abs(minS - 1) > 0.01) {
        console.log("  Non-unit scale track:", st.name, "min:", minS.toFixed(3), "max:", maxS.toFixed(3));
      }
    }
  }
}
`;

const res = await build({
  stdin: { contents: code, resolveDir: root, loader: "js" },
  bundle: true,
  platform: "node",
  format: "esm",
  write: false,
  plugins: [vendoredThree],
  external: ["fs", "path", "url"],
});

const fn = new Function("import_meta", res.outputFiles[0].text.replace(/import\s+fs\s+from\s+"fs";/, 'const fs = globalThis.__fs;'));
import fs from "node:fs";
globalThis.__fs = fs;
fn({});

