import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

// Polyfill minimal browser DOM
globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {} })
};
global.HTMLImageElement = function() {};

const fbxLoader = new FBXLoader();

function inspectFbx(filePath) {
  console.log(`\n================ Inspecting: ${filePath} ================`);
  const buf = fs.readFileSync(filePath);
  const group = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");

  const bones = [];
  group.traverse((n) => {
    if (n.isBone) bones.push(n.name);
  });
  console.log(`Total bones found: ${bones.length}`);
  console.log(`Sample bones: ${bones.slice(0, 10).join(", ")}`);

  console.log(`Animations count: ${group.animations?.length || 0}`);
  if (group.animations?.length) {
    for (let i = 0; i < group.animations.length; i++) {
      const clip = group.animations[i];
      console.log(`Clip ${i}: "${clip.name}", duration: ${clip.duration}s, tracks: ${clip.tracks.length}`);

      // Find hips track if any
      const hipPosTrack = clip.tracks.find(t => t.name.toLowerCase().includes("hips.position"));
      if (hipPosTrack) {
        console.log(`Hips pos track times count: ${hipPosTrack.times.length}, duration: ${hipPosTrack.times[hipPosTrack.times.length - 1]}`);
        console.log(`Start pos: [${hipPosTrack.values[0].toFixed(3)}, ${hipPosTrack.values[1].toFixed(3)}, ${hipPosTrack.values[2].toFixed(3)}]`);
        const midIdx = Math.floor(hipPosTrack.times.length / 2) * 3;
        console.log(`Mid pos: [${hipPosTrack.values[midIdx].toFixed(3)}, ${hipPosTrack.values[midIdx+1].toFixed(3)}, ${hipPosTrack.values[midIdx+2].toFixed(3)}]`);
        const endIdx = (hipPosTrack.times.length - 1) * 3;
        console.log(`End pos: [${hipPosTrack.values[endIdx].toFixed(3)}, ${hipPosTrack.values[endIdx+1].toFixed(3)}, ${hipPosTrack.values[endIdx+2].toFixed(3)}]`);

        // Print min and max of X, Y, Z
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let minZ = Infinity, maxZ = -Infinity;
        for (let j = 0; j < hipPosTrack.values.length; j += 3) {
          const x = hipPosTrack.values[j];
          const y = hipPosTrack.values[j+1];
          const z = hipPosTrack.values[j+2];
          if (x < minX) minX = x; if (x > maxX) maxX = x;
          if (y < minY) minY = y; if (y > maxY) maxY = y;
          if (z < minZ) minZ = z; if (z > maxZ) maxZ = z;
        }
        console.log(`Hips X range: [${minX.toFixed(3)}, ${maxX.toFixed(3)}]`);
        console.log(`Hips Y range: [${minY.toFixed(3)}, ${maxY.toFixed(3)}]`);
        console.log(`Hips Z range: [${minZ.toFixed(3)}, ${maxZ.toFixed(3)}]`);
      }
    }
  }
}

