import fs from "fs";
import * as THREE from "../../vendor/three/three.module.min.js";
import { FBXLoader } from "../fbx/addons/loaders/FBXLoader.js";

// Polyfill minimal browser DOM
globalThis.self = globalThis;
global.window = globalThis;
global.document = {
  createElementNS: () => ({ style: {}, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {} }),
  createElement: () => ({ style: {}, getContext: () => null, addEventListener: (t, fn) => { if (t === 'load') setTimeout(fn, 1); }, removeEventListener: () => {} })
};
global.HTMLImageElement = function() {};

const fbxLoader = new FBXLoader();

const runStopBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/running+stopping.fbx");
const runStopGroup = fbxLoader.parse(runStopBuf.buffer.slice(runStopBuf.byteOffset, runStopBuf.byteOffset + runStopBuf.byteLength), "");
const runStopClip = runStopGroup.animations[0];

const idleBuf = fs.readFileSync("c:/Users/Rigel/Desktop/Cascadeur/idle-animation.fbx");
const idleGroup = fbxLoader.parse(idleBuf.buffer.slice(idleBuf.byteOffset, idleBuf.byteOffset + idleBuf.byteLength), "");
const idleClip = idleGroup.animations[0];

console.log("=== RUNNING+STOPPING (f0 to f29) ===");
const rHips = runStopClip.tracks.find(t => t.name.includes("Hips.position"));
const rLeftFoot = runStopClip.tracks.find(t => t.name.includes("LeftFoot.position"));
const rRightFoot = runStopClip.tracks.find(t => t.name.includes("RightFoot.position"));

for (let f = 0; f < 30; f += 2) {
  const hz = rHips.values[f * 3 + 2];
  const hy = rHips.values[f * 3 + 1];
  console.log(`f${f.toString().padStart(2, "0")} (${(f/60).toFixed(3)}s): Hips Y=${hy.toFixed(1)} Z=${hz.toFixed(1)}`);
}

console.log("\n=== COMPARE LAST FRAME OF RUNNING+STOPPING TO FIRST FRAME OF IDLE ===");
const strip = s => s.replace("mixamorig", "").replace("Armature.", "");

const getRot = (clip, boneName, frameIndex, totalFrames) => {
  const track = clip.tracks.find(t => strip(t.name) === `${boneName}.quaternion`);
  if (!track) return null;
  const idx = Math.min(frameIndex, (track.times.length - 1)) * 4;
  return [track.values[idx], track.values[idx+1], track.values[idx+2], track.values[idx+3]];
};

const bonesToCheck = ["Hips", "Spine", "LeftArm", "RightArm", "LeftUpLeg", "RightUpLeg", "LeftFoot", "RightFoot"];
for (const b of bonesToCheck) {
  const qStopEnd = getRot(runStopClip, b, 29, 30);
  const qIdleStart = getRot(idleClip, b, 0, 40);
  console.log(`Bone ${b}:`);
  console.log(`  Stop end:   [${qStopEnd?.map(v => v.toFixed(3)).join(", ")}]`);
  console.log(`  Idle start: [${qIdleStart?.map(v => v.toFixed(3)).join(", ")}]`);
}

