import fs from "fs";

let world = fs.readFileSync("world.js", "utf8");

// 1. Update default SPRINT_ANIME_FPS
const targetFps = `  const fpsParam = devParam.get("animefps") || devParam.get("fps");
  let SPRINT_ANIME_FPS = fpsParam != null ? parseInt(fpsParam, 10) : 12;`.replace(/\n/g, "\r\n");

const replFps = `  const fpsParam = devParam.get("animefps") || devParam.get("fps");
  let SPRINT_ANIME_FPS = fpsParam != null ? parseInt(fpsParam, 10) : 0;`.replace(/\n/g, "\r\n");

if (!world.includes(targetFps)) throw new Error("targetFps not found");
world = world.replace(targetFps, replFps);

// 2. Rename wasRunning to wasSprinting in state
const targetState = `    wasRunning: false,`.replace(/\n/g, "\r\n");
const replState = `    wasSprinting: false,`.replace(/\n/g, "\r\n");

if (!world.includes(targetState)) throw new Error("targetState not found");
world = world.replace(targetState, replState);

// 3. Update locomotion block
const targetLoco = `    if (input.lengthSq() > 0.0001) {
      state.path = [];
      state.pending = null;
      robot.position.addScaledVector(input, SPEED * state.sprintMul * dt);
      resolveCollisions(robot.position);
      stepTo(before, robot.position);
      state.yaw = Math.atan2(input.x, input.z);
      state.pace = THREE.MathUtils.damp(state.pace, input.length(), 10, dt);
      moving = true;
      if (isSprint && state.sprint > 0.4) {
        state.wasRunning = true;
      }
      if (state.stopping) {
        state.stopping = false;
        state.stopTimer = 0;
        if (bot.actions?.stop) bot.actions.stop.setEffectiveWeight(0);
      }
    } else if (state.path.length) {
      state.pace = THREE.MathUtils.damp(state.pace, 1, 10, dt);
      const target = state.path[0];
      const dx = target.x - robot.position.x;
      const dz = target.z - robot.position.z;
      const dist = Math.hypot(dx, dz);

      if (dist < 0.06) {
        state.path.shift();
        if (!state.path.length) {
          arrive();
        }
      } else {
        const step = Math.min(dist, SPEED * dt);
        robot.position.x += (dx / dist) * step;
        robot.position.z += (dz / dist) * step;
        state.yaw = Math.atan2(dx, dz);
        moving = true;
      }
    } else {
      // Stopping animation ONLY triggers when stopping from running (sprint) mode:
      if (state.wasMoving && state.wasRunning && !state.stopping && !state.punching && !lockTarget) {
        state.stopping = true;
        state.stopTimer = 0;
        state.stopSpeed = SPEED * state.sprintMul;
        state.stopDir.set(Math.sin(state.yaw), 0, Math.cos(state.yaw));
        if (bot.actions?.stop) {
          bot.actions.stop.reset();
          bot.actions.stop.play();
        }
      }
      state.wasRunning = false;
      state.pace = THREE.MathUtils.damp(state.pace, 0, 10, dt);
    }`.replace(/\n/g, "\r\n");

const replLoco = `    if (input.lengthSq() > 0.0001) {
      state.path = [];
      state.pending = null;
      robot.position.addScaledVector(input, SPEED * state.sprintMul * dt);
      resolveCollisions(robot.position);
      stepTo(before, robot.position);
      state.yaw = Math.atan2(input.x, input.z);
      state.pace = THREE.MathUtils.damp(state.pace, input.length(), 10, dt);
      moving = true;
      if (isSprint && state.sprint > 0.3) {
        state.wasSprinting = true;
      }
      if (state.stopping) {
        state.stopping = false;
        state.stopTimer = 0;
        if (bot.actions?.stop) bot.actions.stop.setEffectiveWeight(0);
      }
    } else if (state.path.length) {
      state.pace = THREE.MathUtils.damp(state.pace, 1, 10, dt);
      const target = state.path[0];
      const dx = target.x - robot.position.x;
      const dz = target.z - robot.position.z;
      const dist = Math.hypot(dx, dz);

      if (dist < 0.06) {
        state.path.shift();
        if (!state.path.length) {
          arrive();
        }
      } else {
        const step = Math.min(dist, SPEED * dt);
        robot.position.x += (dx / dist) * step;
        robot.position.z += (dz / dist) * step;
        state.yaw = Math.atan2(dx, dz);
        moving = true;
      }
    } else {
      // Stopping animation ONLY triggers when stopping from sprint mode (WASD + Shift):
      if (state.wasMoving && state.wasSprinting && !state.stopping && !state.punching && !lockTarget) {
        state.stopping = true;
        state.stopTimer = 0;
        state.stopSpeed = SPEED * state.sprintMul;
        state.stopDir.set(Math.sin(state.yaw), 0, Math.cos(state.yaw));
        if (bot.actions?.stop) {
          bot.actions.stop.reset();
          bot.actions.stop.play();
