const model = gltf.scene;
model.updateMatrixWorld(true);
let nikoHips;
model.traverse(n => { if (n.isBone && n.name.includes("Hips")) nikoHips = n; });
console.log("Niko GLB Hips local pos:", nikoHips.position.toArray(), "world pos:", nikoHips.getWorldPosition(new THREE.Vector3()).toArray());

const fbxLoader = new FBXLoader();
const files = [
  "c:/Users/Rigel/Desktop/Cascadeur/niko-cascadeur-clean.fbx",
  "c:/Users/Rigel/Desktop/Cascadeur/in place running.fbx",
  "c:/Users/Rigel/Desktop/Cascadeur/idle-animation.fbx",
  "c:/Users/Rigel/Desktop/Cascadeur/running+stopping.fbx",
];

for (const f of files) {
  const buf = fs.readFileSync(f);
  const g = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  g.updateMatrixWorld(true);
  let h, arm;
  g.traverse(n => {
    if (n.name.includes("Armature")) arm = n;
    if (n.isBone && n.name.includes("Hips")) h = n;
  });
  const wp = h.getWorldPosition(new THREE.Vector3());
  console.log(`\nFile: ${f}`);
  console.log(`  Armature scale: ${arm?.scale.toArray()}, rot: ${arm?.rotation.toArray().slice(0,3)}`);
  console.log(`  Rest Hips local pos: ${h.position.toArray().map(v => +v.toFixed(3))}, world pos: ${wp.toArray().map(v => +v.toFixed(3))}`);
  if (g.animations?.[0]) {
    const mixer = new THREE.AnimationMixer(g);
    mixer.clipAction(g.animations[0]).play();
    mixer.setTime(0);
    g.updateMatrixWorld(true);
    const wp0 = h.getWorldPosition(new THREE.Vector3());
    console.log(`  Frame 0 Hips local pos: ${h.position.toArray().map(v => +v.toFixed(3))}, world pos: ${wp0.toArray().map(v => +v.toFixed(3))}`);
  }
}

