function inspectDetailed(path) {
  console.log(`\n================ ${path} ================`);
  const buf = fs.readFileSync(path);
  const g = fbxLoader.parse(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength), "");
  const clip = g.animations[0];
  console.log(`Duration: ${clip.duration}s, frames: ${clip.tracks[0].times.length}`);

  const lLeg = clip.tracks.find(t => t.name.includes("LeftUpLeg.quaternion"));
  const rLeg = clip.tracks.find(t => t.name.includes("RightUpLeg.quaternion"));
  const hips = clip.tracks.find(t => t.name.includes("Hips.position"));

  const n = hips.times.length;
  for (let i = 0; i < n; i += 3) {
    const lq = [lLeg.values[i*4], lLeg.values[i*4+1], lLeg.values[i*4+2], lLeg.values[i*4+3]];
    const rq = [rLeg.values[i*4], rLeg.values[i*4+1], rLeg.values[i*4+2], rLeg.values[i*4+3]];
    const hp = [hips.values[i*3], hips.values[i*3+1], hips.values[i*3+2]];
    console.log(`f${i.toString().padStart(2, "0")}: HipsY=${hp[1].toFixed(1)} HipsZ=${hp[2].toFixed(1)} | LUpLeg=[${lq.map(v=>v.toFixed(2))}] | RUpLeg=[${rq.map(v=>v.toFixed(2))}]`);
  }
  const last = n - 1;
  const lq = [lLeg.values[last*4], lLeg.values[last*4+1], lLeg.values[last*4+2], lLeg.values[last*4+3]];
  const rq = [rLeg.values[last*4], rLeg.values[last*4+1], rLeg.values[last*4+2], rLeg.values[last*4+3]];
  const hp = [hips.values[last*3], hips.values[last*3+1], hips.values[last*3+2]];
  console.log(`f${last.toString().padStart(2, "0")}: HipsY=${hp[1].toFixed(1)} HipsZ=${hp[2].toFixed(1)} | LUpLeg=[${lq.map(v=>v.toFixed(2))}] | RUpLeg=[${rq.map(v=>v.toFixed(2))}]`);
}

