  const fnLen = buf.readUInt16LE(26);
  const extraLen = buf.readUInt16LE(28);
  const dataStart = 30 + fnLen + extraLen;
  const nextPk = buf.indexOf(Buffer.from([0x50, 0x4b, 0x03, 0x04]), dataStart);
  const compBuf = buf.slice(dataStart, nextPk);
  return JSON.parse(zlib.zstdDecompressSync(compBuf).toString("utf8"));
}

const s = readCascScene("c:/Users/Rigel/Desktop/Cascadeur/niko-run.casc");
const a = Buffer.from(s.animation, "base64");

const animItems = [];
for (const obj of s.objects) {
  for (const d of obj.data) {
    if (d.mode === "animation") animItems.push({ objName: obj.name, typeName: obj.type_name, ...d });
  }
}
const byIndex = new Map(animItems.map((x) => [x.index, x]));
const typeSizes = { int: 4, float: 4, bool: 1, Vector3f: 12, Rotation: 12, Quaternionf: 16, Matrix4f: 64 };

