const fs = require("fs");
const zlib = require("zlib");
function loadCasc(path) {
  const buf = fs.readFileSync(path);
  let pos = 0;
  while (pos < buf.length - 4) {
    if (buf.readUInt32LE(pos) !== 0x04034b50) break;
    const compSize = buf.readUInt32LE(pos + 18);
    const nameLen = buf.readUInt16LE(pos + 26);
    const extraLen = buf.readUInt16LE(pos + 28);
    const name = buf.slice(pos + 30, pos + 30 + nameLen).toString("utf8");
    const dataStart = pos + 30 + nameLen + extraLen;
    if (name === "scene/scene.json") {
      return JSON.parse(zlib.zstdDecompressSync(buf.slice(dataStart, dataStart + compSize)).toString("utf8"));
    }
    pos = dataStart + compSize;
  }
}
const s = loadCasc("c:/Users/Rigel/Desktop/Cascadeur/niko-run.casc");
console.log("data_clusters keys:", Object.keys(s.data_clusters || {}));
