async function run() {
  const fileStream = fs.createReadStream("C:/Users/Rigel/.gemini/antigravity/brain/5fafe6c3-7b6d-489c-8870-78f2aacb5867/.system_generated/logs/transcript_full.jsonl");
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const types = {};
  let total = 0;
  let userInputs = 0;
  let assistantResponses = 0;

  for await (const line of rl) {
