import fs from "fs";
import readline from "readline";
import path from "path";

const rootDir = process.cwd();
const transcriptFullPath = "C:/Users/Rigel/.gemini/antigravity/brain/5fafe6c3-7b6d-489c-8870-78f2aacb5867/.system_generated/logs/transcript_full.jsonl";
const transcriptCompactPath = "C:/Users/Rigel/.gemini/antigravity/brain/5fafe6c3-7b6d-489c-8870-78f2aacb5867/.system_generated/logs/transcript.jsonl";

async function exportConversation() {
  console.log("Reading transcript from:", transcriptFullPath);

  const fileStream = fs.createReadStream(transcriptFullPath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const turns = [];
  let currentTurn = null;

  for await (const line of rl) {
    if (!line.trim()) continue;
    let entry;
    try {
      entry = JSON.parse(line);
    } catch {
      continue;
    }

    if (entry.type === "USER_INPUT") {
      if (currentTurn) {
        turns.push(currentTurn);
      }
      currentTurn = {
        turnIndex: turns.length + 1,
        stepIndex: entry.step_index,
        timestamp: entry.created_at,
        rawUserContent: entry.content || "",
        tools: [],
        assistantResponses: [],
      };
    } else if (currentTurn) {
      if (entry.type === "PLANNER_RESPONSE") {
        if (entry.tool_calls && Array.isArray(entry.tool_calls)) {
          for (const tc of entry.tool_calls) {
            const summary = tc.args?.toolSummary || tc.args?.CommandLine || tc.args?.Path || "";
            currentTurn.tools.push({
              name: tc.name,
              summary: typeof summary === "string" ? summary.slice(0, 150) : "",
            });
          }
        }
        if (entry.content && typeof entry.content === "string" && entry.content.trim()) {
          currentTurn.assistantResponses.push({
            timestamp: entry.created_at,
            content: entry.content.trim(),
          });
        }
      }
    }
  }

  if (currentTurn) {
    turns.push(currentTurn);
  }

  console.log(`Processed ${turns.length} conversation turns.`);

  // Clean user request content
  function cleanUserContent(raw) {
    if (!raw) return "";
    let text = raw;
    const match = text.match(/<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>/);
    if (match) {
      text = match[1].trim();
    }
    // Remove <CONTEXT_SUMMARY> blocks if present
    text = text.replace(/<CONTEXT_SUMMARY>[\s\S]*?<\/CONTEXT_SUMMARY>/g, "").trim();
    return text || raw;
  }

  let md = `# Conversation History Export\n\n`;
  md += `**Export Date:** ${new Date().toISOString()}\n`;
  md += `**Workspace:** \`${rootDir}\`\n`;
  md += `**Total Conversation Turns:** ${turns.length}\n\n`;
  md += `---\n\n`;

  for (const turn of turns) {
    const userText = cleanUserContent(turn.rawUserContent);
    const dateStr = turn.timestamp ? new Date(turn.timestamp).toLocaleString("en-US", { timeZone: "Asia/Manila" }) : "Unknown Time";

    md += `## Turn ${turn.turnIndex} (${dateStr})\n\n`;
    md += `### 👤 User\n\n${userText}\n\n`;

    if (turn.tools.length > 0) {
      md += `<details>\n<summary><b>🛠️ Actions Taken (${turn.tools.length} tool calls)</b></summary>\n\n`;
      for (const t of turn.tools) {
        md += `- \`${t.name}\`${t.summary ? `: ${t.summary}` : ""}\n`;
      }
      md += `\n</details>\n\n`;
    }

    if (turn.assistantResponses.length > 0) {
      md += `### 🤖 Assistant\n\n`;
      for (const resp of turn.assistantResponses) {
        md += `${resp.content}\n\n`;
      }
    } else {
      md += `### 🤖 Assistant\n\n*(In progress / tool execution only)*\n\n`;
    }

    md += `---\n\n`;
  }

  const outMdPath = path.join(rootDir, "CONVERSATION_HISTORY.md");
  fs.writeFileSync(outMdPath, md, "utf8");
  console.log(`Saved Markdown history to: ${outMdPath} (${(fs.statSync(outMdPath).size / 1024).toFixed(1)} KB)`);

  // Also copy the raw transcript jsonl files to the root folder
  const outJsonlPath = path.join(rootDir, "conversation_transcript.jsonl");
  fs.copyFileSync(transcriptCompactPath, outJsonlPath);
  console.log(`Copied compact transcript to: ${outJsonlPath} (${(fs.statSync(outJsonlPath).size / (1024 * 1024)).toFixed(2)} MB)`);

  const outJsonlFullPath = path.join(rootDir, "conversation_transcript_full.jsonl");
  fs.copyFileSync(transcriptFullPath, outJsonlFullPath);
  console.log(`Copied full transcript to: ${outJsonlFullPath} (${(fs.statSync(outJsonlFullPath).size / (1024 * 1024)).toFixed(2)} MB)`);
}

